// ────────────────────────────────────────────────────────────────────────────
// Body shape helpers (mirrors ccBridgeTransforms.ts internals).
// ────────────────────────────────────────────────────────────────────────────

interface RequestBody {
  system?: unknown;
  messages?: unknown;
  tools?: unknown;
  [key: string]: unknown;
}

// ────────────────────────────────────────────────────────────────────────────
// Op: obfuscate_words (the only op kind beyond the base set).
// ────────────────────────────────────────────────────────────────────────────

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const ZWJ = "\u200d";

function obfuscateWord(word: string): string {
  if (word.length <= 1) return word;
  return word[0] + ZWJ + word.slice(1);
}

/**
 * Stateless variant of `obfuscateSensitiveWords` — uses the supplied word
 * list instead of the module-level singleton, so concurrent requests with
 * different op configs do not race.
 */
// Per-word regex cache: obfuscateWithList runs over the whole request body on every
// request when obfuscation is enabled, recompiling one RegExp per word each time. The
// word list is stable per op config, so memoize. Bounded by distinct configured words
// (with a defensive cap). Global regexes are safe to reuse: String.replace resets lastIndex.
const _obfuscationRegexCache = new Map<string, RegExp>();
function getObfuscationRegex(word: string): RegExp {
  let regex = _obfuscationRegexCache.get(word);
  if (!regex) {
    if (_obfuscationRegexCache.size > 2000) _obfuscationRegexCache.clear();
    regex = new RegExp(escapeRegex(word), "gi");
    _obfuscationRegexCache.set(word, regex);
  }
  return regex;
}

function obfuscateWithList(text: string, words: string[]): string {
  if (!text || words.length === 0) return text;
  let result = text;
  for (const word of words) {
    if (!word) continue;
    const regex = getObfuscationRegex(word);
    result = result.replace(regex, (match) => obfuscateWord(match));
  }
  return result;
}

function applyObfuscateWords(body: RequestBody, op: ObfuscateWordsOp): void {
  const words = op.words || [];
  if (words.length === 0) return;
  const targets =
    op.targets && op.targets.length > 0 ? op.targets : ["system", "messages", "tools"];

  if (targets.includes("system")) {
    if (typeof body.system === "string") {
      body.system = obfuscateWithList(body.system, words);
    } else if (Array.isArray(body.system)) {
      for (const block of body.system as Array<Record<string, unknown>>) {
        if (typeof block.text === "string") {
          block.text = obfuscateWithList(block.text, words);
        }
      }
    }
  }

  if (targets.includes("messages") && Array.isArray(body.messages)) {
    for (const msg of body.messages as Array<Record<string, unknown>>) {
      const content = msg.content;
      if (typeof content === "string") {
        msg.content = obfuscateWithList(content, words);
      } else if (Array.isArray(content)) {
        for (const block of content as Array<Record<string, unknown>>) {
          if (typeof block.text === "string") {
            block.text = obfuscateWithList(block.text, words);
          }
        }
      }
    }
  }

  if (targets.includes("tools") && Array.isArray(body.tools)) {
    for (const tool of body.tools as Array<Record<string, unknown>>) {
      if (typeof tool.description === "string") {
        tool.description = obfuscateWithList(tool.description, words);
      }
      const fn = tool.function as Record<string, unknown> | undefined;
      if (fn && typeof fn.description === "string") {
        fn.description = obfuscateWithList(fn.description, words);
      }
    }
  }
}

// ────────────────────────────────────────────────────────────────────────────
// Pipeline executor (delegates base ops to applyCcBridgeTransformPipeline).
// ────────────────────────────────────────────────────────────────────────────

export interface ApplyPipelineResult {
  body: RequestBody;
  appliedOpKinds: string[];
}

function isObfuscateWordsOp(op: TransformOp): op is ObfuscateWordsOp {
  return op.kind === "obfuscate_words";
}

/**
 * Apply a pipeline of generic transforms to a request body.
 *
 * Strategy:
 *   1. Split the pipeline into runs of `obfuscate_words` ops vs base ops.
 *   2. Base-op runs delegate to `applyCcBridgeTransformPipeline` (preserves
 *      the well-tested base executor, including ordering semantics).
 *   3. `obfuscate_words` ops mutate the body in place between base-op runs.
 *
 * This preserves declared order (e.g. drop paragraphs first → obfuscate
 * what survives) while reusing the existing executor.
 */
export function applyTransformPipeline(
  body: RequestBody,
  pipeline: TransformOp[]
): ApplyPipelineResult {
  if (!body || typeof body !== "object") return { body, appliedOpKinds: [] };
  if (!Array.isArray(pipeline) || pipeline.length === 0) {
    return { body, appliedOpKinds: [] };
  }

  const appliedOpKinds: string[] = [];
  let baseRun: BaseTransformOp[] = [];

  const flushBaseRun = () => {
    if (baseRun.length === 0) return;
    const config: CcBridgeTransformsConfig = { enabled: true, pipeline: baseRun };
    // Local `RequestBody` interface is intentionally looser than the strict one
    // exported by ccBridgeTransforms — system transforms accept any shape.
    const result = applyCcBridgeTransformPipeline(
      body as Parameters<typeof applyCcBridgeTransformPipeline>[0],
      config
    );
    appliedOpKinds.push(...result.appliedOpKinds);
    baseRun = [];
  };

  for (const op of pipeline) {
    if (isObfuscateWordsOp(op)) {
      flushBaseRun();
      applyObfuscateWords(body, op);
      appliedOpKinds.push(op.kind);
    } else {
      baseRun.push(op);
    }
  }
  flushBaseRun();

  return { body, appliedOpKinds };
}

/**
 * Apply the configured per-provider pipeline to `body`. No-op when the
 * provider is unconfigured or disabled.
 *
 * `providerId` matches OmniRoute's provider key (`claude`,
 * `anthropic-compatible-cc-…`, `gemini`, etc.). For CC bridge providers,
 * the bridge-prefix match falls back to the `PROVIDER_CC_BRIDGE` key so
 * a single config entry covers every cc/* variant.
 */
export function applySystemTransformPipeline(
  providerId: string,
  body: RequestBody,
  config: SystemTransformsConfig = getSystemTransformsConfig()
): ApplyPipelineResult {
  if (!body || typeof body !== "object") return { body, appliedOpKinds: [] };
  if (!config || !config.providers) return { body, appliedOpKinds: [] };

  const providerConfig = resolveProviderConfig(providerId, config);
  if (!providerConfig || !providerConfig.enabled) {
    return { body, appliedOpKinds: [] };
  }

  return applyTransformPipeline(body, providerConfig.pipeline);
}

function resolveProviderConfig(
  providerId: string,
  config: SystemTransformsConfig
): ProviderTransformsConfig | undefined {
  if (!providerId) return undefined;
  const exact = config.providers[providerId];
  if (exact) return exact;

  // CC bridge providers (anthropic-compatible-cc-*) all share one config.
  if (providerId.startsWith(`${PROVIDER_CC_BRIDGE}-`) || providerId === PROVIDER_CC_BRIDGE) {
    return config.providers[PROVIDER_CC_BRIDGE];
  }
  return undefined;
}

// ────────────────────────────────────────────────────────────────────────────
// Runtime singleton.
// ────────────────────────────────────────────────────────────────────────────

// Backed by globalThis so the config is shared across the SEPARATE webpack module
// graphs Next.js builds for `instrumentation.ts` (boot-time hydration via
// applyRuntimeSettings → setSystemTransformsConfig) and the app-route / open-sse
// executors (per-request reads in base.ts / claudeCodeCompatible.ts). A module-local
// `let` is duplicated per graph, so a Settings-UI override applied at boot never
// reaches the request path (the #5312-class module-graph bug; the protective
// compiled default still runs, but operator customizations were silently dropped).
// Mirrors systemPrompt.ts (#2470) and thinkingBudget.ts (#5312).
const GLOBAL_KEY = "__omniroute_systemTransforms_config__";
const _store = globalThis as unknown as Record<string, SystemTransformsConfig | undefined>;

function getStore(): SystemTransformsConfig {
  if (!_store[GLOBAL_KEY]) {
    _store[GLOBAL_KEY] = DEFAULT_SYSTEM_TRANSFORMS_CONFIG;
  }
  return _store[GLOBAL_KEY]!;
}

/**
 * Replace the active system-transforms config. Called from
 * `runtimeSettings.applySystemTransformsSection()` on Settings UI save.
 *
 * Accepts a legacy `CcBridgeTransformsConfig` shape (single-provider) and
 * migrates it into `providers[PROVIDER_CC_BRIDGE]`.
 */
export function setSystemTransformsConfig(input: unknown): void {
  if (!input || typeof input !== "object") {
    _store[GLOBAL_KEY] = DEFAULT_SYSTEM_TRANSFORMS_CONFIG;
    return;
  }
  const candidate = input as Record<string, unknown>;

  // Legacy shape: { enabled, pipeline } → migrate to per-provider map.
  if ("pipeline" in candidate && Array.isArray(candidate.pipeline)) {
    _store[GLOBAL_KEY] = {
      providers: {
        ...DEFAULT_SYSTEM_TRANSFORMS_CONFIG.providers,
        [PROVIDER_CC_BRIDGE]: {
          enabled: candidate.enabled !== false,
          pipeline: candidate.pipeline as TransformOp[],
        },
      },
    };
    return;
  }

  // Per-provider shape: { providers: Record<string, { enabled, pipeline }> }
  if ("providers" in candidate && candidate.providers && typeof candidate.providers === "object") {
    const next: SystemTransformsConfig = { providers: {} };
    const providers = candidate.providers as Record<string, unknown>;
    for (const [providerId, providerEntry] of Object.entries(providers)) {
      if (!providerEntry || typeof providerEntry !== "object") continue;
      const entry = providerEntry as Record<string, unknown>;
      next.providers[providerId] = {
        enabled: entry.enabled !== false,
        pipeline: Array.isArray(entry.pipeline) ? (entry.pipeline as TransformOp[]) : [],
      };
    }
    // Merge defaults for any unset provider — keeps ZWJ on by default even
    // when the user only configured one provider explicitly.
    for (const [providerId, providerDefault] of Object.entries(
      DEFAULT_SYSTEM_TRANSFORMS_CONFIG.providers
    )) {
      if (!next.providers[providerId]) {
        next.providers[providerId] = providerDefault;
      }
    }
    _store[GLOBAL_KEY] = next;
    return;
  }

  _store[GLOBAL_KEY] = DEFAULT_SYSTEM_TRANSFORMS_CONFIG;
}

export function getSystemTransformsConfig(): SystemTransformsConfig {
  return getStore();
}

export function resetSystemTransformsConfig(): void {
  _store[GLOBAL_KEY] = DEFAULT_SYSTEM_TRANSFORMS_CONFIG;
}

/**
 * CC Bridge Transforms — config-driven request body normalization for the
 * Claude Code Compatible (`anthropic-compatible-cc-*`) bridge.
 *
 * Goal: ensure the final request body OmniRoute sends to Anthropic's
 * `/v1/messages?beta=true` endpoint has classifier-correct structure
 * regardless of which client (OpenCode, Cline, Cursor, Continue, raw API
 * consumer) supplied the prompt.
 *
 * Approach: an ordered pipeline of declarative `TransformOp` entries that
 * mutate the request body in place. Each op is idempotent; the executor is
 * pure (no I/O); new defenses can be added through Settings UI by appending
 * a new op — no new TypeScript needed.
 *
 * Reference implementation: ex-machina/opencode-anthropic-auth `transform.ts`
 * and `cch.ts`. Ported with the same defaults (paragraph anchors, identity
 * prefixes, text replacements, billing header algorithm) but generalised
 * behind a discriminated-union DSL so future fingerprints are configurable.
 *
 * Related: OmniRoute issue #2260.
 */
import { createHash } from "node:crypto";

import {
  CLAUDE_CODE_CLIENT_BUILD_REVISION,
  CLAUDE_CODE_CLIENT_VERSION,
} from "@/shared/constants/claudeCodeClient";

// ────────────────────────────────────────────────────────────────────────────
// DSL types
// ────────────────────────────────────────────────────────────────────────────

export type TransformOp =
  | DropParagraphIfContainsOp
  | DropParagraphIfStartsWithOp
  | ReplaceTextOp
  | ReplaceRegexOp
  | DropBlockIfContainsOp
  | PrependSystemBlockOp
  | AppendSystemBlockOp
  | InjectBillingHeaderOp;

export interface DropParagraphIfContainsOp {
  kind: "drop_paragraph_if_contains";
  needles: string[];
  caseSensitive?: boolean;
}

export interface DropParagraphIfStartsWithOp {
  kind: "drop_paragraph_if_starts_with";
  prefixes: string[];
  caseSensitive?: boolean;
}

export interface ReplaceTextOp {
  kind: "replace_text";
  match: string;
  replacement: string;
  allOccurrences?: boolean;
}

export interface ReplaceRegexOp {
  kind: "replace_regex";
  pattern: string;
  flags?: string;
  replacement: string;
}

export interface DropBlockIfContainsOp {
  kind: "drop_block_if_contains";
  needles: string[];
}

export interface PrependSystemBlockOp {
  kind: "prepend_system_block";
  text: string;
  /** Skip if any earlier block already starts with this prefix. */
  idempotencyKey?: string;
}

export interface AppendSystemBlockOp {
  kind: "append_system_block";
  text: string;
  idempotencyKey?: string;
}

export interface InjectBillingHeaderOp {
  kind: "inject_billing_header";
  /** Anthropic billing entrypoint label (e.g. `sdk-cli`, `cli`). */
  entrypoint: string;
  /**
   * Version suffix algorithm:
   *   - ex-machina: sha256(SALT + chars-at-positions + version).slice(0,3)
   *   - omniroute-daystamp: sha256(YYYY-MM-DD + version).slice(0,3)
   */
  versionFormat: "ex-machina" | "omniroute-daystamp";
  /**
   * CCH attestation algorithm:
   *   - sha256-first-user: sha256(firstUserMessageText).slice(0,5)  (ex-machina)
   *   - xxhash64-body: defer to body-level signRequestBody; emit "00000" here
   *   - static-zero: emit "00000" (relay endpoints don't validate)
   */
  cchAlgo: "sha256-first-user" | "xxhash64-body" | "static-zero";
  /** Override the embedded `cc_version=` value. Defaults to `2.1.219`. */
  version?: string;
  /** Override its captured build revision. Defaults to a computed compatibility suffix. */
  buildRevision?: string;
}

export interface CcBridgeTransformsConfig {
  enabled: boolean;
  pipeline: TransformOp[];
}

// ────────────────────────────────────────────────────────────────────────────
// Ported constants (ex-machina/constants.ts)
// ────────────────────────────────────────────────────────────────────────────

/** Stable salt used by ex-machina/cch.ts for the version-suffix hash. */
export const CCH_SALT = "59cf53e54c78";
/** Character positions sampled from the first user message text. */
export const CCH_POSITIONS = [4, 7, 20] as const;
/** Default `cc_version=` value embedded in the billing header. */
export const DEFAULT_CLAUDE_CODE_VERSION = CLAUDE_CODE_CLIENT_VERSION;
/** Identity sentinel prepended for Claude Agent SDK callers. */
export const CLAUDE_AGENT_SDK_IDENTITY =
  "You are a Claude agent, built on Anthropic's Claude Agent SDK.";
/** Paragraph anchors from ex-machina (URLs identifying third-party agents). */
export const DEFAULT_PARAGRAPH_REMOVAL_ANCHORS = [
  "github.com/anomalyco/opencode",
  "opencode.ai/docs",
  "github.com/cline/cline",
  "github.com/getcursor/cursor",
  "continue.dev",
];
/** Identity paragraph prefixes that signal a third-party agent. */
export const DEFAULT_IDENTITY_PREFIXES = ["You are OpenCode"];
/** Text replacements (last entry is the v1.7.5 phrase-shape filter fix). */
export const DEFAULT_TEXT_REPLACEMENTS: Array<{ match: string; replacement: string }> = [
  { match: "if OpenCode honestly", replacement: "if the assistant honestly" },
  {
    match: "Here is some useful information about the environment you are running in:",
    replacement: "Environment context you are running in:",
  },
];

/**
 * Default pipeline shipped with the PR — matches the T4-200 fixture layout
 * proven against the live OmniRoute deployment (call log
 * f0c2fedb-b27a-4f1d-9ee6-0c88646a6d42).
 *
 * Layout after pipeline (system blocks):
 *   [0] x-anthropic-billing-header: cc_version=…; cc_entrypoint=sdk-cli; cch=…
 *   [1] You are a Claude agent, built on Anthropic's Claude Agent SDK.
 *   [2..] sanitized caller-supplied system blocks
 */
export const DEFAULT_CC_BRIDGE_PIPELINE: TransformOp[] = [
  // Sanitize caller-supplied system blocks first so dropped paragraphs do not
  // accidentally contain a stale billing header from a previous pass.
  {
    kind: "drop_paragraph_if_contains",
    needles: [...DEFAULT_PARAGRAPH_REMOVAL_ANCHORS],
  },
  {
    kind: "drop_paragraph_if_starts_with",
    prefixes: [...DEFAULT_IDENTITY_PREFIXES],
  },
  ...DEFAULT_TEXT_REPLACEMENTS.map<ReplaceTextOp>((r) => ({
    kind: "replace_text",
    match: r.match,
    replacement: r.replacement,
    allOccurrences: true,
  })),
  // Then prepend the SDK identity (becomes block[1] after billing prepend).
  {
    kind: "prepend_system_block",
    text: CLAUDE_AGENT_SDK_IDENTITY,
    idempotencyKey: "claude-agent-sdk-identity",
  },
  // Billing header always lands at block[0] — matches T4-200 fixture layout.
  {
    kind: "inject_billing_header",
    entrypoint: "sdk-cli",
    versionFormat: "ex-machina",
    cchAlgo: "sha256-first-user",
    buildRevision: CLAUDE_CODE_CLIENT_BUILD_REVISION,
  },
];

export const DEFAULT_CC_BRIDGE_TRANSFORMS_CONFIG: CcBridgeTransformsConfig = {
  enabled: true,
  pipeline: DEFAULT_CC_BRIDGE_PIPELINE,
};

// ────────────────────────────────────────────────────────────────────────────
// Billing header value
// ────────────────────────────────────────────────────────────────────────────

interface SystemBlock {
  type: string;
  text?: string;
  [key: string]: unknown;
}

interface MessageContentBlock {
  type?: string;
  text?: string;
  [key: string]: unknown;
}

interface Message {
  role?: string;
  content?: string | MessageContentBlock[];
  [key: string]: unknown;
}

/**
 * Pull the textual content of the first user message in the request.
 * Returns "" when no user message has text content.
 */
export function extractFirstUserMessageText(messages: Message[]): string {
  if (!Array.isArray(messages)) return "";

  for (const msg of messages) {
    if (msg?.role !== "user") continue;
    if (typeof msg.content === "string") return msg.content;
    if (Array.isArray(msg.content)) {
      for (const block of msg.content) {
        if (block?.type === "text" && typeof block.text === "string") {
          return block.text;
        }
      }
    }
  }
  return "";
}

function sha256Hex(input: string): string {
  return createHash("sha256").update(input, "utf8").digest("hex");
}

function pickCharsAtPositions(text: string, positions: readonly number[]): string {
  return positions.map((p) => (typeof text[p] === "string" ? text[p] : "\0")).join("");
}

/**
 * Compute the `cc_version` suffix per the ex-machina algorithm.
 *
 * `sha256(CCH_SALT + chars-at-CCH_POSITIONS(firstUserMessage) + version).slice(0, 3)`
 */
export function computeExMachinaVersionSuffix(firstUserText: string, version: string): string {
  const picks = pickCharsAtPositions(firstUserText, CCH_POSITIONS);
  return sha256Hex(`${CCH_SALT}${picks}${version}`).slice(0, 3);
}

/**
 * Compute the `cc_version` suffix per the OmniRoute native-OAuth algorithm:
 * sha256(YYYY-MM-DD + version).slice(0,3). Stable per UTC day.
 */
export function computeDaystampVersionSuffix(version: string, now: Date = new Date()): string {
  const dayStamp = now.toISOString().slice(0, 10);
  return sha256Hex(`${dayStamp}${version}`).slice(0, 3);
}

/**
 * Compute the `cch=` attestation value per ex-machina algorithm:
 * sha256(firstUserMessage).slice(0,5).
 */
export function computeCchSha256FirstUser(firstUserText: string): string {
  return sha256Hex(firstUserText).slice(0, 5);
}

interface BuildBillingHeaderOptions {
  entrypoint: string;
  versionFormat: "ex-machina" | "omniroute-daystamp";
  cchAlgo: "sha256-first-user" | "xxhash64-body" | "static-zero";
  version?: string;
  buildRevision?: string;
  now?: Date;
}

/**
 * Build the `x-anthropic-billing-header: …` string injected as system block[0].
 *
 * `xxhash64-body` and `static-zero` both emit `cch=00000` here because the
 * actual body-level CCH attestation is computed later by
 * `claudeCodeCCH.signRequestBody()` and replaces a 00000 placeholder in the
 * serialized JSON. ex-machina's `sha256-first-user` value lives in the
 * header itself.
 */
export function buildBillingHeaderValue(
  messages: Message[],
  options: BuildBillingHeaderOptions
): string {
  const version = options.version || DEFAULT_CLAUDE_CODE_VERSION;
  const firstUserText = extractFirstUserMessageText(messages);

  const suffix =
    options.buildRevision ??
    (options.versionFormat === "omniroute-daystamp"
      ? computeDaystampVersionSuffix(version, options.now)
      : computeExMachinaVersionSuffix(firstUserText, version));

  let cch: string;
  switch (options.cchAlgo) {
    case "sha256-first-user":
      cch = computeCchSha256FirstUser(firstUserText);
      break;
    case "xxhash64-body":
    case "static-zero":
    default:
      cch = "00000";
      break;
  }

  return `x-anthropic-billing-header: cc_version=${version}.${suffix}; cc_entrypoint=${options.entrypoint}; cch=${cch};`;
}

// ────────────────────────────────────────────────────────────────────────────
// Body shape helpers
// ────────────────────────────────────────────────────────────────────────────

interface RequestBody {
  system?: string | SystemBlock[];
  messages?: Message[];
  [key: string]: unknown;
}

function normalizeSystemToBlocks(system: unknown): SystemBlock[] {
  if (system === null || system === undefined) return [];
  if (typeof system === "string") {
    return system.length > 0 ? [{ type: "text", text: system }] : [];
  }
  if (Array.isArray(system)) {
    return system
      .filter((b): b is SystemBlock => !!b && typeof b === "object")
      .map((b) => ({ ...b }));
  }
  if (typeof system === "object") {
    const block = system as SystemBlock;
    return block && typeof block.text === "string" ? [{ ...block }] : [];
  }
  return [];
}

function isTextBlock(block: SystemBlock): block is SystemBlock & { text: string } {
  return block.type === "text" && typeof block.text === "string";
}

function containsString(haystack: string, needle: string, caseSensitive: boolean): boolean {
  if (caseSensitive) return haystack.includes(needle);
  return haystack.toLowerCase().includes(needle.toLowerCase());
}

function startsWithString(haystack: string, prefix: string, caseSensitive: boolean): boolean {
  if (caseSensitive) return haystack.startsWith(prefix);
  return haystack.toLowerCase().startsWith(prefix.toLowerCase());
}

// ────────────────────────────────────────────────────────────────────────────
// Op executors
// ────────────────────────────────────────────────────────────────────────────

function applyDropParagraphIfContains(
  blocks: SystemBlock[],
  op: DropParagraphIfContainsOp
): SystemBlock[] {
  const caseSensitive = op.caseSensitive !== false;
  const needles = op.needles || [];
  if (needles.length === 0) return blocks;

  return blocks.map((block) => {
    if (!isTextBlock(block)) return block;
    const paragraphs = block.text.split(/\n\n+/);
    const filtered = paragraphs.filter(
      (p) => !needles.some((n) => containsString(p, n, caseSensitive))
    );
    return { ...block, text: filtered.join("\n\n") };
  });
}

function applyDropParagraphIfStartsWith(
  blocks: SystemBlock[],
  op: DropParagraphIfStartsWithOp
): SystemBlock[] {
  const caseSensitive = op.caseSensitive !== false;
  const prefixes = op.prefixes || [];
  if (prefixes.length === 0) return blocks;

  return blocks.map((block) => {
    if (!isTextBlock(block)) return block;
    const paragraphs = block.text.split(/\n\n+/);
    const filtered = paragraphs.filter(
      (p) => !prefixes.some((prefix) => startsWithString(p.trimStart(), prefix, caseSensitive))
    );
    return { ...block, text: filtered.join("\n\n") };
  });
}

function applyReplaceText(blocks: SystemBlock[], op: ReplaceTextOp): SystemBlock[] {
  if (!op.match) return blocks;
  return blocks.map((block) => {
    if (!isTextBlock(block)) return block;
    if (!block.text.includes(op.match)) return block;
    let next = block.text;
    if (op.allOccurrences) {
      next = next.split(op.match).join(op.replacement);
    } else {
      next = next.replace(op.match, op.replacement);
    }
    return { ...block, text: next };
  });
}

function applyReplaceRegex(blocks: SystemBlock[], op: ReplaceRegexOp): SystemBlock[] {
  if (!op.pattern) return blocks;
  let regex: RegExp;
  try {
    regex = new RegExp(op.pattern, op.flags ?? "u");
  } catch {
    return blocks;
  }
  return blocks.map((block) => {
    if (!isTextBlock(block)) return block;
    return { ...block, text: block.text.replace(regex, op.replacement) };
  });
}

function applyDropBlockIfContains(blocks: SystemBlock[], op: DropBlockIfContainsOp): SystemBlock[] {
  const needles = op.needles || [];
  if (needles.length === 0) return blocks;
  return blocks.filter((block) => {
    if (!isTextBlock(block)) return true;
    return !needles.some((n) => block.text.includes(n));
  });
}

function applyPrependSystemBlock(blocks: SystemBlock[], op: PrependSystemBlockOp): SystemBlock[] {
  if (!op.text) return blocks;
  // Idempotency: skip if any text block already starts with idempotencyKey (when
  // set) or with op.text itself (default). Scans ALL blocks, not just the first.
  const prefix = op.idempotencyKey ?? op.text;
  const alreadyPresent = blocks.some((b) => isTextBlock(b) && b.text.startsWith(prefix));
  if (alreadyPresent) return blocks;
  return [{ type: "text", text: op.text }, ...blocks];
}

function applyAppendSystemBlock(blocks: SystemBlock[], op: AppendSystemBlockOp): SystemBlock[] {
  if (!op.text) return blocks;
  // Idempotency: skip if any text block already starts with idempotencyKey (when
  // set) or is an exact match of op.text (default). Scans ALL blocks.
  const prefix = op.idempotencyKey;
  const alreadyPresent = prefix
    ? blocks.some((b) => isTextBlock(b) && b.text.startsWith(prefix))
    : blocks.some((b) => isTextBlock(b) && b.text === op.text);
  if (alreadyPresent) return blocks;
  return [...blocks, { type: "text", text: op.text }];
}

function applyInjectBillingHeader(
  body: RequestBody,
  blocks: SystemBlock[],
  op: InjectBillingHeaderOp
): SystemBlock[] {
  // No user message → no billing header (ex-machina parity, transform.ts:340).
  const messages = Array.isArray(body.messages) ? body.messages : [];
  const hasUser = messages.some((m) => m?.role === "user");
  if (!hasUser) return blocks;

  const headerValue = buildBillingHeaderValue(messages, {
    entrypoint: op.entrypoint,
    versionFormat: op.versionFormat,
    cchAlgo: op.cchAlgo,
    version: op.version,
    buildRevision: op.buildRevision,
  });

  // Idempotency: replace any existing billing header block (ex-machina + native
  // OAuth path both rebuild on retry; see executors/base.ts issue #1712).
  const headerPrefix = "x-anthropic-billing-header:";
  const filtered = blocks.filter((b) => !(isTextBlock(b) && b.text.startsWith(headerPrefix)));
  return [{ type: "text", text: headerValue }, ...filtered];
}

// ────────────────────────────────────────────────────────────────────────────
// Pipeline executor
// ────────────────────────────────────────────────────────────────────────────

export interface ApplyPipelineResult {
  body: RequestBody;
  appliedOpKinds: string[];
}

/**
 * Run the configured transform pipeline against a request body.
 *
 * The body is mutated in place (its `system` field is replaced); returned for
 * chaining. `appliedOpKinds` lists the ops that ran (omitting no-ops when
 * config is disabled). When `config.enabled === false`, the body is returned
 * unchanged and `appliedOpKinds` is empty.
 */
export function applyCcBridgeTransformPipeline(
  body: RequestBody,
  config: CcBridgeTransformsConfig = getCcBridgeTransformsConfig()
): ApplyPipelineResult {
  if (!body || typeof body !== "object") {
    return { body, appliedOpKinds: [] };
  }
  if (!config.enabled || !Array.isArray(config.pipeline) || config.pipeline.length === 0) {
    return { body, appliedOpKinds: [] };
  }

  let blocks = normalizeSystemToBlocks(body.system);
  const appliedOpKinds: string[] = [];

  for (const op of config.pipeline) {
    switch (op.kind) {
      case "drop_paragraph_if_contains":
        blocks = applyDropParagraphIfContains(blocks, op);
        break;
      case "drop_paragraph_if_starts_with":
        blocks = applyDropParagraphIfStartsWith(blocks, op);
        break;
      case "replace_text":
        blocks = applyReplaceText(blocks, op);
        break;
      case "replace_regex":
        blocks = applyReplaceRegex(blocks, op);
        break;
      case "drop_block_if_contains":
        blocks = applyDropBlockIfContains(blocks, op);
        break;
      case "prepend_system_block":
        blocks = applyPrependSystemBlock(blocks, op);
        break;
      case "append_system_block":
        blocks = applyAppendSystemBlock(blocks, op);
        break;
      case "inject_billing_header":
        blocks = applyInjectBillingHeader(body, blocks, op);
        break;
      default: {
        // Unknown op kind — skip silently to keep forward compatibility.
        continue;
      }
    }
    appliedOpKinds.push(op.kind);
  }

  // Drop empty text blocks left behind by paragraph removal (matches
  // ex-machina sanitizeSystemText trim semantics).
  blocks = blocks.filter((b) => !isTextBlock(b) || b.text.length > 0);

  body.system = blocks;
  return { body, appliedOpKinds };
}

// ────────────────────────────────────────────────────────────────────────────
// Runtime singleton (mirrors cliFingerprints `_cliCompatProviders` pattern).
// ────────────────────────────────────────────────────────────────────────────

let _runtimeConfig: CcBridgeTransformsConfig = DEFAULT_CC_BRIDGE_TRANSFORMS_CONFIG;

/**
 * Replace the active CC bridge transforms config. Called from
 * `runtimeSettings.applyCcBridgeTransformsSection()` when the Settings UI
 * saves a new pipeline.
 */
export function setCcBridgeTransformsConfig(config: CcBridgeTransformsConfig | null): void {
  if (!config) {
    _runtimeConfig = DEFAULT_CC_BRIDGE_TRANSFORMS_CONFIG;
    return;
  }
  _runtimeConfig = {
    enabled: config.enabled !== false,
    pipeline: Array.isArray(config.pipeline) ? config.pipeline : DEFAULT_CC_BRIDGE_PIPELINE,
  };
}

/**
 * Read the currently active config (defaults to DEFAULT_CC_BRIDGE_PIPELINE).
 */
export function getCcBridgeTransformsConfig(): CcBridgeTransformsConfig {
  return _runtimeConfig;
}

/**
 * Reset to defaults — exposed for tests and the Settings UI "Reset" button.
 */
export function resetCcBridgeTransformsConfig(): void {
  _runtimeConfig = DEFAULT_CC_BRIDGE_TRANSFORMS_CONFIG;
}

/**
 * OpenAI-format media parts reach the Claude-Code-compatible bridge
 * untranslated when the source client speaks OpenAI (chatCore skips the
 * OpenAI→Claude translator for CC-compatible providers), so `image_url` /
 * AI SDK `image` / Chat Completions `file` parts must become Claude blocks
 * before dispatch or the upstream silently ignores them (#7777).
 * Claude-native blocks (`image`/`document` carrying `source`) are left for
 * the caller to pass through unchanged.
 */

const DATA_URL_BASE64_PATTERN = /^data:([^;]+);base64,(.+)$/;

/** Returns a Claude block for an OpenAI media part, or null for non-media blocks. */
export function convertOpenAiMediaBlock(
  record: Record<string, unknown>
): Record<string, unknown> | null {
  if (record.type === "image_url") {
    const rawUrl =
      typeof record.image_url === "string" ? record.image_url : readRecord(record.image_url)?.url;
    return claudeImageBlockFromUrl(rawUrl);
  }

  if (record.type === "image" && !readRecord(record.source) && typeof record.image === "string") {
    return claudeImageBlockFromUrl(record.image);
  }

  if (record.type === "file") {
    const file = readRecord(record.file);
    const fileData = toNonEmptyString(file?.file_data) || toNonEmptyString(file?.data);
    if (!fileData) return null;
    const title = toNonEmptyString(file?.filename);
    const match = fileData.match(DATA_URL_BASE64_PATTERN);
    if (match) {
      const mediaType = match[1];
      const source = { type: "base64", media_type: mediaType, data: match[2] };
      if (mediaType === "application/pdf") {
        return { type: "document", source, ...(title ? { title } : {}) };
      }
      if (mediaType.startsWith("image/")) {
        return { type: "image", source };
      }
      return null;
    }
    if (/^https?:\/\//i.test(fileData)) {
      return {
        type: "document",
        source: { type: "url", url: fileData },
        ...(title ? { title } : {}),
      };
    }
    return null;
  }

  return null;
}

/**
 * Collects the Claude-shaped media blocks of a message's content array:
 * OpenAI media parts are converted, Claude-native `image`/`document` blocks
 * are cloned through as-is, everything else is ignored.
 */
export function collectClaudeMediaBlocks(content: unknown): Array<Record<string, unknown>> {
  if (!Array.isArray(content)) return [];

  const blocks: Array<Record<string, unknown>> = [];
  for (const part of content) {
    const record = readRecord(cloneValue(part));
    if (!record) continue;
    const media = convertOpenAiMediaBlock(record);
    if (media) {
      blocks.push(media);
      continue;
    }
    if ((record.type === "image" || record.type === "document") && readRecord(record.source)) {
      blocks.push(record);
    }
  }
  return blocks;
}

function claudeImageBlockFromUrl(rawUrl: unknown): Record<string, unknown> | null {
  const url = toNonEmptyString(rawUrl);
  if (!url) return null;
  const match = url.match(DATA_URL_BASE64_PATTERN);
  if (match) {
    return { type: "image", source: { type: "base64", media_type: match[1], data: match[2] } };
  }
  return { type: "image", source: { type: "url", url } };
}

function readRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function toNonEmptyString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function cloneValue<T>(value: T): T {
  if (typeof structuredClone === "function") {
    return structuredClone(value);
  }
  return JSON.parse(JSON.stringify(value)) as T;
}

/**
 * Context Manager — Phase 4
 *
 * Pre-flight context compression to prevent "prompt too long" errors.
 * 3 layers: trim tool messages, compress structured thinking, aggressive purification.
 */

import { REGISTRY } from "../config/providerRegistry.ts";
import { getModelContextLimit } from "../../src/lib/modelCapabilities.ts";
import { parseModel } from "./model.ts";
import { jsonLength } from "../utils/jsonSize.ts";

// Default token limits per provider (fallbacks when not in registry)
const DEFAULT_LIMITS: Record<string, number> = {
  claude: 200000,
  openai: 128000,
  gemini: 1000000,
  codex: 400000,
  // HyperAgent Claude-family agents (fable/opus/sonnet) — 1M default; was falling
  // through to 128k and blocking normal agentic tool loops with huge catalogs.
  hyperagent: 1_000_000,
  ha: 1_000_000,
  default: 128000,
};

// Environment variable overrides (highest priority)
function getEnvOverride(provider: string): number | null {
  const envKey = `CONTEXT_LENGTH_${provider.toUpperCase().replace(/[^A-Z0-9]/g, "_")}`;
  const envValue = process.env[envKey];
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  // Global override
  const globalValue = process.env.CONTEXT_LENGTH_DEFAULT;
  if (globalValue) {
    const parsed = parseInt(globalValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return null;
}

// Reserve tokens override from environment variable
function getReserveTokensOverride(): number | null {
  const envValue = process.env.CONTEXT_RESERVE_TOKENS;
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return null;
}

// How many of the newest inline images to keep when pruning older ones (#8560).
function getKeepLatestImagesOverride(): number | null {
  const envValue = process.env.CONTEXT_KEEP_LATEST_IMAGES;
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed >= 0) return parsed;
  }
  return null;
}

const DEFAULT_KEEP_LATEST_IMAGES = 2;
const IMAGE_REMOVED_PLACEHOLDER = "[Earlier image removed to fit context window]";

// Rough chars-per-token ratio for quick estimation
const CHARS_PER_TOKEN = 4;

// Bounded per-image token budget used in place of measuring the raw base64
// payload as text. In line with the owner's PoC (~1052 total for prompt +
// 1 image) and litellm's calculate_img_tokens() default-count fast-path —
// see #8368 research notes.
const IMAGE_TOKEN_ESTIMATE = 1200;

// Matches inline base64 data URLs, e.g. "data:image/png;base64,AAAA...".
// Deliberately scoped to `data:image/...;base64,` so remote (http/https)
// URLs and generic long base64 text strings stay on the text-estimation path.
const INLINE_BASE64_IMAGE_RE = /^data:image\/[a-zA-Z0-9.+-]+;base64,/;

function isInlineBase64ImageUrl(value: unknown): boolean {
  return typeof value === "string" && INLINE_BASE64_IMAGE_RE.test(value);
}

// OpenAI chat.completions: { type: 'image_url', image_url: { url: 'data:...' } | 'data:...' }
function matchesOpenAIImageUrlShape(node: Record<string, unknown>): boolean {
  const imageUrl = node.image_url;
  if (isInlineBase64ImageUrl(imageUrl)) return true;
  return (
    !!imageUrl &&
    typeof imageUrl === "object" &&
    isInlineBase64ImageUrl((imageUrl as Record<string, unknown>).url)
  );
}

// AI SDK: { type: 'image', image: 'data:...' } (also covers Responses API's
// { type: 'input_image', image_url: 'data:...' } via matchesOpenAIImageUrlShape above).
function matchesAiSdkImageShape(node: Record<string, unknown>): boolean {
  return node.type === "image" && isInlineBase64ImageUrl(node.image);
}

// Claude: { type: 'image', source: { type: 'base64', data: '...' } }
function matchesClaudeSourceShape(node: Record<string, unknown>): boolean {
  if (node.type !== "image") return false;
  const source = node.source;
  if (!source || typeof source !== "object") return false;
  const src = source as Record<string, unknown>;
  return src.type === "base64" && typeof src.data === "string";
}

// Gemini: { inlineData: { data: '...' } } | { inline_data: { data: '...' } }
function matchesGeminiInlineDataShape(node: Record<string, unknown>): boolean {
  const inlineData = node.inlineData ?? node.inline_data;
  if (!inlineData || typeof inlineData !== "object") return false;
  return typeof (inlineData as Record<string, unknown>).data === "string";
}

/**
 * Detect the 5 documented inline-base64 image content-block shapes (see the
 * shape-specific matchers above).
 */
export function isInlineBase64ImageBlock(node: Record<string, unknown>): boolean {
  return (
    matchesOpenAIImageUrlShape(node) ||
    matchesAiSdkImageShape(node) ||
    matchesClaudeSourceShape(node) ||
    matchesGeminiInlineDataShape(node)
  );
}

function replaceImageBlockWithPlaceholder(block: Record<string, unknown>): Record<string, unknown> {
  // Responses API parts use input_text / input_image — keep that family so restore
  // does not rewrite a chat-completions-shaped part into a Responses input item.
  if (block.type === "input_image") {
    return { type: "input_text", text: IMAGE_REMOVED_PLACEHOLDER };
  }
  if (block.inlineData || block.inline_data) {
    return { text: IMAGE_REMOVED_PLACEHOLDER };
  }
  return { type: "text", text: IMAGE_REMOVED_PLACEHOLDER };
}

/**
 * Replace oldest inline base64 image blocks with short text placeholders while
 * keeping the newest `keepLatest` images intact. Vision models still receive
 * recent screenshots; older ones are dropped so multi-turn Codex/Responses
 * sessions can fit the concrete input cap (#8560).
 */
export function pruneOlderInlineImages(
  messages: Record<string, unknown>[],
  options: { keepLatest?: number; targetTokens?: number } = {}
): { messages: Record<string, unknown>[]; pruned: number } {
  const keepLatest =
    options.keepLatest ?? getKeepLatestImagesOverride() ?? DEFAULT_KEEP_LATEST_IMAGES;
  const targetTokens = options.targetTokens;

  const locations: Array<{ messageIndex: number; contentIndex: number }> = [];
  for (let messageIndex = 0; messageIndex < messages.length; messageIndex++) {
    const content = messages[messageIndex]?.content;
    if (!Array.isArray(content)) continue;
    for (let contentIndex = 0; contentIndex < content.length; contentIndex++) {
      const part = content[contentIndex];
      if (
        part &&
        typeof part === "object" &&
        !Array.isArray(part) &&
        isInlineBase64ImageBlock(part as Record<string, unknown>)
      ) {
        locations.push({ messageIndex, contentIndex });
      }
    }
  }

  if (locations.length <= keepLatest) {
    return { messages, pruned: 0 };
  }

  const prunable = locations.slice(0, Math.max(0, locations.length - keepLatest));
  const next = messages.map((message) => {
    if (!Array.isArray(message.content)) return message;
    return { ...message, content: [...message.content] };
  });
  let pruned = 0;

  for (const location of prunable) {
    if (targetTokens != null && estimateTokens(next) <= targetTokens) break;
    const content = next[location.messageIndex].content as unknown[];
    const block = content[location.contentIndex] as Record<string, unknown>;
    content[location.contentIndex] = replaceImageBlockWithPlaceholder(block);
    pruned += 1;
  }

  return { messages: next, pruned };
}

/**
 * Recursively walk a structured node, replacing every recognized inline
 * base64 image block with a short placeholder (so its bulk is excluded from
 * the char-count pass below) while accumulating a bounded per-image token
 * cost. Returns the accumulated image token cost; the caller measures the
 * placeholder-substituted structure with the normal char/4 heuristic.
 *
 * Non-image content (including remote image URLs and generic base64 text)
 * is left untouched and continues to flow through the text-estimation path.
 */
function extractImageTokens(node: unknown, seen: Set<unknown>): { node: unknown; tokens: number } {
  if (node === null || typeof node !== "object") {
    return { node, tokens: 0 };
  }
  // Guard against cycles in structured request bodies.
  if (seen.has(node)) return { node, tokens: 0 };
  seen.add(node);

  if (Array.isArray(node)) {
    let tokens = 0;
    const out = node.map((item) => {
      const record =
        item && typeof item === "object" && !Array.isArray(item)
          ? (item as Record<string, unknown>)
          : null;
      if (record && isInlineBase64ImageBlock(record)) {
        tokens += IMAGE_TOKEN_ESTIMATE;
        return { __image_token_estimate__: IMAGE_TOKEN_ESTIMATE };
      }
      const result = extractImageTokens(item, seen);
      tokens += result.tokens;
      return result.node;
    });
    return { node: out, tokens };
  }

  const record = node as Record<string, unknown>;
  if (isInlineBase64ImageBlock(record)) {
    return {
      node: { __image_token_estimate__: IMAGE_TOKEN_ESTIMATE },
      tokens: IMAGE_TOKEN_ESTIMATE,
    };
  }

  let tokens = 0;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(record)) {
    const result = extractImageTokens(value, seen);
    out[key] = result.node;
    tokens += result.tokens;
  }
  return { node: out, tokens };
}

/**
 * Estimate token count from text length.
 *
 * Structured input is first walked for inline base64 image blocks (#8368):
 * each recognized image block is substituted with a bounded per-image token
 * budget instead of measuring its base64 payload as raw text, then the
 * remainder of the structure is measured normally via the char/4 heuristic.
 */
export function estimateTokens(text: string | object | null | undefined): number {
  if (!text) return 0;
  if (typeof text === "string") {
    return Math.ceil(text.length / CHARS_PER_TOKEN);
  }
  const { node, tokens: imageTokens } = extractImageTokens(text, new Set());
  // #7847: count the serialized length instead of building the string. Only `.length` was ever
  // used, and on a multi-megabyte agent body that string is a pure transient allocation.
  // jsonLength is exact (property-tested against JSON.stringify), so the estimate is unchanged.
  return Math.ceil(jsonLength(node) / CHARS_PER_TOKEN) + imageTokens;
}

/**
 * Get token limit for a provider/model combination
 * Priority: Env override > models.dev DB > Registry defaultContextLength > DEFAULT_LIMITS
 */
export function getTokenLimit(provider: string, model: string | null = null): number {
  return resolveTokenLimit(provider, model).limit;
}

/**
 * Resolve a combo target's token limit without crashing when `parseModel(modelStr)`
 * returns `provider: null` (model id with no `provider/` prefix).
 *
 * `ResolvedComboTarget.provider` is populated independently of `modelStr`, so fall
 * back to it before calling `getTokenLimit` (#8716).
 */
export function getComboTargetTokenLimit(options: {
  modelStr?: string | null;
  provider?: string | null;
  parsedProvider?: string | null;
  parsedModel?: string | null;
  targetProvider?: string | null;
}): number {
  let parsedProvider = options.parsedProvider;
  let parsedModel = options.parsedModel;
  if (
    (parsedProvider === undefined || parsedModel === undefined) &&
    Object.prototype.hasOwnProperty.call(options, "modelStr")
  ) {
    const parsed = parseModel(options.modelStr);
    if (parsedProvider === undefined) parsedProvider = parsed.provider;
    if (parsedModel === undefined) parsedModel = parsed.model;
  }
  const provider = parsedProvider ?? options.targetProvider ?? options.provider ?? "unknown";
  return getTokenLimit(provider, parsedModel ?? null);
}

/**
 * Same chain as getTokenLimit, but also reports whether the limit came from
 * a provider/model-specific source (env override, synced DB, registry,
 * name heuristic, curated per-provider default) or only from the generic
 * catch-all default.
 */
function resolveTokenLimit(
  provider: string,
  model: string | null = null
): { limit: number; specific: boolean } {
  // 1. Check environment variable override first
  const envOverride = getEnvOverride(provider);
  if (envOverride) return { limit: envOverride, specific: true };

  const lowerModel = (model || "").toLowerCase();

  // 2. Check models.dev synced DB for per-model context limit
  if (model) {
    const dbLimit = getModelContextLimit(provider, model);
    if (dbLimit && dbLimit > 0) return { limit: dbLimit, specific: true };
  }

  // 3. Check registry for provider default
  const registryEntry = REGISTRY[provider];
  if (registryEntry?.defaultContextLength) {
    return { limit: registryEntry.defaultContextLength, specific: true };
  }

  // 4. Check if model name hints at a known limit
  if (model) {
    if (lowerModel.includes("claude")) return { limit: DEFAULT_LIMITS.claude, specific: true };
    if (lowerModel.includes("gemini")) return { limit: DEFAULT_LIMITS.gemini, specific: true };
    if (
      lowerModel.includes("gpt") ||
      lowerModel.includes("o1") ||
      lowerModel.includes("o3") ||
      lowerModel.includes("o4") ||
      lowerModel.includes("codex")
    )
      return { limit: DEFAULT_LIMITS.codex, specific: true };
  }

  // 5. Fallback to DEFAULT_LIMITS or default
  if (DEFAULT_LIMITS[provider]) return { limit: DEFAULT_LIMITS[provider], specific: true };
  return { limit: DEFAULT_LIMITS.default, specific: false };
}

/**
 * Resolve the context limit to use for proactive compression of a COMBO
 * request.
 *
 * chatCore always executes with the CONCRETE target's provider/model
 * (handleSingleModel resolves the target before delegating), so the
 * executing target's own limit is authoritative. Using min(...allTargets)
 * here — the previous behavior — compressed at the smallest sibling's
 * window even when running on the largest target, destructively purging
 * history long before the real window filled ("agent keeps forgetting").
 *
 * min(...comboTargetLimits) is kept only as a defensive fallback for the
 * case where the current provider/model resolves no specific limit at all.
 */
export function resolveComboContextLimit(options: {
  provider: string;
  model: string | null;
  comboTargetLimits: number[];
}): { limit: number; source: "target" | "combo-min" | "fallback" } {
  const own = resolveTokenLimit(options.provider, options.model ?? null);
  if (own.specific) {
    return { limit: own.limit, source: "target" };
  }
  const knownTargets = (options.comboTargetLimits || []).filter(
    (value) => Number.isFinite(value) && value > 0
  );
  if (knownTargets.length > 0) {
    return { limit: Math.min(...knownTargets), source: "combo-min" };
  }
  return { limit: own.limit, source: "fallback" };
}

/**
 * Apply context compression to request body.
 * Operates in layers of increasing aggressiveness:
 *
 * Layer 1: Trim tool_result messages (truncate long outputs)
 * Layer 1.5: Prune older inline images (keep latest N — #8560)
 * Layer 2: Compress structured thinking blocks (remove from history, keep last)
 * Layer 3: Aggressive purification (drop old messages until fitting)
 *
 * Callers with OpenAI Responses `input[]` (Codex) must adapt via
 * `adaptBodyForCompression` before calling and `restore()` after — this helper
 * is message-centric by design.
 *
 * @param {object} body - Request body with messages[]
 * @param {object} options - { provider?, model?, maxTokens?, reserveTokens?, keepLatestImages? }
 * @returns {{ body: object, compressed: boolean, stats: object }}
 */
export function compressContext(
  body: Record<string, unknown> | null | undefined,
  options: {
    provider?: string;
    model?: string;
    maxTokens?: number;
    reserveTokens?: number;
    keepLatestImages?: number;
  } = {}
) {
  if (!body || !body.messages || !Array.isArray(body.messages)) {
    return { body, compressed: false, stats: {} };
  }

  const provider = options.provider || "default";
  const maxTokens =
    options.maxTokens || getTokenLimit(provider, (body.model as string) || options.model || null);
  const defaultReserveTokens = Math.min(16000, Math.max(256, Math.floor(maxTokens * 0.15)));
  const reserveTokens = Math.min(
    options.reserveTokens ?? getReserveTokensOverride() ?? defaultReserveTokens,
    Math.max(0, maxTokens - 1)
  );
  const targetTokens = Math.max(0, maxTokens - reserveTokens);

  let messages = [...(body.messages as Record<string, unknown>[])];
  // #8594: pass the structured messages array directly — estimateTokens walks it for
  // inline base64 image blocks (#8368) and substitutes a bounded per-image estimate.
  // JSON.stringify()-ing first forces the char/4 text path and mis-measures a ~500KB
  // image as ~125k tokens, triggering needless compression / context loss.
  let currentTokens = estimateTokens(messages);
  const stats = { original: currentTokens, layers: [] as { name: string; tokens: number }[] };

  // Already fits
  if (currentTokens <= targetTokens) {
    return { body, compressed: false, stats: { original: currentTokens, final: currentTokens } };
  }

  // Layer 1: Trim tool_result/tool messages
  messages = trimToolMessages(messages, 2000); // Max 2000 chars per tool result
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "trim_tools", tokens: currentTokens });

  if (currentTokens <= targetTokens) {
    return {
      body: { ...body, messages },
      compressed: true,
      stats: { ...stats, final: currentTokens },
    };
  }

  // Layer 1.5: Drop oldest inline images while keeping the newest ones (#8560).
  const imagePrune = pruneOlderInlineImages(messages, {
    keepLatest: options.keepLatestImages,
    targetTokens,
  });
  if (imagePrune.pruned > 0) {
    messages = imagePrune.messages;
    currentTokens = estimateTokens(messages);
    stats.layers.push({ name: "prune_images", tokens: currentTokens });
    if (currentTokens <= targetTokens) {
      return {
        body: { ...body, messages },
        compressed: true,
        stats: { ...stats, final: currentTokens },
      };
    }
  }

  // Layer 2: Compress structured thinking blocks (remove from non-last assistant messages)
  messages = compressThinking(messages);
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "compress_thinking", tokens: currentTokens });

  if (currentTokens <= targetTokens) {
    return {
      body: { ...body, messages },
      compressed: true,
      stats: { ...stats, final: currentTokens },
    };
  }

  // Layer 3: Aggressive purification — drop oldest messages keeping system + last N pairs
  messages = purifyHistory(messages, targetTokens);
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "purify_history", tokens: currentTokens });

  return {
    body: { ...body, messages },
    compressed: true,
    stats: { ...stats, final: currentTokens },
  };
}

// ─── Layer 1: Trim Tool Messages ────────────────────────────────────────────

function trimToolMessages(messages: Record<string, unknown>[], maxChars: number) {
  return messages.map((msg) => {
    if (msg.role === "tool" && typeof msg.content === "string" && msg.content.length > maxChars) {
      return {
        ...msg,
        content: msg.content.slice(0, maxChars) + "\n... [truncated]",
      };
    }
    // Handle array content (Claude format with tool_result blocks)
    if (msg.role === "user" && Array.isArray(msg.content)) {
      return {
        ...msg,
        content: msg.content.map((block) => {
          if (
            block.type === "tool_result" &&
            typeof block.content === "string" &&
            block.content.length > maxChars
          ) {
            return { ...block, content: block.content.slice(0, maxChars) + "\n... [truncated]" };
          }
          return block;
        }),
      };
    }
    return msg;
  });
}

// ─── Layer 2: Compress Structured Thinking Blocks ───────────────────────────

function compressThinking(messages: Record<string, unknown>[]) {
  // Find last assistant message index
  let lastAssistantIdx = -1;
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === "assistant") {
      lastAssistantIdx = i;
      break;
    }
  }

  return messages.map((msg, i) => {
    if (msg.role !== "assistant") return msg;
    if (i === lastAssistantIdx) return msg; // Keep thinking in last assistant msg

    // Remove thinking blocks from content array
    if (Array.isArray(msg.content)) {
      const filtered = msg.content.filter((block) => block.type !== "thinking");
      if (filtered.length === 0) {
        return { ...msg, content: "[thinking compressed]" };
      }
      return { ...msg, content: filtered };
    }

    return msg;
  });
}

// ─── Layer 3: Aggressive Purification ───────────────────────────────────────

function purifyHistory(messages: Record<string, unknown>[], targetTokens: number) {
  // Keep system message(s) and the last N message pairs
  const system = messages.filter((m) => m.role === "system" || m.role === "developer");
  const nonSystem = messages.filter((m) => m.role !== "system" && m.role !== "developer");

  // Binary search for how many messages to keep from the end
  let keep = nonSystem.length;
  while (keep > 2) {
    let candidate = [...system, ...nonSystem.slice(-keep)];
    candidate = fixToolPairs(candidate);
    candidate = fixToolAdjacency(candidate);
    // Re-run pair fix: fixToolAdjacency may have stripped tool_use blocks, leaving
    // orphan tool_results that Claude rejects ("tool_result without preceding tool_use").
    candidate = fixToolPairs(candidate);
    candidate = stripTrailingAssistantOrphanToolUse(candidate);
    // #8594: measure the candidate structure directly so image-bearing turns are not
    // over-counted and pruned during the binary search.
    const tokens = estimateTokens(candidate);
    if (tokens <= targetTokens) break;
    keep = Math.max(2, Math.floor(keep * 0.7)); // Drop 30% each iteration
  }

  let result = [...system, ...nonSystem.slice(-keep)];
  result = fixToolPairs(result);
  result = fixToolAdjacency(result);
  // Re-run pair fix to drop any tool_result whose matching tool_use was removed by
  // fixToolAdjacency (discussion #2410 — orphan tool_result -> upstream 400).
  result = fixToolPairs(result);
  result = stripTrailingAssistantOrphanToolUse(result);

  // Add summary of dropped messages
  if (keep < nonSystem.length) {
    const dropped = nonSystem.length - keep;
    result.splice(system.length, 0, {
      role: "system",
      content: `[Context compressed: ${dropped} earlier messages removed to fit context window]`,
    });
  }

  return result;
}

/**
 * Remove orphaned tool_result messages whose preceding tool_use was dropped.
 * Also removes orphaned tool_use messages without a corresponding tool_result.
 *
 * When purifyHistory() drops oldest messages, it can split tool_use/tool_result
 * pairs — keeping the tool_result but dropping the tool_use that initiated it.
 * This causes upstream providers to reject the request with errors like:
 *   - Claude: "tool_result message must be preceded by a tool_use message"
 *   - OpenAI: "Invalid message format"
 *   - Gemini: "Function response without function call"
 */
export function fixToolPairs(messages: Record<string, unknown>[]) {
  // Pass 1: Collect all tool_result IDs from user/tool messages
  const toolResultIds = new Set();
  for (const msg of messages) {
    if (msg.role === "tool" && msg.tool_call_id) {
      toolResultIds.add(msg.tool_call_id);
    }
    if (msg.role === "user" && Array.isArray(msg.content)) {
      for (const block of msg.content) {
        if (block.type === "tool_result" && block.tool_use_id) {
          toolResultIds.add(block.tool_use_id);
        }
      }
    }
  }

  // Pass 2: Filter assistant messages to remove tool_use without tool_result
  // (Exception: keep tool_use if the assistant message is the last message)
  const isLastMessage = (idx: number) => idx === messages.length - 1;
  const filteredMessages = messages.map((msg, idx) => {
    if (msg.role === "assistant" && !isLastMessage(idx)) {
      let modified = false;
      const newMsg = { ...msg };

      if (Array.isArray(newMsg.tool_calls)) {
        const filteredToolCalls = newMsg.tool_calls.filter(
          (tc: Record<string, unknown>) => !tc.id || toolResultIds.has(tc.id)
        );
        if (filteredToolCalls.length !== newMsg.tool_calls.length) {
          newMsg.tool_calls = filteredToolCalls;
          modified = true;
        }
      }

      if (Array.isArray(newMsg.content)) {
        const filteredContent = newMsg.content.filter(
          (block: Record<string, unknown>) =>
            block.type !== "tool_use" || !block.id || toolResultIds.has(block.id)
        );
        if (filteredContent.length !== newMsg.content.length) {
          newMsg.content = filteredContent;
          modified = true;
        }
      }

      return modified ? newMsg : msg;
    }
    return msg;
  });

  // Pass 3: Collect all remaining tool_use IDs from assistant messages
  const toolCallIds = new Set();
  for (const msg of filteredMessages) {
    if (msg.role === "assistant") {
      if (Array.isArray(msg.tool_calls)) {
        for (const tc of msg.tool_calls) {
          if (tc.id) toolCallIds.add(tc.id);
        }
      }
      if (Array.isArray(msg.content)) {
        for (const block of msg.content) {
          if (block.type === "tool_use" && block.id) {
            toolCallIds.add(block.id);
          }
        }
      }
    }
  }

  // Pass 4: Filter user/tool messages to remove tool_result without tool_use
  return filteredMessages
    .map((msg) => {
      if (msg.role === "tool" && msg.tool_call_id) {
        if (!toolCallIds.has(msg.tool_call_id)) return null;
      }

      if (msg.role === "user" && Array.isArray(msg.content)) {
        const filteredContent = msg.content.filter(
          (block: Record<string, unknown>) =>
            block.type !== "tool_result" || !block.tool_use_id || toolCallIds.has(block.tool_use_id)
        );
        if (filteredContent.length !== msg.content.length) {
          if (filteredContent.length === 0) return null;
          return { ...msg, content: filteredContent };
        }
      }

      // Drop assistant messages if their content AND tool_calls became empty
      if (msg.role === "assistant") {
        const hasContent =
          typeof msg.content === "string"
            ? msg.content.trim().length > 0
            : Array.isArray(msg.content) && msg.content.length > 0;
        const hasToolCalls = Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0;
        if (!hasContent && !hasToolCalls) {
          return null;
        }
      }

      return msg;
    })
    .filter(Boolean) as Record<string, unknown>[];
}

/**
 * Adjacency guard: Claude requires `tool_result` in the IMMEDIATELY NEXT
 * message after `tool_use`, not just somewhere later in the array.
 *
 * `fixToolPairs` checks global ID presence but not adjacency. This function
 * runs after `fixToolPairs` and removes `tool_use` blocks from assistant
 * messages where the next message does not contain a matching `tool_result`.
 */
export function fixToolAdjacency(messages: Record<string, unknown>[]): Record<string, unknown>[] {
  if (messages.length <= 1) return messages;

  const result: Record<string, unknown>[] = [];

  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    const nextMsg = messages[i + 1];

    if (msg.role !== "assistant" || !nextMsg) {
      result.push(msg);
      continue;
    }

    // Collect tool_result IDs from the NEXT message only
    const nextToolResultIds = new Set<string>();
    if (nextMsg.role === "tool" && nextMsg.tool_call_id) {
      nextToolResultIds.add(String(nextMsg.tool_call_id));
    }
    if (nextMsg.role === "user" && Array.isArray(nextMsg.content)) {
      for (const block of nextMsg.content as Record<string, unknown>[]) {
        if (block.type === "tool_result" && block.tool_use_id) {
          nextToolResultIds.add(String(block.tool_use_id));
        }
      }
    }

    let modified = false;
    const newMsg: Record<string, unknown> = { ...msg };

    // Filter tool_use blocks in content array (Claude format)
    if (Array.isArray(newMsg.content)) {
      const filteredContent = (newMsg.content as Record<string, unknown>[]).filter(
        (block) => block.type !== "tool_use" || !block.id || nextToolResultIds.has(String(block.id))
      );
      if (filteredContent.length !== (newMsg.content as unknown[]).length) {
        newMsg.content = filteredContent;
        modified = true;
      }
    }

    // Filter tool_calls array (OpenAI format) — independently of content
    if (Array.isArray(newMsg.tool_calls)) {
      const filteredToolCalls = (newMsg.tool_calls as Record<string, unknown>[]).filter(
        (tc: Record<string, unknown>) => !tc.id || nextToolResultIds.has(String(tc.id))
      );
      if (filteredToolCalls.length !== (newMsg.tool_calls as unknown[]).length) {
        newMsg.tool_calls = filteredToolCalls;
        modified = true;
      }
    }

    if (modified) {
      // Drop assistant message if it became empty
      const hasContent =
        typeof newMsg.content === "string"
          ? (newMsg.content as string).trim().length > 0
          : Array.isArray(newMsg.content) && (newMsg.content as unknown[]).length > 0;
      const hasToolCalls = Array.isArray(newMsg.tool_calls) && newMsg.tool_calls.length > 0;
      if (!hasContent && !hasToolCalls) continue;
      result.push(newMsg);
    } else {
      result.push(msg);
    }
  }

  return result;
}

/**
 * Upstream-send guard: after `fixToolPairs`, strip a trailing assistant
 * message whose only/remaining content is an orphan `tool_use` block.
 *
 * `fixToolPairs` intentionally preserves a final-message `tool_use` because
 * during context pruning the client is still waiting on the matching
 * `tool_result` — dropping it there would lose state. But on the
 * upstream-send path the request body must end on a user turn; a trailing
 * `assistant(tool_use)` triggers the same Anthropic 400 the guard is
 * trying to prevent:
 *   messages.N: `tool_use` ids were found without `tool_result` blocks
 *   immediately after: toolu_...
 *
 * Behavior:
 *  - If the last message is `assistant` and contains any `tool_use` block,
 *    those blocks are removed.
 *  - If removal leaves the message with no content / tool_calls at all, the
 *    message itself is dropped.
 *  - Idempotent on clean histories (trailing user, trailing assistant with
 *    only text/thinking, etc.).
 */
export function stripTrailingAssistantOrphanToolUse(
  messages: Record<string, unknown>[]
): Record<string, unknown>[] {
  if (!Array.isArray(messages) || messages.length === 0) return messages;

  const lastIdx = messages.length - 1;
  const last = messages[lastIdx];
  if (!last || last.role !== "assistant") return messages;

  let modified = false;
  const newLast: Record<string, unknown> = { ...last };

  if (Array.isArray(newLast.tool_calls)) {
    const filteredCalls = (newLast.tool_calls as Record<string, unknown>[]).filter(
      () => false // remove all trailing tool_calls (none can be paired by definition)
    );
    if (filteredCalls.length !== (newLast.tool_calls as unknown[]).length) {
      newLast.tool_calls = filteredCalls;
      modified = true;
    }
  }

  if (Array.isArray(newLast.content)) {
    const filteredContent = (newLast.content as Record<string, unknown>[]).filter(
      (block) => block.type !== "tool_use"
    );
    if (filteredContent.length !== (newLast.content as unknown[]).length) {
      newLast.content = filteredContent;
      modified = true;
    }
  }

  if (!modified) return messages;

  // If the last message is now empty, drop it.
  const hasContent =
    typeof newLast.content === "string"
      ? (newLast.content as string).trim().length > 0
      : Array.isArray(newLast.content) && (newLast.content as unknown[]).length > 0;
  const hasToolCalls =
    Array.isArray(newLast.tool_calls) && (newLast.tool_calls as unknown[]).length > 0;

  const result = messages.slice(0, lastIdx);
  if (hasContent || hasToolCalls) result.push(newLast);
  return result;
}

/**
 * Providers that strictly require the last message to be `user` or `tool`.
 * A trailing `assistant` message with plain text content (no tool_use) is
 * valid for Anthropic/OpenAI (signals "continue from here") but rejected by
 * Mistral with: "Expected last role User or Tool … but got assistant" (#3396).
 */
const PROVIDERS_REQUIRING_USER_LAST_MESSAGE = new Set(["mistral"]);

/**
 * Strip a trailing `assistant` message that contains ONLY plain text (no
 * `tool_use` / `tool_calls`) for providers that mandate user-last format.
 *
 * Call this AFTER `stripTrailingAssistantOrphanToolUse` on the upstream-send
 * path so `tool_use` orphans are already removed before this check runs.
 */
export function stripTrailingAssistantForProvider(
  messages: Record<string, unknown>[],
  provider: string
): Record<string, unknown>[] {
  if (!PROVIDERS_REQUIRING_USER_LAST_MESSAGE.has(provider)) return messages;
  if (!Array.isArray(messages) || messages.length === 0) return messages;

  const last = messages[messages.length - 1];
  if (!last || last.role !== "assistant") return messages;

  // Only strip when the message has NO tool_use / tool_calls (those are
  // handled by stripTrailingAssistantOrphanToolUse upstream of this call).
  const hasToolUse =
    Array.isArray(last.content) &&
    (last.content as Record<string, unknown>[]).some((b) => b.type === "tool_use");
  const hasToolCalls = Array.isArray(last.tool_calls) && (last.tool_calls as unknown[]).length > 0;
  if (hasToolUse || hasToolCalls) return messages;

  return messages.slice(0, messages.length - 1);
}

