};

/**
 * Map a models.dev provider ID to OmniRoute provider IDs.
 * Returns array of provider identifiers (may include aliases).
 */
export function mapProviderId(modelsDevProviderId: string): string[] {
  return MODELS_DEV_PROVIDER_MAP[modelsDevProviderId] || [modelsDevProviderId];
}

// ─── Transform: Pricing ──────────────────────────────────

/**
 * Transform models.dev raw data → OmniRoute PricingByProvider format.
 *
 * models.dev costs are already in $/1M tokens (same as OmniRoute format).
 * Maps: cache_read → cached, cache_write → cache_creation.
 */
export function transformModelsDevToPricing(raw: ModelsDevData): PricingByProvider {
  const result: PricingByProvider = {};

  for (const [providerId, providerData] of Object.entries(raw)) {
    const omniRouteProviders = mapProviderId(providerId);

    for (const [modelId, model] of Object.entries(providerData.models || {})) {
      if (!model.cost) continue;

      // Must have at least input pricing
      if (model.cost.input == null) continue;

      const entry: PricingEntry = {
        input: model.cost.input,
        output: model.cost.output ?? 0,
      };

      if (model.cost.cache_read != null) {
        entry.cached = model.cost.cache_read;
      }
      if (model.cost.cache_write != null) {
        entry.cache_creation = model.cost.cache_write;
      }
      if (model.cost.reasoning != null) {
        entry.reasoning = model.cost.reasoning;
      }

      // Write to ALL mapped OmniRoute providers
      for (const omniProvider of omniRouteProviders) {
        if (!result[omniProvider]) result[omniProvider] = {};
        result[omniProvider][modelId] = entry;
      }
    }
  }

  return result;
}

// ─── Transform: Capabilities ─────────────────────────────

/**
 * Transform models.dev raw data → CapabilitiesByProvider format.
 */
export function transformModelsDevToCapabilities(raw: ModelsDevData): CapabilitiesByProvider {
  const result: CapabilitiesByProvider = {};

  for (const [providerId, providerData] of Object.entries(raw)) {
    const omniRouteProviders = mapProviderId(providerId);

    for (const [modelId, model] of Object.entries(providerData.models || {})) {
      const modalitiesInput = model.modalities?.input ?? [];
      const modalitiesOutput = model.modalities?.output ?? [];
      // #8250: models.dev can ship attachment=false while modalities.input still
      // lists image/video (Kimi K3). Normalize at sync so persisted rows stay
      // internally consistent before resolve-time reconciliation.
      let attachment = model.attachment ?? null;
      if (
        attachment === false &&
        [...modalitiesInput, ...modalitiesOutput].some((entry) => {
          const lower = String(entry).toLowerCase();
          return lower.includes("image") || lower.includes("video");
        })
      ) {
        attachment = true;
      }

      const cap: ModelCapabilityEntry = {
        tool_call: model.tool_call ?? null,
        reasoning: model.reasoning ?? null,
        attachment,
        structured_output: model.structured_output ?? null,
        temperature: model.temperature ?? null,
        modalities_input: JSON.stringify(modalitiesInput),
        modalities_output: JSON.stringify(modalitiesOutput),
        knowledge_cutoff: model.knowledge ?? null,
        release_date: model.release_date ?? null,
        last_updated: model.last_updated ?? null,
        status: model.status ?? null,
        family: model.family ?? null,
        open_weights: model.open_weights ?? null,
        limit_context: model.limit?.context ?? null,
        limit_input: model.limit?.input ?? null,
        limit_output: model.limit?.output ?? null,
        interleaved_field:
          typeof model.interleaved === "object" && model.interleaved?.field
            ? model.interleaved.field
            : model.interleaved === true
              ? "reasoning_content"
              : null,
      };

      for (const omniProvider of omniRouteProviders) {
        if (!result[omniProvider]) result[omniProvider] = {};
        result[omniProvider][modelId] = cap;
      }
    }
  }

  return result;
}

import { getDbInstance } from "./core";

/**
 * Feature 5004 — self-correcting context-window overrides.
 *
 * A persisted override of a model's real context window that wins over the static
 * catalog / models.dev sync in `getModelContextLimit()`. Two sources:
 * - `manual`: operator-set; never overwritten by the auto reconciler.
 * - `auto:discovery`: written by the reconciler when a provider's own `/models`
 *   discovery declares a window that diverges from the catalog.
 *
 * Cacheless on purpose: the read path already touches the DB (synced capabilities),
 * and a single indexed PK lookup is negligible — this avoids any cache-staleness
 * hazard with `resetDbInstance()` in tests.
 */

export type ModelContextOverrideSource = "manual" | "auto:discovery";

export interface ModelContextOverride {
  provider: string;
  modelId: string;
  realContext: number;
  source: ModelContextOverrideSource;
  refreshedAt: string;
}

interface OverrideRow {
  provider: string;
  model_id: string;
  real_context: number;
  source: string;
  refreshed_at: string;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

function normalizeKey(provider: unknown, modelId: unknown): { provider: string; modelId: string } | null {
  const p = typeof provider === "string" ? provider.trim() : "";
  const m = typeof modelId === "string" ? modelId.trim() : "";
  if (!p || !m) return null;
  return { provider: p, modelId: m };
}

function toOverride(row: OverrideRow): ModelContextOverride {
  return {
    provider: row.provider,
    modelId: row.model_id,
    realContext: row.real_context,
    source: row.source === "auto:discovery" ? "auto:discovery" : "manual",
    refreshedAt: row.refreshed_at,
  };
}

/** Full override record for (provider, modelId), or null. Never throws. */
export function getModelContextOverrideRecord(
  provider: string | null | undefined,
  modelId: string | null | undefined
): ModelContextOverride | null {
  const key = normalizeKey(provider, modelId);
  if (!key) return null;
  try {
    const row = getDbInstance()
      .prepare(
        "SELECT provider, model_id, real_context, source, refreshed_at " +
          "FROM model_context_overrides WHERE provider = ? AND model_id = ?"
      )
      .get(key.provider, key.modelId) as OverrideRow | undefined;
    return row ? toOverride(row) : null;
  } catch {
    // Table may not exist yet (pre-migration) — fall through to the catalog.
    return null;
  }
}

/** The overridden context window (tokens) for (provider, modelId), or null. Never throws. */
export function getModelContextOverride(
  provider: string | null | undefined,
  modelId: string | null | undefined
): number | null {
  const record = getModelContextOverrideRecord(provider, modelId);
  return record ? record.realContext : null;
}

/**
 * Upsert an override. `realContext` must be a positive integer (a token count);
 * anything else is rejected (no write). Returns true when a row was written.
 */
export function setModelContextOverride(
  provider: string,
  modelId: string,
  realContext: number,
  source: ModelContextOverrideSource = "manual"
): boolean {
  const key = normalizeKey(provider, modelId);
  if (!key || !isPositiveInteger(realContext)) return false;
  const normalizedSource: ModelContextOverrideSource =
    source === "auto:discovery" ? "auto:discovery" : "manual";
  getDbInstance()
    .prepare(
      "INSERT OR REPLACE INTO model_context_overrides " +
        "(provider, model_id, real_context, source, refreshed_at) " +
        "VALUES (?, ?, ?, ?, datetime('now'))"
    )
    .run(key.provider, key.modelId, realContext, normalizedSource);
  return true;
}

/** Remove an override. Returns true when a row was deleted. */
export function removeModelContextOverride(provider: string, modelId: string): boolean {
  const key = normalizeKey(provider, modelId);
  if (!key) return false;
  const info = getDbInstance()
    .prepare("DELETE FROM model_context_overrides WHERE provider = ? AND model_id = ?")
    .run(key.provider, key.modelId);
  return info.changes > 0;
}

/** All overrides, newest refresh first. Never throws. */
export function listModelContextOverrides(): ModelContextOverride[] {
  try {
    const rows = getDbInstance()
      .prepare(
        "SELECT provider, model_id, real_context, source, refreshed_at " +
          "FROM model_context_overrides ORDER BY refreshed_at DESC"
      )
      .all() as OverrideRow[];
    return rows.map(toOverride);
  } catch {
    return [];
  }
}

import { getDbInstance } from "./core";

export type ModelCapabilityOverrideKey = "max_token";

export interface ModelCapabilityOverride {
  provider: string;
  modelId: string;
  target: string;
  key: ModelCapabilityOverrideKey;
  value: number;
  refreshedAt: string;
}

interface OverrideRow {
  provider: string;
  model_id: string;
  override_key: string;
  override_value: string;
  refreshed_at: string;
}

function isSupportedKey(value: unknown): value is ModelCapabilityOverrideKey {
  return value === "max_token";
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

export function parseModelOverrideTarget(
  target: unknown
): { provider: string; modelId: string } | null {
  const raw = typeof target === "string" ? target.trim() : "";
  const slashIndex = raw.indexOf("/");
  if (slashIndex <= 0 || slashIndex === raw.length - 1) return null;

  const provider = raw.slice(0, slashIndex).trim();
  const modelId = raw.slice(slashIndex + 1).trim();
  if (!provider || !modelId) return null;
  return { provider, modelId };
}

function toOverride(row: OverrideRow): ModelCapabilityOverride | null {
  if (!isSupportedKey(row.override_key)) return null;

  let parsedValue: unknown;
  try {
    parsedValue = JSON.parse(row.override_value);
  } catch {
    return null;
  }

  if (!isPositiveInteger(parsedValue)) return null;

  return {
    provider: row.provider,
    modelId: row.model_id,
    target: `${row.provider}/${row.model_id}`,
    key: row.override_key,
    value: parsedValue,
    refreshedAt: row.refreshed_at,
  };
}

export function getModelCapabilityOverride(
  provider: string | null | undefined,
  modelId: string | null | undefined,
  key: ModelCapabilityOverrideKey
): number | null {
  const target = parseModelOverrideTarget(`${provider || ""}/${modelId || ""}`);
  if (!target || !isSupportedKey(key)) return null;

  try {
    const row = getDbInstance()
      .prepare(
        "SELECT provider, model_id, override_key, override_value, refreshed_at " +
          "FROM model_capability_overrides WHERE provider = ? AND model_id = ? AND override_key = ?"
      )
      .get(target.provider, target.modelId, key) as OverrideRow | undefined;
    const override = row ? toOverride(row) : null;
    return override?.value ?? null;
  } catch {
    return null;
  }
}

export function setModelCapabilityOverride(
  target: string,
  key: ModelCapabilityOverrideKey,
  value: number
): boolean {
  const parsedTarget = parseModelOverrideTarget(target);
  if (!parsedTarget || !isSupportedKey(key) || !isPositiveInteger(value)) return false;

  getDbInstance()
    .prepare(
      "INSERT OR REPLACE INTO model_capability_overrides " +
        "(provider, model_id, override_key, override_value, refreshed_at) " +
        "VALUES (?, ?, ?, ?, datetime('now'))"
    )
    .run(parsedTarget.provider, parsedTarget.modelId, key, JSON.stringify(value));
  return true;
}

export function removeModelCapabilityOverride(
  target: string,
  key: ModelCapabilityOverrideKey
): boolean {
  const parsedTarget = parseModelOverrideTarget(target);
  if (!parsedTarget || !isSupportedKey(key)) return false;

  const info = getDbInstance()
    .prepare(
      "DELETE FROM model_capability_overrides " +
        "WHERE provider = ? AND model_id = ? AND override_key = ?"
    )
    .run(parsedTarget.provider, parsedTarget.modelId, key);
  return info.changes > 0;
}

export function listModelCapabilityOverrides(): ModelCapabilityOverride[] {
  try {
    const rows = getDbInstance()
      .prepare(
        "SELECT provider, model_id, override_key, override_value, refreshed_at " +
          "FROM model_capability_overrides ORDER BY refreshed_at DESC"
      )
      .all() as OverrideRow[];
    return rows.map(toOverride).filter((entry): entry is ModelCapabilityOverride => entry !== null);
  } catch {
    return [];
  }
}

/**
 * Serialized JSON length without materializing the JSON (#7847).
 *
 * Several hot-path call sites only need `JSON.stringify(body).length` — a readiness-timeout
 * threshold, a payload-size metric, a token estimate. On a 3.05 MiB agent request each of those
 * allocates a full 3 MiB string that is read once for its length and thrown away, and #7847
 * reports that class of transient allocation driving V8/cgroup OOM under concurrent long-context
 * traffic.
 *
 * `jsonLength()` walks the value and counts instead. Same O(n) scan, no allocation.
 *
 * It is EXACT, not an approximation: every consumer feeds a threshold, and an approximation
 * would silently shift routing and timeout decisions. `tests/unit/json-size-exactness.test.ts`
 * property-tests `jsonLength(x) === JSON.stringify(x).length` over generated structures.
 *
 * Anything outside the plain-JSON subset (Date, toJSON, class instances, Map, ...) falls back to
 * `JSON.stringify` for THAT SUBTREE only, so an exotic leaf never forces the multi-megabyte
 * message history back onto the allocating path.
 */

/** Length of a JSON-encoded string, including the surrounding quotes. */
function encodedStringLength(value: string): number {
  let len = 2; // the quotes
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code === 0x22 || code === 0x5c) {
      len += 2; // \" and \\
    } else if (code === 0x08 || code === 0x09 || code === 0x0a || code === 0x0c || code === 0x0d) {
      len += 2; // \b \t \n \f \r
    } else if (code < 0x20) {
      len += 6; // \u00XX
    } else if (code >= 0xd800 && code <= 0xdfff) {
      // Surrogates: a well-formed pair serializes as its two code units (2 chars); a LONE
      // surrogate is escaped as \uXXXX since ES2019 well-formed JSON.stringify.
      const isHigh = code <= 0xdbff;
      const next = isHigh ? value.charCodeAt(i + 1) : NaN;
      const paired = isHigh && next >= 0xdc00 && next <= 0xdfff;
      if (paired) {
        len += 2;
        i++; // consume the low surrogate
      } else {
        len += 6;
      }
    } else {
      len += 1;
    }
  }
  return len;
}

/** True for values JSON.stringify drops (object values) or renders as null (array items). */
function isOmitted(value: unknown): boolean {
  return value === undefined || typeof value === "function" || typeof value === "symbol";
}

function isPlainContainer(value: object): boolean {
  if (Array.isArray(value)) return true;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/**
 * Exact `JSON.stringify(value).length`, computed without building the string.
 * Returns 0 for values JSON.stringify renders as `undefined` (functions, symbols, undefined),
 * matching the `try { JSON.stringify(x).length } catch { 0 }` shape of the call sites replaced.
 * Throws on circular structures and BigInt, exactly as JSON.stringify does.
 */
export function jsonLength(value: unknown): number {
  return lengthOf(value, new Set<object>());
}

function lengthOf(value: unknown, seen: Set<object>): number {
  if (value === null) return 4; // "null"
  const type = typeof value;

  if (type === "string") return encodedStringLength(value as string);
  if (type === "boolean") return value ? 4 : 5;
  if (type === "number") {
    // Non-finite numbers serialize as null.
    return Number.isFinite(value as number) ? String(value).length : 4;
  }
  if (type === "bigint") {
    // Match JSON.stringify, which throws rather than guessing an encoding.
    throw new TypeError("Do not know how to serialize a BigInt");
  }
  if (isOmitted(value)) return 0;
  if (type !== "object") return 0;

  const obj = value as object;

  // Delegate anything that is not a plain object/array — Date, class instances with toJSON,
  // Map, boxed primitives. Scoped to this subtree so the big arrays stay on the fast path.
  if (!isPlainContainer(obj) || typeof (obj as { toJSON?: unknown }).toJSON === "function") {
    const encoded = JSON.stringify(obj);
    return encoded === undefined ? 0 : encoded.length;
  }

  if (seen.has(obj)) {
    throw new TypeError("Converting circular structure to JSON");
  }
  seen.add(obj);
  try {
    if (Array.isArray(obj)) {
      let len = 2; // []
      for (let i = 0; i < obj.length; i++) {
        if (i > 0) len += 1; // comma
        const item = obj[i];
        // Omitted values render as null inside arrays rather than disappearing.
        len += isOmitted(item) ? 4 : lengthOf(item, seen);
      }
      return len;
    }

    let len = 2; // {}
    let first = true;
    for (const key of Object.keys(obj)) {
      const item = (obj as Record<string, unknown>)[key];
      if (isOmitted(item)) continue; // the whole entry disappears
      if (!first) len += 1; // comma
      first = false;
      len += encodedStringLength(key) + 1 + lengthOf(item, seen); // "key":value
    }
    return len;
  } finally {
    seen.delete(obj);
  }
}

/**
 * Claude Code fingerprint computation.
 *
 * The billing header includes a 3-char fingerprint derived from:
 *   SHA256(SALT + msg[4] + msg[7] + msg[20] + version)[:3]
 *
 * This fingerprint is computed from the first user message text and
 * included in cc_version=VERSION.FINGERPRINT in the billing header.
 */

import { createHash } from "node:crypto";

const FINGERPRINT_SALT = "59cf53e54c78";

export function computeFingerprint(firstUserMessageText: string, version: string): string {
  const indices = [4, 7, 20];
  const chars = indices.map((i) => firstUserMessageText[i] || "0").join("");
  const input = `${FINGERPRINT_SALT}${chars}${version}`;
  const hash = createHash("sha256").update(input).digest("hex");
  return hash.slice(0, 3);
}

export function extractFirstUserMessageText(
  messages: Array<{ role?: string; content?: unknown }> | undefined
): string {
  if (!Array.isArray(messages)) return "";
  for (const msg of messages) {
    if (String(msg?.role).toLowerCase() !== "user") continue;
    const content = msg?.content;
    if (typeof content === "string") return content;
    if (Array.isArray(content)) {
      for (const block of content) {
        if (
          block &&
          typeof block === "object" &&
          "text" in block &&
          typeof (block as Record<string, unknown>).text === "string"
        ) {
          return (block as Record<string, unknown>).text as string;
        }
      }
    }
    return "";
  }
  return "";
}

type JsonRecord = Record<string, unknown>;
const CLAUDE_CODE_COMPATIBLE_PROVIDER_PREFIX = "anthropic-compatible-cc-";

import { normalizeExcludedModelPatterns } from "@/domain/connectionModelRules";
import { normalizeRoutingTags } from "@/domain/tagRouter";
import { normalizeOpenRouterPreset } from "@/shared/constants/openRouterPreset";

export const CODEX_REASONING_EFFORT_VALUES = [
  "none",
  "low",
  "medium",
  "high",
  "xhigh",
  "max",
] as const;

export type CodexReasoningEffort = (typeof CODEX_REASONING_EFFORT_VALUES)[number];

const CODEX_REASONING_EFFORT_SET = new Set<string>(CODEX_REASONING_EFFORT_VALUES);

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function normalizeString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const normalized = value.trim().toLowerCase();
  return normalized || undefined;
}

const BEDROCK_REGION_PATTERN = /^[a-z]{2}(?:-gov)?-[a-z]+-\d+$/i;

function normalizeAwsRegion(value: unknown): string | undefined {
  const normalized = normalizeString(value);
  if (!normalized || !BEDROCK_REGION_PATTERN.test(normalized)) return undefined;
  return normalized;
}

function hasNonEmptyString(value: unknown): boolean {
  return typeof value === "string" && value.trim().length > 0;
}

function isClaudeCodeCompatibleProvider(provider: string | null | undefined): boolean {
  return (
    typeof provider === "string" && provider.startsWith(CLAUDE_CODE_COMPATIBLE_PROVIDER_PREFIX)
  );
}

export function normalizeCodexReasoningEffort(value: unknown): CodexReasoningEffort | undefined {
  const normalized = normalizeString(value);
  if (!normalized || !CODEX_REASONING_EFFORT_SET.has(normalized)) {
    return undefined;
  }
  return normalized as CodexReasoningEffort;
}

export type CodexServiceTier = "default" | "priority" | "flex";

export function normalizeCodexServiceTier(value: unknown): CodexServiceTier | undefined {
  const normalized = normalizeString(value);
  if (!normalized) return undefined;
  if (normalized === "fast" || normalized === "priority") return "priority";
  if (normalized === "default" || normalized === "flex") return normalized;
  return undefined;
}

export function normalizeClaudeCodeCompatibleContext1m(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeClaudeCodeCompatibleRedactThinking(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeClaudeCodeCompatibleSummarizeThinking(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeRequestDefaults(
  provider: string | null | undefined,
  value: unknown
): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = { ...record };

  if (provider === "codex") {
    const reasoningEffort = normalizeCodexReasoningEffort(record.reasoningEffort);
    if (reasoningEffort) {
      normalized.reasoningEffort = reasoningEffort;
    } else {
      delete normalized.reasoningEffort;
    }

    const serviceTier = normalizeCodexServiceTier(record.serviceTier);
    if (serviceTier) {
      normalized.serviceTier = serviceTier;
    } else {
      delete normalized.serviceTier;
    }
  }

  if (isClaudeCodeCompatibleProvider(provider)) {
    const context1m = normalizeClaudeCodeCompatibleContext1m(record.context1m);
    if (context1m) {
      normalized.context1m = true;
    } else {
      delete normalized.context1m;
    }

    const redactThinking = normalizeClaudeCodeCompatibleRedactThinking(record.redactThinking);
    if (redactThinking) {
      normalized.redactThinking = true;
    } else {
      delete normalized.redactThinking;
    }

    const summarizeThinking = normalizeClaudeCodeCompatibleSummarizeThinking(
      record.summarizeThinking
    );
    if (summarizeThinking) {
      normalized.summarizeThinking = true;
    } else {
      delete normalized.summarizeThinking;
    }
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

const CACHE_PASSTHROUGH_VALUES = new Set(["strip", "openai-format", "claude-format"]);

// #6880 — per-connection prompt-cache capability override: strip unknown keys / invalid
// types, drop the sub-object entirely when nothing valid survives.
export function normalizeCacheOverride(value: unknown): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = {};
  if (typeof record.supportsPromptCaching === "boolean") {
    normalized.supportsPromptCaching = record.supportsPromptCaching;
  }
  if (
    typeof record.cacheControlPassthrough === "string" &&
    CACHE_PASSTHROUGH_VALUES.has(record.cacheControlPassthrough)
  ) {
    normalized.cacheControlPassthrough = record.cacheControlPassthrough;
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

// #6880 — extracted so normalizeProviderSpecificData() stays under the
// max-lines-per-function gate: normalizes the two nested-object sub-fields
// (requestDefaults, cache) in one pass.
function normalizeNestedSubObjects(
  provider: string | null | undefined,
  normalized: JsonRecord
): void {
  if ("requestDefaults" in normalized) {
    const requestDefaults = normalizeRequestDefaults(provider, normalized.requestDefaults);
    if (requestDefaults) {
      normalized.requestDefaults = requestDefaults;
    } else {
      delete normalized.requestDefaults;
    }
  }

  if ("cache" in normalized) {
    const cache = normalizeCacheOverride(normalized.cache);
    if (cache) {
      normalized.cache = cache;
    } else {
      delete normalized.cache;
    }
  }
}

export function normalizeProviderSpecificData(
  provider: string | null | undefined,
  value: unknown
): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = { ...record };

  normalizeNestedSubObjects(provider, normalized);

  if ("openaiStoreEnabled" in normalized && typeof normalized.openaiStoreEnabled !== "boolean") {
    delete normalized.openaiStoreEnabled;
  }

  if ("blockExtraUsage" in normalized && typeof normalized.blockExtraUsage !== "boolean") {
    delete normalized.blockExtraUsage;
  }

  // #2997: per-connection transient-cooldown opt-out — only persist a real boolean.
  if ("disableCooling" in normalized && typeof normalized.disableCooling !== "boolean") {
    delete normalized.disableCooling;
  }

  if ("autoFetchModels" in normalized && typeof normalized.autoFetchModels !== "boolean") {
    delete normalized.autoFetchModels;
  }

  if ("preset" in normalized) {
    const preset = provider === "openrouter" ? normalizeOpenRouterPreset(normalized.preset) : null;
    if (preset) {
      normalized.preset = preset;
    } else {
      delete normalized.preset;
    }
  }

  if (provider === "bedrock" && "region" in normalized) {
    const region = normalizeAwsRegion(normalized.region);
    if (region) {
      normalized.region = region;
    } else {
      delete normalized.region;
    }
  }

  if ("tag" in normalized) {
    if (typeof normalized.tag === "string") {
      const trimmedTag = normalized.tag.trim();
      if (trimmedTag) {
        normalized.tag = trimmedTag;
      } else {
        delete normalized.tag;
      }
    } else {
      delete normalized.tag;
    }
  }

  if ("tags" in normalized) {
    const tags = normalizeRoutingTags(normalized.tags);
    if (tags.length > 0) {
      normalized.tags = tags;
    } else {
      delete normalized.tags;
    }
  }

  if ("excludedModels" in normalized || "excluded_models" in normalized) {
    const excludedModels = normalizeExcludedModelPatterns(
      normalized.excludedModels ?? normalized.excluded_models
    );
    if (excludedModels.length > 0) {
      normalized.excludedModels = excludedModels;
    } else {
      delete normalized.excludedModels;
    }
    delete normalized.excluded_models;
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

export function sanitizeProviderSpecificDataForResponse(value: unknown): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const sanitized: JsonRecord = { ...record };
  delete sanitized.consoleApiKey;
  delete sanitized.secretAccessKey;
  delete sanitized.awsSecretAccessKey;
  delete sanitized.sessionToken;
  delete sanitized.awsSessionToken;
  delete sanitized.openCodeGoAuthCookie;
  delete sanitized.opencodeGoAuthCookie;
  delete sanitized.authCookie;
  delete sanitized.ollamaUsageCookie;
  delete sanitized.ollamaCloudUsageCookie;
  delete sanitized.ollamaCloudCookie;
  delete sanitized.usageCookie;
  return sanitized;
}

export function isOpenAIResponsesStoreEnabled(providerSpecificData: unknown): boolean {
  return asRecord(providerSpecificData).openaiStoreEnabled === true;
}

export function buildOpenAIStoreSessionId(sessionId: unknown): string | undefined {
  if (!hasNonEmptyString(sessionId)) return undefined;

  const normalized = String(sessionId)
    .trim()
    .replace(/^ext:/i, "")
    .replace(/[^a-zA-Z0-9._:-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 96);

  if (!normalized) return undefined;
  return `omniroute-session-${normalized}`;
}

export function ensureOpenAIStoreSessionFallback(
  body: Record<string, unknown>,
  sessionId: unknown
): Record<string, unknown> {
  const explicitSessionId = body.session_id;
  const explicitConversationId = body.conversation_id;
  const promptCacheKey = body.prompt_cache_key ?? body.promptCacheKey;

  if (
    hasNonEmptyString(explicitSessionId) ||
    hasNonEmptyString(explicitConversationId) ||
    hasNonEmptyString(promptCacheKey)
  ) {
    return body;
  }

  const fallbackSessionId = buildOpenAIStoreSessionId(sessionId);
  if (!fallbackSessionId) return body;

  return {
    ...body,
    session_id: fallbackSessionId,
  };
}

export function getProviderRequestDefaults(
  provider: string | null | undefined,
  providerSpecificData: unknown
): JsonRecord {
  return normalizeRequestDefaults(provider, asRecord(providerSpecificData).requestDefaults) || {};
}

export function getCodexRequestDefaults(providerSpecificData: unknown): {
  reasoningEffort?: CodexReasoningEffort;
  serviceTier?: CodexServiceTier;
} {
  const defaults = getProviderRequestDefaults("codex", providerSpecificData);
  const reasoningEffort = normalizeCodexReasoningEffort(defaults.reasoningEffort);
  const serviceTier = normalizeCodexServiceTier(defaults.serviceTier);
  return {
    ...(reasoningEffort ? { reasoningEffort } : {}),
    ...(serviceTier ? { serviceTier } : {}),
  };
}

export function getClaudeCodeCompatibleRequestDefaults(providerSpecificData: unknown): {
  context1m?: true;
  redactThinking?: true;
  summarizeThinking?: true;
} {
  const defaults = getProviderRequestDefaults(
    "anthropic-compatible-cc-default",
    providerSpecificData
  );
  const context1m = normalizeClaudeCodeCompatibleContext1m(defaults.context1m);
  const redactThinking = normalizeClaudeCodeCompatibleRedactThinking(defaults.redactThinking);
  const summarizeThinking = normalizeClaudeCodeCompatibleSummarizeThinking(
    defaults.summarizeThinking
  );
  return {
    ...(context1m ? { context1m } : {}),
    ...(redactThinking ? { redactThinking } : {}),
    ...(summarizeThinking ? { summarizeThinking } : {}),
  };
}

import { wildcardMatch } from "@omniroute/open-sse/services/wildcardRouter.ts";

type JsonRecord = Record<string, unknown>;

interface ConnectionLike {
  providerSpecificData?: unknown;
}

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function normalizePattern(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim();
  if (!normalized || normalized === "**") return null;
  return normalized;
}

function toPatternList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map(normalizePattern).filter((pattern): pattern is string => Boolean(pattern));
  }
  if (typeof value === "string") {
    return value
      .split(",")
      .map(normalizePattern)
      .filter((pattern): pattern is string => Boolean(pattern));
  }
  return [];
}

function uniquePatterns(patterns: string[]): string[] {
  return Array.from(new Set(patterns));
}

function getModelMatchCandidates(modelId: string): string[] {
  const normalized = modelId.trim();
  if (!normalized) return [];

  const withoutExtendedContext = normalized.endsWith("[1m]") ? normalized.slice(0, -4) : normalized;
  const lastSlashIndex = withoutExtendedContext.lastIndexOf("/");
  const rawModel =
    lastSlashIndex >= 0 ? withoutExtendedContext.slice(lastSlashIndex + 1) : withoutExtendedContext;

  return Array.from(new Set([normalized, withoutExtendedContext, rawModel].filter(Boolean)));
}

export function normalizeExcludedModelPatterns(value: unknown): string[] {
  return uniquePatterns(toPatternList(value));
}

export function getConnectionExcludedModels(providerSpecificData: unknown): string[] {
  const data = asRecord(providerSpecificData);
  return normalizeExcludedModelPatterns(data.excludedModels ?? data.excluded_models);
}

export function isModelExcludedByConnection(
  modelId: unknown,
  providerSpecificData: unknown
): boolean {
  if (typeof modelId !== "string" || modelId.trim().length === 0) return false;

  const candidates = getModelMatchCandidates(modelId);
  const excludedModels = getConnectionExcludedModels(providerSpecificData);
  if (candidates.length === 0 || excludedModels.length === 0) return false;

  return excludedModels.some((pattern) =>
    candidates.some((candidate) => wildcardMatch(candidate, pattern))
  );
}

export function hasEligibleConnectionForModel(
  connections: ConnectionLike[] | null | undefined,
  modelId: unknown
): boolean {
  if (!Array.isArray(connections) || connections.length === 0) return false;

  return connections.some(
    (connection) => !isModelExcludedByConnection(modelId, connection?.providerSpecificData)
  );
}

type JsonRecord = Record<string, unknown>;

export type RoutingTagMatchMode = "any" | "all";

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function normalizeSingleRoutingTag(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  return normalized.length > 0 ? normalized : null;
}

export function normalizeRoutingTags(value: unknown): string[] {
  const rawValues = Array.isArray(value)
    ? value
    : typeof value === "string"
      ? value.split(",")
      : [];

  const deduped = new Set<string>();
  for (const rawValue of rawValues) {
    const normalized = normalizeSingleRoutingTag(rawValue);
    if (normalized) deduped.add(normalized);
  }
  return Array.from(deduped);
}

export function normalizeRoutingTagMatchMode(value: unknown): RoutingTagMatchMode {
  const normalized =
    typeof value === "string" ? value.trim().toLowerCase() : typeof value === "number" ? "" : "";
  return normalized === "all" ? "all" : "any";
}

export function getConnectionRoutingTags(providerSpecificData: unknown): string[] {
  return normalizeRoutingTags(asRecord(providerSpecificData).tags);
}

export function matchesRoutingTags(
  connectionTags: string[],
  requestTags: string[],
  matchMode: RoutingTagMatchMode = "any"
): boolean {
  if (requestTags.length === 0) return true;
  if (connectionTags.length === 0) return false;

  const tagSet = new Set(connectionTags);
  if (matchMode === "all") {
    return requestTags.every((tag) => tagSet.has(tag));
  }
  return requestTags.some((tag) => tagSet.has(tag));
}

export function resolveRequestRoutingTags(body: Record<string, unknown> | null | undefined): {
  tags: string[];
  matchMode: RoutingTagMatchMode;
} {
  const metadata = asRecord(body?.metadata);
  return {
    tags: normalizeRoutingTags(metadata.tags),
    matchMode: normalizeRoutingTagMatchMode(metadata.tag_match_mode ?? metadata.tagMatchMode),
  };
}

export const OPENROUTER_PRESET_MAX_LENGTH = 200;

export function isOpenRouterPresetValue(value: unknown): value is string {
  return typeof value === "string" && value.trim().length <= OPENROUTER_PRESET_MAX_LENGTH;
}

export function normalizeOpenRouterPreset(value: unknown): string | undefined {
  if (!isOpenRouterPresetValue(value)) return undefined;
  const normalized = value.trim();
  return normalized || undefined;
}

/**
 * Cline (cline.bot) auth-shape helpers.
 *
 * Cline's API expects the bearer token to be prefixed with `workos:` (the
 * upstream auth provider), and a set of Cline client-identification headers
 * (HTTP-Referer / X-Title / X-CLIENT-* / X-PLATFORM*). Plain `Bearer <token>`
 * without the `workos:` prefix is rejected upstream, so every Cline request
 * must route its headers through `buildClineHeaders()`.
 */

import { randomUUID } from "node:crypto";

import { APP_CONFIG } from "../constants/appConfig";

const APP_VERSION = APP_CONFIG.version;

export interface ClineHeaderContext {
  taskId?: string;
  clientType?: string;
  clientVersion?: string;
  platform?: string;
  platformVersion?: string;
  coreVersion?: string;
  isMultiRoot?: boolean;
}

function cleanHeaderValue(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const cleaned = value.trim();
  if (!cleaned || cleaned.length > 256 || /[\r\n\0]/.test(cleaned)) return undefined;
  return cleaned;
}

function getHeaderCaseInsensitive(
  headers: Record<string, string> | null | undefined,
  name: string
): string | undefined {
  const key = Object.keys(headers ?? {}).find((candidate) => candidate.toLowerCase() === name);
  return key ? cleanHeaderValue(headers?.[key]) : undefined;
}

/** Keep an inbound Cline task id when supplied; otherwise create one per request. */
export function resolveClineTaskId(clientHeaders?: Record<string, string> | null): string {
  return getHeaderCaseInsensitive(clientHeaders, "x-task-id") ?? randomUUID();
}

/**
 * Apply the required Cline billing headers with case-insensitive replacement.
 * These fields are authoritative in the official client and must win over
 * stored/configured header layers.
 */
export function applyClineProtocolHeaders(
  headers: Record<string, string>,
  context: ClineHeaderContext = {}
): Record<string, string> {
  const taskId =
    cleanHeaderValue(context.taskId) ??
    getHeaderCaseInsensitive(headers, "x-task-id") ??
    randomUUID();
  const clientVersion = cleanHeaderValue(context.clientVersion) ?? APP_VERSION;
  const required: Record<string, string> = {
    "HTTP-Referer": "https://cline.bot",
    "X-Title": "Cline",
    "User-Agent": `Cline/${clientVersion}`,
    "X-IS-MULTIROOT": context.isMultiRoot === true ? "true" : "false",
    "X-CLIENT-TYPE": cleanHeaderValue(context.clientType) ?? "omniroute",
    "X-CLIENT-VERSION": clientVersion,
    "X-PLATFORM": cleanHeaderValue(context.platform) ?? process.platform ?? "unknown",
    "X-PLATFORM-VERSION": cleanHeaderValue(context.platformVersion) ?? process.version ?? "unknown",
    "X-CORE-VERSION": cleanHeaderValue(context.coreVersion) ?? APP_VERSION,
    "X-Task-ID": taskId,
  };

  for (const [name, value] of Object.entries(required)) {
    for (const existing of Object.keys(headers)) {
      if (existing !== name && existing.toLowerCase() === name.toLowerCase()) {
        delete headers[existing];
      }
    }
    headers[name] = value;
  }
  return headers;
}

/**
 * Normalize a raw Cline token into the `workos:`-prefixed access-token shape
 * Cline expects. Idempotent: a token that already carries the prefix is
 * returned untouched. Non-string / empty input yields an empty string.
 */
export function getClineAccessToken(token: unknown): string {
  if (typeof token !== "string") return "";
  const trimmed = token.trim();
  if (!trimmed) return "";
  return trimmed.startsWith("workos:") ? trimmed : `workos:${trimmed}`;
}

/**
 * Build the full `Authorization` header value for a Cline request, or an empty
 * string when no usable token is present.
 */
export function getClineAuthorizationHeader(token: unknown): string {
  const accessToken = getClineAccessToken(token);
  return accessToken ? `Bearer ${accessToken}` : "";
}

/**
 * Build the complete Cline client header set, optionally merged with caller
 * extras. The `Authorization` header is only added when a usable token is
 * present (so callers can build probe headers without a token).
 */
export function buildClineHeaders(
  token: unknown,
  extraHeaders: Record<string, string> = {},
  context: ClineHeaderContext = {}
): Record<string, string> {
  const authorization = getClineAuthorizationHeader(token);
  const headers = applyClineProtocolHeaders({ ...extraHeaders }, context);

  if (authorization) {
    headers.Authorization = authorization;
  }

  return headers;
}

/**
 * Build headers for a ClinePass request. ClinePass is dual-auth: an OAuth
 * connection (workos:-prefixed token in `accessToken`) needs the full Cline
 * client header set from `buildClineHeaders()`; a BYOK API-key connection
 * (`sk_...` key, #5942) sends the key as a plain Bearer token — no `workos:`
 * prefix — alongside the Cline identification headers.
 */
export function buildClinepassHeaders(
  credentials: { accessToken?: unknown; apiKey?: unknown } | null | undefined,
  effectiveKey?: string,
  context: ClineHeaderContext = {}
): Record<string, string> {
  if (credentials?.accessToken) {
    return buildClineHeaders(credentials.accessToken, {}, context);
  }
  const headers = applyClineProtocolHeaders({}, context);
  const byokKey = effectiveKey || (credentials?.apiKey as string | undefined);
  if (byokKey) headers.Authorization = `Bearer ${byokKey}`;
  return headers;
}

/**
 * Executor call-site helper: merge the Cline/ClinePass auth headers directly
 * into an in-progress `headers` record, mutating it in place. Keeps the
 * `case "cline"` / `case "clinepass"` branches in the executor down to a
 * single call each — `isClinepass` selects `buildClinepassHeaders()`'s
 * dual-auth (OAuth or BYOK) shape vs. `buildClineHeaders()`'s single-token
 * `workos:`-prefixed shape.
 */
export function applyClineAuthHeaders(
  headers: Record<string, string>,
  credentials: { accessToken?: unknown; apiKey?: unknown } | null | undefined,
  effectiveKey: string | undefined,
  clientHeaders: Record<string, string> | null | undefined,
  isClinepass: boolean
): Record<string, string> {
  const context: ClineHeaderContext = { taskId: resolveClineTaskId(clientHeaders) };
  const built = isClinepass
    ? buildClinepassHeaders(credentials, effectiveKey, context)
    : buildClineHeaders(effectiveKey || credentials?.accessToken, {}, context);
  Object.assign(headers, built);
  return headers;
}

import pkg from "../../../package.json" with { type: "json" };

export const APP_CONFIG = {
  name: "OmniRoute",
  description: "AI Gateway for Multi-Provider LLMs",
  version: pkg.version,
};

export const THEME_CONFIG = {
  storageKey: "theme",
  defaultTheme: "system",
};

export function normalizeCliCompatProviderId(providerId: string): string {
  const normalized = providerId.toLowerCase();
  if (normalized === "copilot") return "github";
  return normalized;
}

/**
 * Thinking Budget Control — Phase 2
 *
 * Provides proxy-level control over AI thinking/reasoning budgets.
 * Modes: auto, passthrough, custom, adaptive
 */

// Thinking budget modes
export const ThinkingMode = {
  AUTO: "auto", // Let provider decide (remove client's budget)
  PASSTHROUGH: "passthrough", // No changes (current behavior)
  CUSTOM: "custom", // Set fixed budget
  ADAPTIVE: "adaptive", // Scale based on request complexity
};
export type ThinkingModeValue = (typeof ThinkingMode)[keyof typeof ThinkingMode];

type JsonRecord = Record<string, unknown>;
type ThinkingBudgetConfig = {
  mode: ThinkingModeValue;
  customBudget: number;
  effortLevel: string;
};

import {
  capThinkingBudget,
  getDefaultThinkingBudget,
  getResolvedModelCapabilities,
  supportsReasoning,
} from "@/lib/modelCapabilities";

// Effort → budget token mapping
export const EFFORT_BUDGETS: Record<string, number> = {
  none: 0,
  low: 1024,
  medium: 10240,
  high: 131072, // Handled globally by capThinkingBudget later
  max: 131072, // T11: Claude "max" / "xhigh" — full budget
  xhigh: 131072, // T11: explicit alias used internally
};

// thinkingLevel string → budget token mapping
// Used when clients send string-based thinking levels (e.g., VS Code Copilot)
export const THINKING_LEVEL_MAP: Record<string, number> = {
  none: 0,
  low: 4096,
  medium: 8192,
  high: 24576,
  max: 131072, // T11: max = full Claude budget (sub2api: xhigh)
  xhigh: 131072, // T11: explicit xhigh alias
};

// Default config (passthrough = backward compatible)
export const DEFAULT_THINKING_CONFIG = {
  mode: ThinkingMode.PASSTHROUGH,
  customBudget: 10240,
  effortLevel: "medium",
} satisfies ThinkingBudgetConfig;

// In-memory config (loaded from DB on startup, or default).
//
// Backed by globalThis so the singleton is shared across the SEPARATE webpack
// module graphs Next.js builds for `instrumentation.ts` (boot-time hydration via
// hydrateThinkingBudgetConfig) and the app-route / open-sse executors (per-request
// reads in base.ts). A plain module-level `let` is DUPLICATED per graph, so the
// boot hydration would land on the instrumentation graph's copy and never reach
// base.ts — exactly the #5312 fix-A break proven on the VPS. Mirrors the same
// globalThis pattern systemPrompt.ts already uses for the Global System Prompt (#2470).
const GLOBAL_KEY = "__omniroute_thinkingBudget_config__";
const _store = globalThis as unknown as Record<string, ThinkingBudgetConfig | undefined>;

function getConfig(): ThinkingBudgetConfig {
  if (!_store[GLOBAL_KEY]) {
    _store[GLOBAL_KEY] = { ...DEFAULT_THINKING_CONFIG };
  }
  return _store[GLOBAL_KEY]!;
}

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function getStringField(record: JsonRecord, key: string): string {
  const value = record[key];
  return typeof value === "string" ? value : "";
}

/**
 * Set the thinking budget config (called from settings API or startup)
 */
export function setThinkingBudgetConfig(config: Partial<ThinkingBudgetConfig>) {
  _store[GLOBAL_KEY] = { ...DEFAULT_THINKING_CONFIG, ...config };
}

/**
 * Get current thinking budget config
 */
export function getThinkingBudgetConfig() {
  return { ...getConfig() };
}

/**
 * Startup hydration (#5312 RC-A): the dashboard Thinking-Budget setting is persisted
 * under `settings.thinkingBudget`, but nothing read it back at boot, so `_config`
 * reset to DEFAULT (passthrough) on every restart. Call this once during server
 * bootstrap with the loaded settings object to restore the operator's choice.
 * Returns true when a valid config was applied, false otherwise (zero behavior
 * change when the setting is unset).
 */
export function hydrateThinkingBudgetConfig(settings: unknown): boolean {
  const tb = toRecord(settings).thinkingBudget;
  if (tb && typeof tb === "object" && !Array.isArray(tb)) {
    setThinkingBudgetConfig(tb as Partial<ThinkingBudgetConfig>);
    return true;
  }
  return false;
}

/**
 * Normalize thinkingLevel string fields into numeric budget.
 * Handles: body.thinkingLevel, body.thinking_level,
 * and Gemini's generationConfig.thinkingConfig.thinkingLevel
 *
 * @param {object} body - Request body
 * @returns {object} Body with string thinkingLevel converted to numeric budget
 */
export function normalizeThinkingLevel(body: unknown) {
  if (!body || typeof body !== "object") return body;
  const result: JsonRecord = { ...(body as JsonRecord) };

  // Handle top-level thinkingLevel or thinking_level string fields
  const levelStr = result.thinkingLevel || result.thinking_level;
  if (typeof levelStr === "string" && THINKING_LEVEL_MAP[levelStr.toLowerCase()] !== undefined) {
    const rawBudget = THINKING_LEVEL_MAP[levelStr.toLowerCase()];
    const budget = capThinkingBudget(getStringField(result, "model"), rawBudget);
    // Convert to Claude thinking format as canonical representation
    result.thinking = {
      type: budget > 0 ? "enabled" : "disabled",
      budget_tokens: budget,
    };
    delete result.thinkingLevel;
    delete result.thinking_level;
  }

  // Handle Gemini's generationConfig.thinkingConfig.thinkingLevel
  const generationConfig = toRecord(result.generationConfig);
  const thinkingConfig = toRecord(generationConfig.thinkingConfig);
  const thinkingConfigSnake = toRecord(generationConfig.thinking_config);
  const geminiLevel = thinkingConfig.thinkingLevel || thinkingConfigSnake.thinkingLevel;
  if (
    typeof geminiLevel === "string" &&
    THINKING_LEVEL_MAP[geminiLevel.toLowerCase()] !== undefined
  ) {
    const rawBudget = THINKING_LEVEL_MAP[geminiLevel.toLowerCase()];
    const budget = capThinkingBudget(getStringField(result, "model"), rawBudget);
    result.generationConfig = {
      ...generationConfig,
      thinkingConfig: { ...thinkingConfig, thinkingBudget: budget },
    };
    // Clean up string variants
    const nextGenerationConfig = result.generationConfig as JsonRecord;
    const nextThinkingConfig = toRecord(nextGenerationConfig.thinkingConfig);
    if (Object.keys(nextThinkingConfig).length > 0) {
      delete nextThinkingConfig.thinkingLevel;
      nextGenerationConfig.thinkingConfig = nextThinkingConfig;
    }
    if ("thinking_config" in nextGenerationConfig) {
      delete nextGenerationConfig.thinking_config;
    }
  }

  return result;
}

/**
 * Ensure models with -thinking suffix have thinking config injected.
 * Prevents 400 errors from Claude API when thinking params are missing.
 *
 * @param {object} body - Request body
 * @returns {object} Body with thinking config auto-injected if needed
 */
export function ensureThinkingConfig(body: unknown) {
  if (!body || typeof body !== "object") return body;
  const bodyRecord = body as JsonRecord;
  const model = getStringField(bodyRecord, "model");

  // Only auto-inject for models with -thinking suffix
  if (!model.endsWith("-thinking")) return body;

  // If thinking config already present, don't override
  if (bodyRecord.thinking) return body;

  const result: JsonRecord = { ...bodyRecord };
  result.thinking = {
    type: "enabled",
    budget_tokens: getDefaultThinkingBudget(model) || EFFORT_BUDGETS.medium,
  };
  return result;
}

/**
 * Apply thinking budget control to a request body.
 * Called before format-specific translation.
 *
 * Pipeline: normalizeThinkingLevel → ensureThinkingConfig → mode processing
 *
 * @param {object} body - Request body (supported formats)
 * @param {object} [config] - Override config (defaults to stored config)
 * @returns {object} Modified body
 */
export function applyThinkingBudget(
  body: unknown,
  config: Partial<ThinkingBudgetConfig> | null = null
) {
  const cfg = config || getConfig();
  if (!body || typeof body !== "object") return body;

  // Early exit: strip ALL reasoning/thinking params for models that don't support them.
  // Provider-specific Cloud Code restrictions should be handled at the executor boundary.
  const bodyRecord = body as JsonRecord;
  const modelStr = typeof bodyRecord.model === "string" ? bodyRecord.model : "";
  if (modelStr && !supportsReasoning(modelStr)) {
    return stripThinkingConfig(body);
  }

  // Pre-processing: convert string thinkingLevel to numeric budget
  let processed = normalizeThinkingLevel(body);

  // Pre-processing: auto-inject thinking config for -thinking suffix models
  processed = ensureThinkingConfig(processed);

  switch (cfg.mode) {
    case ThinkingMode.AUTO:
      return stripThinkingConfig(processed);

    case ThinkingMode.PASSTHROUGH:
      return processed;

    case ThinkingMode.CUSTOM:
      return setCustomBudget(processed, cfg.customBudget ?? DEFAULT_THINKING_CONFIG.customBudget);

    case ThinkingMode.ADAPTIVE:
      return applyAdaptiveBudget(processed, cfg);

    default:
      return processed;
  }
}

/**
 * AUTO mode: strip all thinking configuration, let provider decide
 */
function stripThinkingConfig(body: unknown) {
  const result: JsonRecord = { ...toRecord(body) };

  // Claude format
  delete result.thinking;

  // OpenAI format
  delete result.reasoning_effort;
  delete result.reasoning;

  // Claude Code output_config.effort — strip the effort hint too, otherwise the
  // claude→openai translator re-injects reasoning_effort downstream (#3258).
  if (result.output_config && typeof result.output_config === "object") {
    const outputConfig = { ...toRecord(result.output_config) };
    delete outputConfig.effort;
    if (Object.keys(outputConfig).length === 0) {
      delete result.output_config;
    } else {
      result.output_config = outputConfig;
    }
  }

  // Gemini format
  if (result.generationConfig) {
    const generationConfig = { ...toRecord(result.generationConfig) };
    delete generationConfig.thinking_config;
    delete generationConfig.thinkingConfig;
    result.generationConfig = generationConfig;
  }

  return result;
}

/**
 * CUSTOM mode: set exact budget tokens
 */
function setCustomBudget(body: unknown, budget: number) {
  const result: JsonRecord = { ...toRecord(body) };

  // If body already has thinking config in Claude format, update it
  if (result.thinking || hasThinkingCapableModel(result)) {
    result.thinking = {
      type: budget > 0 ? "enabled" : "disabled",
      budget_tokens: budget,
    };
  }

  // OpenAI reasoning_effort mapping.
  // GPT-5/Codex accepts xhigh for the top tier; keep full budget aligned.
  if (result.reasoning_effort !== undefined || result.reasoning !== undefined) {
    if (budget <= 0) {
      delete result.reasoning_effort;
      delete result.reasoning;
    } else if (budget <= 1024) {
      result.reasoning_effort = "low";
    } else if (budget <= 10240) {
      result.reasoning_effort = "medium";
    } else if (budget < 131072) {
      result.reasoning_effort = "high";
    } else {
      result.reasoning_effort = "xhigh";
    }
  }

  // Gemini thinking_config
  const generationConfig = toRecord(result.generationConfig);
  if (generationConfig.thinking_config || generationConfig.thinkingConfig) {
    result.generationConfig = {
      ...generationConfig,
      thinking_config: { thinking_budget: budget },
    };
  }

  return result;
}

/**
 * ADAPTIVE mode: scale budget based on request complexity
 */
function applyAdaptiveBudget(body: unknown, cfg: Partial<ThinkingBudgetConfig>) {
  const bodyRecord = toRecord(body);
  const messages = Array.isArray(bodyRecord.messages)
    ? bodyRecord.messages
    : Array.isArray(bodyRecord.input)
      ? bodyRecord.input
      : [];
  const messageCount = messages.length;
  const tools = Array.isArray(bodyRecord.tools) ? bodyRecord.tools : [];
  const toolCount = tools.length;

  // Get last user message length
  let lastMsgLength = 0;
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    const msgRecord = toRecord(msg);
    if (msgRecord.role === "user") {
      lastMsgLength =
        typeof msgRecord.content === "string"
          ? msgRecord.content.length
          : JSON.stringify(msgRecord.content || "").length;
      break;
    }
  }

  // Calculate multiplier
  let multiplier = 1.0;
  if (messageCount > 10) multiplier += 0.5;
  if (toolCount > 3) multiplier += 0.5;
  if (lastMsgLength > 2000) multiplier += 0.3;

  const baseBudget =
    EFFORT_BUDGETS[typeof cfg.effortLevel === "string" ? cfg.effortLevel : "medium"] ||
    getDefaultThinkingBudget(getStringField(bodyRecord, "model")) ||
    EFFORT_BUDGETS.medium;
  const budget = capThinkingBudget(
    getStringField(bodyRecord, "model"),
    Math.ceil(baseBudget * multiplier)
  );

  return setCustomBudget(body, budget);
}

/**
 * Check if model name suggests thinking capability
 */
export function hasThinkingCapableModel(body: unknown) {
  const model = getStringField(toRecord(body), "model");
  const resolved = getResolvedModelCapabilities(model);
  if (resolved.supportsThinking === true) return true;
  if (resolved.supportsThinking === false) return false;
  return (
    model.includes("claude") ||
    model.includes("o1") ||
    model.includes("o3") ||
    model.includes("o4") ||
    model.includes("gemini") ||
    model.endsWith("-thinking") ||
    model.includes("thinking")
  );
}

/**
 * openrouterFreeWindow.ts — OpenRouter `:free`-variant local window tracker (#6842)
 *
 * OpenRouter's official monitoring API (`/api/v1/key`, `/api/v1/credits`) reports
 * USD spend, never request counts — so the `:free`-model per-account request
 * windows (docs/reference/FREE_TIERS.md) cannot be read from those endpoints.
 * This module tracks them locally instead:
 *
 *   - A UTC-day counter: 50 requests/day at $0 all-time purchased, 1000/day
 *     once $10+ has been purchased (operator-overridable via setPurchasedTier).
 *   - A 20 RPM rolling window (true rolling — timestamps pruned to the last 60s,
 *     not a fixed-bucket reset).
 *
 * Bucketed by ACCOUNT, not by connection/key — multiple OmniRoute connections
 * that share one upstream OpenRouter account must share one window. OmniRoute's
 * `provider_connections` are per-key, so callers resolve an account bucket key
 * via `resolveAccountKey()`: an explicit `providerSpecificData.openrouterAccountKey`
 * groups keys under one account; otherwise each connection gets its own bucket
 * (safe default — never worse than no tracking).
 *
 * State is in-memory only (module-level Map, not persisted). This is a
 * deliberate MVP scope: local counting is inherently best-effort (drifts on
 * process restart or multi-instance deployments sharing one OpenRouter
 * account) and is corrected from upstream `X-RateLimit-*` response headers on
 * every 429, which is authoritative. See the plan's "Risks" section — SQLite
 * persistence is a possible follow-up, not required for correctness here.
 */

const RPM_WINDOW_MS = 60_000;
const RPM_LIMIT = 20;
const DAILY_LIMIT_BASE = 50;
const DAILY_LIMIT_PURCHASED = 1000;

interface AccountWindowState {
  dayKey: string;
  dayCount: number;
  purchasedAtLeast10: boolean;
  requestTimestamps: number[];
  serverDailyLimit: number | null;
  serverDailyRemaining: number | null;
  serverResetAtMs: number | null;
}

export interface FreeWindowStatus {
  dailyLimit: number;
  dailyUsed: number;
  dailyRemaining: number;
  dailyResetAt: string;
  rpmLimit: number;
  rpmUsed: number;
  rpmRemaining: number;
}

const accountWindows = new Map<string, AccountWindowState>();

function utcDayKey(now: number): string {
  return new Date(now).toISOString().slice(0, 10);
}

function nextUtcMidnightIso(now: number): string {
  const date = new Date(now);
  const next = Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate() + 1,
    0,
    0,
    0,
    0
  );
  return new Date(next).toISOString();
}

/**
 * Whether a model id is an OpenRouter `:free`-variant (e.g.
 * `x-ai/grok-4-fast:free`). Shared by the dispatch-time record/correct hooks
 * (`open-sse/executors/base.ts`) and the quota-preflight enforcement hook
 * (`open-sse/services/openrouterQuotaFetcher.ts`) so both sides agree on the
 * same definition of "free variant."
 */
export function isFreeVariantModel(model: string | null | undefined): boolean {
  return typeof model === "string" && model.endsWith(":free");
}

/**
 * Resolve the shared account bucket key for a connection. Operators group
 * multiple keys under one OpenRouter account via `providerSpecificData.
 * openrouterAccountKey`; without it, each connection is its own bucket.
 */
export function resolveAccountKey(
  connectionId: string,
  connection?: Record<string, unknown> | null
): string {
  const psd = connection?.providerSpecificData as Record<string, unknown> | undefined;
  const explicit = typeof psd?.openrouterAccountKey === "string" ? psd.openrouterAccountKey : "";
  return explicit.trim().length > 0 ? `acct:${explicit.trim()}` : `conn:${connectionId}`;
}

function getOrInitState(accountKey: string, now: number): AccountWindowState {
  const dayKey = utcDayKey(now);
  const existing = accountWindows.get(accountKey);
  if (existing && existing.dayKey === dayKey) return existing;

  const fresh: AccountWindowState = {
    dayKey,
    dayCount: 0,
    purchasedAtLeast10: existing?.purchasedAtLeast10 ?? false,
    requestTimestamps: [],
    serverDailyLimit: null,
    serverDailyRemaining: null,
    serverResetAtMs: null,
  };
  accountWindows.set(accountKey, fresh);
  return fresh;
}

function pruneRpmWindow(state: AccountWindowState, now: number): void {
  const cutoff = now - RPM_WINDOW_MS;
  state.requestTimestamps = state.requestTimestamps.filter((ts) => ts > cutoff);
}

/**
 * Operator override: declare whether $10+ has been purchased all-time on this
 * account, unlocking the 1000/day tier instead of the 50/day default.
 */
export function setPurchasedTier(accountKey: string, purchasedAtLeast10: boolean): void {
  const state = getOrInitState(accountKey, Date.now());
  state.purchasedAtLeast10 = purchasedAtLeast10;
}

/**
 * Record a `:free`-variant request attempt against the account bucket.
 * Failed attempts count toward the daily cap too (per OpenRouter's own
 * accounting — a rejected request still consumed a request slot).
 */
export function recordFreeWindowAttempt(accountKey: string, now: number = Date.now()): void {
  const state = getOrInitState(accountKey, now);
  pruneRpmWindow(state, now);
  state.dayCount += 1;
  state.requestTimestamps.push(now);
}

function getHeader(headers: Headers | Record<string, string>, name: string): string | null {
  if (typeof (headers as Headers).get === "function") {
    return (headers as Headers).get(name);
  }
  const record = headers as Record<string, string>;
  return record[name] ?? record[name.toLowerCase()] ?? null;
}

function parseResetMsFromHeader(reset: string | null): number | null {
  if (reset === null) return null;
  const resetNum = Number(reset);
  if (!Number.isFinite(resetNum)) return null;
  return resetNum > 10_000_000_000 ? resetNum : resetNum * 1000;
}

function parseRetryAfterMs(retryAfter: string | null, now: number): number | null {
  if (retryAfter === null) return null;
  const seconds = Number(retryAfter);
  if (!Number.isFinite(seconds) || seconds <= 0) return null;
  return now + seconds * 1000;
}

function resolveResetMs(
  reset: string | null,
  retryAfter: string | null,
  now: number
): number | null {
  const headerResetMs = parseResetMsFromHeader(reset);
  const retryAfterMs = parseRetryAfterMs(retryAfter, now);
  if (retryAfterMs === null) return headerResetMs;
  return headerResetMs === null ? retryAfterMs : Math.max(headerResetMs, retryAfterMs);
}

/**
 * Correct local counters from OpenRouter's authoritative rate-limit headers,
 * present on 429 responses per OpenRouter's docs. `Retry-After` (seconds)
 * is folded into the reset timestamp when present and later than the
 * `X-RateLimit-Reset` value.
 */
export function correctFromRateLimitHeaders(
  accountKey: string,
  headers: Headers | Record<string, string>,
  now: number = Date.now()
): void {
  const state = getOrInitState(accountKey, now);
  const limit = getHeader(headers, "x-ratelimit-limit");
  const remaining = getHeader(headers, "x-ratelimit-remaining");

  if (limit !== null && Number.isFinite(Number(limit))) {
    state.serverDailyLimit = Number(limit);
  }
  if (remaining !== null && Number.isFinite(Number(remaining))) {
    state.serverDailyRemaining = Number(remaining);
  }

  const resetMs = resolveResetMs(
    getHeader(headers, "x-ratelimit-reset"),
    getHeader(headers, "retry-after"),
    now
  );
  if (resetMs !== null) {
    state.serverResetAtMs = resetMs;
  }
}

function resolveDailyLimit(state: AccountWindowState): number {
  if (state.serverDailyLimit !== null) return state.serverDailyLimit;
  return state.purchasedAtLeast10 ? DAILY_LIMIT_PURCHASED : DAILY_LIMIT_BASE;
}

function resolveDailyUsed(state: AccountWindowState, dailyLimit: number): number {
  if (state.serverDailyRemaining !== null) {
    return Math.max(0, dailyLimit - state.serverDailyRemaining);
  }
  return state.dayCount;
}

/**
 * Current window status for the account bucket: daily count vs limit
 * (50-or-1000, server-corrected when available) and the 20 RPM rolling
 * window, plus reset timestamps for the dashboard countdown.
 */
export function getFreeWindowStatus(
  accountKey: string,
  now: number = Date.now()
): FreeWindowStatus {
  const state = getOrInitState(accountKey, now);
  pruneRpmWindow(state, now);

  const dailyLimit = resolveDailyLimit(state);
  const dailyUsed = resolveDailyUsed(state, dailyLimit);
  const dailyResetAt =
    state.serverResetAtMs !== null
      ? new Date(state.serverResetAtMs).toISOString()
      : nextUtcMidnightIso(now);

  const rpmUsed = state.requestTimestamps.length;

  return {
    dailyLimit,
    dailyUsed,
    dailyRemaining: Math.max(0, dailyLimit - dailyUsed),
    dailyResetAt,
    rpmLimit: RPM_LIMIT,
    rpmUsed,
    rpmRemaining: Math.max(0, RPM_LIMIT - rpmUsed),
  };
}

/** Test/ops helper — clears all in-memory account window state. */
export function clearFreeWindowState(): void {
  accountWindows.clear();
}

/**
 * SessionPool — Pool manager for anonymous web sessions
 *
 * Manages N sessions across N browser fingerprints, distributing requests
 * round-robin to avoid rate-limiting any single "browser identity."
 *
 * Key behaviors:
 *   - acquire(): Returns the next available session (round-robin)
 *   - reportSuccess(session): Updates metrics, marks session healthy
 *   - reportFailure(session, status): Cooldown on 429, dead on 5xx
 *   - Scalability: Round-robin across sessions prevents one session from
 *     being overused while others sit idle.
 *   - Auto-heal: Sessions in cooldown auto-recover after the backoff window.
 *   - Self-repair: Dead sessions are replaced on next acquire if below maxSessions.
 *   - Thread-safe for concurrent request patterns (each acquire/release pair
 *     is atomic within one async flow).
 *
 * Usage:
 *   const pool = new SessionPool("pollinations", poolConfig, factory);
 *   await pool.ensureMinSessions();
 *   const session = pool.acquire();
 *   try {
 *     const res = await fetch(url, { headers: session.buildHeaders() });
 *     if (!res.ok && res.status === 429) pool.reportCooldown(session);
 *     else pool.reportSuccess(session);
 *   } catch { pool.reportDead(session); }
 *   finally { session.release(); }
 */

import { type EventEmitter } from "node:events";
import { createHash, randomUUID } from "node:crypto";
import { setTimeout as sleep } from "node:timers/promises";

import { Session } from "./session.ts";
import { SessionFactory } from "./sessionFactory.ts";
import {
  type PoolConfig,
  type PoolSessionDetail,
  type PoolStats,
  DEFAULT_POOL_CONFIG,
} from "./types.ts";

export class SessionPool {
  readonly provider: string;
  readonly poolId: string;
  readonly createdAt: number;

  private sessions: Session[] = [];
  private index = 0;
  private config: PoolConfig;
  private factory: SessionFactory;

  // Aggregate stats
  totalRequests = 0;
  successfulRequests = 0;
  rate429count = 0;
  otherErrors = 0;

  // Track throughput
  private startTime: number = Date.now();
  private lastLog = 0;

  constructor(
    provider: string,
    config?: Partial<PoolConfig>,
    factory?: SessionFactory,
  ) {
    this.provider = provider;
    this.poolId = `pool-${provider}-${Date.now().toString(36)}`;
    this.createdAt = Date.now();
    this.config = { ...DEFAULT_POOL_CONFIG, ...config };
    this.factory = factory ?? new SessionFactory(this.config);
  }

  // ─── Pool Lifecycle ──────────────────────────────────────────────────

  /** Ensure the pool has at least minSessions ready */
  async ensureMinSessions(): Promise<void> {
    const needed = this.config.minSessions - this.sessions.length;
    if (needed <= 0) return;

    const promises: Promise<Session>[] = [];
    for (let i = 0; i < needed; i++) {
      promises.push(Promise.resolve(this.createSession()));
    }
    await Promise.allSettled(promises);
  }

  /** Warm up the pool to a specific size (bypasses minSessions limit) */
  async warmUp(count: number): Promise<void> {
    const target = Math.min(count, this.config.maxSessions);
    const needed = target - this.sessions.length;
    if (needed <= 0) return;

    const promises: Promise<Session>[] = [];
    for (let i = 0; i < needed; i++) {
      promises.push(Promise.resolve(this.createSession()));
    }
    await Promise.allSettled(promises);
  }

  /** Graceful shutdown — mark all sessions dead */
  async shutdown(): Promise<void> {
    for (const s of this.sessions) {
      s.markDead();
    }
    this.sessions = [];
  }

  // ─── Acquire / Release ───────────────────────────────────────────────

  /**
   * Acquire the next available session (round-robin with availability check).
   * Returns null if no sessions are available (all on cooldown/dead).
   */
  acquire(): Session | null {
    // First pass: try round-robin from current index
    if (this.sessions.length === 0) return null;

    const startIdx = this.index % this.sessions.length;

    for (let i = 0; i < this.sessions.length; i++) {
      const idx = (startIdx + i) % this.sessions.length;
      const session = this.sessions[idx];
      if (session.isAvailable) {
        // Skip sessions that hit max inflight limit (safety valve)
        // For anonymous web providers we allow high concurrency per session
        this.index = (idx + 1) % this.sessions.length;
        session.acquire();
        this.totalRequests++;
        return session;
      }
    }

    // No ready sessions — try to create a new one if under max
    if (this.sessions.length < this.config.maxSessions) {
      const session = this.createSession();
      session.acquire();
      this.totalRequests++;
      return session;
    }

    // Last resort: wait for the nearest cooldown to expire (caller should retry)
    return null;
  }

  /**
   * Report a successful request. Updates metrics pool-wide and per-session.
   */
  reportSuccess(session: Session): void {
    session.markSuccess();
    this.successfulRequests++;
  }

  /**
   * Report a rate-limit (429). Puts the session into exponential-backoff cooldown.
   */
  reportCooldown(session: Session): void {
    session.markCooldown();
    this.rate429count++;
    this.maybeLog();
  }

  /**
   * Report a non-recoverable error. Marks session as dead.
   */
  reportDead(session: Session): void {
    session.markDead();
    this.otherErrors++;
  }

  // ─── Health / Stats ──────────────────────────────────────────────────

  /** Count of available (active, not in cooldown) sessions */
  get availableCount(): number {
    return this.sessions.filter((s) => s.isAvailable).length;
  }

  /** Number of sessions currently in cooldown */
  get cooldownCount(): number {
    return this.sessions.filter((s) => s.status === "cooldown").length;
  }

  /** Number of dead sessions */
  get deadCount(): number {
    return this.sessions.filter((s) => s.status === "dead").length;
  }

  /** Total sessions managed */
  get totalCount(): number {
    return this.sessions.length;
  }

  /** Current throughput in req/s */
  get currentThroughput(): number {
    const elapsed = (Date.now() - this.startTime) / 1000;
    return elapsed > 0 ? this.totalRequests / elapsed : 0;
  }

  /** Snapshot for dashboard/API */
  getStats(): PoolStats {
    const elapsed = (Date.now() - this.startTime) / 1000;
    return {
      provider: this.provider,
      sessions: {
        total: this.sessions.length,
        active: this.availableCount,
        cooldown: this.cooldownCount,
        dead: this.deadCount,
      },
      requests: {
        total: this.totalRequests,
        success: this.successfulRequests,
        rate429: this.rate429count,
        otherErrors: this.otherErrors,
      },
      throughput: this.currentThroughput.toFixed(1),
      successRate:
        this.totalRequests > 0
          ? ((this.successfulRequests / this.totalRequests) * 100).toFixed(1)
          : "100.0",
      elapsed: elapsed.toFixed(0),
    };
  }

  /** Per-session details */
  getSessionDetails(): PoolSessionDetail[] {
    return this.sessions.map((s) => ({
      id: s.id,
      fingerprint: s.fingerprint.id,
      status: s.status,
      totalRequests: s.totalRequests,
      successfulRequests: s.successfulRequests,
      successRate:
        s.totalRequests > 0
          ? ((s.successfulRequests / s.totalRequests) * 100).toFixed(1)
          : "100.0",
      inflight: s.inflight,
      cooldownRemaining: s.cooldownRemaining > 0
        ? `${(s.cooldownRemaining / 1000).toFixed(1)}s`
        : "0s",
      age: `${(s.age / 1000).toFixed(0)}s`,
    }));
  }

  /** As acquire(), but blocks until a session is available */
  async acquireBlocking(timeoutMs = 10_000): Promise<Session> {
    const deadline = Date.now() + timeoutMs;

    // Fast path
    const fast = this.acquire();
    if (fast) return fast;

    // Wait-loop with backoff (50ms → 200ms)
    let delay = 50;
    while (Date.now() < deadline) {
      await sleep(delay);
      const session = this.acquire();
      if (session) return session;
      delay = Math.min(delay * 2, 200);
    }

    throw new Error(
      `[SessionPool:${this.provider}] No session available after ${timeoutMs}ms timeout`,
    );
  }

  /** As acquireBlocking(), but accepts arbitrary function to wrap */
  async executeWithSession<T>(
    fn: (session: Session) => Promise<T>,
    timeoutMs = 10_000,
  ): Promise<T> {
    const session = await this.acquireBlocking(timeoutMs);
    try {
      const result = await fn(session);
      return result;
    } finally {
      session.release();
    }
  }

  // ─── Internal ────────────────────────────────────────────────────────

  /** Create and register a new session */
  private createSession(): Session {
    const session = this.factory.createSession();
    this.sessions.push(session);
    return session;
  }

  /** Periodic log of pool health (every 5s) */
  private maybeLog(): void {
    const now = Date.now();
    if (now - this.lastLog < 5_000) return;
    this.lastLog = now;

    const stats = this.getStats();
    if (stats.requests.total % 50 === 0) {
      // Rate-limited to avoid log spam
    }
  }

  /** Remove dead sessions and idle sessions older than maxIdleMs */
  pruneDeadSessions(maxIdleMs = 300_000): void {
    const now = Date.now();
    const before = this.sessions.length;
    this.sessions = this.sessions.filter((s) => {
      if (s.status === "dead") return false;
      // Prune idle sessions older than maxIdleMs (default 5min)
      if (s.inflight === 0 && s.lastUsedAt > 0 && now - s.lastUsedAt > maxIdleMs) return false;
      return true;
    });

    // If we pruned sessions, ensure minimum
    if (this.sessions.length < before && this.sessions.length < this.config.minSessions) {
      this.ensureMinSessions();
    }
  }

  /** Start periodic pruning (every 60s) */
  startAutoPrune(intervalMs = 60_000): ReturnType<typeof setInterval> {
    const timer = setInterval(() => this.pruneDeadSessions(), intervalMs);
    timer.unref();
    return timer;
  }
}

/**
 * SessionFactory — Creates initialized Session instances
 *
 * For zero-auth providers (Pollinations, Puter): just assigns a fingerprint.
 * For cookie-based providers (ChatGPT Web, DeepSeek Web): would launch
 * headless Playwright, solve Turnstile, and extract cookies.
 *
 * Currently only zero-auth is implemented. Cookie-based provider support
 * is planned for Phase 3.
 */

import { FingerprintRotator } from "./fingerprintRotator.ts";
import { Session } from "./session.ts";
import type { PoolConfig } from "./types.ts";

export class SessionFactory {
  private rotator = new FingerprintRotator();

  constructor(private config: PoolConfig) {}

  /**
   * Create a new session with the next available fingerprint.
   * For zero-auth providers, this is a lightweight operation
   * (just picks a fingerprint). For cookie-based providers this
   * would involve Playwright browser automation.
   */
  createSession(): Session {
    // Round-robin so each session in a warm pool gets a distinct fingerprint
    // (a pool of look-alike sessions defeats the purpose). The rotator still
    // exposes random() for callers that want unpredictability over time.
    const fingerprint = this.rotator.next();
    return new Session(
      fingerprint,
      this.config.cooldownBase,
      this.config.cooldownMax,
      this.config.cooldownJitter,
    );
  }

  /** Reset the fingerprint rotator (e.g., after config change) */
  resetRotator(): void {
    this.rotator.reset();
  }

  /** Number of available fingerprint profiles */
  get profileCount(): number {
    return this.rotator.count;
  }

  /** Build headers from session fingerprint */
  buildHeaders(
    session: Session,
    extra?: Record<string, string>,
  ): Record<string, string> {
    return session.buildHeaders(extra);
  }
}

