import {
  getGitHubCopilotChatHeaders,
  getGitHubCopilotRefreshHeaders,
} from "../config/providerHeaderProfiles.ts";
import { sanitizeResponsesInputItems } from "../services/responsesInputSanitizer.ts";
import { stripUnsupportedParams } from "../translator/paramSupport.ts";

/**
 * What a Copilot credential refresh resolves to.
 *
 * `refreshCredentials()` returns one of three shapes — the raw GitHub token pair, that pair
 * plus the minted Copilot token, or the Copilot token folded onto the existing credentials —
 * and `null` when nothing could be refreshed. Left to inference, the union of those literals
 * is narrower than the contract subclasses actually honor: `GheCopilotExecutor` carries a
 * wider `providerSpecificData` (it also records the enterprise proxy URL) and omits
 * `expiresIn`, which made a valid override fail with TS2416. Every field is therefore
 * optional here — callers already treat them as such.
 */
export interface RefreshedCopilotCredentials {
  accessToken?: string;
  refreshToken?: string;
  expiresIn?: number;
  copilotToken?: string;
  copilotTokenExpiresAt?: string | number;
  providerSpecificData?: Record<string, unknown>;
}

export class GithubExecutor extends BaseExecutor {
  constructor() {
    super("github", PROVIDERS.github);
  }

  getCopilotToken(credentials: Record<string, any> | null | undefined) {
    return credentials?.copilotToken || credentials?.providerSpecificData?.copilotToken || null;
  }

  getCopilotTokenExpiresAt(credentials: Record<string, any> | null | undefined) {
    return (
      credentials?.copilotTokenExpiresAt ||
      credentials?.providerSpecificData?.copilotTokenExpiresAt ||
      null
    );
  }

  // GitHub Copilot's /responses endpoint only serves OpenAI (gpt/codex) models.
  // Gemini and Claude variants on Copilot reject with HTTP 400
  //   "model <id> does not support Responses API." (unsupported_api_for_model)
  // Pin a defensive invariant: even if a future registry edit (or an upstream
  // model-discovery refresh) tagged a Claude/Gemini entry as openai-responses,
  // the executor must still route it to /chat/completions. Port of 9router#1536
  // (follow-up to #663); also reinforces the existing comments on the gh
  // registry entries (claude-opus-4-5-20251101, claude-opus-4.7, gemini-*).
  supportsResponsesEndpoint(model: string | null | undefined): boolean {
    const m = (model || "").toLowerCase();
    if (!m) return true;
    return !(m.includes("gemini") || m.includes("claude"));
  }

  buildUrl(model: string, _stream: boolean, _urlIndex = 0) {
    const targetFormat = getModelTargetFormat("gh", model);
    // Claude models: route to Copilot's Anthropic-native /v1/messages shim — the
    // only Copilot endpoint that surfaces prompt-cache token counts for Claude and
    // avoids a lossy round-trip of tool_use/tool_result/thinking content blocks
    // through the OpenAI shape. Driven by the registry's per-model targetFormat
    // (see registry/github/index.ts), which chatCore.ts also uses to translate the
    // request to Claude shape before the executor ever sees it.
    // Port of decolua/9router#2608 (author: yidecode).
    if (targetFormat === "claude" && this.config.messagesUrl) {
      return this.config.messagesUrl;
    }
    // 9router#102: Copilot Codex models advertise supported_endpoints: ["/responses"]
    // and 400 on /chat/completions. Route any *-codex id to /responses even when it
    // isn't in the curated registry, so newly-shipped Codex models work out of the box.
    // 9router#1536: but never route Gemini/Claude variants to /responses (they 400) —
    // gate the whole decision on supportsResponsesEndpoint().
    if (
      (targetFormat === "openai-responses" || /codex/i.test(model)) &&
      this.supportsResponsesEndpoint(model)
    ) {
      return (
        this.config.responsesBaseUrl ||
        this.config.baseUrl?.replace(/\/chat\/completions\/?$/, "/responses") ||
        "https://api.githubcopilot.com/responses"
      );
    }
    return this.config.baseUrl;
  }

  injectResponseFormat(messages: Array<Record<string, any>>, responseFormat: any) {
    if (!responseFormat) return messages;

    let formatInstruction = "";
    if (responseFormat.type === "json_object") {
      formatInstruction =
        "Respond only with valid JSON. Do not include any text before or after the JSON object.";
    } else if (responseFormat.type === "json_schema" && responseFormat.json_schema) {
      formatInstruction = `Respond only with valid JSON matching this schema:\n${JSON.stringify(
        responseFormat.json_schema.schema,
        null,
        2
      )}\nDo not include any text before or after the JSON.`;
    }

    if (!formatInstruction) return messages;

    const systemIdx = messages.findIndex((m) => m.role === "system");
    if (systemIdx >= 0) {
      return messages.map((m, i: number) =>
        i === systemIdx ? { ...m, content: `${m.content}\n\n${formatInstruction}` } : m
      );
    }

    return [{ role: "system", content: formatInstruction }, ...messages];
  }

  transformRequest(model: string, body: any, stream: boolean, credentials: any): any {
    void stream;
    void credentials;

    const sourceBody = body && typeof body === "object" ? body : {};
    const modifiedBody = { ...sourceBody };

    // Claude models arrive here already translated to Anthropic-native shape by
    // chatCore.ts (registry targetFormat: "claude" — see registry/github/index.ts)
    // and are dispatched at /v1/messages (buildUrl above), which behaves like the
    // real Anthropic API. None of the /chat/completions-only quirks below apply —
    // content-part flattening would destroy native tool_use/tool_result/thinking
    // blocks, and the native endpoint (unlike Copilot's /chat/completions) honors
    // assistant-message prefill. Port of decolua/9router#2608 (author: yidecode).
    const isClaudeNative = getModelTargetFormat("gh", model) === "claude";

    if (Array.isArray(sourceBody.input)) {
      modifiedBody.input = sanitizeResponsesInputItems(sourceBody.input, false);
    }

    if (Array.isArray(sourceBody.messages)) {
      modifiedBody.messages = sourceBody.messages.map((msg) => {
        if (!msg || typeof msg !== "object") return msg;
        const role = typeof msg.role === "string" ? msg.role.toLowerCase() : "";
        if (role !== "assistant") return msg;
        if (msg.reasoning_text === undefined && msg.reasoning_content === undefined) return msg;
        const next = { ...msg };
        delete next.reasoning_text;
        delete next.reasoning_content;
        return next;
      });
    }

    if (Array.isArray(modifiedBody.tools) && modifiedBody.tools.length > 128) {
      modifiedBody.tools = modifiedBody.tools.slice(0, 128);
    }

    // GitHub Copilot's gpt-5.4 family rejects requests carrying `temperature` with HTTP 400:
    //   "Unsupported parameter: 'temperature' is not supported with this model."
    // OmniRoute's existing `stripGpt5SamplingWhenReasoning` guard only fires for
    // provider==="openai" (raw api.openai.com Chat Completions), so GitHub Copilot routes
    // never hit it. Strip temperature here unconditionally for gpt-5.4 so the 400 cannot
    // reach the user. Port from 9router#612 (closes upstream #536).
    if (
      typeof model === "string" &&
      /gpt-5\.4/i.test(model) &&
      modifiedBody.temperature !== undefined
    ) {
      delete modifiedBody.temperature;
    }

    // The quirks below (response_format-as-system-prompt, content-part flattening,
    // trailing-assistant-prefill drop) are all workarounds for /chat/completions-only
    // limitations. They either don't apply to Claude-shape bodies or actively corrupt
    // them, so they are skipped entirely for the native /v1/messages path. Port of
    // decolua/9router#2608 (author: yidecode) — see class doc comment above.
    if (!isClaudeNative) {
      this.applyChatCompletionsOnlyQuirks(model, modifiedBody);
    }

    // Config-driven strip of params unsupported by the target provider/model.
    // For GitHub Copilot this removes Claude-style `thinking` and
    // `reasoning_effort` for Claude models that reject them upstream
    // (Haiku 4.5 / Opus 4.7 — Opus 4.6 / Sonnet 4.6 keep them).
    // Port from 9router#7ae9fff6 (fixes upstream #1748, #713).
    stripUnsupportedParams("github", model, modifiedBody);

    return modifiedBody;
  }

  // GitHub Copilot's /chat/completions endpoint has several quirks that the native
  // /v1/messages shim doesn't share — extracted from transformRequest so the native
  // path (the common case for Claude models going forward) doesn't pay their branch
  // cost. Mutates modifiedBody in place.
  private applyChatCompletionsOnlyQuirks(model: string, modifiedBody): void {
    // Claude models on /chat/completions don't support response_format — inject the
    // instruction as a system message instead. Port from 9router (see
    // injectResponseFormat above).
    if (modifiedBody.response_format && model.toLowerCase().includes("claude")) {
      modifiedBody.messages = this.injectResponseFormat(
        Array.isArray(modifiedBody.messages) ? modifiedBody.messages : [],
        modifiedBody.response_format
      );
      delete modifiedBody.response_format;
    }

    if (!Array.isArray(modifiedBody.messages)) return;

    // GitHub Copilot /chat/completions only accepts {type:'text'} or {type:'image_url'}
    // content parts. Clients like Cursor IDE pass through Anthropic-shape parts
    // (tool_use, tool_result, thinking) untouched when using Claude models, which makes
    // the endpoint return: "type has to be either 'image_url' or 'text'" (HTTP 400).
    // Serialize unknown part types as text, drop empty parts, and collapse to null when
    // every part is stripped (assistant messages whose only content was tool_calls).
    // Port from 9router#220 (fixes 9router#219).
    modifiedBody.messages = modifiedBody.messages.map((msg: any) =>
      this.sanitizeChatCompletionsMessage(msg)
    );

    // GitHub Copilot's /chat/completions endpoint rejects a conversation that ends
    // with an assistant message: "This model does not support assistant message
    // prefill. The conversation must end with a user message." (HTTP 400). Anthropic
    // clients such as newest Claude Desktop send a trailing assistant turn as a
    // prefill seed — the Anthropic API honors it, but Copilot does not. Drop it here,
    // scoped to the GitHub executor only (the shared translator/contextManager and
    // other providers that DO honor prefill are untouched).
    // Port of 9router#2143 (author: Manuel <baslr@users.noreply.github.com>).
    modifiedBody.messages = this.dropTrailingAssistantPrefill(modifiedBody.messages);
  }

  private sanitizeChatCompletionsMessage(msg: any): any {
    if (!msg || typeof msg !== "object") return msg;
    // String content and missing content (e.g. assistant w/ only tool_calls) pass through.
    if (typeof msg.content === "string" || msg.content == null) return msg;
    if (!Array.isArray(msg.content)) return msg;

    const cleanContent = msg.content
      .map((part: any) => {
        if (!part || typeof part !== "object") return part;
        if (part.type === "text") return part;
        if (part.type === "image_url") return part;
        // Serialize any unsupported part (tool_use, tool_result, thinking, etc.) as text.
        // Try common text-carrying fields first; fall back to a JSON dump so nothing is
        // silently dropped from the model's context.
        const raw =
          (typeof part.text === "string" && part.text) ||
          (typeof part.thinking === "string" && part.thinking) ||
          (typeof part.content === "string" && part.content) ||
          (part.content != null && JSON.stringify(part.content)) ||
          JSON.stringify(part);
        return { type: "text", text: typeof raw === "string" ? raw : JSON.stringify(raw) };
      })
      .filter((part: any) => !(part && part.type === "text" && part.text === ""));

    // If every part stripped to empty (e.g. tool_use with no text), collapse to null so
    // GitHub does not reject an empty-array body. tool_calls ride alongside content.
    return { ...msg, content: cleanContent.length > 0 ? cleanContent : null };
  }

  // Remove trailing assistant message(s). GitHub Copilot's /chat/completions endpoint
  // can't honor an assistant prefill and 400s unless the conversation ends with a
  // non-assistant (user/tool) message. Never empties the array — an assistant-only
  // conversation keeps its last message. No-op (same array reference) when the
  // conversation already ends with a non-assistant message.
  // Port of 9router#2143 (author: Manuel <baslr@users.noreply.github.com>).
  dropTrailingAssistantPrefill(messages: any): any {
    if (!Array.isArray(messages) || messages.length === 0) return messages;
    let end = messages.length;
    while (end > 1 && messages[end - 1]?.role === "assistant") end--;
    return end === messages.length ? messages : messages.slice(0, end);
  }

  async execute(input: ExecuteInput) {
    const result = await super.execute(input);
    // BaseExecutor.execute() is typed as the union it contracts for; the bare-Response
    // arm has nothing to materialize, which is what the existing `!result.response`
    // guard already meant.
    if (result instanceof Response || !result?.response) return result;

    if (!input.stream) {
      // wreq-js clone/text semantics consume the original response body. Materialize
      // non-streaming responses immediately so downstream code always sees a native
      // fetch Response with a readable body.
      const status = result.response.status;
      const statusText = result.response.statusText;
      const headers = new Headers(result.response.headers);
      const payload = await result.response.text();
      result.response = new Response(payload, { status, statusText, headers });
      return result;
    }

    return result;
  }

  buildHeaders(
    credentials: ProviderCredentials,
    stream = true,
    clientHeaders?: Record<string, string> | null,
    model?: string
  ): Record<string, string> {
    const token = this.getCopilotToken(credentials) || credentials.accessToken;
    const initiator = this.resolveInitiatorHeader(clientHeaders);

    const headers: Record<string, string> = {
      ...getGitHubCopilotChatHeaders(stream ? "text/event-stream" : "application/json", initiator),
      Authorization: `Bearer ${token}`,
      "x-request-id":
        crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    };

    // Claude models routed to the Anthropic-native /v1/messages shim require the
    // anthropic-version header (harmless no-op on /chat/completions and /responses,
    // but /v1/messages rejects the request without it). Port of decolua/9router#2608.
    if (model && getModelTargetFormat("gh", model) === "claude") {
      headers["anthropic-version"] = "2023-06-01";
    }

    return headers;
  }

  // Forward the client's x-initiator header when present. OpenCode and other
  // Copilot-aware clients use this to distinguish user-initiated turns
  // (x-initiator: user) from autonomous tool-call continuations
  // (x-initiator: agent). GitHub Copilot's billing treats "agent" turns as
  // free, so forwarding the value avoids burning a premium request on every
  // tool-call round-trip. Falls back to "user" when the header is absent to
  // preserve the existing default behaviour. Extracted from buildHeaders so
  // header assembly stays the one place that reads it.
  private resolveInitiatorHeader(clientHeaders?: Record<string, string> | null): string {
    let clientInitiator = clientHeaders?.["x-initiator"] || clientHeaders?.["X-Initiator"];
    if (!clientInitiator && clientHeaders) {
      for (const key in clientHeaders) {
        if (key.toLowerCase() === "x-initiator") {
          clientInitiator = clientHeaders[key];
          break;
        }
      }
    }
    return clientInitiator === "agent" || clientInitiator === "user" ? clientInitiator : "user";
  }

  async refreshCopilotToken(githubAccessToken, log) {
    try {
      const response = await fetch("https://api.github.com/copilot_internal/v2/token", {
        headers: getGitHubCopilotRefreshHeaders(`token ${githubAccessToken}`),
      });
      if (!response.ok) return null;
      const data = await response.json();
      log?.info?.("TOKEN", "Copilot token refreshed");
      return { token: data.token, expiresAt: data.expires_at };
    } catch (error) {
      log?.error?.("TOKEN", `Copilot refresh error: ${error.message}`);
      return null;
    }
  }

  async refreshGitHubToken(refreshToken, log) {
    try {
      // GitHub Copilot is a public device-flow client: send the public client_id, and
      // only attach client_secret when one is actually configured — never the literal
      // "undefined" that new URLSearchParams produces for a missing value (9router#442).
      const params = new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: refreshToken,
        client_id: this.config.clientId,
      });
      if (this.config.clientSecret) {
        params.set("client_secret", this.config.clientSecret);
      }
      const response = await fetch(OAUTH_ENDPOINTS.github.token, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Accept: "application/json",
        },
        body: params,
      });
      if (!response.ok) return null;
      const tokens = await response.json();
      log?.info?.("TOKEN", "GitHub token refreshed");
      return {
        accessToken: tokens.access_token,
        refreshToken: tokens.refresh_token || refreshToken,
        expiresIn: tokens.expires_in,
      };
    } catch (error) {
      log?.error?.("TOKEN", `GitHub refresh error: ${error.message}`);
      return null;
    }
  }

  async refreshCredentials(credentials, log): Promise<RefreshedCopilotCredentials | null> {
    let copilotResult = await this.refreshCopilotToken(credentials.accessToken, log);

    if (!copilotResult && credentials.refreshToken) {
      const githubTokens = await this.refreshGitHubToken(credentials.refreshToken, log);
      if (githubTokens?.accessToken) {
        copilotResult = await this.refreshCopilotToken(githubTokens.accessToken, log);
        if (copilotResult) {
          return {
            ...githubTokens,
            copilotToken: copilotResult.token,
            copilotTokenExpiresAt: copilotResult.expiresAt,
            providerSpecificData: {
              copilotToken: copilotResult.token,
              copilotTokenExpiresAt: copilotResult.expiresAt,
            },
          };
        }
        return githubTokens;
      }
    }

    if (copilotResult) {
      return {
        accessToken: credentials.accessToken,
        refreshToken: credentials.refreshToken,
        copilotToken: copilotResult.token,
        copilotTokenExpiresAt: copilotResult.expiresAt,
        providerSpecificData: {
          copilotToken: copilotResult.token,
          copilotTokenExpiresAt: copilotResult.expiresAt,
        },
      };
    }

    return null;
  }

  needsRefresh(credentials) {
    // Always refresh if no copilotToken
    if (!this.getCopilotToken(credentials)) return true;

    const copilotTokenExpiresAt = this.getCopilotTokenExpiresAt(credentials);
    if (copilotTokenExpiresAt) {
      // Handle both Unix timestamp (seconds) and ISO string
      let expiresAtMs = copilotTokenExpiresAt;
      if (typeof expiresAtMs === "number" && expiresAtMs < 1e12) {
        expiresAtMs = expiresAtMs * 1000; // Convert seconds to ms
      } else if (typeof expiresAtMs === "string") {
        expiresAtMs = new Date(expiresAtMs).getTime();
      }
      if (expiresAtMs - Date.now() < 5 * 60 * 1000) return true;
    }
    return super.needsRefresh(credentials);
  }
}

export default GithubExecutor;

// Strip request params a given provider/model rejects upstream (e.g. HTTP 400).
// Config-driven: add a rule here instead of scattering `delete body.x` across
// executors. Port from 9router#7ae9fff6 (fixes upstream #1748).
//
// Rule semantics:
//   - `provider` (optional) limits the rule to a single provider id.
//   - `match` is a RegExp tested against the model id OR a predicate (model -> boolean).
//   - `drop` is the list of param keys to remove when the rule fires.
//   - `clampToModelMaxOutput` clamps max_tokens/max_completion_tokens/max_output_tokens
//     down to the model's catalog `maxOutputTokens` ceiling, when one is set.
//   - `maxOutputCap` clamps the same keys down to a fixed endpoint-imposed ceiling
//     (independent of the model's own advertised ceiling). When both are present on
//     the same rule, the lower of the two wins.
//
// A param is removed only when it is present (!== undefined). The helper never
// introduces new keys and never throws on null/undefined bodies — call sites
// can chain it without extra guards.

import { getParamFilterConfig, ModelParamFilter, ProviderParamFilter } from "@/lib/db/paramFilters";
import { getProviderModel } from "../config/providerModels.ts";

type StripRule = {
  provider?: string;
  match: RegExp | ((model: string) => boolean);
  drop?: string[];
  clampToModelMaxOutput?: boolean;
  maxOutputCap?: number;
};

const MAX_OUTPUT_TOKEN_KEYS = ["max_tokens", "max_completion_tokens", "max_output_tokens"] as const;

const STRIP_RULES: StripRule[] = [
  // claude-opus-4 series: temperature is deprecated (Anthropic returns 400). #1748
  { match: /claude-opus-4/i, drop: ["temperature"] },
  // GitHub Copilot gpt-5.4: temperature unsupported.
  { provider: "github", match: /gpt-5\.4/i, drop: ["temperature"] },
  // GitHub Copilot Claude (except opus/sonnet 4.6): thinking + reasoning_effort rejected. #713
  {
    provider: "github",
    match: (m: string) => /claude/i.test(m) && !/claude.*(opus|sonnet).*4\.6/i.test(m),
    drop: ["thinking", "reasoning_effort"],
  },
  // NVIDIA NIM z-ai/glm-5.2: OpenAI-compatible wrapper rejects BOTH the `reasoning`
  // body field (#6102) and the Claude-style `thinking` field. A Claude-format
  // client (e.g. Claude Code) routed here leaves a `thinking:{type:"adaptive"}`
  // that the wrapper 400s on — same class already handled for minimax-m2.7 below.
  // 9router#2023.
  { provider: "nvidia", match: /z-ai\/glm-5\.2\b/i, drop: ["reasoning", "thinking"] },
  // NVIDIA NIM minimaxai/minimax-m2.7: NVIDIA's OpenAI-compatible wrapper
  // (format:"openai") does not accept the Claude-style `thinking` body field
  // and returns 400 "Unsupported parameter(s): thinking". Upstream #2268.
  { provider: "nvidia", match: /minimax-m2\.7/i, drop: ["thinking"] },
  // NVIDIA NIM: OpenAI-compatible wrapper 400s on `prompt_cache_key` (Codex CLI
  // injects it natively for its own prompt caching). NIM has no documented
  // support for this field (providerSupportsCaching already treats nvidia as
  // non-cache-capable) — safe to drop provider-wide, not model-specific. #7617.
  { provider: "nvidia", match: /.*/, drop: ["prompt_cache_key"] },
  // VolcEngine Ark caps the Kimi coding-plan endpoint at max_tokens <= 32768
  // server-side ("integer above maximum value, expected a value <= 32768"),
  // independent of the model's own catalog ceiling. Confirmed against two
  // independent live-endpoint reports hitting the same Ark endpoint for both
  // kimi-k2.5 and kimi-k2.7-code (NousResearch/hermes-agent#51773,
  // MoonshotAI/kimi-cli#1124), and by upstream decolua/9router#2460. Scoped to
  // OmniRoute's actual volcengine Kimi id (not a broad /kimi/i regex) so it
  // never clamps an unrelated future Kimi listing whose Ark cap may differ.
  { provider: "volcengine", match: /^kimi-k2-5-260127$/, maxOutputCap: 32768, clampToModelMaxOutput: true },
  // #7364: Z.AI's glm-4.6v vision endpoint enforces a 32768 max_tokens ceiling
  // server-side and 400s when a client sends a larger explicit max_tokens (e.g. a
  // client defaulting to 65536). Scoped to both wire paths that can reach this
  // model: "zai" (DefaultExecutor, Claude format by default — glm-4.6v is only
  // reachable there as a custom model attached to the connection, so it is NOT in
  // PROVIDER_MODELS["zai"] and clampToModelMaxOutput would find no catalog ceiling
  // to clamp against, hence the fixed maxOutputCap) and "glm" (GlmExecutor, OpenAI
  // format — glm-4.6v IS in the registry catalog there, `GLM_SHARED_MODELS` in
  // glmProvider.ts, maxOutputTokens: 32768, so clampToModelMaxOutput suffices).
  { provider: "zai", match: /^glm-4\.6v$/i, maxOutputCap: 32768 },
  { provider: "glm", match: /^glm-4\.6v$/i, clampToModelMaxOutput: true },
];

function matches(rule: StripRule, model: string): boolean {
  return typeof rule.match === "function" ? rule.match(model) : rule.match.test(model);
}

/**
 * When a rule requests it, clamp the max-output-token family of params down to
 * the lowest applicable ceiling: the model's own catalog `maxOutputTokens`
 * (`clampToModelMaxOutput`) and/or a fixed endpoint cap (`maxOutputCap`). Only
 * clamps keys that are present and numeric; never introduces a new key.
 */
function applyMaxOutputClamp(
  rule: StripRule,
  provider: string | null | undefined,
  model: string,
  body: Record<string, unknown>
): void {
  if (!rule.clampToModelMaxOutput && !Number.isFinite(rule.maxOutputCap)) return;

  const candidates: number[] = [];
  if (rule.clampToModelMaxOutput) {
    const modelCeiling = getProviderModel(provider ?? "", model)?.maxOutputTokens;
    if (Number.isFinite(modelCeiling) && (modelCeiling as number) > 0) {
      candidates.push(modelCeiling as number);
    }
  }
  if (Number.isFinite(rule.maxOutputCap) && (rule.maxOutputCap as number) > 0) {
    candidates.push(rule.maxOutputCap as number);
  }
  if (candidates.length === 0) return;

  const ceiling = Math.min(...candidates);
  for (const key of MAX_OUTPUT_TOKEN_KEYS) {
    const value = body[key];
    if (typeof value === "number" && Number.isFinite(value) && value > ceiling) {
      body[key] = ceiling;
    }
  }
}

/**
 * Remove unsupported params from `body` in place. Returns the same reference
 * (or `body` unchanged when it is not a plain object / model is empty).
 */
export function stripUnsupportedParams<T>(
  provider: string | null | undefined,
  model: string | null | undefined,
  body: T
): T {
  if (!model || !body || typeof body !== "object") return body;
  const rec = body as unknown as Record<string, unknown>;
  // Snapshot the original body before any mutations so the allowlist can
  // restore params that were stripped by hardcoded or config-driven denylist.
  const snapshot = { ...rec };

  // Phase 1: Hardcoded rules (unchanged)
  for (const rule of STRIP_RULES) {
    if (rule.provider && rule.provider !== provider) continue;
    if (!matches(rule, model)) continue;
    for (const key of rule.drop ?? []) {
      if (rec[key] !== undefined) delete rec[key];
    }
    applyMaxOutputClamp(rule, provider, model, rec);
  }

  // Phase 2: Config-driven rules from DB
  applyConfigFilters(provider, model, rec, snapshot);

  return body;
}

/**
 * Restore keys from `snapshot` into `body` for every key listed in `allow`,
 * but only when the key was present in the original request. Shared by the
 * provider-level and model-level allowlist passes below.
 */
function restoreAllowedKeys(
  body: Record<string, unknown>,
  snapshot: Record<string, unknown>,
  allow: readonly string[]
): void {
  for (const key of allow) {
    if (key in snapshot) {
      body[key] = snapshot[key];
    }
  }
}

/**
 * Apply the provider-level denylist, then restore the provider-level
 * allowlist from `snapshot`. Runs BEFORE model-level operations so
 * model-level settings can override provider-level ones.
 */
function applyProviderLevelFilters(
  body: Record<string, unknown>,
  snapshot: Record<string, unknown>,
  config: ProviderParamFilter
): void {
  for (const key of config.block) {
    delete body[key];
  }
  if (config.allow.length > 0) {
    restoreAllowedKeys(body, snapshot, config.allow);
  }
}

/**
 * Apply the model-level denylist (overrides the provider-level allowlist),
 * then restore the model-level allowlist from `snapshot` (final pass, most
 * specific wins).
 */
function applyModelLevelFilters(
  body: Record<string, unknown>,
  snapshot: Record<string, unknown>,
  modelCfg: ModelParamFilter | undefined
): void {
  if (modelCfg?.block) {
    for (const key of modelCfg.block) {
      delete body[key];
    }
  }
  if (modelCfg?.allow) {
    restoreAllowedKeys(body, snapshot, modelCfg.allow);
  }
}

/**
 * Apply config-driven denylist + allowlist rules from the DB-backed
 * ProviderParamFilter store. Order of operations:
 *   1. Provider-level denylist
 *   2. Model-level denylist
 *   3. Provider-level allowlist (restores from snapshot)
 *   4. Model-level allowlist (restores from snapshot)
 *
 * The allowlist only restores keys that were present in the original request
 * (the snapshot). It never introduces new params the client didn't send.
 */
export function applyConfigFilters(
  provider: string | null | undefined,
  model: string | null | undefined,
  body: Record<string, unknown>,
  snapshot: Record<string, unknown>
): void {
  if (!provider || !body) return;
  const config = getParamFilterConfig(provider);
  if (!config) return;

  applyProviderLevelFilters(body, snapshot, config);

  const modelCfg = config.models?.[model ?? ""];
  applyModelLevelFilters(body, snapshot, modelCfg);
}

// Exported for unit tests only — do not import from production code.
export const __STRIP_RULES_FOR_TEST: ReadonlyArray<StripRule> = STRIP_RULES;

import { GithubExecutor } from "./github.ts";
import type { ProviderCredentials, ExecuteInput, ExecutorLog } from "./base.ts";
import { getModelTargetFormat } from "../config/providerModels.ts";

/** Result of a successful GHE Copilot internal token exchange. */
type CopilotTokenResult = {
  token: string;
  expiresAt: string | number;
  endpoints?: { proxy?: string; api?: string };
};

export class GheCopilotExecutor extends GithubExecutor {
  constructor(config?: Record<string, unknown>) {
    super("ghe-copilot", {
      format: "openai",
      baseUrl: "https://api.githubcopilot.com/chat/completions",
      responsesBaseUrl: "https://api.githubcopilot.com/responses",
      authType: "oauth",
      authHeader: "bearer",
      ...config,
    });
  }

  /**
   * Derive the base URL for chat/completions from gheUrl in providerSpecificData.
   * Appends /chat/completions if not already present.
   */
  private getChatCompletionsBase(credentials: ProviderCredentials | null): string {
    // The GHE token endpoint returns TWO hosts:
    //   endpoints.api   → copilotApiUrl   (chat/completions + the /models catalog)
    //   endpoints.proxy → copilotProxyUrl (NES / autocomplete / instant-apply only)
    // Chat MUST go to the api host. The proxy host only serves the completion
    // models (copilot-nes-*, instant-apply, suggestions) and 404s/errors for
    // real chat models. Prefer copilotApiUrl, fall back to copilotProxyUrl for
    // legacy connections, then the static gheUrl/chat/completions path.
    const psd = credentials?.providerSpecificData;
    const apiOrProxy =
      (typeof psd?.copilotApiUrl === "string" ? psd.copilotApiUrl : undefined) ||
      (typeof psd?.copilotProxyUrl === "string" ? psd.copilotProxyUrl : undefined);
    if (apiOrProxy) {
      const base = apiOrProxy.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "").replace(/\/+$/, "");
      return base.endsWith("/chat/completions") ? base : `${base}/chat/completions`;
    }
    const gheUrl = psd?.gheUrl as string | undefined;
    if (!gheUrl) {
      throw new Error("GHE Copilot executor requires gheUrl in providerSpecificData");
    }
    const base = gheUrl.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "").replace(/\/+$/, "");
    return base.endsWith("/chat/completions") ? base : `${base}/chat/completions`;
  }

  /**
   * Derive the base URL for /responses from gheUrl in providerSpecificData.
   * Appends /responses if not already present.
   */
  private getResponsesBase(credentials: ProviderCredentials | null): string {
    const psd = credentials?.providerSpecificData;
    const apiOrProxy =
      (typeof psd?.copilotApiUrl === "string" ? psd.copilotApiUrl : undefined) ||
      (typeof psd?.copilotProxyUrl === "string" ? psd.copilotProxyUrl : undefined);
    if (apiOrProxy) {
      const base = apiOrProxy.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "").replace(/\/+$/, "");
      return `${base}/responses`;
    }
    const gheUrl = psd?.gheUrl as string | undefined;
    if (!gheUrl) {
      throw new Error("GHE Copilot executor requires gheUrl in providerSpecificData");
    }
    const base = gheUrl.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "").replace(/\/+$/, "");
    return `${base}/responses`;
  }

  /**
   * Strip the `ghe-copilot/` provider prefix from a model id so the upstream
   * GHE Copilot proxy receives the bare id (e.g. `gpt-5-mini`).
   */
  private stripPrefix(model: string): string {
    return typeof model === "string" && model.startsWith("ghe-copilot/")
      ? model.slice("ghe-copilot/".length)
      : model;
  }

  override buildUrl(model: string, stream: boolean, urlIndex = 0, credentials: ProviderCredentials | null = null): string {
    const bareModel = this.stripPrefix(model);
    const targetFormat = getModelTargetFormat("ghe-copilot", bareModel);
    if (
      (targetFormat === "openai-responses" || /codex/i.test(bareModel)) &&
      this.supportsResponsesEndpoint(bareModel)
    ) {
      return this.getResponsesBase(credentials);
    }
    return this.getChatCompletionsBase(credentials);
  }

  /**
   * Strip the `ghe-copilot/` provider prefix from the model before sending to
   * the upstream GHE Copilot proxy, which expects bare model ids.
   */
  override transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ): unknown {
    const bareModel = this.stripPrefix(model);
    const transformed = super.transformRequest(bareModel, body, stream, credentials);
    if (transformed && typeof transformed === "object") {
      const record = transformed as Record<string, unknown>;
      if (typeof record.model === "string") {
        record.model = this.stripPrefix(record.model);
      }
      // GHE Copilot proxy is streaming-only: force stream:true upstream
      // (chatCore drains the SSE back to JSON for non-stream clients).
      record.stream = true;
    }
    return transformed;
  }

  override async refreshCopilotToken(
    githubAccessToken: string,
    log?: { info?: (cat: string, msg: string) => void; error?: (cat: string, msg: string) => void },
    credentials?: ProviderCredentials | null
  ): Promise<CopilotTokenResult | null> {
    const gheUrl = credentials?.providerSpecificData?.gheUrl as string | undefined;
    if (!gheUrl) return null;

    try {
      const baseUrl = gheUrl.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "");
      const tokenUrl = `${baseUrl}/api/v3/copilot_internal/v2/token`;

      const response = await fetch(tokenUrl, {
        headers: {
          Authorization: `Bearer ${githubAccessToken}`,
          Accept: "application/json",
        },
      });

      if (!response.ok) return null;
      const data = await response.json();
      log?.info?.("TOKEN", "GHE Copilot token refreshed");
      // GHE returns a dynamic `endpoints` object; the chat/responses proxy host
      // lives at endpoints.proxy (NOT a static path on the GHE web host).
      const endpoints = data.endpoints
        ? { proxy: data.endpoints.proxy, api: data.endpoints.api }
        : undefined;
      return {
        token: data.token,
        expiresAt: data.expires_at,
        ...(endpoints ? { endpoints } : {}),
      };
    } catch (error) {
      log?.error?.("TOKEN", `GHE Copilot refresh error: ${error.message}`);
      return null;
    }
  }

  override async refreshGitHubToken(
    refreshToken: string,
    log?: { info?: (cat: string, msg: string) => void; error?: (cat: string, msg: string) => void },
    credentials?: ProviderCredentials | null
  ): Promise<{
    accessToken: string;
    refreshToken: string;
    expiresIn: number;
  } | null> {
    const gheUrl = credentials?.providerSpecificData?.gheUrl as string | undefined;
    if (!gheUrl) return null;

    try {
      // GHE OAuth token endpoint
      const baseUrl = gheUrl.replace(/\/chat\/completions\/?$/, "").replace(/\/responses\/?$/, "");
      const tokenUrl = `${baseUrl}/login/oauth/access_token`;

      const params = new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: refreshToken,
        client_id: this.config.clientId,
      });

      if (this.config.clientSecret) {
        params.set("client_secret", this.config.clientSecret);
      }

      const response = await fetch(tokenUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Accept: "application/json",
        },
        body: params,
      });

      if (!response.ok) return null;
      const tokens = await response.json();
      log?.info?.("TOKEN", "GHE GitHub token refreshed");
      return {
        accessToken: tokens.access_token,
        refreshToken: tokens.refresh_token || refreshToken,
        expiresIn: tokens.expires_in,
      };
    } catch (error) {
      log?.error?.("TOKEN", `GHE GitHub refresh error: ${error.message}`);
      return null;
    }
  }

  /**
   * Merge a fresh Copilot token result into providerSpecificData, preserving
   * existing fields and updating the token/expiry/endpoint bookkeeping GHE
   * Copilot needs (copilotApiUrl for chat/models, copilotProxyUrl legacy
   * fallback, gheUrl for the next refresh round-trip).
   */
  private buildRefreshedProviderSpecificData(
    credentials: ProviderCredentials,
    copilotResult: CopilotTokenResult
  ): Record<string, unknown> {
    return {
      ...credentials?.providerSpecificData,
      copilotToken: copilotResult.token,
      copilotTokenExpiresAt: copilotResult.expiresAt,
      copilotApiUrl: copilotResult.endpoints?.api,
      copilotProxyUrl: copilotResult.endpoints?.proxy,
      gheUrl: credentials?.providerSpecificData?.gheUrl,
    };
  }

  /**
   * Fallback path when the cached GitHub access token can no longer mint a
   * Copilot token directly: refresh the GitHub OAuth token first, then retry
   * the Copilot token exchange with the new access token.
   */
  private async refreshViaGitHubToken(credentials: ProviderCredentials, log?: ExecutorLog | null) {
    const githubTokens = await this.refreshGitHubToken(
      credentials.refreshToken as string,
      log,
      credentials
    );
    if (!githubTokens?.accessToken) return null;

    const copilotResult = await this.refreshCopilotToken(githubTokens.accessToken, log, credentials);
    if (!copilotResult) return githubTokens;

    return {
      ...githubTokens,
      copilotToken: copilotResult.token,
      copilotTokenExpiresAt: copilotResult.expiresAt,
      providerSpecificData: this.buildRefreshedProviderSpecificData(credentials, copilotResult),
    };
  }

  /**
   * Refresh credentials and capture the GHE Copilot proxy URL (endpoints.proxy)
   * returned by the token endpoint, storing it in providerSpecificData so
   * buildUrl routes chat/responses traffic to the correct enterprise host.
   */
  override async refreshCredentials(credentials: ProviderCredentials, log?: ExecutorLog | null) {
    const copilotResult = await this.refreshCopilotToken(credentials?.accessToken, log, credentials);

    if (!copilotResult && credentials?.refreshToken) {
      return this.refreshViaGitHubToken(credentials, log);
    }

    if (copilotResult) {
      return {
        accessToken: credentials?.accessToken,
        refreshToken: credentials?.refreshToken,
        copilotToken: copilotResult.token,
        copilotTokenExpiresAt: copilotResult.expiresAt,
        providerSpecificData: this.buildRefreshedProviderSpecificData(credentials, copilotResult),
      };
    }

    return null;
  }
}

export default GheCopilotExecutor;

import {
  BaseExecutor,
  mergeUpstreamExtraHeaders,
  setUserAgentHeader,
  type ExecuteInput,
  type ProviderCredentials,
} from "./base.ts";
import { PROVIDERS } from "../config/constants.ts";
import {
  getQoderDashscopeCompatHeaders,
  QODER_DEFAULT_USER_AGENT,
} from "../config/providerHeaderProfiles.ts";
import { randomUUID } from "node:crypto";
import { sanitizeQwenThinkingToolChoice } from "../services/qwenThinking.ts";
import {
  buildQoderChunk,
  buildQoderCompletionPayload,
  buildQoderPrompt,
  createQoderErrorResponse,
  parseQoderCliFailure,
  parseQoderCliResult,
  runQoderCli,
} from "../services/qoderCli.ts";
import { sanitizeErrorMessage } from "../utils/error.ts";

function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}…`;
}

/**
 * Wrap a full qodercli reply as an OpenAI-compatible SSE stream (role chunk →
 * content chunk → stop chunk → [DONE]). qodercli's `--print` mode returns the
 * whole answer at once, so there are no incremental deltas to forward.
 */
function buildQoderCliSseStream(model: string, text: string): ReadableStream<Uint8Array> {
  const id = `chatcmpl-${randomUUID()}`;
  const created = Math.floor(Date.now() / 1000);
  const encoder = new TextEncoder();
  const send = (obj: unknown) => encoder.encode(`data: ${JSON.stringify(obj)}\n\n`);
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(
        send(buildQoderChunk({ id, model, created, delta: { role: "assistant", content: "" } }))
      );
      if (text) {
        controller.enqueue(send(buildQoderChunk({ id, model, created, delta: { content: text } })));
      }
      controller.enqueue(
        send(buildQoderChunk({ id, model, created, delta: {}, finishReason: "stop" }))
      );
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      controller.close();
    },
  });
}

/**
 * Peek at the first SSE event from a Qoder response to detect upstream errors
 * that Qoder wraps inside an HTTP 200 SSE envelope ({statusCodeValue, body}).
 * Returns a proper HTTP error Response when found, so downstream fallback
 * logic (combo routing, account fallback) can trigger. For success, re-creates
 * the stream with the first chunk prepended so the body passes through
 * transparently.
 */
async function unwrapQoderEnvelope(response: Response): Promise<Response> {
  if (!response.ok || !response.body) {
    return response;
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();

  const { done, value } = await reader.read();
  if (done) {
    reader.cancel();
    return new Response(
      JSON.stringify({ error: { message: "[qoder] empty response", type: "provider_error" } }),
      { status: 502, headers: { "Content-Type": "application/json" } }
    );
  }

  const text = decoder.decode(value, { stream: true });

  let errorStatus: number | null = null;
  let errorMsg = "";
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) continue;
    const jsonStr = trimmed.slice(5).trim();
    if (jsonStr === "[DONE]") break;
    try {
      const envelope = JSON.parse(jsonStr) as Record<string, unknown>;
      const statusVal =
        typeof envelope.statusCodeValue === "number" ? envelope.statusCodeValue : 200;
      if (statusVal !== 200) {
        errorStatus = statusVal >= 400 ? statusVal : 502;
        errorMsg =
          typeof envelope.body === "string" ? envelope.body : `upstream status ${statusVal}`;
      }
    } catch {
      // Malformed JSON — treat as non-error; downstream handling parses it.
    }
    break;
  }

  if (errorStatus) {
    reader.cancel();
    const errType =
      errorStatus === 401 || errorStatus === 403 ? "authentication_error" : "provider_error";
    return new Response(
      JSON.stringify({
        error: {
          message: `[qoder error ${errorStatus}: ${sanitizeErrorMessage(truncate(errorMsg, 200))}]`,
          type: errType,
        },
      }),
      { status: errorStatus, headers: { "Content-Type": "application/json" } }
    );
  }

  // Re-create the stream with the first chunk prepended so the success body
  // passes through unchanged.
  const restStream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(value);
    },
    pull(controller) {
      return reader.read().then(({ done, value }) => {
        if (done) {
          controller.close();
          return;
        }
        controller.enqueue(value);
      });
    },
    cancel() {
      reader.cancel();
    },
  });

  return new Response(restStream, {
    status: response.status,
    statusText: response.statusText,
    headers: new Headers(response.headers),
  });
}

function getAuthToken(credentials: ProviderCredentials): string {
  if (typeof credentials.apiKey === "string" && credentials.apiKey.trim()) {
    return credentials.apiKey.trim();
  }
  if (typeof credentials.accessToken === "string" && credentials.accessToken.trim()) {
    return credentials.accessToken.trim();
  }
  if (typeof credentials.refreshToken === "string" && credentials.refreshToken.trim()) {
    return credentials.refreshToken.trim();
  }
  // Fallback: QODER_PERSONAL_ACCESS_TOKEN env var (#966)
  const envToken = String(process.env.QODER_PERSONAL_ACCESS_TOKEN || "").trim();
  if (envToken) return envToken;
  return "";
}

export class QoderExecutor extends BaseExecutor {
  constructor() {
    super("qoder", PROVIDERS.qoder);
  }

  buildHeaders(
    credentials: ProviderCredentials,
    stream = true,
    clientHeaders?: Record<string, string> | null,
    model?: string
  ): Record<string, string> {
    const headers = super.buildHeaders(credentials, stream, clientHeaders, model);
    setUserAgentHeader(headers, QODER_DEFAULT_USER_AGENT);
    return headers;
  }

  transformRequest(model: string, body: unknown): Record<string, unknown> {
    const payload = {
      ...(typeof body === "object" && body !== null ? body : {}),
      model,
    };

    return sanitizeQwenThinkingToolChoice(payload, "QoderExecutor");
  }

  async execute({ model, body, stream, credentials, signal, upstreamExtraHeaders }: ExecuteInput) {
    const token = getAuthToken(credentials);

    if (!token) {
      return {
        response: new Response(
          JSON.stringify({
            error: {
              message: "Qoder access token or API Key is required. Please sign in or set a PAT.",
              type: "authentication_error",
              code: "token_required",
            },
          }),
          { status: 401, headers: { "Content-Type": "application/json" } }
        ),
        url: "https://dashscope.aliyuncs.com",
        headers: { "Content-Type": "application/json" },
        transformedBody: body,
      };
    }

    const resolvedModel = model || "qwen3.8-max-preview";

    // Detect token type: PAT (Personal Access Token) starts with "pt-".
    // PATs are driven through the local qodercli binary (see executeViaQoderCli);
    // only the qodercli binary can produce the WASM-signed Cosy request the raw
    // HTTP path can no longer replicate.
    const isPatToken = token.startsWith("pt-");
    if (isPatToken) {
      return this.executeViaQoderCli({ model: resolvedModel, body, stream, token, signal });
    }

    // Non-PAT tokens (OAuth apiKey / DashScope key) → DashScope OpenAI-compatible API.
    let mappedModel = resolvedModel;
    if (resolvedModel === "qwen3.5-plus" || resolvedModel === "qwen3.6-plus") {
      mappedModel = "coder-model";
    } else if (resolvedModel === "vision-model") {
      mappedModel = "qwen3-vl-plus";
    }
    let endpointUrl = "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions";

    // Check for custom API base via credentials (overrides the default)
    let credentialsApiBase: unknown;
    if (typeof credentials === "object" && credentials !== null) {
      const credsObj = credentials as Record<string, unknown>;
      credentialsApiBase = credsObj.customApiBase || credsObj.resourceUrl;
    }
    if (typeof credentialsApiBase === "string" && credentialsApiBase.trim()) {
      let base = credentialsApiBase.trim();
      if (!base.startsWith("http")) base = `https://${base}`;
      if (!base.endsWith("/v1")) base = base.endsWith("/") ? `${base}v1` : `${base}/v1`;
      endpointUrl = `${base}/chat/completions`;
    }

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
      ...getQoderDashscopeCompatHeaders(),
    };

    mergeUpstreamExtraHeaders(headers, upstreamExtraHeaders);

    const payload = this.transformRequest(mappedModel, body);

    const bodyStr = JSON.stringify(payload);

    try {
      const response = await fetch(endpointUrl, {
        method: "POST",
        headers,
        body: bodyStr,
        signal,
      });

      if (!response.ok) {
        let errText = await response.text();
        return {
          response: new Response(
            JSON.stringify({
              error: {
                message: `Qoder API failed with status ${response.status}: ${errText}`,
                type: response.status === 401 ? "authentication_error" : "provider_error",
              },
            }),
            { status: response.status, headers: { "Content-Type": "application/json" } }
          ),
          url: endpointUrl,
          headers,
          transformedBody: payload,
        };
      }

      // Qoder wraps upstream errors inside an HTTP 200 SSE envelope
      // ({statusCodeValue}). Peek at the first event to detect this and return
      // a proper HTTP error so combo/account fallback logic can trigger.
      const unwrapped = await unwrapQoderEnvelope(response);
      return {
        response: unwrapped,
        url: endpointUrl,
        headers,
        transformedBody: payload,
      };
    } catch (e: unknown) {
      const error = e as Error;
      if (error.name === "AbortError") {
        throw error;
      }
      return {
        response: new Response(
          JSON.stringify({
            error: {
              message: `Qoder fetch error: ${sanitizeErrorMessage(error.message)}`,
              type: "provider_error",
            },
          }),
          { status: 502, headers: { "Content-Type": "application/json" } }
        ),
        url: endpointUrl,
        headers,
        transformedBody: payload,
      };
    }
  }

  /**
   * Drive a PAT (`pt-*`) completion through the local qodercli binary. The CLI
   * performs Qoder's WASM-signed Cosy auth internally, so this is the only path
   * that works for PATs now that the pure-HTTP Cosy reimplementation is dead.
   */
  private async executeViaQoderCli({
    model,
    body,
    stream,
    token,
    signal,
  }: {
    model: string;
    body: unknown;
    stream: boolean;
    token: string;
    signal?: AbortSignal | null;
  }): Promise<{
    response: Response;
    url: string;
    headers: Record<string, string>;
    transformedBody: unknown;
  }> {
    const url = "qodercli://stdio";
    const prompt = buildQoderPrompt(body);

    const run = await runQoderCli({ token, prompt, stream: false, model, signal });

    // Honor client cancellation the same way the HTTP path does.
    if (signal?.aborted) {
      const abortError = new Error("Aborted");
      abortError.name = "AbortError";
      throw abortError;
    }

    if (run.error && /enoent|not found|no such file|spawn/i.test(run.error)) {
      return {
        response: createQoderErrorResponse({
          status: 502,
          message:
            `Qoder CLI (qodercli) was not found on the OmniRoute host (${run.error}). ` +
            "Install it from https://qoder.com or set CLI_QODER_BIN to its path.",
          code: "cli_not_found",
        }),
        url,
        headers: {},
        transformedBody: body,
      };
    }

    if (!run.ok) {
      return {
        response: createQoderErrorResponse(parseQoderCliFailure(run.stderr, run.stdout)),
        url,
        headers: {},
        transformedBody: body,
      };
    }

    const { text, isError, errorMessage } = parseQoderCliResult(run.stdout);
    if (isError) {
      return {
        response: createQoderErrorResponse(parseQoderCliFailure(errorMessage)),
        url,
        headers: {},
        transformedBody: body,
      };
    }

    if (stream) {
      return {
        response: new Response(buildQoderCliSseStream(model, text), {
          status: 200,
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache",
            Connection: "keep-alive",
          },
        }),
        url,
        headers: {},
        transformedBody: body,
      };
    }

    return {
      response: new Response(JSON.stringify(buildQoderCompletionPayload({ model, text })), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
      url,
      headers: {},
      transformedBody: body,
    };
  }
}

