type ZaiCredentialsLike = {
  providerSpecificData?: { targetFormat?: unknown } | null;
} | null;

/**
 * #7364: "zai"/"glm-coding-apikey" default to the Anthropic Messages wire format
 * (registry format:"claude"), but a per-model `targetFormat` override (custom-model
 * dropdown, #2905) can resolve to "openai" — e.g. for a vision model like glm-4.6v
 * that the operator wants routed through the OpenAI-compatible endpoint instead.
 * chatCore/executionCredentials.ts threads that resolved override onto
 * `providerSpecificData.targetFormat`; DefaultExecutor.buildUrl() has no other way
 * to see it, so without this check every zai/glm-coding-apikey request silently hit
 * the Claude-format endpoint regardless of the override.
 */
export function resolveZaiUrl(
  credentials: ZaiCredentialsLike,
  resolveBaseUrl: (fallback?: string) => string
): string {
  if (credentials?.providerSpecificData?.targetFormat === "openai") {
    return resolveBaseUrl(GLM_DEFAULT_BASE_URLS.international);
  }
  return `${resolveBaseUrl()}?beta=true`;
}

/**
 * nvidiaConcurrencyGate — per-connection concurrency cap for the `nvidia`
 * provider (#6846 Phase 1).
 *
 * NVIDIA NIM's free tier sends no rate-limit headers and has no usage API
 * (see docs/reference/PROVIDER_REFERENCE.md `nvidia` note), so most 429 storms
 * come from parallel bursts against one connection rather than sustained total
 * volume. This reuses the generic `rateLimitSemaphore` FIFO queue (already used
 * by combo round-robin/quota-share dispatch) to serialize concurrent requests
 * per `nvidia:<connectionId>` — excess requests wait in the queue instead of
 * firing doomed parallel calls.
 *
 * No-op for every other provider and for a missing `connectionId` — returns
 * `null`, and callers should skip the `finally` release when the return value
 * is `null`.
 */
import * as semaphore from "../../services/rateLimitSemaphore.ts";
import { getProviderConcurrencyCap } from "../../services/providerDefaultRateLimit.ts";

const NVIDIA_DEFAULT_CONCURRENCY_CAP = 6;
const NVIDIA_ACQUIRE_TIMEOUT_MS = 30_000;

/**
 * Acquire a concurrency slot for an nvidia request. Resolves to a release
 * function that MUST be called (typically in a `finally`) once the request
 * completes, or `null` when the gate does not apply (non-nvidia provider, or
 * no connection id to scope the gate to). Rejects with a
 * `SEMAPHORE_TIMEOUT`-coded error if the queue wait exceeds the timeout —
 * propagates like any other executor failure (caller/combo fallback handles it).
 */
export function acquireNvidiaConcurrencySlot(
  provider: string,
  connectionId: string | null | undefined
): Promise<(() => void) | null> {
  if (provider !== "nvidia" || !connectionId) return Promise.resolve(null);
  const maxConcurrency = getProviderConcurrencyCap(provider, NVIDIA_DEFAULT_CONCURRENCY_CAP);
  const key = `${provider}:${connectionId}`;
  return semaphore.acquire(key, { maxConcurrency, timeoutMs: NVIDIA_ACQUIRE_TIMEOUT_MS });
}

/**
 * Rate-Limit Semaphore
 *
 * Per-model concurrency limiter with FIFO queue for round-robin combo strategy.
 * When a model is at max concurrency, requests wait in a queue instead of failing.
 * When a model hits rate-limits, it's temporarily paused and queued requests wait.
 *
 * All state is in-memory — resets on server restart (by design, since rate-limit
 * windows are typically short-lived).
 */

interface QueueItem {
  resolve: (release: () => void) => void;
  reject: (error: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

interface ModelGate {
  running: number;
  max: number;
  queue: QueueItem[];
  rateLimitedUntil: number | null;
}

interface AcquireOptions {
  maxConcurrency?: number;
  timeoutMs?: number;
  /**
   * Maximum number of requests allowed to wait in the per-model queue (#3872). When
   * the queue is already this deep, a new acquire rejects immediately with
   * `SEMAPHORE_QUEUE_FULL` instead of waiting, so the round-robin combo loop cascades
   * to the next member right away (0 = never queue → fail over immediately). Omitted /
   * negative keeps the historical unbounded-queue behavior.
   */
  maxQueueSize?: number;
}

interface RateLimitStatsEntry {
  running: number;
  queued: number;
  max: number;
  rateLimitedUntil: string | null;
}

/** @type {Map<string, ModelGate>} */
const gates = new Map<string, ModelGate>();

/**
 * Get or create gate for a model
 * @param {string} modelStr
 * @param {number} maxConcurrency
 * @returns {ModelGate}
 */
function getGate(modelStr: string, maxConcurrency = 3): ModelGate {
  if (!gates.has(modelStr)) {
    gates.set(modelStr, {
      running: 0,
      max: maxConcurrency,
      queue: [],
      rateLimitedUntil: null,
    });
  }
  const gate = gates.get(modelStr)!;
  // Update max if config changed
  gate.max = maxConcurrency;
  return gate;
}

/**
 * Check if a model is currently rate-limited
 * @param {ModelGate} gate
 * @returns {boolean}
 */
function isRateLimited(gate: ModelGate): boolean {
  if (!gate.rateLimitedUntil) return false;
  if (Date.now() >= gate.rateLimitedUntil) {
    gate.rateLimitedUntil = null;
    return false;
  }
  return true;
}

/**
 * Try to drain queued requests when slots become available
 * @param {string} modelStr
 */
function drainQueue(modelStr: string): void {
  const gate = gates.get(modelStr);
  if (!gate) return;

  while (gate.queue.length > 0 && gate.running < gate.max && !isRateLimited(gate)) {
    const next = gate.queue.shift();
    if (!next) break;
    clearTimeout(next.timer);
    gate.running++;
    next.resolve(createReleaseFn(modelStr));
  }

  if (gate.running === 0 && gate.queue.length === 0) {
    gates.delete(modelStr);
  }
}

/**
 * Create a release function for a slot
 * @param {string} modelStr
 * @returns {Function}
 */
function createReleaseFn(modelStr: string): () => void {
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const gate = gates.get(modelStr);
    if (gate && gate.running > 0) {
      gate.running--;
      if (gate.running === 0 && gate.queue.length === 0) {
        gates.delete(modelStr);
        return;
      }
      drainQueue(modelStr);
    }
  };
}

/**
 * Acquire a concurrency slot for a model.
 * If slots are available and model is not rate-limited, resolves immediately.
 * Otherwise waits in a FIFO queue until a slot opens or timeout expires.
 *
 * @param {string} modelStr - The model identifier
 * @param {Object} [options]
 * @param {number} [options.maxConcurrency=3] - Max concurrent requests for this model
 * @param {number} [options.timeoutMs=30000] - Max wait time in queue
 * @param {number} [options.maxQueueSize] - Max queued waiters before SEMAPHORE_QUEUE_FULL (#3872)
 * @returns {Promise<Function>} Release function — MUST be called when done
 * @throws {Error} If queue timeout expires ("SEMAPHORE_TIMEOUT") or the queue is full ("SEMAPHORE_QUEUE_FULL")
 */
export function acquire(
  modelStr: string,
  { maxConcurrency = 3, timeoutMs = 30000, maxQueueSize }: AcquireOptions = {}
): Promise<() => void> {
  const gate = getGate(modelStr, maxConcurrency);

  // Fast path: slot available and not rate-limited
  if (gate.running < gate.max && !isRateLimited(gate)) {
    gate.running++;
    return Promise.resolve(createReleaseFn(modelStr));
  }

  // #3872: bounded queue — once the queue is full, fail fast so the round-robin combo
  // cascades to the next member immediately instead of deep-queueing for up to timeoutMs.
  if (typeof maxQueueSize === "number" && maxQueueSize >= 0 && gate.queue.length >= maxQueueSize) {
    const err = new Error(`Semaphore queue full (${maxQueueSize}) for ${modelStr}`) as Error & {
      code?: string;
    };
    err.code = "SEMAPHORE_QUEUE_FULL";
    // Drop a freshly-created idle gate so we don't leak an empty entry.
    if (gate.running === 0 && gate.queue.length === 0) gates.delete(modelStr);
    return Promise.reject(err);
  }

  // Slow path: enqueue and wait
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      // Remove from queue on timeout
      const idx = gate.queue.findIndex((item) => item.timer === timer);
      if (idx !== -1) gate.queue.splice(idx, 1);
      const err = new Error(`Semaphore timeout after ${timeoutMs}ms for ${modelStr}`) as Error & {
        code?: string;
      };
      err.code = "SEMAPHORE_TIMEOUT";
      reject(err);
    }, timeoutMs);

    gate.queue.push({ resolve, reject, timer });
  });
}

/**
 * Mark a model as rate-limited for a given duration.
 * Existing running requests continue, but new acquisitions are blocked
 * until the cooldown expires. After expiry, the queue drains automatically.
 *
 * @param {string} modelStr - The model identifier
 * @param {number} cooldownMs - How long to block (milliseconds)
 */
export function markRateLimited(modelStr: string, cooldownMs: number): void {
  const gate = getGate(modelStr);
  gate.rateLimitedUntil = Date.now() + cooldownMs;

  // Schedule drain after cooldown expires
  setTimeout(() => {
    if (gate.rateLimitedUntil && Date.now() >= gate.rateLimitedUntil) {
      gate.rateLimitedUntil = null;
      drainQueue(modelStr);
    }
  }, cooldownMs + 50); // +50ms buffer
}

/**
 * Get stats for all tracked models (for monitoring/UI)
 * @returns {Object} Map of modelStr → { running, queued, max, rateLimitedUntil }
 */
export function getStats(): Record<string, RateLimitStatsEntry> {
  const stats: Record<string, RateLimitStatsEntry> = {};
  for (const [model, gate] of gates) {
    stats[model] = {
      running: gate.running,
      queued: gate.queue.length,
      max: gate.max,
      rateLimitedUntil: gate.rateLimitedUntil
        ? new Date(gate.rateLimitedUntil).toISOString()
        : null,
    };
  }
  return stats;
}

/**
 * Reset all gates (for testing)
 */
export function resetAll(): void {
  for (const [, gate] of gates) {
    for (const item of gate.queue) {
      clearTimeout(item.timer);
      item.reject(new Error("Semaphore reset"));
    }
  }
  gates.clear();
}

/**
 * Provider-default sliding-window rate-limit fallback (free-claude-code port, Fase 8.2).
 *
 * Providers that do NOT send rate-limit headers never let the adaptive Bottleneck path
 * in rateLimitManager learn a reservoir, so `resolveRpm` leaves them effectively
 * un-throttled. For such a provider with a *documented* fixed cap, an operator can
 * declare a default here and a sliding window (burst-free, unlike Bottleneck's
 * fixed-window reservoir which refills in one burst every interval) enforces it
 * proactively. `nvidia` is the first (and currently only) real entry — NVIDIA NIM's
 * free tier is documented as "~40 RPM" and exposes no rate-limit headers or usage
 * API (#6846 Phase 1). Every other provider still gets zero behavior change; the
 * whole path is a no-op unless an entry (or a resolved override, see below) exists.
 *
 * Wired as a pre-schedule gate in `withRateLimit` (rateLimitManager.ts). Bottleneck
 * still applies on top — this only adds a floor for header-less providers.
 */
import { SlidingWindowLimiter, type RateLimitWindow } from "./slidingWindowLimiter.ts";

// Opt-in per-provider caps. Example shape (commented — add real entries as needed):
//   "some-headerless-provider": { requests: 60, windowMs: 60_000 },
const PROVIDER_DEFAULT_RATE_LIMITS: Record<string, RateLimitWindow> = {
  nvidia: { requests: 40, windowMs: 60_000 },
};

/** #6846 Phase 1: default per-connection concurrency cap for providers whose static
 * budget is enforced via `open-sse/services/rateLimitSemaphore.ts` (nvidia only,
 * today). Mid-point of the issue's suggested 4-8 range. */
export const PROVIDER_DEFAULT_CONCURRENCY_CAP: Record<string, number> = {
  nvidia: 6,
};

let providerDefaultOverrides: Record<string, RateLimitWindow> | null = null;
const limiter = new SlidingWindowLimiter();

/**
 * Operator-configured overrides, resolved from `ResilienceSettings.providerQuotaOverrides`
 * (see `src/lib/resilience/settings.ts`) by `rateLimitManager.ts` on init/refresh.
 * `rpm` overrides the static sliding-window budget; `concurrency` overrides the
 * default per-connection concurrency cap. A 0/missing field falls back to the
 * static default for that field.
 */
let providerQuotaOverrides: Record<string, { rpm?: number; concurrency?: number }> | null = null;

/** Test hook: override the provider-default map and clear accumulated history. */
export function __setProviderDefaultRateLimitsForTests(
  map: Record<string, RateLimitWindow> | null
): void {
  providerDefaultOverrides = map;
  limiter.reset();
}

/**
 * Set (or clear, with `null`) the operator-configured per-provider RPM/concurrency
 * overrides. Called by `rateLimitManager.ts::initializeRateLimitProtection()` and
 * `applyRequestQueueSettings()` after resolving `ResilienceSettings`.
 */
export function setProviderQuotaOverrides(
  map: Record<string, { rpm?: number; concurrency?: number }> | null
): void {
  providerQuotaOverrides = map;
}

export function getProviderDefaultRateLimit(provider: string): RateLimitWindow | undefined {
  if (!provider) return undefined;
  const rpmOverride = providerQuotaOverrides?.[provider]?.rpm;
  if (typeof rpmOverride === "number" && rpmOverride > 0) {
    return { requests: rpmOverride, windowMs: 60_000 };
  }
  return (providerDefaultOverrides ?? PROVIDER_DEFAULT_RATE_LIMITS)[provider];
}

/**
 * Resolve a provider's per-connection concurrency cap: operator override →
 * `PROVIDER_DEFAULT_CONCURRENCY_CAP[provider]` → `fallback`. Used by the nvidia
 * executor concurrency gate (`open-sse/executors/default/nvidiaConcurrencyGate.ts`).
 */
export function getProviderConcurrencyCap(provider: string, fallback: number): number {
  const override = providerQuotaOverrides?.[provider]?.concurrency;
  if (typeof override === "number" && override > 0) return override;
  const staticDefault = PROVIDER_DEFAULT_CONCURRENCY_CAP[provider];
  return typeof staticDefault === "number" && staticDefault > 0 ? staticDefault : fallback;
}

/**
 * Consume one slot from the provider's opt-in sliding-window default.
 * Returns 0 when a slot was taken (proceed) or no default is configured; otherwise the
 * ms until a slot frees, so the caller can wait and retry.
 */
export function acquireProviderDefaultSlot(provider: string, connectionId?: string | null): number {
  const cfg = getProviderDefaultRateLimit(provider);
  if (!cfg) return 0;
  const res = limiter.tryAcquire(`${provider}:${connectionId || "_"}`, cfg);
  return res.allowed ? 0 : Math.max(1, res.retryAfterMs);
}

/** Abort-aware sleep: resolves after `ms`, or rejects with AbortError if `signal` fires. */
function sleepOrAbort(ms: number, signal: AbortSignal | null): Promise<void> {
  return new Promise((resolve, reject) => {
    let onAbort: (() => void) | null = null;
    const timer = setTimeout(() => {
      if (signal && onAbort) signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    if (signal) {
      onAbort = () => {
        clearTimeout(timer);
        const reason = signal.reason;
        const err =
          reason instanceof Error
            ? reason
            : new Error(typeof reason === "string" ? reason : "The operation was aborted");
        err.name = "AbortError";
        reject(err);
      };
      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

/**
 * Block until the provider's opt-in sliding-window default has a free slot (or the wait
 * budget is exhausted, in which case we proceed — Bottleneck still applies). No-op when
 * the provider has no configured default. Converges: each wait frees at least one slot.
 */
export async function awaitProviderDefaultSlot(
  provider: string,
  connectionId: string | null,
  signal: AbortSignal | null,
  maxWaitMs?: number
): Promise<void> {
  const cfg = getProviderDefaultRateLimit(provider);
  if (!cfg) return;
  const budget = Math.max(cfg.windowMs, maxWaitMs && maxWaitMs > 0 ? maxWaitMs : 0);
  const start = Date.now();
  for (;;) {
    const waitMs = acquireProviderDefaultSlot(provider, connectionId);
    if (waitMs === 0) return;
    if (Date.now() - start >= budget) return; // waited the budget; let it through
    await sleepOrAbort(Math.min(waitMs, budget), signal);
  }
}

/**
 * Sliding-window rate limiter (free-claude-code port, Fase 8.2).
 *
 * A small, dependency-free fallback limiter for providers that do NOT expose
 * rate-limit headers (so the adaptive Bottleneck path in rateLimitManager never
 * learns a reservoir) but have a documented fixed cap. Bottleneck's reservoir is a
 * fixed-window counter that refills in one burst every interval; a true sliding
 * window enforces "no more than N requests in ANY trailing windowMs", which avoids
 * the 2× burst at window boundaries that can trip an upstream 429.
 *
 * It is intentionally a pure allowed/blocked oracle (no internal queueing) — the
 * caller decides whether to wait `retryAfterMs` or fall back. See
 * `withRateLimit` in rateLimitManager.ts for the opt-in wiring, gated on
 * PROVIDER_DEFAULT_RATE_LIMITS so existing providers are unaffected.
 */

export interface RateLimitWindow {
  /** Max requests permitted in any trailing `windowMs`. */
  requests: number;
  /** Window length in milliseconds. */
  windowMs: number;
}

export interface AcquireResult {
  allowed: boolean;
  /** When blocked, ms until the oldest in-window hit ages out and a slot frees. 0 when allowed. */
  retryAfterMs: number;
}

// Hard ceiling on distinct keys tracked, so a pathological key space (e.g. a
// per-request id leaking into the key) can never grow the map without bound.
const MAX_KEYS = 5000;

export class SlidingWindowLimiter {
  private readonly hits = new Map<string, number[]>();
  private readonly now: () => number;

  constructor(opts: { now?: () => number } = {}) {
    this.now = opts.now ?? Date.now;
  }

  /**
   * Try to consume one slot for `key`. Records a timestamp and returns
   * `{allowed:true}` when under the cap; returns `{allowed:false, retryAfterMs}`
   * (without recording) when the trailing window is saturated.
   */
  tryAcquire(key: string, window: RateLimitWindow): AcquireResult {
    const { requests, windowMs } = window;
    // A non-positive cap or window means "no limit configured" → always allow.
    if (!(requests > 0) || !(windowMs > 0)) return { allowed: true, retryAfterMs: 0 };

    const now = this.now();
    const cutoff = now - windowMs;
    const previous = this.hits.get(key);
    // Drop timestamps that have aged out of the trailing window.
    const live = previous ? previous.filter((ts) => ts > cutoff) : [];

    if (live.length >= requests) {
      // The oldest in-window hit is the first to expire and free a slot.
      const retryAfterMs = Math.max(0, live[0] + windowMs - now);
      this.hits.set(key, live); // persist the pruned list; do NOT record a blocked attempt
      return { allowed: false, retryAfterMs };
    }

    live.push(now);
    this.set(key, live);
    return { allowed: true, retryAfterMs: 0 };
  }

  /** Clear history for one key, or all keys when called with no argument. */
  reset(key?: string): void {
    if (key === undefined) this.hits.clear();
    else this.hits.delete(key);
  }

  private set(key: string, live: number[]): void {
    if (!this.hits.has(key) && this.hits.size >= MAX_KEYS) {
      // Evict the least-recently-inserted key (Map preserves insertion order).
      const oldest = this.hits.keys().next().value;
      if (oldest !== undefined) this.hits.delete(oldest);
    }
    this.hits.set(key, live);
  }
}

export const ALIBABA_PROVIDER_REGION_VALUES = ["global-sg", "china-beijing"] as const;

export type AlibabaProviderRegion = (typeof ALIBABA_PROVIDER_REGION_VALUES)[number];
export type AlibabaProviderFamily =
  "alibaba" | "bailian-coding-plan" | "qwen-cloud" | "qwen-cloud-token-plan";

export const ALIBABA_PROVIDER_ENDPOINTS: Readonly<
  Record<AlibabaProviderFamily, Readonly<Record<AlibabaProviderRegion, string>>>
> = {
  alibaba: {
    "global-sg": "https://dashscope-intl.aliyuncs.com/compatible-mode/v1",
    "china-beijing": "https://dashscope.aliyuncs.com/compatible-mode/v1",
  },
  "bailian-coding-plan": {
    "global-sg": "https://coding-intl.dashscope.aliyuncs.com/apps/anthropic/v1",
    "china-beijing": "https://coding.dashscope.aliyuncs.com/apps/anthropic/v1",
  },
  "qwen-cloud": {
    "global-sg": "https://dashscope-intl.aliyuncs.com/compatible-mode/v1",
    "china-beijing": "https://dashscope.aliyuncs.com/compatible-mode/v1",
  },
  "qwen-cloud-token-plan": {
    "global-sg": "https://token-plan.ap-southeast-1.maas.aliyuncs.com/compatible-mode/v1",
    "china-beijing": "https://token-plan.cn-beijing.maas.aliyuncs.com/compatible-mode/v1",
  },
};

const REGIONAL_PROVIDER_IDS = new Set([
  "alibaba",
  "alibaba-cn",
  "bailian-coding-plan",
  "qwen-cloud",
  "qwen-cloud-token-plan",
]);

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function canonicalProviderFamily(providerId: string): AlibabaProviderFamily | null {
  if (providerId === "alibaba-cn") return "alibaba";
  if (
    providerId === "alibaba" ||
    providerId === "bailian-coding-plan" ||
    providerId === "qwen-cloud" ||
    providerId === "qwen-cloud-token-plan"
  ) {
    return providerId;
  }
  return null;
}

const SLASH_CHAR_CODE = 47;

/**
 * Strip every trailing "/" in linear time.
 *
 * Deliberately not a regex: `/\/+$/` has no left anchor, so the engine retries at
 * every start offset and each attempt re-walks the slash run before failing `$` —
 * quadratic on an endpoint made of many slashes (CodeQL js/polynomial-redos).
 * Connection base URLs are operator-supplied, so they reach this trim directly.
 */
function stripTrailingSlashes(value: string): string {
  let end = value.length;
  while (end > 0 && value.charCodeAt(end - 1) === SLASH_CHAR_CODE) end--;
  return end === value.length ? value : value.slice(0, end);
}

function normalizeEndpoint(value: string): string {
  return stripTrailingSlashes(value.trim())
    .replace(/\/(?:chat\/completions|messages)$/i, "")
    .toLowerCase();
}

function isFamilyPresetUrl(family: AlibabaProviderFamily, value: string): boolean {
  const normalized = normalizeEndpoint(value);
  return ALIBABA_PROVIDER_REGION_VALUES.some(
    (region) => normalizeEndpoint(ALIBABA_PROVIDER_ENDPOINTS[family][region]) === normalized
  );
}

export function isAlibabaRegionalProvider(providerId: string | null | undefined): boolean {
  return typeof providerId === "string" && REGIONAL_PROVIDER_IDS.has(providerId);
}

export function getDefaultAlibabaProviderRegion(
  providerId: string | null | undefined
): AlibabaProviderRegion {
  return providerId === "alibaba-cn" ? "china-beijing" : "global-sg";
}

export function normalizeAlibabaProviderRegion(
  value: unknown,
  fallback: AlibabaProviderRegion = "global-sg"
): AlibabaProviderRegion {
  if (typeof value !== "string") return fallback;
  switch (value.trim().toLowerCase()) {
    case "global-sg":
    case "global":
    case "international":
    case "singapore":
    case "ap-southeast-1":
      return "global-sg";
    case "china-beijing":
    case "china":
    case "cn":
    case "beijing":
    case "cn-beijing":
      return "china-beijing";
    default:
      return fallback;
  }
}

export function resolveAlibabaProviderRegion(
  providerId: string,
  providerSpecificData?: unknown
): AlibabaProviderRegion {
  const fallback = getDefaultAlibabaProviderRegion(providerId);
  return normalizeAlibabaProviderRegion(asRecord(providerSpecificData).region, fallback);
}

/**
 * Resolve the Alibaba-family API root for a connection.
 *
 * A genuinely custom base URL wins. Historical saved preset URLs do not: they are treated as
 * defaults so changing the region selector immediately switches to the matching regional host.
 */
export function resolveAlibabaProviderBaseUrl(
  providerId: string,
  providerSpecificData?: unknown,
  fallback = ""
): string {
  const family = canonicalProviderFamily(providerId);
  const data = asRecord(providerSpecificData);
  const configuredBaseUrl =
    typeof data.baseUrl === "string" && data.baseUrl.trim() ? data.baseUrl.trim() : "";

  if (!family) return configuredBaseUrl || fallback;
  if (configuredBaseUrl && !isFamilyPresetUrl(family, configuredBaseUrl)) {
    return configuredBaseUrl;
  }

  const region = resolveAlibabaProviderRegion(providerId, data);
  return ALIBABA_PROVIDER_ENDPOINTS[family][region];
}

export function resolveAlibabaProviderModelsUrl(
  providerId: string,
  providerSpecificData?: unknown,
  fallback = ""
): string {
  const baseUrl = stripTrailingSlashes(
    resolveAlibabaProviderBaseUrl(providerId, providerSpecificData, fallback).trim()
  ).replace(/\/(?:chat\/completions|messages|models)$/i, "");
  return baseUrl ? `${baseUrl}/models` : "";
}

/**
 * Resolve the dedicated Alibaba-family media API root from the connection's
 * regional OpenAI/Anthropic-compatible endpoint.
 */
export function resolveAlibabaProviderMediaBaseUrl(
  providerId: string,
  providerSpecificData?: unknown,
  fallback = ""
): string {
  return stripTrailingSlashes(
    resolveAlibabaProviderBaseUrl(providerId, providerSpecificData, fallback).trim()
  )
    .replace(/\/compatible-mode\/v1(?:\/(?:chat\/completions|models))?$/i, "/api/v1")
    .replace(/\/apps\/anthropic(?:\/v1)?(?:\/messages)?$/i, "/api/v1");
}

// @ts-nocheck
import {
  BedrockRuntimeClient,
  ConverseCommand,
  ConverseStreamCommand,
} from "@aws-sdk/client-bedrock-runtime";
import { randomUUID } from "node:crypto";

import { BaseExecutor } from "./base.ts";
import { PROVIDERS } from "../config/constants.ts";
import { buildBedrockNativeConverseUrl, resolveBedrockRegion } from "../config/bedrock.ts";
import * as prl from "../utils/providerRequestLogging.ts";

const encoder = new TextEncoder();

function asRecord(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function getCustomUserAgent(providerSpecificData) {
  const value = asRecord(providerSpecificData).customUserAgent;
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function toText(value) {
  if (typeof value === "string") return value;
  if (value === null || value === undefined) return "";
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function stripDataUrlPrefix(value) {
  if (typeof value !== "string") return null;
  const match = value.match(/^data:image\/(png|jpeg|jpg|gif|webp);base64,(.+)$/i);
  if (!match) return null;
  const format = match[1].toLowerCase() === "jpg" ? "jpeg" : match[1].toLowerCase();
  return { format, data: match[2] };
}

function decodeBase64(value) {
  return Uint8Array.from(Buffer.from(value, "base64"));
}

function normalizeRole(role) {
  if (role === "assistant") return "assistant";
  return "user";
}

function normalizeToolUseId(value) {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function textBlocksFromContent(content, options = {}) {
  if (typeof content === "string") return content.trim() ? [{ text: content }] : [];
  if (!Array.isArray(content)) return [];

  const blocks = [];
  for (const part of content) {
    if (typeof part === "string") {
      if (part.trim()) blocks.push({ text: part });
      continue;
    }
    const p = asRecord(part);
    const type = typeof p.type === "string" ? p.type : "";
    if ((type === "text" || type === "input_text") && typeof p.text === "string") {
      if (p.text.trim()) blocks.push({ text: p.text });
      continue;
    }
    if (type === "image_url" || type === "input_image") {
      const url = typeof p.image_url === "string" ? p.image_url : p.image_url?.url || p.image_url;
      const image = stripDataUrlPrefix(url);
      if (image) {
        blocks.push({
          image: { format: image.format, source: { bytes: decodeBase64(image.data) } },
        });
      }
      continue;
    }
    if (type === "tool_use" && typeof p.id === "string" && typeof p.name === "string") {
      const rawId = normalizeToolUseId(p.id);
      if (rawId && options.skipToolUseIds?.has(rawId)) continue;
      if (rawId && !options.answeredToolUseIds?.has(rawId)) continue;
      blocks.push({
        toolUse: {
          toolUseId: rawId || `toolu_${randomUUID()}`,
          name: p.name,
          input: asRecord(p.input),
        },
      });
      continue;
    }
    if (type === "tool_result" && typeof p.tool_use_id === "string") {
      blocks.push({
        toolResult: {
          toolUseId: p.tool_use_id,
          content: [{ text: toText(p.content) }],
          status: p.is_error ? "error" : "success",
        },
      });
    }
  }

  return blocks;
}

function systemBlocksFromOpenAI(messages) {
  const blocks = [];
  for (const message of messages) {
    const role = message?.role;
    if (role !== "system" && role !== "developer") continue;
    const text = textBlocksFromContent(message.content)
      .map((block) => (typeof block.text === "string" ? block.text : ""))
      .filter(Boolean)
      .join("\n");
    if (text.trim()) blocks.push({ text });
  }
  return blocks;
}

function toolResultContentFromMessage(message) {
  const content = message.content;
  if (typeof content === "string") return [{ text: content || " " }];
  if (Array.isArray(content)) {
    const result = [];
    for (const part of content) {
      if (typeof part === "string") {
        result.push({ text: part || " " });
        continue;
      }
      const p = asRecord(part);
      if (typeof p.text === "string") result.push({ text: p.text || " " });
      else if (p.type === "json" && p.json !== undefined) result.push({ json: p.json });
      else if (p.content !== undefined) result.push({ text: toText(p.content) });
    }
    return result.length > 0 ? result : [{ text: " " }];
  }
  return [{ text: toText(content) || " " }];
}

function collectAnsweredToolUseIds(messages) {
  const answered = new Set();
  for (const message of messages) {
    if (!message || typeof message !== "object") continue;
    if (message.role === "tool") {
      const id = normalizeToolUseId(message.tool_call_id);
      if (id) answered.add(id);
    }
    if (!Array.isArray(message.content)) continue;
    for (const part of message.content) {
      const p = asRecord(part);
      if (p.type !== "tool_result") continue;
      const id = normalizeToolUseId(p.tool_use_id);
      if (id) answered.add(id);
    }
  }
  return answered;
}

function getToolUseIdFromBlock(block) {
  return normalizeToolUseId(block?.toolUse?.toolUseId);
}

function getToolResultIdFromBlock(block) {
  return normalizeToolUseId(block?.toolResult?.toolUseId);
}

function isToolResultOnlyMessage(message) {
  return (
    message?.role === "user" &&
    Array.isArray(message.content) &&
    message.content.length > 0 &&
    message.content.every((block) => Boolean(getToolResultIdFromBlock(block)))
  );
}

function mergeConsecutiveToolResultMessages(messages) {
  const merged = [];
  for (const message of messages) {
    const previous = merged[merged.length - 1];
    if (isToolResultOnlyMessage(previous) && isToolResultOnlyMessage(message)) {
      previous.content.push(...message.content);
      continue;
    }
    merged.push(message);
  }
  return merged;
}

function ensureNonEmptyContent(message) {
  if (!Array.isArray(message.content) || message.content.length === 0) {
    message.content = [{ text: " " }];
  }
}

function sanitizeBedrockToolPairs(messages) {
  const normalized = mergeConsecutiveToolResultMessages(messages);
  const validResultCounts = new Map();

  for (let i = 0; i < normalized.length; i++) {
    const message = normalized[i];
    if (message?.role !== "assistant" || !Array.isArray(message.content)) continue;

    const nextMessage = normalized[i + 1];
    const nextResultIds = new Set(
      nextMessage?.role === "user" && Array.isArray(nextMessage.content)
        ? nextMessage.content.map(getToolResultIdFromBlock).filter(Boolean)
        : []
    );

    const toolUseIds = message.content.map(getToolUseIdFromBlock).filter(Boolean);
    if (toolUseIds.length === 0) continue;

    const allowedIds = new Set(toolUseIds.filter((id) => nextResultIds.has(id)));
    message.content = message.content.filter((block) => {
      const toolUseId = getToolUseIdFromBlock(block);
      return !toolUseId || allowedIds.has(toolUseId);
    });
    ensureNonEmptyContent(message);
    for (const id of allowedIds) {
      validResultCounts.set(id, (validResultCounts.get(id) || 0) + 1);
    }
  }

  for (const message of normalized) {
    if (message?.role !== "user" || !Array.isArray(message.content)) continue;
    message.content = message.content.filter((block) => {
      const resultId = getToolResultIdFromBlock(block);
      if (!resultId) return true;
      const remaining = validResultCounts.get(resultId) || 0;
      if (remaining <= 0) return false;
      validResultCounts.set(resultId, remaining - 1);
      return true;
    });
    ensureNonEmptyContent(message);
  }

  return normalized;
}

function messagesFromOpenAI(messages) {
  const converted = [];
  const pendingToolUseIds = new Set();
  const answeredToolUseIds = collectAnsweredToolUseIds(messages);

  for (const message of messages) {
    if (!message || typeof message !== "object") continue;
    if (message.role === "system" || message.role === "developer") continue;

    if (message.role === "tool") {
      const toolUseId = normalizeToolUseId(message.tool_call_id) || `toolu_${randomUUID()}`;
      pendingToolUseIds.delete(toolUseId);
      answeredToolUseIds.add(toolUseId);
      converted.push({
        role: "user",
        content: [
          {
            toolResult: {
              toolUseId,
              content: toolResultContentFromMessage(message),
              status: "success",
            },
          },
        ],
      });
      continue;
    }

    const toolCalls = Array.isArray(message.tool_calls) ? message.tool_calls : [];
    const toolCallIds = new Set(
      toolCalls.map((call) => normalizeToolUseId(call?.id)).filter(Boolean)
    );
    const content = textBlocksFromContent(message.content, {
      skipToolUseIds: toolCallIds,
      answeredToolUseIds,
    });
    for (const call of toolCalls) {
      const fn = asRecord(call.function);
      const rawArgs = typeof fn.arguments === "string" ? fn.arguments : "{}";
      let input = {};
      try {
        input = rawArgs.trim() ? JSON.parse(rawArgs) : {};
      } catch {
        input = { arguments: rawArgs };
      }
      const toolUseId = normalizeToolUseId(call.id) || `toolu_${randomUUID()}`;
      if (pendingToolUseIds.has(toolUseId)) continue;
      if (!answeredToolUseIds.has(toolUseId)) continue;
      pendingToolUseIds.add(toolUseId);
      content.push({
        toolUse: {
          toolUseId,
          name: typeof fn.name === "string" && fn.name ? fn.name : "unknown_tool",
          input,
        },
      });
    }

    if (content.length === 0) {
      content.push({ text: " " });
    }

    converted.push({ role: normalizeRole(message.role), content });
  }

  if (converted.length === 0) {
    converted.push({ role: "user", content: [{ text: " " }] });
  }

  return sanitizeBedrockToolPairs(converted);
}

function toolConfigFromOpenAI(tools, toolChoice) {
  if (!Array.isArray(tools) || tools.length === 0) return undefined;
  const bedrockTools = [];
  for (const tool of tools) {
    const t = asRecord(tool);
    const fn = t.type === "function" ? asRecord(t.function) : t;
    const name = typeof fn.name === "string" ? fn.name.trim() : "";
    if (!name) continue;
    bedrockTools.push({
      toolSpec: {
        name,
        description: typeof fn.description === "string" ? fn.description : undefined,
        inputSchema: { json: asRecord(fn.parameters) },
      },
    });
  }
  if (bedrockTools.length === 0) return undefined;

  const config = { tools: bedrockTools };
  if (toolChoice === "required") config.toolChoice = { any: {} };
  else if (toolChoice === "auto") config.toolChoice = { auto: {} };
  else if (toolChoice && typeof toolChoice === "object") {
    const fn = asRecord(toolChoice.function);
    const name = typeof fn.name === "string" ? fn.name : "";
    if (name) config.toolChoice = { tool: { name } };
  }
  return config;
}

export function openAIToBedrockConverse(model, body) {
  const request = asRecord(body);
  const messages = Array.isArray(request.messages) ? request.messages : [];
  const inferenceConfig = {};

  const maxTokens = request.max_tokens ?? request.max_completion_tokens;
  if (typeof maxTokens === "number") inferenceConfig.maxTokens = Math.max(1, Math.floor(maxTokens));
  if (typeof request.temperature === "number") inferenceConfig.temperature = request.temperature;
  if (typeof request.top_p === "number") inferenceConfig.topP = request.top_p;
  if (Array.isArray(request.stop)) inferenceConfig.stopSequences = request.stop.filter(Boolean);
  else if (typeof request.stop === "string" && request.stop)
    inferenceConfig.stopSequences = [request.stop];

  const payload = {
    modelId: model,
    messages: messagesFromOpenAI(messages),
  };

  const system = systemBlocksFromOpenAI(messages);
  if (system.length > 0) payload.system = system;
  if (Object.keys(inferenceConfig).length > 0) payload.inferenceConfig = inferenceConfig;

  const toolConfig = toolConfigFromOpenAI(request.tools, request.tool_choice);
  if (toolConfig) payload.toolConfig = toolConfig;

  if (request.additionalModelRequestFields !== undefined) {
    payload.additionalModelRequestFields = request.additionalModelRequestFields;
  }

  return payload;
}

function convertStopReason(reason) {
  switch (reason) {
    case "tool_use":
      return "tool_calls";
    case "max_tokens":
      return "length";
    case "stop_sequence":
    case "end_turn":
    default:
      return "stop";
  }
}

function usageFromBedrock(usage) {
  const input = Number(usage?.inputTokens || 0);
  const output = Number(usage?.outputTokens || 0);
  return {
    prompt_tokens: input,
    completion_tokens: output,
    total_tokens: Number(usage?.totalTokens || input + output),
  };
}

function contentBlocksToOpenAIMessage(blocks) {
  const text = [];
  const reasoning = [];
  const toolCalls = [];
  for (const block of Array.isArray(blocks) ? blocks : []) {
    if (typeof block?.text === "string") text.push(block.text);
    if (typeof block?.reasoningContent?.reasoningText?.text === "string") {
      reasoning.push(block.reasoningContent.reasoningText.text);
    }
    if (block?.toolUse) {
      toolCalls.push({
        id: block.toolUse.toolUseId,
        type: "function",
        function: {
          name: block.toolUse.name,
          arguments: JSON.stringify(block.toolUse.input || {}),
        },
      });
    }
  }

  const message = { role: "assistant", content: text.join("") };
  if (reasoning.length > 0) message.reasoning_content = reasoning.join("");
  if (toolCalls.length > 0) {
    message.content = message.content || null;
    message.tool_calls = toolCalls;
  }
  return message;
}

function openAICompletionFromConverse(output, model) {
  const message = contentBlocksToOpenAIMessage(output?.output?.message?.content || []);
  return {
    id: `chatcmpl-bedrock-${randomUUID()}`,
    object: "chat.completion",
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [
      {
        index: 0,
        message,
        finish_reason: convertStopReason(output?.stopReason),
      },
    ],
    usage: usageFromBedrock(output?.usage),
  };
}

function sse(data) {
  return encoder.encode(`data: ${JSON.stringify(data)}\n\n`);
}

function done() {
  return encoder.encode("data: [DONE]\n\n");
}

function openAIChunk(model, delta, finishReason = null, usage = undefined) {
  const chunk = {
    id: `chatcmpl-bedrock-${model}`,
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{ index: 0, delta, finish_reason: finishReason }],
  };
  if (usage) chunk.usage = usage;
  return chunk;
}

function statusFromError(error) {
  const status = Number(error?.$metadata?.httpStatusCode || error?.statusCode || error?.status);
  return Number.isInteger(status) && status >= 400 && status <= 599 ? status : 502;
}

function errorBody(error, fallback = "Bedrock request failed") {
  const status = statusFromError(error);
  const code = typeof error?.name === "string" ? error.name : `HTTP_${status}`;
  const message = typeof error?.message === "string" && error.message ? error.message : fallback;
  return {
    error: {
      message,
      type:
        status === 429
          ? "rate_limit_error"
          : status === 401 || status === 403
            ? "auth_error"
            : "upstream_error",
      code,
      status,
    },
  };
}

function streamExceptionPayload(event) {
  const candidates = [
    event?.throttlingException,
    event?.validationException,
    event?.modelStreamErrorException,
    event?.serviceUnavailableException,
    event?.internalServerException,
  ].filter(Boolean);
  return candidates[0] || null;
}

function statusFromStreamException(exception) {
  const name = String(exception?.name || exception?.code || "");
  if (name.includes("Throttling")) return 429;
  if (name.includes("Validation")) return 400;
  if (name.includes("ServiceUnavailable")) return 503;
  if (name.includes("InternalServer")) return 500;
  return 502;
}

function createOpenAIStreamFromBedrock(stream, model) {
  const blockToolIndexes = new Map();
  let nextToolIndex = 0;
  let finishReason = "stop";
  let finalUsage = null;

  return new ReadableStream({
    async start(controller) {
      try {
        controller.enqueue(sse(openAIChunk(model, { role: "assistant" })));
        for await (const event of stream || []) {
          const exception = streamExceptionPayload(event);
          if (exception) {
            const status = statusFromStreamException(exception);
            controller.enqueue(
              sse({
                error: {
                  message: exception.message || "Bedrock stream failed",
                  type: status === 429 ? "rate_limit_error" : "upstream_error",
                  code: exception.name || "bedrock_stream_error",
                  status,
                },
              })
            );
            break;
          }

          if (event.contentBlockStart?.start?.toolUse) {
            const tool = event.contentBlockStart.start.toolUse;
            const index = nextToolIndex++;
            blockToolIndexes.set(event.contentBlockStart.contentBlockIndex, index);
            controller.enqueue(
              sse(
                openAIChunk(model, {
                  tool_calls: [
                    {
                      index,
                      id: tool.toolUseId,
                      type: "function",
                      function: { name: tool.name, arguments: "" },
                    },
                  ],
                })
              )
            );
            continue;
          }

          if (event.contentBlockDelta?.delta) {
            const delta = event.contentBlockDelta.delta;
            if (typeof delta.text === "string" && delta.text.length > 0) {
              controller.enqueue(sse(openAIChunk(model, { content: delta.text })));
            }
            if (typeof delta.reasoningContent?.text === "string" && delta.reasoningContent.text) {
              controller.enqueue(
                sse(openAIChunk(model, { reasoning_content: delta.reasoningContent.text }))
              );
            }
            if (typeof delta.toolUse?.input === "string") {
              const index = blockToolIndexes.get(event.contentBlockDelta.contentBlockIndex) ?? 0;
              controller.enqueue(
                sse(
                  openAIChunk(model, {
                    tool_calls: [{ index, function: { arguments: delta.toolUse.input } }],
                  })
                )
              );
            }
            continue;
          }

          if (event.messageStop?.stopReason) {
            finishReason = convertStopReason(event.messageStop.stopReason);
            continue;
          }

          if (event.metadata?.usage) {
            finalUsage = usageFromBedrock(event.metadata.usage);
          }
        }

        controller.enqueue(sse(openAIChunk(model, {}, finishReason, finalUsage || undefined)));
        controller.enqueue(done());
        controller.close();
      } catch (error) {
        const body = errorBody(error);
        controller.enqueue(sse(body));
        controller.enqueue(done());
        controller.close();
      }
    },
  });
}

export class BedrockExecutor extends BaseExecutor {
  constructor(clientFactory = null) {
    super("bedrock", PROVIDERS.bedrock || { format: "openai" });
    this.clientFactory = clientFactory;
  }

  buildUrl(model, stream, _urlIndex = 0, credentials = null) {
    return buildBedrockNativeConverseUrl(
      resolveBedrockRegion(credentials?.providerSpecificData),
      model,
      stream
    );
  }

  buildHeaders(credentials) {
    return {
      "Content-Type": "application/json",
      Authorization: credentials?.apiKey ? "Bearer ***" : "",
    };
  }

  createClient(credentials) {
    if (this.clientFactory) return this.clientFactory(credentials);
    const region = resolveBedrockRegion(credentials?.providerSpecificData);
    const customUserAgent = getCustomUserAgent(credentials?.providerSpecificData);
    return new BedrockRuntimeClient({
      region,
      token: { token: credentials.apiKey },
      authSchemePreference: ["httpBearerAuth"],
      maxAttempts: 1,
      ...(customUserAgent ? { customUserAgent } : {}),
    });
  }

  async execute({ model, body, stream, credentials, signal, log }) {
    const url = this.buildUrl(model, stream, 0, credentials);
    const headers = this.buildHeaders(credentials);

    if (!credentials?.apiKey) {
      return {
        response: new Response(
          JSON.stringify(
            errorBody({
              name: "MissingCredentials",
              message: "Missing Bedrock API key",
              $metadata: { httpStatusCode: 401 },
            })
          ),
          {
            status: 401,
            headers: { "Content-Type": "application/json" },
          }
        ),
        url,
        headers,
        transformedBody: null,
      };
    }

    const cleanedBody = this.transformRequest(model, body, stream, credentials);
    const transformedBody = openAIToBedrockConverse(model, cleanedBody);

    try {
      const client = this.createClient(credentials);
      await prl.captureCurrentProviderRequest(
        url,
        headers,
        transformedBody,
        JSON.stringify(transformedBody),
        log
      );
      if (stream) {
        const output = await client.send(new ConverseStreamCommand(transformedBody), {
          abortSignal: signal || undefined,
        });
        return {
          response: new Response(createOpenAIStreamFromBedrock(output.stream, model), {
            status: 200,
            headers: { "Content-Type": "text/event-stream" },
          }),
          url,
          headers,
          transformedBody,
        };
      }

      const output = await client.send(new ConverseCommand(transformedBody), {
        abortSignal: signal || undefined,
      });
      return {
        response: new Response(JSON.stringify(openAICompletionFromConverse(output, model)), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
        url,
        headers,
        transformedBody,
      };
    } catch (error) {
      const status = statusFromError(error);
      return {
        response: new Response(JSON.stringify(errorBody(error)), {
          status,
          headers: { "Content-Type": "application/json" },
        }),
        url,
        headers,
        transformedBody,
      };
    }
  }
}

export default BedrockExecutor;

import { getModelSpec } from "../../src/shared/constants/modelSpecs.ts";

export const BEDROCK_DEFAULT_REGION = "us-east-1";
export const BEDROCK_DASHBOARD_DEFAULT_REGION = "eu-west-2";

const BEDROCK_REGION_PATTERN = /^[a-z]{2}(?:-gov)?-[a-z]+-\d+$/i;

export function normalizeBedrockRegion(value: unknown, fallback = BEDROCK_DEFAULT_REGION): string {
  if (typeof value !== "string") return fallback;
  const trimmed = value.trim().toLowerCase();
  return BEDROCK_REGION_PATTERN.test(trimmed) ? trimmed : fallback;
}

export function extractBedrockRegionFromBaseUrl(value: string | null | undefined): string | null {
  if (!value) return null;
  try {
    const hostname = new URL(value).hostname;
    const match = hostname.match(/^bedrock(?:-runtime|-mantle)?\.([a-z0-9-]+)\./i);
    return match?.[1] ? normalizeBedrockRegion(match[1], "") || null : null;
  } catch {
    return null;
  }
}

export function resolveBedrockRegion(providerSpecificData: unknown): string {
  const data =
    providerSpecificData && typeof providerSpecificData === "object"
      ? (providerSpecificData as Record<string, unknown>)
      : {};
  const explicit = normalizeBedrockRegion(data.region, "");
  if (explicit) return explicit;

  const baseUrl = typeof data.baseUrl === "string" ? data.baseUrl : null;
  return extractBedrockRegionFromBaseUrl(baseUrl) || BEDROCK_DEFAULT_REGION;
}

export function buildBedrockControlBaseUrl(region: string): string {
  return `https://bedrock.${normalizeBedrockRegion(region)}.amazonaws.com`;
}

export function buildBedrockRuntimeBaseUrl(region: string): string {
  return `https://bedrock-runtime.${normalizeBedrockRegion(region)}.amazonaws.com`;
}

export function buildBedrockNativeModelsUrl(region: string): string {
  return `${buildBedrockControlBaseUrl(region)}/foundation-models?byOutputModality=TEXT`;
}

export function buildBedrockNativeInferenceProfilesUrl(
  region: string,
  options: { nextToken?: string | null; typeEquals?: "SYSTEM_DEFINED" | "APPLICATION" } = {}
): string {
  const url = new URL(`${buildBedrockControlBaseUrl(region)}/inference-profiles`);
  url.searchParams.set("maxResults", "100");
  url.searchParams.set("typeEquals", options.typeEquals || "SYSTEM_DEFINED");
  if (options.nextToken) url.searchParams.set("nextToken", options.nextToken);
  return url.toString();
}

export function buildBedrockNativeConverseUrl(region: string, modelId: string, stream = false) {
  const encodedModel = encodeURIComponent(modelId);
  return `${buildBedrockRuntimeBaseUrl(region)}/model/${encodedModel}/${stream ? "converse-stream" : "converse"}`;
}

function modelIdFromArn(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const marker = ":foundation-model/";
  const idx = value.indexOf(marker);
  if (idx < 0) return null;
  const id = value.slice(idx + marker.length).trim();
  return id || null;
}

export type BedrockDiscoveredModel = {
  id: string;
  name: string;
  source: "foundation" | "inference_profile";
  provider?: string | null;
  supportsStreaming?: boolean;
  supportsVision?: boolean;
  inputTokenLimit?: number;
  outputTokenLimit?: number;
};

export function getBedrockKnownModelLimits(modelId: string): {
  inputTokenLimit?: number;
  outputTokenLimit?: number;
} | null {
  const trimmed = typeof modelId === "string" ? modelId.trim() : "";
  if (!trimmed) return null;

  const unqualified = trimmed.includes("/") ? trimmed.slice(trimmed.indexOf("/") + 1) : trimmed;
  const withoutProfilePrefix = unqualified.replace(/^(?:eu|us|global)\./i, "");
  const withoutProviderPrefix = withoutProfilePrefix.replace(/^anthropic\./i, "");
  const spec =
    getModelSpec(trimmed) ||
    getModelSpec(unqualified) ||
    getModelSpec(withoutProfilePrefix) ||
    getModelSpec(withoutProviderPrefix);

  if (!spec?.contextWindow && !spec?.maxOutputTokens) return null;
  return {
    ...(typeof spec.contextWindow === "number" ? { inputTokenLimit: spec.contextWindow } : {}),
    ...(typeof spec.maxOutputTokens === "number" ? { outputTokenLimit: spec.maxOutputTokens } : {}),
  };
}

function withKnownBedrockLimits(model: BedrockDiscoveredModel): BedrockDiscoveredModel {
  return {
    ...model,
    ...(getBedrockKnownModelLimits(model.id) || {}),
  };
}

export function normalizeBedrockDiscoveredModels(
  foundationModelsResponse: unknown,
  inferenceProfilesResponse: unknown = null
): BedrockDiscoveredModel[] {
  const byId = new Map<string, BedrockDiscoveredModel>();
  const add = (model: BedrockDiscoveredModel) => {
    if (!model.id || byId.has(model.id)) return;
    byId.set(model.id, model);
  };

  const foundationModels =
    foundationModelsResponse && typeof foundationModelsResponse === "object"
      ? (foundationModelsResponse as Record<string, unknown>).modelSummaries
      : null;
  if (Array.isArray(foundationModels)) {
    for (const item of foundationModels) {
      const model = item && typeof item === "object" ? (item as Record<string, unknown>) : {};
      const id = typeof model.modelId === "string" ? model.modelId.trim() : "";
      if (!id) continue;
      const outputModalities = Array.isArray(model.outputModalities) ? model.outputModalities : [];
      const inputModalities = Array.isArray(model.inputModalities) ? model.inputModalities : [];
      add(
        withKnownBedrockLimits({
          id,
          name:
            typeof model.modelName === "string" && model.modelName.trim() ? model.modelName : id,
          source: "foundation",
          provider: typeof model.providerName === "string" ? model.providerName : null,
          supportsStreaming: model.responseStreamingSupported === true,
          supportsVision: inputModalities.includes("IMAGE") || outputModalities.includes("IMAGE"),
        })
      );
    }
  }

  const profiles =
    inferenceProfilesResponse && typeof inferenceProfilesResponse === "object"
      ? (inferenceProfilesResponse as Record<string, unknown>).inferenceProfileSummaries
      : null;
  if (Array.isArray(profiles)) {
    for (const item of profiles) {
      const profile = item && typeof item === "object" ? (item as Record<string, unknown>) : {};
      const id =
        typeof profile.inferenceProfileId === "string" ? profile.inferenceProfileId.trim() : "";
      if (id) {
        add(
          withKnownBedrockLimits({
            id,
            name:
              typeof profile.inferenceProfileName === "string" &&
              profile.inferenceProfileName.trim()
                ? profile.inferenceProfileName
                : id,
            source: "inference_profile",
            supportsStreaming: true,
          })
        );
      }

      const models = Array.isArray(profile.models) ? profile.models : [];
      for (const profileModel of models) {
        const modelRecord =
          profileModel && typeof profileModel === "object"
            ? (profileModel as Record<string, unknown>)
            : {};
        const modelId = modelIdFromArn(modelRecord.modelArn);
        if (modelId) {
          add(
            withKnownBedrockLimits({
              id: modelId,
              name: modelId,
              source: "foundation",
              supportsStreaming: true,
            })
          );
        }
      }
    }
  }

  return [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
}

import { randomUUID } from "node:crypto";

import { DefaultExecutor } from "./default.ts";
import {
  applyConfiguredUserAgent,
  mergeAbortSignals,
  mergeUpstreamExtraHeaders,
  type CountTokensInput,
  type ExecuteInput,
  type ProviderCredentials,
} from "./base.ts";
import {
  buildGlmBaseHeaders,
  buildGlmChatUrl,
  buildGlmCodingHeaders,
  buildGlmCountTokensUrl,
  GLM_COUNT_TOKENS_TIMEOUT_MS,
  type GlmTransport,
  getGlmTransport,
} from "../config/glmProvider.ts";
import { applyProviderRequestDefaults } from "../services/providerRequestDefaults.ts";
import { stripUnsupportedParams } from "../translator/paramSupport.ts";
import { getRotatingApiKey } from "../services/apiKeyRotator.ts";
import { CLAUDE_CLI_STAINLESS_PACKAGE_VERSION } from "../config/anthropicHeaders.ts";
import {
  getRuntimeVersion,
  normalizeStainlessArch,
  normalizeStainlessPlatform,
} from "../config/providerHeaderProfiles.ts";
import { translateNonStreamingResponse } from "../handlers/responseTranslator.ts";
import { translateRequest } from "../translator/index.ts";
import { FORMATS } from "../translator/formats.ts";
import { createSSETransformStreamWithLogger } from "../utils/stream.ts";
import { ensureStreamReadiness } from "../utils/streamReadiness.ts";
import { STREAM_READINESS_TIMEOUT_MS } from "../config/constants.ts";
import { resolveSuppressThinkClose, THINKING_MARKER_HEADER } from "../utils/thinkCloseMarker.ts";

type JsonRecord = Record<string, unknown>;
type GlmExecuteResult = Awaited<ReturnType<DefaultExecutor["execute"]>> & {
  targetFormat?: string;
};

function asRecord(value: unknown): JsonRecord | null {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : null;
}

function getEffectiveKey(credentials: ProviderCredentials): string {
  const extraKeys = (credentials.providerSpecificData?.extraApiKeys as string[] | undefined) ?? [];
  if (credentials.apiKey && credentials.connectionId && extraKeys.length > 0) {
    return getRotatingApiKey(credentials.connectionId, credentials.apiKey, extraKeys);
  }
  return credentials.apiKey || credentials.accessToken || "";
}

/**
 * GLM-5.2 effort tiers route exclusively through the Anthropic transport,
 * where Zhipu maps Claude Code effort selectors (high/max) to reasoning
 * intensity. The base model ID sent upstream is always "glm-5.2".
 *
 * https://docs.z.ai/devpack/latest-model
 */
function parseGlm52Effort(model: string): { baseModel: string; effort: "high" | "max" } | null {
  if (model === "glm-5.2-high") return { baseModel: "glm-5.2", effort: "high" };
  if (model === "glm-5.2-max") return { baseModel: "glm-5.2", effort: "max" };
  return null;
}

/**
 * Detects GLM models that support deep thinking (5.2+).
 * These models share a single max_tokens budget for reasoning + response
 * (Z.AI does not document a separate thinking budget). When the client
 * doesn't explicitly request max_tokens, we default to the model's full
 * output capacity so reasoning isn't truncated by a low generic default.
 *
 * To add future models (e.g. glm-5.3, glm-5.4), just extend the regex.
 * https://docs.z.ai/guides/overview/concept-param
 */
const GLM_THINKING_MODEL_PATTERN = /^glm-5\.(?:[2-9]|\d{2,})/i;

function isGlmThinkingModel(model: string): boolean {
  return GLM_THINKING_MODEL_PATTERN.test(model);
}

/**
 * Z.AI's official max output for GLM-5.2+ is 131072 tokens (128K).
 * This budget covers BOTH reasoning and the final response.
 * https://z.ai/blog/glm-5.2
 */
const GLM_THINKING_DEFAULT_MAX_TOKENS = 131072;

function applyGlmRequestDefaults(body: unknown, defaults?: JsonRecord | null): unknown {
  const record = asRecord(body);
  if (!record || !defaults) return body;

  const next = { ...(applyProviderRequestDefaults(record, defaults) as JsonRecord) };
  const thinkingType = typeof defaults.thinkingType === "string" ? defaults.thinkingType : null;

  if (thinkingType && next.thinking === undefined) {
    next.thinking = { type: thinkingType };
  } else if (thinkingType && asRecord(next.thinking)?.type === "enabled") {
    next.thinking = { ...asRecord(next.thinking), type: thinkingType };
  }

  return next;
}

function hasTools(body: unknown): boolean {
  const record = asRecord(body);
  return Array.isArray(record?.tools) && record.tools.length > 0;
}

function isRetryableGlmFallbackStatus(status: number): boolean {
  return status === 404 || status === 408 || status === 409 || status === 429 || status >= 500;
}

function isRetryableGlmFallbackError(error: unknown): boolean {
  if (!error) return false;
  const err = error instanceof Error ? error : new Error(String(error));
  if (err.name === "AbortError") return false;
  return true;
}

function cloneHeaders(headers: Headers): Headers {
  const next = new Headers();
  headers.forEach((value, key) => next.set(key, value));
  return next;
}

function isJsonResponse(response: Response): boolean {
  return (response.headers.get("content-type") || "").toLowerCase().includes("application/json");
}

async function translateJsonResponse(response: Response): Promise<Response> {
  const parsed = await response.json().catch(() => null);
  const translated = translateNonStreamingResponse(parsed, FORMATS.CLAUDE, FORMATS.OPENAI);
  const headers = cloneHeaders(response.headers);
  headers.set("content-type", "application/json");
  headers.delete("content-length");
  return new Response(JSON.stringify(translated), {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

async function translateAnthropicJsonResponse(response: Response): Promise<Response> {
  const parsed = await response.json().catch(() => null);
  const translated = response.ok
    ? translateNonStreamingResponse(parsed, FORMATS.CLAUDE, FORMATS.OPENAI)
    : translateAnthropicJsonError(parsed);
  const headers = cloneHeaders(response.headers);
  headers.set("content-type", "application/json");
  headers.delete("content-length");
  return new Response(JSON.stringify(translated), {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function translateAnthropicJsonError(parsed: unknown): JsonRecord {
  const root = asRecord(parsed) || {};
  const error = asRecord(root.error) || root;
  const message =
    typeof error.message === "string" && error.message.trim()
      ? error.message
      : typeof root.message === "string" && root.message.trim()
        ? root.message
        : "GLM Anthropic transport error";
  const type =
    typeof error.type === "string" && error.type.trim()
      ? error.type
      : typeof root.type === "string" && root.type.trim()
        ? root.type
        : "upstream_error";

  return {
    error: {
      message,
      type,
    },
  };
}

export function translateSseResponse(
  response: Response,
  provider: string,
  model: string,
  suppressThinkClose: boolean = false
): Response {
  if (!response.body) return response;
  const transform = createSSETransformStreamWithLogger(
    FORMATS.CLAUDE,
    FORMATS.OPENAI,
    provider,
    null,
    null,
    model,
    null,
    null,
    null,
    null,
    null,
    false,
    suppressThinkClose
  );
  const headers = cloneHeaders(response.headers);
  headers.set("content-type", "text/event-stream");
  headers.delete("content-length");
  return new Response(response.body.pipeThrough(transform), {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export class GlmExecutor extends DefaultExecutor {
  constructor(provider = "glm") {
    super(provider);
  }

  buildUrl(
    _model: string,
    _stream: boolean,
    _urlIndex = 0,
    credentials: ProviderCredentials | null = null
  ) {
    const primaryTransport = getGlmTransport(credentials?.providerSpecificData);
    const transport =
      _urlIndex === 1 ? (primaryTransport === "openai" ? "anthropic" : "openai") : primaryTransport;
    return buildGlmChatUrl(credentials?.providerSpecificData, transport, this.config.baseUrl);
  }

  buildCountTokensUrl(_model: string, credentials: ProviderCredentials | null = null) {
    return buildGlmCountTokensUrl(credentials?.providerSpecificData, this.config.baseUrl);
  }

  getCountTokensTimeoutMs() {
    return GLM_COUNT_TOKENS_TIMEOUT_MS;
  }

  buildHeaders(
    credentials: ProviderCredentials,
    stream = true,
    _clientHeaders?: Record<string, string> | null,
    _model?: string,
    transport: GlmTransport = getGlmTransport(credentials.providerSpecificData)
  ): Record<string, string> {
    if (transport === "openai") {
      return buildGlmCodingHeaders(getEffectiveKey(credentials), stream);
    }

    return {
      ...buildGlmBaseHeaders(getEffectiveKey(credentials), stream),
      "X-Stainless-Arch": normalizeStainlessArch(),
      "X-Stainless-OS": normalizeStainlessPlatform(),
      "X-Stainless-Runtime-Version": getRuntimeVersion(),
      "X-Stainless-Package-Version": CLAUDE_CLI_STAINLESS_PACKAGE_VERSION,
      "X-Claude-Code-Session-Id": randomUUID(),
      "x-client-request-id": randomUUID(),
    };
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ) {
    const cleanedBody = super.transformRequest(model, body, stream, credentials);
    return applyGlmRequestDefaults(cleanedBody, this.config.requestDefaults as JsonRecord | null);
  }

  transformForTransport(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials,
    transport: GlmTransport
  ) {
    const effortTier = parseGlm52Effort(model);
    const effectiveModel = effortTier ? effortTier.baseModel : model;

    const transformed = this.transformRequest(effectiveModel, body, stream, credentials);
    const record = asRecord(transformed);

    // #7364: unlike DefaultExecutor.execute() (default.ts), GlmExecutor.execute()
    // never calls the base execute() loop — it drives its own fetch via
    // executeTransport()/transformForTransport() — so stripUnsupportedParams()
    // (normally applied at default.ts's execute() call site) never ran for GLM
    // requests. Without this call, a STRIP_RULES clamp entry for provider "glm"
    // (e.g. the glm-4.6v max_tokens ceiling) would be silently dead code.
    if (record) stripUnsupportedParams(this.provider, effectiveModel, record);

    // Ensure upstream receives the base model ID, not the effort-suffixed alias
    if (record && effortTier) {
      record.model = effectiveModel;
    }

    // GLM-5.2+ models share a single max_tokens budget for reasoning + response.
    // When the client doesn't explicitly set max_tokens, default to the model's
    // full output capacity (131072) so deep reasoning isn't truncated by the
    // generic translator defaults (64000 for Anthropic, 16384 for OpenAI).
    // This acts as the "transparent proxy override" described in Z.AI's own
    // Terminal-Bench evaluation methodology.
    // https://huggingface.co/blog/zai-org/glm-52-blog
    if (record && isGlmThinkingModel(effectiveModel)) {
      const clientBody = asRecord(body);
      const clientMaxTokens = clientBody?.max_tokens ?? clientBody?.max_completion_tokens;
      if (!clientMaxTokens) {
        record.max_tokens = GLM_THINKING_DEFAULT_MAX_TOKENS;
      }
    }

    if (transport === "openai") {
      if (record && stream && hasTools(record) && record.tool_stream === undefined) {
        return { ...record, tool_stream: true };
      }
      return transformed;
    }

    const translated = translateRequest(
      FORMATS.OPENAI,
      FORMATS.CLAUDE,
      effectiveModel,
      { ...(record ?? {}), _disableToolPrefix: true },
      stream,
      credentials,
      this.provider,
      null,
      { preserveCacheControl: false }
    );

    // Inject effort and thinking for the Anthropic transport.
    // Zhipu's Anthropic endpoint requires thinking.type=enabled to emit
    // thinking_delta blocks in the SSE response. Without it, reasoning is
    // not surfaced and clients see no thinking content.
    // The effort-2025-11-24 beta header (in GLM_ANTHROPIC_BETA) carries
    // the high/max intensity selector.
    if (effortTier) {
      const translatedRecord = asRecord(translated);
      if (translatedRecord) {
        translatedRecord.effort = effortTier.effort;
        // Zhipu's Anthropic endpoint only supports thinking.type
        // "enabled"/"disabled" — not "adaptive". Clients like Claude Code
        // default to "adaptive" for reasoning models, so force "enabled"
        // here while preserving any other fields (e.g. budget_tokens).
        const existingThinking = asRecord(translatedRecord.thinking);
        if (!existingThinking || existingThinking.type !== "enabled") {
          translatedRecord.thinking = {
            ...existingThinking,
            type: "enabled",
          };
        }
      }
    }

    return translated;
  }

  private async executeTransport(
    input: ExecuteInput,
    transport: GlmTransport
  ): Promise<GlmExecuteResult> {
    const credentials = input.credentials;
    const url = buildGlmChatUrl(credentials?.providerSpecificData, transport, this.config.baseUrl);
    const headers = this.buildHeaders(
      credentials,
      input.stream,
      input.clientHeaders,
      input.model,
      transport
    );
    applyConfiguredUserAgent(headers, credentials.providerSpecificData);
    mergeUpstreamExtraHeaders(headers, input.upstreamExtraHeaders);

    const transformedBody = this.transformForTransport(
      input.model,
      input.body,
      input.stream,
      credentials,
      transport
    );

    const fetchStartTimeoutMs = this.getTimeoutMs();
    const timeoutController = fetchStartTimeoutMs > 0 ? new AbortController() : null;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    if (timeoutController) {
      timeoutId = setTimeout(() => {
        const timeoutError = new Error(`Fetch timeout after ${fetchStartTimeoutMs}ms on ${url}`);
        timeoutError.name = "TimeoutError";
        timeoutController.abort(timeoutError);
      }, fetchStartTimeoutMs);
    }

    const timeoutSignal = timeoutController?.signal ?? null;
    const combinedSignal =
      input.signal && timeoutSignal
        ? mergeAbortSignals(input.signal, timeoutSignal)
        : input.signal || timeoutSignal;

    let response: Response;
    try {
      response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(transformedBody),
        signal: combinedSignal || undefined,
      });
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
    }

    if (input.stream && response.ok) {
      const readiness = await ensureStreamReadiness(response, {
        timeoutMs: STREAM_READINESS_TIMEOUT_MS,
        provider: this.provider,
        model: input.model,
        log: input.log,
      });
      response = readiness.response;
    }

    const result = { response, url, headers, transformedBody };

    if (transport === "anthropic") {
      return this.finalizeAnthropicTransportResult(input, result);
    }

    return {
      ...result,
      url,
      headers,
      transformedBody,
      targetFormat: FORMATS.OPENAI,
    };
  }

  /**
   * GLM's Anthropic transport does its own Claude→OpenAI translation
   * (bypassing chatCore's stream), so the `</think>` close-marker
   * suppression flag and the response translation both have to be resolved
   * here from the original client headers (#5245 / #5312). Extracted from
   * `executeTransport` to keep that method's cyclomatic complexity under the
   * project cap.
   */
  private async finalizeAnthropicTransportResult(
    input: ExecuteInput,
    result: { response: Response; url: string; headers: Record<string, string>; transformedBody: unknown }
  ): Promise<GlmExecuteResult> {
    const { response: rawResponse, url, headers, transformedBody } = result;
    const clientHeaders = input.clientHeaders ?? {};
    const suppressThinkClose = resolveSuppressThinkClose({
      userAgent: clientHeaders["user-agent"] ?? clientHeaders["User-Agent"] ?? null,
      thinkingMarkerHeader:
        clientHeaders[THINKING_MARKER_HEADER] ??
        clientHeaders["x-omniroute-thinking-marker"] ??
        null,
      clientResponseFormat: input.clientResponseFormat ?? null,
    });

    const translatedResponse =
      input.stream && rawResponse.ok
        ? translateSseResponse(rawResponse, this.provider, input.model, suppressThinkClose)
        : isJsonResponse(rawResponse)
          ? await translateAnthropicJsonResponse(rawResponse)
          : rawResponse;
    return {
      response: translatedResponse,
      url,
      headers,
      transformedBody,
      targetFormat: FORMATS.OPENAI,
    };
  }

  async execute(input: ExecuteInput): Promise<GlmExecuteResult> {
    const effortTier = parseGlm52Effort(input.model);

    // GLM-5.2 effort tiers route directly through Anthropic transport (no fallback).
    // Zhipu only graduates effort on the Anthropic endpoint via the
    // effort-2025-11-24 beta header included in GLM_ANTHROPIC_BETA.
    if (effortTier) {
      return this.executeTransport(input, "anthropic");
    }

    const primaryTransport = getGlmTransport(
      input.credentials.providerSpecificData,
      this.config.baseUrl
    );
    const fallbackTransport: GlmTransport = primaryTransport === "openai" ? "anthropic" : "openai";

    let primaryResult: GlmExecuteResult | null = null;
    try {
      primaryResult = await this.executeTransport(input, primaryTransport);
      if (!isRetryableGlmFallbackStatus(primaryResult.response.status)) {
        return primaryResult;
      }
      input.log?.debug?.(
        "GLM_FALLBACK",
        `${primaryTransport} returned ${primaryResult.response.status}; trying ${fallbackTransport}`
      );
    } catch (error) {
      if (!isRetryableGlmFallbackError(error)) throw error;
      input.log?.debug?.(
        "GLM_FALLBACK",
        `${primaryTransport} error (${error instanceof Error ? error.message : String(error)}); trying ${fallbackTransport}`
      );
    }

    try {
      const fallbackResult = await this.executeTransport(input, fallbackTransport);
      if (fallbackResult.response.ok || !primaryResult) {
        return fallbackResult;
      }
    } catch (error) {
      if (!primaryResult) throw error;
      input.log?.debug?.(
        "GLM_FALLBACK",
        `${fallbackTransport} fallback failed (${error instanceof Error ? error.message : String(error)}); returning primary response`
      );
    }

    return primaryResult;
  }

  async countTokens(input: CountTokensInput) {
    return super.countTokens({
      ...input,
      credentials: {
        ...input.credentials,
        providerSpecificData: {
          ...(input.credentials.providerSpecificData || {}),
          primaryTransport: "anthropic",
        },
      },
    });
  }
}

export default GlmExecutor;

import { FORMATS } from "../translator/formats.ts";
import {
  buildGeminiThoughtSignatureKey,
  storeGeminiThoughtSignature,
} from "../services/geminiThoughtSignatureStore.ts";
import { normalizeOpenAICompatibleFinishReasonString } from "../utils/finishReason.ts";
import { containsTextualToolCallMarker } from "../utils/textualToolCall.ts";
import { getAnyReasoningValue } from "../utils/reasoningFields.ts";

type JsonRecord = Record<string, unknown>;

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toString(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

function toNumber(value: unknown, fallback = 0): number {
  const parsed =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim().length > 0
        ? Number(value)
        : Number.NaN;
  return Number.isFinite(parsed) ? parsed : fallback;
}

function firstPositiveNumber(...values: unknown[]): number {
  for (const value of values) {
    const parsed = toNumber(value, 0);
    if (parsed > 0) {
      return parsed;
    }
  }
  return 0;
}

function normalizeToolCallArgs(args: unknown): unknown {
  if (typeof args !== "string") return args;
  const trimmed = args.trim();
  if (!trimmed || !(trimmed.startsWith("{") || trimmed.startsWith("["))) return args;
  try {
    return JSON.parse(trimmed);
  } catch {
    return args;
  }
}

function parseTextualToolCall(text: unknown): { name: string; args: unknown } | null {
  if (typeof text !== "string") return null;

  // Gemini/Antigravity sometimes imitates the request-side fallback with small
  // variations, e.g. a leading "(empty)" marker or zero-width chars inserted
  // into argument strings. Normalize those variants before parsing so the
  // response is still surfaced as a structured OpenAI tool call.
  const normalized = text.replace(/[\u200B-\u200D\uFEFF]/g, "");
  const match = normalized.match(
    /^[\s\S]*?\[Tool call:\s*([^\]\n]+)\]\s*\nArguments:\s*([\s\S]+?)\s*$/
  );
  if (!match) return null;
  const name = match[1]?.trim();
  const rawArgs = match[2]?.trim();
  if (!name || !rawArgs) return null;
  try {
    let args = JSON.parse(rawArgs);
    if (typeof args === "string") {
      const trimmed = args.trim();
      if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
        args = JSON.parse(trimmed);
      }
    }
    if (args && typeof args === "object" && !Array.isArray(args)) {
      return { name, args };
    }
  } catch {}
  return null;
}

function extractMessageOutputText(item: JsonRecord): string {
  if (!Array.isArray(item.content)) return "";
  let text = "";
  for (const part of item.content) {
    if (!part || typeof part !== "object") continue;
    const partObj = toRecord(part);
    if (partObj.type === "output_text" && typeof partObj.text === "string") {
      text += partObj.text;
    }
  }
  return text;
}

/**
 * T19: Pick the last non-empty message output text from Responses API output.
 * Falls back to the last message item even when all message texts are empty.
 */
function findBestMessageText(output: unknown[]): {
  text: string;
  selectedMessageIndex: number;
  messageItems: JsonRecord[];
} {
  const messageItems = output
    .map((item) => toRecord(item))
    .filter((item) => item.type === "message" && Array.isArray(item.content));

  for (let i = messageItems.length - 1; i >= 0; i -= 1) {
    const text = extractMessageOutputText(messageItems[i]);
    if (text.trim().length > 0) {
      return { text, selectedMessageIndex: i, messageItems };
    }
  }

  if (messageItems.length > 0) {
    const lastIndex = messageItems.length - 1;
    return {
      text: extractMessageOutputText(messageItems[lastIndex]),
      selectedMessageIndex: lastIndex,
      messageItems,
    };
  }

  return { text: "", selectedMessageIndex: -1, messageItems: [] };
}

/**
 * Translate non-streaming response to OpenAI format
 * Handles different provider response formats (Gemini, Claude, etc.)
 *
 * @param toolNameMap - Optional Map<prefixedName, originalName> for Claude OAuth tool name stripping
 */
export function translateNonStreamingResponse(
  responseBody: unknown,
  targetFormat: string,
  sourceFormat: string,
  toolNameMap?: Map<string, string> | null
): unknown {
  // If already in source format, return as-is
  if (targetFormat === sourceFormat) {
    return responseBody;
  }

  let intermediateOpenAI = responseBody;

  // Handle OpenAI Responses API format
  if (targetFormat === FORMATS.OPENAI_RESPONSES) {
    const responseRoot = toRecord(responseBody);
    const response =
      responseRoot.object === "response"
        ? responseRoot
        : toRecord(responseRoot.response ?? responseRoot);
    const output = Array.isArray(response.output) ? response.output : [];
    const usage = toRecord(response.usage ?? responseRoot.usage);

    const messageSelection = findBestMessageText(output);
    let textContent = messageSelection.text;
    let reasoningContent = "";
    const toolCalls: JsonRecord[] = [];

    for (const item of output) {
      if (!item || typeof item !== "object") continue;
      const itemObj = toRecord(item);

      if (itemObj.type === "message" && Array.isArray(itemObj.content)) {
        for (const part of itemObj.content) {
          if (!part || typeof part !== "object") continue;
          const partObj = toRecord(part);
          if (partObj.type === "summary_text" && typeof partObj.text === "string") {
            reasoningContent += partObj.text;
          }
        }
      } else if (itemObj.type === "reasoning" && Array.isArray(itemObj.summary)) {
        for (const part of itemObj.summary) {
          const partObj = toRecord(part);
          if (partObj.type === "summary_text" && typeof partObj.text === "string") {
            reasoningContent += partObj.text;
          }
        }
      } else if (itemObj.type === "function_call") {
        const callId =
          toString(itemObj.call_id) ||
          toString(itemObj.id) ||
          `call_${Date.now()}_${toolCalls.length}`;
        let argsToEmit = itemObj.arguments;
        if (argsToEmit != null && typeof argsToEmit === "object" && !Array.isArray(argsToEmit)) {
          const cleaned: JsonRecord = { ...(argsToEmit as JsonRecord) };
          for (const [k, v] of Object.entries(cleaned)) {
            if (v === "" || (Array.isArray(v) && v.length === 0)) delete cleaned[k];
          }
          argsToEmit = cleaned;
        }

        const fnArgs =
          typeof argsToEmit === "string" ? argsToEmit : JSON.stringify(argsToEmit || {});
        const rawName = toString(itemObj.name);
        // Strip Claude OAuth proxy_ prefix using toolNameMap
        const resolvedName = toolNameMap?.get(rawName) ?? rawName;
        toolCalls.push({
          id: callId,
          type: "function",
          function: {
            name: resolvedName,
            arguments: fnArgs,
          },
        });
      }
    }

    const message: JsonRecord = { role: "assistant" };
    if (textContent) {
      message.content = textContent;
    }
    if (reasoningContent) {
      message.reasoning_content = reasoningContent;
    }
    if (toolCalls.length > 0) {
      message.tool_calls = toolCalls;
    }
    if (message.content === undefined) {
      message.content = "";
    }

    if (process.env.DEBUG_RESPONSES_SSE_TO_JSON === "true") {
      console.log(
        `[ResponsesSSE] ${output.length} output items, ${messageSelection.messageItems.length} message items`
      );
      messageSelection.messageItems.forEach((item, idx) => {
        const textLen = extractMessageOutputText(item).length;
        console.log(`  [${idx}] text length: ${textLen}`);
      });
      console.log(`  → Selected message index: ${messageSelection.selectedMessageIndex}`);
      console.log(`  → Final text content length: ${textContent.length}`);
    }

    const createdAt = toNumber(response.created_at, Math.floor(Date.now() / 1000));
    const model = toString(response.model || responseRoot.model, "openai-responses");
    const finishReason = toolCalls.length > 0 ? "tool_calls" : "stop";

    const result: JsonRecord = {
      id: `chatcmpl-${toString(response.id, String(Date.now()))}`,
      object: "chat.completion",
      created: createdAt,
      model,
      choices: [
        {
          index: 0,
          message,
          finish_reason: finishReason,
        },
      ],
    };

    if (Object.keys(usage).length > 0) {
      const inputTokens = toNumber(usage.input_tokens, 0);
      const outputTokens = toNumber(usage.output_tokens, 0);
      const inputTokensDetails = toRecord(usage.input_tokens_details);
      const outputTokensDetails = toRecord(usage.output_tokens_details);
      const promptTokensDetails = toRecord(usage.prompt_tokens_details);
      const completionTokensDetails = toRecord(usage.completion_tokens_details);
      const cachedInputTokens = firstPositiveNumber(
        inputTokensDetails.cached_tokens,
        promptTokensDetails.cached_tokens,
        usage.cache_read_input_tokens
      );
      const cacheCreationInputTokens = firstPositiveNumber(
        inputTokensDetails.cache_creation_tokens,
        promptTokensDetails.cache_creation_tokens,
        usage.cache_creation_input_tokens
      );
      const reasoningTokens = firstPositiveNumber(
        outputTokensDetails.reasoning_tokens,
        completionTokensDetails.reasoning_tokens,
        usage.reasoning_tokens
      );

      result.usage = {
        prompt_tokens: inputTokens,
        completion_tokens: outputTokens,
        total_tokens: inputTokens + outputTokens,
      };

      if (reasoningTokens > 0) {
        (result.usage as JsonRecord).completion_tokens_details = {
          reasoning_tokens: reasoningTokens,
        };
      }
      if (cachedInputTokens > 0 || cacheCreationInputTokens > 0) {
        (result.usage as JsonRecord).prompt_tokens_details = {};
        const promptDetails = (result.usage as JsonRecord).prompt_tokens_details as JsonRecord;
        if (cachedInputTokens > 0) {
          promptDetails.cached_tokens = cachedInputTokens;
        }
        if (cacheCreationInputTokens > 0) {
          promptDetails.cache_creation_tokens = cacheCreationInputTokens;
        }
      }
    }

    intermediateOpenAI = result;
  }

  // Handle Gemini/Antigravity format
  else if (targetFormat === FORMATS.GEMINI || targetFormat === FORMATS.ANTIGRAVITY) {
    const root = toRecord(responseBody);
    const response = toRecord(root.response ?? root);
    const candidates = Array.isArray(response.candidates) ? response.candidates : [];
    const usage = toRecord(response.usageMetadata ?? root.usageMetadata);
    const promptFeedback = toRecord(response.promptFeedback ?? root.promptFeedback);
    if (candidates.length > 0 || Object.keys(promptFeedback).length > 0) {
      const createdMs = Date.parse(toString(response.createTime));
      const created = Number.isFinite(createdMs)
        ? Math.floor(createdMs / 1000)
        : Math.floor(Date.now() / 1000);

      const choices =
        candidates.length > 0
          ? candidates.map((candidateValue, index) => {
              const candidate = toRecord(candidateValue);
              const content = toRecord(candidate.content);

              let textContent = "";
              const contentParts: JsonRecord[] = [];
              const toolCalls: JsonRecord[] = [];
              let reasoningContent = "";
              let pendingThoughtSignature = "";

              if (Array.isArray(content.parts)) {
                for (const part of content.parts) {
                  const partObj = toRecord(part);
                  if (partObj.thought === true && typeof partObj.text === "string") {
                    reasoningContent += partObj.text;
                    continue;
                  }

                  // Capture thoughtSignature from thinking parts (Gemini thinking models)
                  // so it can be stored alongside any subsequent functionCall part.
                  const partThoughtSig = toString(
                    partObj.thoughtSignature ?? partObj.thought_signature
                  );
                  if (partThoughtSig) {
                    pendingThoughtSignature = partThoughtSig;
                  }

                  if (typeof partObj.text === "string") {
                    const textualToolCall = parseTextualToolCall(partObj.text);
                    if (textualToolCall) {
                      const toolCallId = `call_${toString(textualToolCall.name, "unknown")}_${Date.now()}_${toolCalls.length}`;
                      toolCalls.push({
                        id: toolCallId,
                        type: "function",
                        function: {
                          name: textualToolCall.name,
                          arguments: JSON.stringify(textualToolCall.args || {}),
                        },
                      });
                    } else if (!containsTextualToolCallMarker(partObj.text)) {
                      textContent += partObj.text;
                      contentParts.push({ type: "text", text: partObj.text });
                    }
                  }

                  const inlineData = toRecord(partObj.inlineData ?? partObj.inline_data);
                  if (typeof inlineData.data === "string" && inlineData.data.length > 0) {
                    const mimeType = toString(
                      inlineData.mimeType ?? inlineData.mime_type,
                      "image/png"
                    );
                    contentParts.push({
                      type: "image_url",
                      image_url: { url: `data:${mimeType};base64,${inlineData.data}` },
                    });
                  }

                  if (partObj.functionCall) {
                    const fn = toRecord(partObj.functionCall);
                    const rawName = toString(fn.name);
                    const restoredName = toolNameMap?.get(rawName) ?? rawName;
                    const nativeId = toString(fn.id);
                    const toolCallId =
                      nativeId.length > 0
                        ? nativeId
                        : `call_${toString(restoredName, "unknown")}_${Date.now()}_${toolCalls.length}`;

                    // Persist the thought signature so openai-to-gemini can
                    // resolve it on the next turn. Use the part-level field
                    // (part.thoughtSignature) and fall back to any signature
                    // captured from an earlier thinking-only part.
                    const sig = partThoughtSig || pendingThoughtSignature;
                    if (sig) {
                      const sigKey = buildGeminiThoughtSignatureKey(null, toolCallId);
                      storeGeminiThoughtSignature(sigKey, sig);
                    }

                    toolCalls.push({
                      id: toolCallId,
                      type: "function",
                      function: {
                        name: restoredName,
                        arguments: JSON.stringify(normalizeToolCallArgs(fn.args || {})),
                      },
                    });
                  }
                }
              }

              const message: JsonRecord = { role: "assistant" };
              if (contentParts.length === 1 && contentParts[0].type === "text") {
                message.content = contentParts[0].text;
              } else if (contentParts.length > 0) {
                message.content = contentParts;
              } else if (textContent) {
                message.content = textContent;
              }
              if (reasoningContent) {
                message.reasoning_content = reasoningContent;
              }
              if (toolCalls.length > 0) {
                message.tool_calls = toolCalls;
              }
              if (!message.content && !message.tool_calls) {
                message.content = "";
              }

              let finishReason = normalizeOpenAICompatibleFinishReasonString(
                toString(candidate.finishReason, "stop")
              );
              if (finishReason === "stop" && toolCalls.length > 0) {
                finishReason = "tool_calls";
              }

              return {
                index,
                message,
                finish_reason: finishReason,
              };
            })
          : [
              {
                index: 0,
                message: { role: "assistant", content: "" },
                finish_reason: "content_filter",
              },
            ];

      const result: JsonRecord = {
        id: `chatcmpl-${toString(response.responseId, String(Date.now()))}`,
        object: "chat.completion",
        created,
        model: toString(response.modelVersion, "gemini"),
        choices,
      };

      if (Object.keys(usage).length > 0) {
        const promptTokens = toNumber(usage.promptTokenCount, 0);
        const reasoningTokens = toNumber(usage.thoughtsTokenCount, 0);
        const completionTokens = toNumber(usage.candidatesTokenCount, 0) + reasoningTokens;

        result.usage = {
          prompt_tokens: promptTokens,
          completion_tokens: completionTokens,
          total_tokens: toNumber(usage.totalTokenCount, 0),
        };
        if (reasoningTokens > 0) {
          (result.usage as JsonRecord).completion_tokens_details = {
            reasoning_tokens: reasoningTokens,
          };
        }
        if (toNumber(usage.cachedContentTokenCount, 0) > 0) {
          (result.usage as JsonRecord).prompt_tokens_details = {
            cached_tokens: toNumber(usage.cachedContentTokenCount, 0),
          };
        }
      }

      intermediateOpenAI = result;
    }
  }

  // Handle Claude format
  else if (targetFormat === FORMATS.CLAUDE) {
    const root = toRecord(responseBody);
    const contentBlocks = Array.isArray(root.content) ? root.content : [];
    if (contentBlocks.length > 0) {
      let textContent = "";
      let thinkingContent = "";
      const toolCalls: JsonRecord[] = [];

      for (const block of contentBlocks) {
        const blockObj = toRecord(block);
        if (blockObj.type === "text") {
          textContent += toString(blockObj.text);
        } else if (blockObj.type === "thinking") {
          thinkingContent += toString(blockObj.thinking);
        } else if (blockObj.type === "tool_use") {
          const rawName = toString(blockObj.name);
          const strippedName = toolNameMap?.get(rawName) ?? rawName;
          toolCalls.push({
            id: toString(blockObj.id, `call_${Date.now()}_${toolCalls.length}`),
            type: "function",
            function: {
              name: strippedName,
              arguments: JSON.stringify(blockObj.input || {}),
            },
          });
        }
      }

      const message: JsonRecord = { role: "assistant" };
      if (textContent) {
        message.content = textContent;
      }
      if (thinkingContent) {
        message.reasoning_content = thinkingContent;
      }
      if (toolCalls.length > 0) {
        message.tool_calls = toolCalls;
      }
      if (message.content === undefined) {
        message.content = "";
      }

      let finishReason = toString(root.stop_reason, "stop");
      if (finishReason === "end_turn") finishReason = "stop";
      if (finishReason === "tool_use") finishReason = "tool_calls";

      const result: JsonRecord = {
        id: `chatcmpl-${toString(root.id, String(Date.now()))}`,
        object: "chat.completion",
        created: Math.floor(Date.now() / 1000),
        model: toString(root.model, "claude"),
        choices: [
          {
            index: 0,
            message,
            finish_reason: finishReason,
          },
        ],
      };

      const usage = toRecord(root.usage);
      if (Object.keys(usage).length > 0) {
        // Mirror the streaming translator's usage contract (#1426/#2215):
        // cache_read folds into prompt_tokens (it is billed prompt input);
        // cache_creation stays out of prompt_tokens and is exposed via
        // prompt_tokens_details, alongside cached_tokens (OpenAI field name).
        const cachedTokens = toNumber(usage.cache_read_input_tokens, 0);
        const cacheCreationTokens = toNumber(usage.cache_creation_input_tokens, 0);
        const promptTokens = toNumber(usage.input_tokens, 0) + cachedTokens;
        const completionTokens = toNumber(usage.output_tokens, 0);
        const usageOut: JsonRecord = {
          prompt_tokens: promptTokens,
          completion_tokens: completionTokens,
          total_tokens: promptTokens + completionTokens,
        };
        if (cachedTokens > 0 || cacheCreationTokens > 0) {
          const details: JsonRecord = {};
          if (cachedTokens > 0) details.cached_tokens = cachedTokens;
          if (cacheCreationTokens > 0) details.cache_creation_tokens = cacheCreationTokens;
          usageOut.prompt_tokens_details = details;
        }
        result.usage = usageOut;
      }

      intermediateOpenAI = result;
    }
  }

  // Phase 3: Translate from OpenAI back to Client Source format
  if (sourceFormat === FORMATS.CLAUDE && sourceFormat !== targetFormat) {
    return convertOpenAINonStreamingToClaude(toRecord(intermediateOpenAI));
  }

  // Gemini-family clients (Gemini, Antigravity): the streaming SSE path already
  // projects OpenAI chunks into the `{ response: { candidates: [...] } }` envelope
  // via the registered FORMATS.OPENAI -> FORMATS.ANTIGRAVITY translator
  // (translator/response/openai-to-antigravity.ts), but this non-streaming path had
  // no equivalent back-conversion step — it silently returned the raw OpenAI
  // chat.completion shape (leaking `choices[]`/`tool_calls` instead of
  // `candidates[]`/`functionCall`) to any non-streaming Gemini/Antigravity client.
  if (
    (sourceFormat === FORMATS.GEMINI || sourceFormat === FORMATS.ANTIGRAVITY) &&
    sourceFormat !== targetFormat
  ) {
    return convertOpenAINonStreamingToGeminiFamily(toRecord(intermediateOpenAI));
  }

  // Return intermediateOpenAI (which is either the raw response if unknown targetFormat, or an OpenAI compatible payload)
  return intermediateOpenAI;
}

/**
 * Resolve reasoning/thinking text off a non-streaming OpenAI-format message object.
 * Delegates to the shared reasoning-field resolver (`open-sse/utils/reasoningFields.ts`)
 * so every reasoning alias — DeepSeek-style `reasoning_content`, the OpenRouter/StepFun
 * `reasoning` string, GitHub Copilot's `reasoning_text`, `thinking`/`thought`, and
 * `reasoning_details[]` (array of { text | content }) — is read from one place instead
 * of a divergent local copy. Mirrors the streaming translator's fallback chain in
 * open-sse/translator/response/openai-to-claude.ts.
 */
function resolveReasoningText(messageObj: JsonRecord): string {
  return getAnyReasoningValue(messageObj);
}

/**
 * Helper to convert an OpenAI chat.completion JSON object to Claude format for non-streaming.
 */
function convertOpenAINonStreamingToClaude(openaiResponse: JsonRecord): JsonRecord {
  const choices = openaiResponse.choices as unknown[] | undefined;
  const isChoicesArray = Array.isArray(choices);
  if (!isChoicesArray && openaiResponse.object !== "chat.completion") {
    return openaiResponse; // If it doesn't look like OpenAI, return as-is
  }

  const choice = isChoicesArray ? choices[0] : null;
  const choiceObj = choice ? toRecord(choice) : {};
  const messageObj = choiceObj.message ? toRecord(choiceObj.message) : {};

  const content: JsonRecord[] = [];

  let hasTextOrReasoning = false;

  const reasoningText = resolveReasoningText(messageObj);
  if (reasoningText) {
    hasTextOrReasoning = true;
    content.push({
      type: "thinking",
      thinking: reasoningText,
    });
  }

  // Always include text if it exists (even empty string), or if there are no tool calls and no reasoning
  const hasToolCalls = Array.isArray(messageObj.tool_calls) && messageObj.tool_calls.length > 0;

  if (messageObj.content !== undefined && messageObj.content !== null) {
    hasTextOrReasoning = true;
    const resolvedText = toString(messageObj.content);
    content.push({
      type: "text",
      text: resolvedText === "" ? "(empty response)" : resolvedText,
    });
  } else if (!hasTextOrReasoning) {
    content.push({
      type: "text",
      text: "(empty response)",
    });
  }

  if (Array.isArray(messageObj.tool_calls)) {
    for (const tool of messageObj.tool_calls) {
      const toolObj = toRecord(tool);
      const fn = toRecord(toolObj.function);
      content.push({
        type: "tool_use",
        id: toString(toolObj.id, `call_${Date.now()}`),
        name: toString(fn.name),
        input:
          typeof fn.arguments === "string" ? JSON.parse(fn.arguments || "{}") : fn.arguments || {},
      });
    }
  }

  let stopReason = toString(choiceObj.finish_reason, "end_turn");
  if (stopReason === "stop") stopReason = "end_turn";
  if (stopReason === "tool_calls") stopReason = "tool_use";

  const usageSrc = toRecord(openaiResponse.usage);
  const claudeResponse: JsonRecord = {
    id: toString(openaiResponse.id, `msg_${Date.now()}`),
    type: "message",
    role: "assistant",
    model: toString(openaiResponse.model, "claude"),
    content,
    stop_reason: stopReason,
    stop_sequence: null,
    usage: {
      input_tokens: toNumber(usageSrc.prompt_tokens, 0),
      output_tokens: toNumber(usageSrc.completion_tokens, 0),
    },
  };

  return claudeResponse;
}

const OPENAI_TO_GEMINI_FINISH_REASON: Record<string, string> = {
  stop: "STOP",
  length: "MAX_TOKENS",
  tool_calls: "STOP",
  content_filter: "SAFETY",
};

/**
 * Parse an OpenAI tool-call `arguments` payload into a Gemini `functionCall.args`
 * object. Never throws: a provider emitting malformed/truncated JSON must not take
 * down the whole non-streaming response path, so an unparseable payload degrades to
 * `{}` (matching the streaming Gemini translator's behaviour).
 */
function parseFunctionCallArgs(args: unknown): Record<string, unknown> {
  if (typeof args !== "string") return toRecord(args);
  try {
    return toRecord(JSON.parse(args || "{}"));
  } catch {
    return {};
  }
}

/**
 * Helper to convert an OpenAI chat.completion JSON object into the Gemini/Antigravity
 * `{ response: { candidates: [...] } }` envelope for non-streaming clients. Mirrors the
 * shape already produced for streaming by the registered
 * FORMATS.OPENAI -> FORMATS.ANTIGRAVITY translator
 * (translator/response/openai-to-antigravity.ts) so both paths agree.
 */
function convertOpenAINonStreamingToGeminiFamily(openaiResponse: JsonRecord): JsonRecord {
  const choices = openaiResponse.choices as unknown[] | undefined;
  const isChoicesArray = Array.isArray(choices);
  if (!isChoicesArray && openaiResponse.object !== "chat.completion") {
    return openaiResponse; // If it doesn't look like OpenAI, return as-is
  }

  const choice = isChoicesArray ? toRecord(choices[0]) : {};
  const messageObj = toRecord(choice.message);

  const parts: JsonRecord[] = [];
  const reasoningText = resolveReasoningText(messageObj);
  if (reasoningText) {
    parts.push({ text: reasoningText, thought: true });
  }
  if (typeof messageObj.content === "string" && messageObj.content.length > 0) {
    parts.push({ text: messageObj.content });
  }
  const toolCalls = Array.isArray(messageObj.tool_calls) ? messageObj.tool_calls : [];
  for (const toolCall of toolCalls) {
    const toolObj = toRecord(toolCall);
    const fn = toRecord(toolObj.function);
    parts.push({
      functionCall: {
        name: toString(fn.name),
        args: parseFunctionCallArgs(fn.arguments),
      },
    });
  }
  if (parts.length === 0) parts.push({ text: "" });

  const finishReason =
    OPENAI_TO_GEMINI_FINISH_REASON[toString(choice.finish_reason, "stop")] ?? "STOP";

  const usageSrc = toRecord(openaiResponse.usage);
  const promptTokens = toNumber(usageSrc.prompt_tokens, 0);
  const completionTokens = toNumber(usageSrc.completion_tokens, 0);

  const geminiResponse: JsonRecord = {
    response: {
      candidates: [
        {
          content: { role: "model", parts },
          finishReason,
          index: 0,
        },
      ],
      usageMetadata: {
        promptTokenCount: promptTokens,
        candidatesTokenCount: completionTokens,
        totalTokenCount: toNumber(usageSrc.total_tokens, promptTokens + completionTokens),
      },
      modelVersion: toString(openaiResponse.model, "unknown"),
      responseId: toString(openaiResponse.id, `resp_${Date.now()}`),
    },
  };

  return geminiResponse;
}

import { getDbInstance } from "../../src/lib/db/core.ts";

const MAX_SIGNATURES = 1000;
const MAX_PERSISTED_SIGNATURES = 2_000;
const MEMORY_TTL_MS = 1000 * 60 * 60;
const PERSISTED_TTL_MS = 1000 * 60 * 60 * 24 * 30;
const NAMESPACE = "gemini_thought_signatures";

export type SignatureCacheMode = "enabled" | "bypass" | "bypass-strict";

type Entry = {
  signature: string;
  expiresAt: number;
};

type PersistedEntry = Entry & {
  createdAt: number;
};

const signatures = new Map<string, Entry>();
let signatureCacheMode: SignatureCacheMode = "enabled";
let persistedPruneCounter = 0;
const MAX_LOGGED_ERRORS = 50;
const loggedPersistenceErrors = new Set<string>();

function warnPersistenceError(operation: string, error: unknown) {
  if (process.env.NODE_ENV === "test") return;
  if (loggedPersistenceErrors.has(operation)) return;
  if (loggedPersistenceErrors.size >= MAX_LOGGED_ERRORS) {
    const first = loggedPersistenceErrors.values().next().value;
    if (first !== undefined) loggedPersistenceErrors.delete(first);
  }
  loggedPersistenceErrors.add(operation);
  const message = error instanceof Error ? error.message : String(error);
  console.warn(`[signature-cache] persisted ${operation} failed: ${message}`);
}

export function buildGeminiThoughtSignatureKey(namespace: unknown, toolCallId: unknown): unknown {
  if (
    typeof namespace === "string" &&
    namespace.length > 0 &&
    typeof toolCallId === "string" &&
    toolCallId.length > 0
  ) {
    return `${namespace}:${toolCallId}`;
  }
  return toolCallId;
}

function pruneExpired() {
  const now = Date.now();
  for (const [key, value] of signatures.entries()) {
    if (value.expiresAt <= now) {
      signatures.delete(key);
    }
  }

  while (signatures.size > MAX_SIGNATURES) {
    const oldestKey = signatures.keys().next().value;
    if (!oldestKey) break;
    signatures.delete(oldestKey);
  }
}

function serializePersistedEntry(entry: PersistedEntry): string {
  return JSON.stringify(entry);
}

function parsePersistedEntry(value: string, now = Date.now()) {
  try {
    const parsed = JSON.parse(value) as Partial<PersistedEntry>;
    if (typeof parsed.signature !== "string" || parsed.signature.length === 0) return null;
    const createdAt = typeof parsed.createdAt === "number" ? parsed.createdAt : now;
    const expiresAt =
      typeof parsed.expiresAt === "number" ? parsed.expiresAt : now + PERSISTED_TTL_MS;
    if (expiresAt <= now) return null;
    return {
      entry: { signature: parsed.signature, createdAt, expiresAt },
      shouldRewrite: createdAt !== parsed.createdAt || expiresAt !== parsed.expiresAt,
    };
  } catch {
    if (!value) return null;
    return {
      entry: {
        signature: value,
        createdAt: now,
        expiresAt: now + PERSISTED_TTL_MS,
      },
      shouldRewrite: true,
    };
  }
}

function maybePrunePersistedSignatures(db: ReturnType<typeof getDbInstance>) {
  persistedPruneCounter += 1;
  if (persistedPruneCounter % 100 !== 0) return;

  const rows = db
    .prepare("SELECT key, value FROM key_value WHERE namespace = ?")
    .all(NAMESPACE) as Array<{ key: string; value: string }>;

  const now = Date.now();
  const validRows: Array<{ key: string; createdAt: number }> = [];
  const keysToDelete = new Set<string>();

  for (const row of rows) {
    const parsed = parsePersistedEntry(row.value, now);
    if (!parsed) {
      keysToDelete.add(row.key);
      continue;
    }
    validRows.push({ key: row.key, createdAt: parsed.entry.createdAt });
  }

  if (rows.length <= MAX_PERSISTED_SIGNATURES && keysToDelete.size === 0) return;

  validRows.sort((a, b) => b.createdAt - a.createdAt);
  for (const row of validRows.slice(MAX_PERSISTED_SIGNATURES)) {
    keysToDelete.add(row.key);
  }

  if (keysToDelete.size === 0) return;
  const remove = db.prepare("DELETE FROM key_value WHERE namespace = ? AND key = ?");
  const tx = db.transaction((keys: string[]) => {
    for (const key of keys) remove.run(NAMESPACE, key);
  });
  tx([...keysToDelete]);
}

export function storeGeminiThoughtSignature(toolCallId: unknown, signature: unknown) {
  if (typeof toolCallId !== "string" || !toolCallId) return;
  if (typeof signature !== "string" || !signature) return;

  const now = Date.now();
  pruneExpired();
  signatures.set(toolCallId, {
    signature,
    expiresAt: now + MEMORY_TTL_MS,
  });

  try {
    const db = getDbInstance();
    db.prepare("INSERT OR REPLACE INTO key_value (namespace, key, value) VALUES (?, ?, ?)").run(
      NAMESPACE,
      toolCallId,
      serializePersistedEntry({ signature, createdAt: now, expiresAt: now + PERSISTED_TTL_MS })
    );
    maybePrunePersistedSignatures(db);
  } catch (error) {
    warnPersistenceError("store", error);
  }
}

export function getGeminiThoughtSignature(toolCallId: unknown) {
  if (typeof toolCallId !== "string" || !toolCallId) return null;

  pruneExpired();
  const entry = signatures.get(toolCallId);
  if (entry) return entry.signature;

  try {
    const db = getDbInstance();
    const row = db
      .prepare("SELECT value FROM key_value WHERE namespace = ? AND key = ?")
      .get(NAMESPACE, toolCallId) as { value: string } | undefined;

    if (row?.value) {
      const persisted = parsePersistedEntry(row.value);
      if (!persisted) {
        db.prepare("DELETE FROM key_value WHERE namespace = ? AND key = ?").run(
          NAMESPACE,
          toolCallId
        );
        return null;
      }

      signatures.set(toolCallId, {
        signature: persisted.entry.signature,
        expiresAt: Date.now() + MEMORY_TTL_MS,
      });

      if (persisted.shouldRewrite) {
        db.prepare("UPDATE key_value SET value = ? WHERE namespace = ? AND key = ?").run(
          serializePersistedEntry(persisted.entry),
          NAMESPACE,
          toolCallId
        );
      }

      return persisted.entry.signature;
    }
  } catch (error) {
    warnPersistenceError("read", error);
  }

  return null;
}

export function normalizeSignatureCacheMode(value: unknown): SignatureCacheMode {
  return value === "bypass" || value === "bypass-strict" ? value : "enabled";
}

export function setGeminiThoughtSignatureMode(mode: unknown) {
  signatureCacheMode = normalizeSignatureCacheMode(mode);
}

export function getGeminiThoughtSignatureMode(): SignatureCacheMode {
  return signatureCacheMode;
}

function decodeSignature(signature: string): Buffer | null {
  if (!signature || (signature[0] !== "R" && signature[0] !== "E")) return null;

  const payload = signature.slice(1);
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(payload) || payload.length % 4 === 1) {
    return null;
  }

  try {
    const decoded = Buffer.from(payload, "base64");
    if (decoded.length === 0) return null;

    const canonical = decoded.toString("base64").replace(/=+$/g, "");
    if (canonical !== payload.replace(/=+$/g, "")) {
      return null;
    }

    return decoded;
  } catch {
    return null;
  }
}

function readVarint(
  buffer: Buffer,
  startOffset: number
): { nextOffset: number; value: number } | null {
  let offset = startOffset;
  let result = 0;
  let shift = 0;

  while (offset < buffer.length && shift < 35) {
    const byte = buffer[offset];
    result |= (byte & 0x7f) << shift;
    offset += 1;

    if ((byte & 0x80) === 0) {
      return { nextOffset: offset, value: result };
    }

    shift += 7;
  }

  return null;
}

export function isValidBasicGeminiThoughtSignature(signature: unknown): boolean {
  if (typeof signature !== "string") return false;
  const decoded = decodeSignature(signature);
  return Boolean(decoded && decoded[0] === 0x12);
}

export function isValidFullGeminiThoughtSignature(signature: unknown): boolean {
  if (typeof signature !== "string") return false;
  const decoded = decodeSignature(signature);
  if (!decoded || decoded[0] !== 0x12) return false;

  const outerLength = readVarint(decoded, 1);
  if (!outerLength) return false;

  const outerEnd = outerLength.nextOffset + outerLength.value;
  if (outerEnd !== decoded.length) return false;

  const inner = decoded.subarray(outerLength.nextOffset, outerEnd);
  if (inner.length === 0 || inner[0] !== 0x0a) return false;

  const innerLength = readVarint(inner, 1);
  if (!innerLength) return false;

  return innerLength.nextOffset + innerLength.value === inner.length;
}

export function resolveGeminiThoughtSignature(
  toolCallId: unknown,
  clientSignature?: unknown
): string | null {
  const persisted = getGeminiThoughtSignature(toolCallId);
  if (typeof clientSignature !== "string" || clientSignature.length === 0) {
    return persisted;
  }

  if (signatureCacheMode === "enabled") {
    return persisted;
  }

  const isValid =
    signatureCacheMode === "bypass-strict"
      ? isValidFullGeminiThoughtSignature(clientSignature)
      : isValidBasicGeminiThoughtSignature(clientSignature);

  if (isValid) {
    return clientSignature;
  }

  console.warn(
    `[signature-cache] ${signatureCacheMode}: invalid client thought signature, falling back`
  );
  return persisted;
}

export function clearGeminiThoughtSignatures() {
  signatures.clear();
  signatureCacheMode = "enabled";
  try {
    const db = getDbInstance();
    db.prepare("DELETE FROM key_value WHERE namespace = ?").run(NAMESPACE);
  } catch (error) {
    warnPersistenceError("clear", error);
  }
}

export function clearGeminiThoughtSignatureMemoryForTests() {
  signatures.clear();
}

export function getGeminiThoughtSignatureMemorySizeForTests() {
  pruneExpired();
  return signatures.size;
}

export function stripZeroWidth(value: unknown): unknown {
  if (typeof value === "string") {
    return value.replace(/[\u200B-\u200D\uFEFF]/g, "");
  }
  if (Array.isArray(value)) {
    return value.map((item) => stripZeroWidth(item));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, item]) => [
        key,
        stripZeroWidth(item),
      ])
    );
  }
  return value;
}

export function isValidToolCallHeaderPrefix(candidate: string): boolean {
  if (!candidate.startsWith("[Tool call:")) return false;

  const bracketIndex = candidate.indexOf("]");
  if (bracketIndex === -1) {
    const namePart = candidate.slice("[Tool call:".length);
    if (namePart.includes("\n") || namePart.includes("[")) return false;
    return true;
  }

  const namePart = candidate.slice("[Tool call:".length, bracketIndex);
  if (namePart.includes("\n") || namePart.trim().length === 0) return false;

  const afterBracket = candidate.slice(bracketIndex + 1);
  const leadingWhitespaceMatch = afterBracket.match(/^[\s\r\n]*/);
  const leadingWhitespace = leadingWhitespaceMatch ? leadingWhitespaceMatch[0] : "";
  const textAfterWhitespace = afterBracket.slice(leadingWhitespace.length);

  if (textAfterWhitespace.length === 0) {
    return true;
  }

  if (!leadingWhitespace.includes("\n")) {
    return false;
  }

  const expectedText = "Arguments:";
  if (expectedText.startsWith(textAfterWhitespace)) {
    return true;
  }

  if (textAfterWhitespace.startsWith(expectedText)) {
    return true;
  }

  return false;
}

export function parseTextualToolCallCandidate(
  text: unknown
): { kind: "complete"; name: string; args: unknown } | { kind: "partial" } | null {
  if (typeof text !== "string") return null;
  const normalized = text.replace(/[\u200B-\u200D\uFEFF]/g, "");
  const toolCallIndex = normalized.lastIndexOf("[Tool call:");
  if (toolCallIndex < 0) {
    const lastParen = normalized.lastIndexOf("(");
    if (lastParen !== -1 && "(empty)[Tool call:".startsWith(normalized.slice(lastParen))) {
      return { kind: "partial" };
    }
    const lastBracket = normalized.lastIndexOf("[");
    if (lastBracket !== -1 && "[Tool call:".startsWith(normalized.slice(lastBracket))) {
      return { kind: "partial" };
    }
    return null;
  }
  const candidate = normalized.slice(toolCallIndex);
  if (!isValidToolCallHeaderPrefix(candidate)) {
    return null;
  }
  const headerMatch = candidate.match(/^\[Tool call:\s*([^\]\n]+)\]\s*\nArguments:\s*/);
  if (!headerMatch) return { kind: "partial" };
  const name = headerMatch[1]?.trim();
  const rawArgs = candidate.slice(headerMatch[0].length).trim();
  if (!name || !rawArgs) return { kind: "partial" };
  const decoders = [
    (value: string) => value,
    (value: string) => {
      if (value.startsWith('"') && value.endsWith('"')) {
        const decoded = JSON.parse(value);
        return typeof decoded === "string" ? decoded : value;
      }
      return value;
    },
  ];
  for (const decode of decoders) {
    try {
      const decoded = decode(rawArgs);
      const parsed = JSON.parse(decoded);
      return { kind: "complete", name, args: stripZeroWidth(parsed) };
    } catch {}
  }
  return { kind: "partial" };
}

export function containsTextualToolCallMarker(text: unknown): boolean {
  if (typeof text !== "string") return false;
  const normalized = text.replace(/[\u200B-\u200D\uFEFF]/g, "");

  if (!normalized.includes("[Tool call:")) return false;
  if (normalized.includes("Arguments:")) return true;

  const trimmed = normalized.trim();
  return trimmed.startsWith("[Tool call:") || trimmed.startsWith("(empty)[Tool call:");
}

type JsonRecord = Record<string, unknown>;

export function asReasoningRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function nonEmptyString(value: unknown): string {
  return typeof value === "string" && value.length > 0 ? value : "";
}

export function extractReasoningDetailsText(value: unknown): string {
  const record = asReasoningRecord(value);
  if (!Array.isArray(record.reasoning_details)) return "";
  return record.reasoning_details
    .map((detail) => {
      const item = asReasoningRecord(detail);
      return nonEmptyString(item.text) || nonEmptyString(item.content);
    })
    .join("");
}

export function getReadableReasoningValue(value: unknown): string {
  const record = asReasoningRecord(value);
  return nonEmptyString(record.reasoning_content) || nonEmptyString(record.reasoning);
}

export function getUnsupportedReasoningValue(value: unknown): string {
  const record = asReasoningRecord(value);
  return (
    nonEmptyString(record.reasoning_text) ||
    nonEmptyString(record.thinking) ||
    nonEmptyString(record.thought) ||
    extractReasoningDetailsText(record)
  );
}

export function getAnyReasoningValue(value: unknown): string {
  return getReadableReasoningValue(value) || getUnsupportedReasoningValue(value);
}

export function hasUnsupportedReasoningSignal(value: unknown): boolean {
  const record = asReasoningRecord(value);
  return Boolean(
    !getReadableReasoningValue(record) &&
    (nonEmptyString(record.reasoning_text) ||
      nonEmptyString(record.thinking) ||
      nonEmptyString(record.thought) ||
      (Array.isArray(record.reasoning_details) && record.reasoning_details.length > 0))
  );
}

export function hasAnyReasoningSignal(value: unknown): boolean {
  const record = asReasoningRecord(value);
  return Boolean(
    getReadableReasoningValue(record) ||
    nonEmptyString(record.reasoning_text) ||
    nonEmptyString(record.thinking) ||
    nonEmptyString(record.thought) ||
    (Array.isArray(record.reasoning_details) && record.reasoning_details.length > 0)
  );
}

export function copyOpenAICompatibleReasoningFields(source: JsonRecord, target: JsonRecord) {
  if (source.reasoning_content !== undefined) target.reasoning_content = source.reasoning_content;
  if (source.reasoning !== undefined) target.reasoning = source.reasoning;
  if (source.reasoning_text !== undefined) target.reasoning_text = source.reasoning_text;
  if (Array.isArray(source.reasoning_details)) target.reasoning_details = source.reasoning_details;
  if (!getReadableReasoningValue(target)) {
    const mirrored = getUnsupportedReasoningValue(source);
    if (mirrored) target.reasoning_content = mirrored;
  }
}

