/**
 * Escape control characters (newlines, tabs, carriage returns) that appear
 * inside JSON string values, ensuring the resulting string is valid JSON.
 * This handles upstream providers (e.g. Gemini/Gemma) that emit literal
 * newlines (0x0A) instead of \n escapes inside tool call argument JSON.
 * Only escapes characters inside string contexts to avoid double-escaping
 * already-proper JSON or corrupting structural newlines.
 */
function escapeJsonStringValues(json: string): string {
  let result = "";
  let inString = false;

  for (let i = 0; i < json.length; i++) {
    const ch = json[i];

    // Inside a string, skip over escape sequences
    if (inString && ch === "\\") {
      result += ch + (json[i + 1] ?? "");
      i++;
      continue;
    }

    // Toggle string state on unescaped double quotes
    if (ch === '"') {
      result += ch;
      inString = !inString;
      continue;
    }

    // Escape control characters only inside string values
    if (inString && (ch === "\n" || ch === "\r" || ch === "\t")) {
      result += ch === "\n" ? "\\n" : ch === "\r" ? "\\r" : "\\t";
      continue;
    }

    result += ch;
  }

  return result;
}

/**
 * Translate OpenAI chunk to Responses API events
 * @returns {Array} Array of events with { event, data } structure
 */
export function openaiToOpenAIResponsesResponse(chunk, state) {
  if (!chunk) {
    return flushEvents(state);
  }

  // Capture usage from all chunks that carry it (usage-only chunks OR final chunks with finish_reason)
  // Normalize Chat Completions format (prompt_tokens/completion_tokens) to Responses API format
  // (input_tokens/output_tokens) so response.completed always has the fields Codex expects.
  if (chunk.usage) {
    const u = chunk.usage;
    const input_tokens = u.input_tokens ?? u.prompt_tokens ?? 0;
    const output_tokens = u.output_tokens ?? u.completion_tokens ?? 0;
    state.usage = {
      input_tokens,
      output_tokens,
      total_tokens: u.total_tokens ?? input_tokens + output_tokens,
    };
    const cachedTokens =
      u.input_tokens_details?.cached_tokens ?? u.prompt_tokens_details?.cached_tokens;
    if (cachedTokens) {
      state.usage.input_tokens_details = { cached_tokens: cachedTokens };
    }
    const reasoningTokens =
      u.output_tokens_details?.reasoning_tokens ?? u.completion_tokens_details?.reasoning_tokens;
    if (reasoningTokens) {
      state.usage.output_tokens_details = { reasoning_tokens: reasoningTokens };
    }
  }

  if (!chunk.choices?.length) {
    // Mid-stream aggregator error: OpenRouter (and similar OpenAI-compatible
    // aggregators) can send an HTTP 200 SSE stream whose body carries a chunk with
    // empty `choices` and a top-level `error` object instead of any delta — e.g. the
    // underlying provider hitting its own capacity limit mid-request. Without this
    // branch the chunk has no choices, so it falls into the awaitingTrailingUsage/
    // no-op path below and the stream silently ends with a false "completed, empty
    // output" response, masking the failure and skipping combo fallback. Surface it
    // as state.upstreamError so stream.ts errors the stream out (mirrors the
    // Gemini-to-OpenAI translator's #4177 fix).
    if (chunk.error && typeof chunk.error === "object") {
      const rawCode = chunk.error.code;
      const status =
        typeof rawCode === "number" && rawCode >= 400 && rawCode <= 599 ? rawCode : 502;
      state.upstreamError = {
        status,
        type: status === 429 ? "rate_limit_error" : "server_error",
        code:
          typeof chunk.error.metadata?.error_type === "string"
            ? chunk.error.metadata.error_type
            : status === 429
              ? "rate_limit_exceeded"
              : "bad_gateway",
        message: typeof chunk.error.message === "string" ? chunk.error.message : "Upstream failure",
      };
      return [];
    }
    // #6906: a deferred finish_reason (awaitingTrailingUsage, see below) completes here —
    // the trailing usage-only chunk (choices: [], usage: {...}) is what real
    // stream_options.include_usage=true upstreams send after finish_reason (see the
    // "READ THIS" block in stream.ts); state.usage was already captured above.
    if (state.awaitingTrailingUsage && !state.completedSent) {
      const { events, emit } = createEventEmitter(state);
      sendCompleted(state, emit);
      return events;
    }
    return [];
  }

  const { events, emit } = createEventEmitter(state);

  const choice = chunk.choices[0];
  const idx = choice.index || 0;
  const delta = choice.delta || {};
  if (state.parseTextualReasoningTags !== true && typeof chunk.model === "string") {
    state.parseTextualReasoningTags = shouldParseTextualReasoningTags(undefined, chunk.model);
  }
  const parseTextualReasoningTags = state.parseTextualReasoningTags === true;
  // #3697: remember the upstream-resolved model so response.created/in_progress/completed
  // can carry a `model` field (the Responses API spec has one; this translator previously
  // omitted it). Codex CLI compatibility shim (chatCore's echoModel pipeline) rewrites this
  // field to the client-requested effort-suffixed id for codex-originated requests.
  if (!state.model && typeof chunk.model === "string" && chunk.model.trim()) {
    state.model = chunk.model.trim();
  }

  // Emit initial events
  if (!state.started) {
    state.started = true;
    state.responseId = chunk.id ? `resp_${chunk.id}` : state.responseId;

    const createdResponse: Record<string, unknown> = {
      id: state.responseId,
      object: "response",
      created_at: state.created,
      status: "in_progress",
      background: false,
      error: null,
      output: [],
    };
    if (state.model) createdResponse.model = state.model;
    emit("response.created", {
      type: "response.created",
      response: createdResponse,
    });

    const inProgressResponse: Record<string, unknown> = {
      id: state.responseId,
      object: "response",
      created_at: state.created,
      status: "in_progress",
    };
    if (state.model) inProgressResponse.model = state.model;
    emit("response.in_progress", {
      type: "response.in_progress",
      response: inProgressResponse,
    });
  }

  if (delta.reasoning_content && !isInternalReasoningPlaceholder(delta.reasoning_content)) {
    startReasoning(state, emit, idx);
    emitReasoningDelta(state, emit, delta.reasoning_content);
  }
  // Strip the internal reasoning placeholder if the model echoed it
  // through ordinary content (#8081). Only the text-content emission is
  // skipped when nothing meaningful remains; tool_calls / finish_reason
  // handling below must still run for this same chunk.
  if (delta.content) {
    const strippedContent = stripInternalReasoningPlaceholder(delta.content);
    if (strippedContent) {
      if (
        state.reasoningId &&
        !state.reasoningDone &&
        (!parseTextualReasoningTags || !state.inThinking)
      ) {
        closeReasoning(state, emit);
      }

      let content = strippedContent;

      if (parseTextualReasoningTags) {
        if (content.includes("<think>")) {
          state.inThinking = true;
          content = content.replaceAll("<think>", "");
          startReasoning(state, emit, idx);
        }

        if (content.includes("</think>")) {
          const parts = content.split("</think>");
          const thinkPart = parts[0];
          const textPart = parts.slice(1).join("</think>");
          if (thinkPart) emitReasoningDelta(state, emit, thinkPart);
          closeReasoning(state, emit);
          state.inThinking = false;
          content = textPart;
        }

        if (state.inThinking && content) {
          emitReasoningDelta(state, emit, content);
          // Pre-existing behaviour (unrelated to #8081): a still-open
          // textual <think> block ends this chunk's handling early.
          return events;
        }
      }

      if (content) {
        const msgIdx = state.reasoningId ? state.reasoningIndex + 1 : idx;
        emitTextContent(state, emit, msgIdx, content);
      }
    }
  }

  // Handle tool_calls
  if (delta.tool_calls) {
    // Close reasoning first so tool calls do not collide with an open
    // reasoning item, then close the message at its real index.
    if (state.reasoningId && !state.reasoningDone) {
      closeReasoning(state, emit);
    }
    const msgIdx = state.reasoningId ? state.reasoningIndex + 1 : idx;
    closeMessage(state, emit, msgIdx);
    for (const tc of delta.tool_calls) {
      emitToolCall(state, emit, tc);
    }
  }

  // Handle finish_reason
  if (choice.finish_reason) {
    for (const i in state.msgItemAdded) closeMessage(state, emit, i);
    closeReasoning(state, emit);
    for (const i in state.funcCallIds) closeToolCall(state, emit, i);
    // #6906: usage already captured (same chunk or earlier) completes now; otherwise
    // defer for a trailing usage-only chunk, handled above and in flushEvents().
    if (state.usage) {
      sendCompleted(state, emit);
    } else {
      state.awaitingTrailingUsage = true;
    }
  }

  return events;
}

// Normalize output_index to a non-negative integer (replaces fragile parseInt calls)
// Record a finalized item keyed by output_index so buildDenseOutput can sort later
function recordCompletedItem(state, outputIndex, item) {
  if (!Array.isArray(state.completedOutputItems)) {
    state.completedOutputItems = [];
  }
  const normalized = normalizeOutputIndex(outputIndex);
  state.completedOutputItems.push({ output_index: normalized, item, seq: state.seq });
  return normalized;
}

// Build a dense, deterministic output array sorted by output_index then by seq
function buildDenseOutput(state) {
  const items = Array.isArray(state.completedOutputItems) ? state.completedOutputItems : [];
  return items
    .slice()
    .sort((left, right) => {
      if (left.output_index !== right.output_index) {
        return left.output_index - right.output_index;
      }
      return left.seq - right.seq;
    })
    .map(({ item }) => item);
}

// Helper functions
function startReasoning(state, emit, idx) {
  if (!state.reasoningId) {
    state.reasoningId = `rs_${state.responseId}_${idx}`;
    state.reasoningIndex = idx;

    emit("response.output_item.added", {
      type: "response.output_item.added",
      output_index: idx,
      item: { id: state.reasoningId, type: "reasoning", summary: [] },
    });

    emit("response.reasoning_summary_part.added", {
      type: "response.reasoning_summary_part.added",
      item_id: state.reasoningId,
      output_index: idx,
      summary_index: 0,
      part: { type: "summary_text", text: "" },
    });
    state.reasoningPartAdded = true;
  }
}

function emitReasoningDelta(state, emit, text) {
  if (!text) return;
  state.reasoningBuf += text;
  emit("response.reasoning_summary_text.delta", {
    type: "response.reasoning_summary_text.delta",
    item_id: state.reasoningId,
    output_index: state.reasoningIndex,
    summary_index: 0,
    delta: text,
  });
}

function closeReasoning(state, emit) {
  if (state.reasoningId && !state.reasoningDone) {
    state.reasoningDone = true;

    emit("response.reasoning_summary_text.done", {
      type: "response.reasoning_summary_text.done",
      item_id: state.reasoningId,
      output_index: state.reasoningIndex,
      summary_index: 0,
      text: state.reasoningBuf,
    });

    emit("response.reasoning_summary_part.done", {
      type: "response.reasoning_summary_part.done",
      item_id: state.reasoningId,
      output_index: state.reasoningIndex,
      summary_index: 0,
      part: { type: "summary_text", text: state.reasoningBuf },
    });

    const reasoningItem = {
      id: state.reasoningId,
      type: "reasoning",
      summary: [{ type: "summary_text", text: state.reasoningBuf }],
    };

    emit("response.output_item.done", {
      type: "response.output_item.done",
      output_index: state.reasoningIndex,
      item: reasoningItem,
    });

    recordCompletedItem(state, state.reasoningIndex, reasoningItem);
  }
}

function emitTextContent(state, emit, idx, content) {
  if (!state.msgItemAdded[idx]) {
    state.msgItemAdded[idx] = true;
    const msgId = `msg_${state.responseId}_${idx}`;

    emit("response.output_item.added", {
      type: "response.output_item.added",
      output_index: idx,
      item: { id: msgId, type: "message", content: [], role: "assistant" },
    });
  }

  if (!state.msgContentAdded[idx]) {
    state.msgContentAdded[idx] = true;

    emit("response.content_part.added", {
      type: "response.content_part.added",
      item_id: `msg_${state.responseId}_${idx}`,
      output_index: idx,
      content_index: 0,
      part: { type: "output_text", annotations: [], logprobs: [], text: "" },
    });
  }

  emit("response.output_text.delta", {
    type: "response.output_text.delta",
    item_id: `msg_${state.responseId}_${idx}`,
    output_index: idx,
    content_index: 0,
    delta: content,
    logprobs: [],
  });

  if (!state.msgTextBuf[idx]) state.msgTextBuf[idx] = "";
  state.msgTextBuf[idx] += content;
}

function closeMessage(state, emit, idx) {
  if (state.msgItemAdded[idx] && !state.msgItemDone[idx]) {
    state.msgItemDone[idx] = true;
    const fullText = state.msgTextBuf[idx] || "";
    const normalizedIndex = normalizeOutputIndex(idx);
    const msgId = `msg_${state.responseId}_${normalizedIndex}`;

    emit("response.output_text.done", {
      type: "response.output_text.done",
      item_id: msgId,
      output_index: normalizedIndex,
      content_index: 0,
      text: fullText,
      logprobs: [],
    });

    emit("response.content_part.done", {
      type: "response.content_part.done",
      item_id: msgId,
      output_index: normalizedIndex,
      content_index: 0,
      part: { type: "output_text", annotations: [], logprobs: [], text: fullText },
    });

    const msgItem = {
      id: msgId,
      type: "message",
      content: [{ type: "output_text", annotations: [], logprobs: [], text: fullText }],
      role: "assistant",
    };

    emit("response.output_item.done", {
      type: "response.output_item.done",
      output_index: normalizedIndex,
      item: msgItem,
    });

    recordCompletedItem(state, normalizedIndex, msgItem);
  }
}

function emitToolCall(state, emit, tc) {
  const tcIdx = tc.index ?? 0;
  const outputIndex = state.reasoningId
    ? normalizeOutputIndex(state.reasoningIndex) + 1 + normalizeOutputIndex(tcIdx)
    : normalizeOutputIndex(tcIdx);
  const newCallId = tc.id;
  const funcName = tc.function?.name;

  // T37: If we already have a tool call at this index but the ID changed,
  // we must close the current one and start a new one to prevent merging.
  if (state.funcCallIds[tcIdx] && newCallId && state.funcCallIds[tcIdx] !== newCallId) {
    // Superseded call: close and emit output_item.done but do NOT record as final output
    // since this call was replaced by a new one at the same index.
    closeToolCall(state, emit, tcIdx, false);
    delete state.funcCallIds[tcIdx];
    delete state.funcNames[tcIdx];
    delete state.funcArgsBuf[tcIdx];
    delete state.funcArgsDone[tcIdx];
    delete state.funcItemAdded[tcIdx];
    delete state.funcItemDone[tcIdx];
  }

  if (funcName) state.funcNames[tcIdx] = funcName;

  // Custom tools are surfaced as custom_tool_call items and stream raw input instead of the
  // function_call_arguments.* events used for regular function tools. (#1007)
  const toolName = state.funcNames[tcIdx] || funcName || "";
  const isCustomTool =
    toolName === "apply_patch" || state.customToolNames?.has?.(toolName) === true;

  if (!state.funcCallIds[tcIdx] && newCallId) state.funcCallIds[tcIdx] = newCallId;
  const callId = state.funcCallIds[tcIdx];

  if (callId && toolName && !state.funcItemAdded[tcIdx]) {
    // #7936 — restore the codex-side `{namespace, name}` pair when the bare
    // leaf on the Chat wire was flattened from a Responses namespace sub-tool.
    // Codex dispatches from `namespace` independently of `name` (no `__` split).
    const identity = resolveRequestToolIdentity(state.requestToolIdentityMap, toolName);
    emit("response.output_item.added", {
      type: "response.output_item.added",
      output_index: outputIndex,
      item: buildResponsesToolCallItem({
        callId,
        toolName: identity ? identity.name : toolName,
        custom: isCustomTool,
        namespace: identity ? identity.namespace : null,
      }),
    });
    state.funcItemAdded[tcIdx] = true;

    const bufferedArgs = state.funcArgsBuf[tcIdx] || "";
    if (bufferedArgs && !isCustomTool) {
      emit("response.function_call_arguments.delta", {
        type: "response.function_call_arguments.delta",
        item_id: `fc_${callId}`,
        output_index: outputIndex,
        delta: bufferedArgs,
      });
    }
  }

  if (!state.funcArgsBuf[tcIdx]) state.funcArgsBuf[tcIdx] = "";

  if (tc.function?.arguments) {
    const refCallId = state.funcCallIds[tcIdx] || newCallId;
    const existingArgs = state.funcArgsBuf[tcIdx] || "";
    const sanitized = escapeJsonStringValues(tc.function.arguments);
    const nextArgs = appendToolCallArgumentDelta(existingArgs, sanitized);
    const emittedDelta = nextArgs.slice(existingArgs.length);
    state.funcArgsBuf[tcIdx] = nextArgs;

    if (refCallId && emittedDelta && !isCustomTool && state.funcItemAdded[tcIdx]) {
      emit("response.function_call_arguments.delta", {
        type: "response.function_call_arguments.delta",
        item_id: `fc_${refCallId}`,
        output_index: outputIndex,
        delta: emittedDelta,
      });
    }
  }
}

function closeToolCall(state, emit, idx, recordAsCompleted = true) {
  const callId = state.funcCallIds[idx];
  if (callId && !state.funcItemDone[idx]) {
    const normalizedIndex = state.reasoningId
      ? normalizeOutputIndex(state.reasoningIndex) + 1 + normalizeOutputIndex(idx)
      : normalizeOutputIndex(idx);
    const args = state.funcArgsBuf[idx] || "{}";
    const toolName = state.funcNames[idx] || "";
    const isCustomTool =
      toolName === "apply_patch" || state.customToolNames?.has?.(toolName) === true;

    let funcItem;
    if (isCustomTool) {
      // The model produced JSON {"input":"..."} against the normalized custom-tool schema.
      // Unwrap it back to the raw patch string the Codex runtime expects. (#1007)
      let rawInput = args;
      try {
        const parsed = JSON.parse(args);
        if (parsed && typeof parsed.input === "string") rawInput = parsed.input;
      } catch {
        // Not JSON — fall back to the raw buffered arguments.
      }

      emit("response.custom_tool_call_input.delta", {
        type: "response.custom_tool_call_input.delta",
        item_id: `fc_${callId}`,
        output_index: normalizedIndex,
        delta: rawInput,
      });

      emit("response.custom_tool_call_input.done", {
        type: "response.custom_tool_call_input.done",
        item_id: `fc_${callId}`,
        output_index: normalizedIndex,
        input: rawInput,
      });

      funcItem = {
        id: `fc_${callId}`,
        type: "custom_tool_call",
        input: rawInput,
        call_id: callId,
        name: state.funcNames[idx] || "",
        status: "completed",
      };

      // #7936 identity closure for custom_tool_call items (apply_patch stays
      // bare; namespace sub-tools get back their `namespace` + `name`).
      const customIdentity = resolveRequestToolIdentity(
        state.requestToolIdentityMap,
        state.funcNames[idx] || ""
      );
      if (customIdentity) {
        funcItem.namespace = customIdentity.namespace;
        funcItem.name = customIdentity.name;
      }

      emit("response.output_item.done", {
        type: "response.output_item.done",
        output_index: normalizedIndex,
        item: funcItem,
      });
    } else {
      emit("response.function_call_arguments.done", {
        type: "response.function_call_arguments.done",
        item_id: `fc_${callId}`,
        output_index: normalizedIndex,
        arguments: args,
      });

      funcItem = {
        id: `fc_${callId}`,
        type: "function_call",
        arguments: args,
        call_id: callId,
        name: state.funcNames[idx] || "",
        status: "completed",
      };

      // #7936 identity closure: rewrite the function_call item's `name` back to
      // its bare leaf and stamp the original `namespace` alongside it, matching
      // the codex ResponseItem::FunctionCall schema (independent `namespace`
      // field, NOT a `__` split on `name`).
      const fnIdentity = resolveRequestToolIdentity(
        state.requestToolIdentityMap,
        state.funcNames[idx] || ""
      );
      if (fnIdentity) {
        funcItem.namespace = fnIdentity.namespace;
        funcItem.name = fnIdentity.name;
      }

      emit("response.output_item.done", {
        type: "response.output_item.done",
        output_index: normalizedIndex,
        item: funcItem,
      });
    }

    // Only record as a completed output item when this is a final close (not a
    // superseded-call eviction where a new call replaced this one at the same index).
    if (recordAsCompleted) {
      recordCompletedItem(state, normalizedIndex, funcItem);
      // Mirror into the shared state.toolCalls map (populated by the other response
      // translators) so stream.ts's completion-log summary reports finish_reason
      // "tool_calls" and message.tool_calls instead of "stop" with no tool calls.
      if (state.toolCalls instanceof Map) {
        state.toolCalls.set(idx, {
          id: callId,
          index: normalizedIndex,
          type: isCustomTool ? "custom_tool_call" : "function",
          function: { name: funcItem.name, arguments: args },
        });
      }
    }

    state.funcItemDone[idx] = true;
    state.funcArgsDone[idx] = true;
  }
}

function sendCompleted(state, emit) {
  if (!state.completedSent) {
    state.completedSent = true;

    // Build a dense, deterministic output array from items recorded as they were emitted
    // (each close*() call records its item via recordCompletedItem — including the
    // #1007 custom_tool_call shape for apply_patch). Sorted by output_index then by
    // emission sequence for stable ordering.
    const output = buildDenseOutput(state);

    // Surface upstream mid-stream errors (e.g. Gemini 503) in the
    // Responses-API `response.completed` event instead of silently emitting
    // `status: "completed"`. The error is set by the Gemini-to-OpenAI
    // translator or the OpenAI-Responses translator itself when the upstream
    // SSE stream emits a JSON error object after partial content.
    const upstreamErr = state.upstreamError;

    const response: Record<string, unknown> = {
      id: state.responseId,
      object: "response",
      created_at: state.created,
      status: upstreamErr ? "failed" : "completed",
      background: false,
      error: upstreamErr
        ? { code: String(upstreamErr.status ?? ""), message: upstreamErr.message ?? "" }
        : null,
      output,
    };

    // #3697: same model echo as response.created/in_progress above.
    if (state.model) {
      response.model = state.model;
    }

    if (state.usage) {
      response.usage = state.usage;
    }

    emit("response.completed", {
      type: "response.completed",
      response,
    });
  }
}

function flushEvents(state) {
  if (state.completedSent) return [];

  const { events, emit } = createEventEmitter(state);

  for (const i in state.msgItemAdded) closeMessage(state, emit, i);
  closeReasoning(state, emit);
  for (const i in state.funcCallIds) closeToolCall(state, emit, i);
  sendCompleted(state, emit);

  return events;
}

// #5786 — remember that a reasoning delta was streamed for a given reasoning item, so
// the terminal `response.output_item.done` snapshot for that item is NOT re-emitted
// (which would duplicate the reasoning channel). Keyed by item_id when present, with a
// global fallback for streams whose deltas carry no item_id.
function markResponsesReasoningDeltaEmitted(state, itemId) {
  state.reasoningDeltaEmitted = true;
  const id = itemId != null ? String(itemId) : "";
  if (!id) return;
  if (!(state.reasoningItemsWithDelta instanceof Set)) {
    state.reasoningItemsWithDelta = new Set();
  }
  state.reasoningItemsWithDelta.add(id);
}

// #5786 — build a Chat-format reasoning delta chunk in the shape the client renders in
// its thinking panel (`reasoning_content`, or `reasoning_text` for Copilot-compatible
// clients). Mirrors the `response.reasoning_summary_text.delta` branch.
function buildResponsesReasoningDeltaChunk(state, text) {
  if (isInternalReasoningPlaceholder(text)) return null;
  const delta = state.copilotCompatibleReasoning
    ? { reasoning_text: text }
    : { reasoning_content: text };
  return {
    id: state.chatId,
    object: "chat.completion.chunk",
    created: state.created,
    model: state.model || "gpt-4",
    choices: [
      {
        index: 0,
        delta,
        finish_reason: null,
      },
    ],
  };
}

/**
 * Translate OpenAI Responses API chunk to OpenAI Chat Completions format
 * This is for when Codex returns data and we need to send it to an OpenAI-compatible client
 */
export function openaiResponsesToOpenAIResponse(chunk, state) {
  return withAssistantRoleOnFirstDelta(state, openaiResponsesToOpenAIResponseStream(chunk, state));
}

function openaiResponsesToOpenAIResponseStream(chunk, state) {
  if (!chunk) {
    // Flush: send final chunk with finish_reason
    if (!state.finishReasonSent && state.started) {
      state.finishReasonSent = true;
      const finishReason = computeFinishReason(state);
      return {
        id: state.chatId || `chatcmpl-${Date.now()}`,
        object: "chat.completion.chunk",
        created: state.created || Math.floor(Date.now() / 1000),
        model: state.model || "gpt-4",
        choices: [
          {
            index: 0,
            delta: {},
            finish_reason: finishReason,
          },
        ],
      };
    }
    return null;
  }

  // Handle different event types from Responses API
  const eventType = chunk.type || chunk.event;
  const data = chunk.data || chunk;

  if (!state.model) {
    const upstreamModel =
      (data?.response && typeof data.response === "object" && data.response.model) ||
      data?.model ||
      data?.modelVersion ||
      data?.model_version ||
      null;

    if (typeof upstreamModel === "string" && upstreamModel.trim().length > 0) {
      state.model = upstreamModel.trim();
    }
  }

  // Initialize state
  if (!state.started) {
    state.started = true;
    state.chatId = `chatcmpl-${Date.now()}`;
    state.created = Math.floor(Date.now() / 1000);
    state.toolCallIndex = 0;
    state.currentToolCallId = null;
  }

  // Text content delta
  if (eventType === "response.output_text.delta") {
    const delta = data.delta || "";
    if (!delta) return null;

    return {
      id: state.chatId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "gpt-4",
      choices: [
        {
          index: 0,
          delta: { content: delta },
          finish_reason: null,
        },
      ],
    };
  }

  // Text content done (ignore, we handle via delta)
  if (eventType === "response.output_text.done") {
    return null;
  }

  // Function call started
  if (eventType === "response.output_item.added" && data.item?.type === "function_call") {
    const item = data.item;
    state.currentToolCallId = item.call_id || fallbackToolCallId();
    state.currentToolCallArgsBuffer = ""; // reset per-call arg buffer
    state.currentToolCallDeferred = false;

    // Track this call_id so response.completed doesn't synthesize a duplicate
    if (!state.toolCallIdsSeen) state.toolCallIdsSeen = new Set();
    if (state.currentToolCallId) state.toolCallIdsSeen.add(state.currentToolCallId);

    const toolName = normalizeToolName(item.name);
    if (!toolName) {
      // Some Responses providers briefly emit placeholder/empty tool names.
      // Defer emission until output_item.done in case the final name is populated there.
      state.currentToolCallDeferred = true;
      return null;
    }

    return {
      id: state.chatId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "gpt-4",
      choices: [
        {
          index: 0,
          delta: {
            tool_calls: [
              {
                index: state.toolCallIndex,
                id: state.currentToolCallId,
                type: "function",
                function: {
                  name: toolName,
                  arguments: "",
                },
              },
            ],
          },
          finish_reason: null,
        },
      ],
    };
  }

  // Function call arguments delta
  // NOTE: Do NOT include `id` or `type` here - only first chunk (response.output_item.added)
  // should have them. Including `id` on every chunk causes openai-to-claude.ts to emit
  // a new content_block_start for each delta, breaking Claude Code ACP sessions.
  if (eventType === "response.function_call_arguments.delta") {
    const argsDelta = data.delta || "";
    if (!argsDelta) return null;

    state.currentToolCallArgsBuffer = (state.currentToolCallArgsBuffer || "") + argsDelta;
    if (state.currentToolCallDeferred) return null;

    return {
      id: state.chatId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "gpt-4",
      choices: [
        {
          index: 0,
          delta: {
            tool_calls: [
              {
                index: state.toolCallIndex,
                function: { arguments: argsDelta },
              },
            ],
          },
          finish_reason: null,
        },
      ],
    };
  }

  // Function call done — emit args chunk from item.arguments when no deltas were received,
  // then advance the tool-call index. This handles Codex Responses API payloads that
  // carry the complete arguments only in output_item.done (no preceding delta events).
  if (eventType === "response.output_item.done" && data.item?.type === "function_call") {
    const item = data.item;
    const buffered = state.currentToolCallArgsBuffer || "";
    const currentIndex = state.toolCallIndex; // capture before increment
    const callId = item.call_id || state.currentToolCallId || fallbackToolCallId();
    const toolName = normalizeToolName(item.name);
    const toolSchema = state.toolSchemas?.get(toolName);

    // Track this call_id so response.completed doesn't synthesize a duplicate
    if (!state.toolCallIdsSeen) state.toolCallIdsSeen = new Set();
    if (callId) state.toolCallIdsSeen.add(callId);

    if (state.currentToolCallDeferred) {
      state.currentToolCallDeferred = false;
      state.currentToolCallArgsBuffer = "";
      state.currentToolCallId = null;

      if (!toolName) {
        return null;
      }

      state.toolCallIndex++;

      const argsToEmit = stripEmptyOptionalToolArgs(item.arguments, toolName, toolSchema);

      const argsStr =
        argsToEmit != null
          ? typeof argsToEmit === "string"
            ? argsToEmit
            : JSON.stringify(argsToEmit)
          : buffered;

      return {
        id: state.chatId,
        object: "chat.completion.chunk",
        created: state.created,
        model: state.model || "gpt-4",
        choices: [
          {
            index: 0,
            delta: {
              tool_calls: [
                {
                  index: currentIndex,
                  id: callId,
                  type: "function",
                  function: {
                    name: toolName,
                    arguments: argsStr || "",
                  },
                },
              ],
            },
            finish_reason: null,
          },
        ],
      };
    }

    state.toolCallIndex++;
    state.currentToolCallArgsBuffer = ""; // reset for next tool call
    state.currentToolCallId = null;

    // Only emit if arguments exist in the done event AND they weren't already streamed via deltas
    if (item.arguments != null && !buffered) {
      const argsToEmit = stripEmptyOptionalToolArgs(item.arguments, toolName, toolSchema);

      const argsStr = typeof argsToEmit === "string" ? argsToEmit : JSON.stringify(argsToEmit);
      if (argsStr) {
        return {
          id: state.chatId,
          object: "chat.completion.chunk",
          created: state.created,
          model: state.model || "gpt-4",
          choices: [
            {
              index: 0,
              delta: {
                tool_calls: [
                  {
                    index: currentIndex,
                    function: { arguments: argsStr },
                  },
                ],
              },
              finish_reason: null,
            },
          ],
        };
      }
    }

    return null;
  }

  // Response completed
  if (eventType === "response.completed") {
    // Extract usage from response.completed event
    const responseUsage = data.response?.usage;
    if (responseUsage && typeof responseUsage === "object") {
      const inputTokens = responseUsage.input_tokens || responseUsage.prompt_tokens || 0;
      const outputTokens = responseUsage.output_tokens || responseUsage.completion_tokens || 0;
      const cacheReadTokens =
        responseUsage.cache_read_input_tokens ||
        responseUsage.input_tokens_details?.cached_tokens ||
        responseUsage.prompt_tokens_details?.cached_tokens ||
        0;
      const cacheCreationTokens = responseUsage.cache_creation_input_tokens || 0;
      const reasoningTokens =
        responseUsage.output_tokens_details?.reasoning_tokens ||
        responseUsage.completion_tokens_details?.reasoning_tokens ||
        responseUsage.reasoning_tokens ||
        0;

      // prompt_tokens = input_tokens + cache_read + cache_creation (all prompt-side tokens)
      const promptTokens = inputTokens + cacheReadTokens + cacheCreationTokens;

      state.usage = {
        prompt_tokens: promptTokens,
        completion_tokens: outputTokens,
        total_tokens: promptTokens + outputTokens,
      };

      // Add prompt_tokens_details if cache tokens exist
      if (cacheReadTokens > 0 || cacheCreationTokens > 0) {
        state.usage.prompt_tokens_details = {};
        if (cacheReadTokens > 0) {
          state.usage.prompt_tokens_details.cached_tokens = cacheReadTokens;
        }
        if (cacheCreationTokens > 0) {
          state.usage.prompt_tokens_details.cache_creation_tokens = cacheCreationTokens;
        }
      }

      // Add completion_tokens_details if reasoning tokens exist
      if (reasoningTokens > 0) {
        state.usage.completion_tokens_details = {
          reasoning_tokens: reasoningTokens,
        };
      }
    }

    // #fix: synthesize tool call chunks from response.completed output[] for
    // providers that batch everything into response.completed without prior
    // incremental output_item.* events — including the dedup guard against
    // providers that DO stream incrementally and also echo the same
    // function_call items here. See synthesizeCompletedToolCalls's own
    // doc-comment for the full rationale.
    const synthesized = synthesizeCompletedToolCalls(state, data.response?.output);
    if (synthesized) return synthesized;

    if (!state.finishReasonSent) {
      state.finishReasonSent = true;
      const reason = computeFinishReason(state);
      state.finishReason = reason; // Mark for usage injection in stream.js

      const finalChunk: Record<string, unknown> = {
        id: state.chatId,
        object: "chat.completion.chunk",
        created: state.created,
        model: state.model || "gpt-4",
        choices: [
          {
            index: 0,
            delta: {},
            finish_reason: reason,
          },
        ],
      };

      // Include usage in final chunk if available
      if (state.usage && typeof state.usage === "object") {
        finalChunk.usage = state.usage;
      }

      return finalChunk;
    }
    return null;
  }

  if (eventType === "response.failed" || eventType === "error") {
    state.upstreamError = normalizeUpstreamFailure(data);
    state.finishReasonSent = true;
    return null;
  }

  // Reasoning events — emit as reasoning_content in Chat format
  if (
    eventType === "response.reasoning_content_text.delta" ||
    eventType === "response.reasoning_text.delta"
  ) {
    const reasoningDelta = data.delta || "";
    if (!reasoningDelta) return null;
    markResponsesReasoningDeltaEmitted(state, data.item_id);
    return {
      id: state.chatId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "gpt-4",
      choices: [
        {
          index: 0,
          delta: { reasoning_content: reasoningDelta },
          finish_reason: null,
        },
      ],
    };
  }

  // Handle true reasoning summary ("Thought for 15s").
  // Emit as `delta.reasoning_content` — matches the shape used by the
  // `reasoning_content_text.delta` branch above and is what Chat clients
  // (OpenCode, Claude Code, Cursor, etc.) actually render in their thinking
  // panel. A nested `delta.reasoning.summary` object is swallowed by most
  // stream mergers and never reaches the user.
  if (eventType === "response.reasoning_summary_text.delta") {
    const reasoningDelta = data.delta || "";
    if (!reasoningDelta) return null;
    markResponsesReasoningDeltaEmitted(state, data.item_id);
    return buildResponsesReasoningDeltaChunk(state, reasoningDelta);
  }

  // #5786 — reasoning summary exposed ONLY as a terminal snapshot on
  // `response.output_item.done` (no preceding reasoning_summary_text.delta events — e.g.
  // Codex reasoning models that surface the summary once at item close). Without this the
  // reasoning channel is silently dropped and never reaches the client's thinking panel.
  // Only synthesize when NO reasoning delta was already streamed for this item, so normal
  // delta streams are never duplicated.
  if (eventType === "response.output_item.done" && data.item?.type === "reasoning") {
    const item = data.item;
    const itemId = item.id != null ? String(item.id) : "";
    const emittedForItem =
      state.reasoningItemsWithDelta instanceof Set &&
      itemId &&
      state.reasoningItemsWithDelta.has(itemId);
    // Deltas were streamed but carried no item_id: fall back to the global flag and
    // suppress synthesis to avoid duplicating that same reasoning text.
    const emittedWithoutItemId =
      state.reasoningDeltaEmitted &&
      !(state.reasoningItemsWithDelta instanceof Set && state.reasoningItemsWithDelta.size > 0);
    if (emittedForItem || emittedWithoutItemId) return null;

    // #7095/#7176 reconciliation: computed WITHOUT mutating `item`, so an
    // encrypted-only reasoning item (and its `encrypted_content`) is never
    // rewritten with a fabricated `summary` — the placeholder only feeds this
    // synthetic client-facing delta chunk.
    const summaryText = getVisibleResponsesReasoningSummaryText(item);
    if (!summaryText) return null;
    return buildResponsesReasoningDeltaChunk(state, summaryText);
  }

  // Ignore other events
  return null;
}

// Register both directions
register(FORMATS.OPENAI, FORMATS.OPENAI_RESPONSES, null, openaiToOpenAIResponsesResponse);
register(FORMATS.OPENAI_RESPONSES, FORMATS.OPENAI, null, openaiResponsesToOpenAIResponse);

import {
  copyOpenAICompatibleReasoningFields,
  getReadableReasoningValue,
} from "../utils/reasoningFields.ts";
import { stripInternalReasoningPlaceholder } from "../utils/reasoningPlaceholder.ts";
import { normalizeOpenAICompatibleFinishReason } from "../utils/finishReason.ts";
import {
  collapseExcessiveNewlines,
  extractThinkingFromContent,
} from "./responseSanitizer/reasoning.ts";
export {
  extractThinkingFromContent,
  shouldParseTextualReasoningTags,
} from "./responseSanitizer/reasoning.ts";

/**
 * Response Sanitizer — Normalizes LLM responses to strict OpenAI SDK format.
 *
 * Fixes Issues:
 * 1. Strips non-standard fields (x_groq, usage_breakdown, service_tier) that
 *    break OpenAI Python SDK v1.83+ Pydantic validation (returns str instead of object)
 * 2. Optionally extracts native textual reasoning tags from known tag-style models
 * 3. Normalizes response id, object, and usage fields
 * 4. Converts developer role → system for non-OpenAI providers
 */

const ALLOWED_USAGE_FIELDS = new Set([
  "prompt_tokens",
  "completion_tokens",
  "total_tokens",
  "cached_tokens",
  "prompt_tokens_details",
  "completion_tokens_details",
  // Keep through sanitize → applyClientUsageBuffer so heuristic web usage is
  // not inflated by the default USAGE_TOKEN_BUFFER (2000).
  "estimated",
]);
const ALLOWED_RESPONSES_USAGE_FIELDS = new Set([
  "input_tokens",
  "output_tokens",
  "total_tokens",
  "input_tokens_details",
  "output_tokens_details",
  "estimated",
]);

type JsonRecord = Record<string, unknown>;
type ParseOptions = { parseTextualReasoningTags?: boolean };

export const OMIT_STREAMING_CHUNK_MARKER = "__omniroute_omit_streaming_chunk";

function toRecord(value: unknown): JsonRecord | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as JsonRecord;
}

function toString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function toNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function deleteOpenAICompatibleReasoningFields(record: JsonRecord): void {
  delete record.reasoning_content;
  delete record.reasoning;
  delete record.reasoning_text;
  delete record.reasoning_details;
}

function stripZeroWidthText(value: string): string {
  return value.replace(/[\u200B-\u200D\uFEFF]/g, "");
}

function stripZeroWidthToolArgumentJson(value: unknown): string {
  return stripZeroWidthText(typeof value === "string" ? value : JSON.stringify(value || {}));
}

function stripZeroWidthFunctionArguments(functionCall: unknown): unknown {
  const fn = toRecord(functionCall);
  if (!fn || typeof fn.arguments !== "string") return functionCall;
  const stripped = stripZeroWidthText(fn.arguments);
  // Fast path: return the original reference when there is nothing to strip, so
  // hot streaming paths avoid a per-chunk shallow clone of every tool call.
  if (stripped === fn.arguments) return functionCall;
  return { ...fn, arguments: stripped };
}

function stripZeroWidthToolCallArguments(toolCall: unknown): unknown {
  const tc = toRecord(toolCall);
  if (!tc) return toolCall;
  const fn = stripZeroWidthFunctionArguments(tc.function);
  return fn === tc.function ? toolCall : { ...tc, function: fn };
}

function stripZeroWidthValue(value: unknown): unknown {
  if (typeof value === "string") return stripZeroWidthText(value);
  if (Array.isArray(value)) return value.map((item) => stripZeroWidthValue(item));
  const record = toRecord(value);
  if (record) {
    return Object.fromEntries(
      Object.entries(record).map(([key, item]) => [key, stripZeroWidthValue(item)])
    );
  }
  return value;
}

function findBalancedJsonEnd(text: string, startIndex: number): number {
  if (startIndex < 0 || startIndex >= text.length || text[startIndex] !== "{") return -1;

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let index = startIndex; index < text.length; index += 1) {
    const char = text[index];

    if (inString) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (char === "\\") {
        escaped = true;
        continue;
      }
      if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === "{") {
      depth += 1;
      continue;
    }

    if (char === "}") {
      depth -= 1;
      if (depth === 0) return index;
    }
  }

  return -1;
}

function stripInternalToolEnvelopeText(content: string): string {
  let sanitized = stripZeroWidthText(content);
  const markerRegex =
    /to=(?:functions\.[A-Za-z0-9_.-]+|multi_tool_use\.[A-Za-z0-9_.-]+|[A-Za-z_][A-Za-z0-9_]*)/g;

  while (true) {
    const match = markerRegex.exec(sanitized);
    if (!match || match.index < 0) break;

    const searchWindowEnd = Math.min(sanitized.length, match.index + 1200);
    const jsonStart = sanitized.indexOf("{", match.index);
    if (jsonStart < 0 || jsonStart >= searchWindowEnd) {
      sanitized = `${sanitized.slice(0, match.index)}${sanitized.slice(match.index + match[0].length)}`;
      markerRegex.lastIndex = 0;
      continue;
    }

    const jsonEnd = findBalancedJsonEnd(sanitized, jsonStart);
    if (jsonEnd < 0) {
      sanitized = sanitized.slice(0, match.index);
      break;
    }

    const prefix = sanitized.slice(0, match.index).replace(/[ \t]+$/g, "");
    const suffix = sanitized.slice(jsonEnd + 1).replace(/^[ \t]+/g, "");
    sanitized = `${prefix}${suffix}`;
    markerRegex.lastIndex = 0;
  }

  return sanitized.replace(/\n{3,}/g, "\n\n").trim();
}

function parseTextualToolCallContent(content: unknown): { name: string; args: unknown } | null {
  if (typeof content !== "string") return null;
  const normalized = stripInternalToolEnvelopeText(content);
  const toolCallIndex = normalized.lastIndexOf("[Tool call:");
  if (toolCallIndex < 0) return null;
  const candidate = normalized.slice(toolCallIndex);
  const headerMatch = candidate.match(/^\[Tool call:\s*([^\]\n]+)\]\s*\nArguments:\s*/);
  if (!headerMatch) return null;
  const name = headerMatch[1]?.trim();
  const rawArgs = candidate.slice(headerMatch[0].length).trim();
  if (!name || !rawArgs) return null;
  const decoders = [
    (value: string) => value,
    (value: string) => {
      if (value.startsWith('"') && value.endsWith('"')) {
        const decoded = JSON.parse(value);
        return typeof decoded === "string" ? decoded : value;
      }
      return value;
    },
  ];
  for (const decode of decoders) {
    try {
      const decoded = decode(rawArgs);
      return { name, args: stripZeroWidthValue(JSON.parse(decoded)) };
    } catch {}
  }
  return null;
}

// Matches the exact header format required by parseTextualToolCallContent:
// "[Tool call: name]\nArguments:" (with optional whitespace).  Using the full
// header pattern prevents false positives when the model quotes "[Tool call:"
// in prose, code examples, or terminal output (#3355).
const TEXTUAL_TOOL_CALL_HEADER = /\[Tool call:[^\]\n]+\]\s*\nArguments:/;

function containsTextualToolCallContent(content: unknown): boolean {
  return (
    typeof content === "string" &&
    TEXTUAL_TOOL_CALL_HEADER.test(stripInternalToolEnvelopeText(content))
  );
}

/**
 * Sanitize a non-streaming OpenAI ChatCompletion response.
 * Strips non-standard fields and normalizes required fields.
 */
export interface SanitizeOpenAIResponseOptions {
  /**
   * When true, unconditionally remove `reasoning_content` from every choice
   * message in the final payload — including reasoning-only messages and
   * DeepSeek V4 — even though the default sanitizer keeps it in those cases.
   * Wired to the `x-omniroute-strip-reasoning` request header for clients whose
   * JSON parsers cannot tolerate the non-standard field (e.g. Firecrawl AI SDK).
   * Ported from upstream 9router#517 (closes upstream #509).
   */
  stripReasoning?: boolean;
  /**
   * Keep disabled for generic OpenAI-compatible responses: prompt-format tags
   * can be user-requested visible content. Enable only for routes/models whose
   * upstream contract uses textual tags as the native reasoning channel.
   */
  parseTextualReasoningTags?: boolean;
}

export function sanitizeOpenAIResponse(
  body: unknown,
  options: SanitizeOpenAIResponseOptions = {}
): unknown {
  const bodyRecord = toRecord(body);
  if (!bodyRecord) return body;
  const stripReasoning = options.stripReasoning === true;
  const parseTextualReasoningTags = options.parseTextualReasoningTags === true;

  // Build sanitized response with only allowed top-level fields
  const sanitized: JsonRecord = {};

  // Ensure required fields exist
  sanitized.id = normalizeResponseId(bodyRecord.id);
  sanitized.object = toString(bodyRecord.object) || "chat.completion";
  sanitized.created = toNumber(bodyRecord.created) ?? Math.floor(Date.now() / 1000);
  sanitized.model = toString(bodyRecord.model) || "unknown";

  // Sanitize choices
  if (Array.isArray(bodyRecord.choices)) {
    sanitized.choices = bodyRecord.choices.map((choice, idx) => {
      const sanitizedChoice = sanitizeChoice(choice, idx, { parseTextualReasoningTags });
      const message = toRecord(sanitizedChoice.message);
      if (
        message &&
        Array.isArray(message.tool_calls) &&
        message.tool_calls.length > 0 &&
        sanitizedChoice.finish_reason !== "tool_calls"
      ) {
        sanitizedChoice.finish_reason = "tool_calls";
      }
      if (stripReasoning && message) {
        deleteOpenAICompatibleReasoningFields(message);
      }
      return sanitizedChoice;
    });
  } else {
    sanitized.choices = [];
  }

  // Sanitize usage
  if (bodyRecord.usage !== undefined) {
    sanitized.usage = sanitizeUsage(bodyRecord.usage);
  }

  // Keep system_fingerprint if present (it's a valid OpenAI field)
  if (bodyRecord.system_fingerprint) {
    sanitized.system_fingerprint = bodyRecord.system_fingerprint;
  }

  return sanitized;
}

export function sanitizeResponsesApiResponse(body: unknown): unknown {
  const bodyRecord = toRecord(body);
  if (!bodyRecord) return body;

  if (Array.isArray(bodyRecord.choices)) {
    return convertOpenAIResponseToResponses(bodyRecord);
  }

  const responseRoot =
    bodyRecord.object === "response"
      ? bodyRecord
      : toRecord(bodyRecord.response ?? bodyRecord) || bodyRecord;

  const sanitized: JsonRecord = {
    id: normalizeResponsesId(responseRoot.id),
    object: "response",
    created_at:
      toNumber(responseRoot.created_at) ??
      toNumber(responseRoot.created) ??
      Math.floor(Date.now() / 1000),
    model: toString(responseRoot.model) || "unknown",
    status: toString(responseRoot.status) || "completed",
    background: typeof responseRoot.background === "boolean" ? responseRoot.background : false,
    error: responseRoot.error ?? null,
  };

  const output = sanitizeResponsesOutput(responseRoot.output);

  // Some upstreams return a shorthand Responses body that carries the answer only
  // in `output_text` with an empty/absent `output[]`. Synthesize a message item so
  // the sanitized response still has usable structured output — otherwise the text
  // is dropped and the response is later flagged malformed (#4942 regression).
  if (
    output.length === 0 &&
    typeof responseRoot.output_text === "string" &&
    responseRoot.output_text.trim().length > 0
  ) {
    output.push({
      id: "msg_0",
      type: "message",
      role: "assistant",
      content: [{ type: "output_text", text: responseRoot.output_text.trim() }],
    });
  }
  sanitized.output = output;

  const outputText = extractResponsesOutputText(output);
  if (outputText.length > 0) {
    sanitized.output_text = outputText;
  }

  if (responseRoot.usage !== undefined) {
    sanitized.usage = sanitizeResponsesUsage(responseRoot.usage);
  }

  return sanitized;
}

/**
 * Sanitize a single choice object.
 */
function sanitizeChoice(
  choice: unknown,
  defaultIndex: number,
  options: ParseOptions = {}
): JsonRecord {
  const choiceRecord = toRecord(choice);
  const sanitized: JsonRecord = {
    index: defaultIndex,
    finish_reason: null,
  };

  if (choiceRecord?.index !== undefined) {
    sanitized.index = choiceRecord.index;
  }

  if (choiceRecord?.finish_reason !== undefined) {
    sanitized.finish_reason = normalizeOpenAICompatibleFinishReason(choiceRecord.finish_reason);
  }

  if (choiceRecord?.message !== undefined) {
    sanitized.message = sanitizeMessage(choiceRecord.message, options);
  }
  if (choiceRecord?.delta !== undefined) {
    sanitized.delta = sanitizeMessage(choiceRecord.delta, options);
  }

  if (choiceRecord?.logprobs !== undefined) {
    sanitized.logprobs = choiceRecord.logprobs;
  }

  return sanitized;
}

function sanitizeMessageContent(msgRecord: JsonRecord, options: ParseOptions = {}): JsonRecord {
  if (typeof msgRecord.content === "string") {
    const strippedContent = stripInternalReasoningPlaceholder(
      stripInternalToolEnvelopeText(msgRecord.content)
    );
    const nativeReasoning = getReadableReasoningValue(msgRecord);
    const { content, thinking } =
      options.parseTextualReasoningTags === true && !nativeReasoning
        ? extractThinkingFromContent(strippedContent)
        : { content: strippedContent, thinking: null };
    const sanitized: JsonRecord = { content: collapseExcessiveNewlines(content) };
    if (thinking) sanitized.reasoning_content = thinking;
    return sanitized;
  }

  return msgRecord.content !== undefined ? { content: msgRecord.content } : {};
}

function applyTextualToolCallSanitization(sanitized: JsonRecord, msgRecord: JsonRecord): void {
  const textualToolCall = parseTextualToolCallContent(sanitized.content);
  if (textualToolCall && !msgRecord.tool_calls) {
    sanitized.content = null;
    sanitized.tool_calls = [
      {
        id: `call_${Date.now()}_0`,
        type: "function",
        function: {
          name: textualToolCall.name,
          arguments: JSON.stringify(textualToolCall.args || {}),
        },
      },
    ];
  } else if (containsTextualToolCallContent(sanitized.content) && !msgRecord.tool_calls) {
    sanitized.content = null;
  }
}

function sanitizeMessage(msg: unknown, options: ParseOptions = {}): unknown {
  const msgRecord = toRecord(msg);
  if (!msgRecord) return msg;

  const sanitized: JsonRecord = {};

  if (msgRecord.role) sanitized.role = msgRecord.role;
  if (msgRecord.refusal !== undefined) sanitized.refusal = msgRecord.refusal;

  Object.assign(sanitized, sanitizeMessageContent(msgRecord, options));

  copyOpenAICompatibleReasoningFields(msgRecord, sanitized);
  applyTextualToolCallSanitization(sanitized, msgRecord);

  if (msgRecord.tool_calls) {
    sanitized.tool_calls = Array.isArray(msgRecord.tool_calls)
      ? msgRecord.tool_calls.map((toolCall) => stripZeroWidthToolCallArguments(toolCall))
      : msgRecord.tool_calls;
  }

  if (msgRecord.function_call) {
    sanitized.function_call = stripZeroWidthFunctionArguments(msgRecord.function_call);
  }

  return sanitized;
}

/**
 * Sanitize usage object — keep only standard fields.
 */
function sanitizeUsage(usage: unknown): unknown {
  const usageRecord = toRecord(usage);
  if (!usageRecord) return usage;

  const sanitized: JsonRecord = {};

  // Cross-map Claude-style → OpenAI-style field names.
  // Some providers return input_tokens/output_tokens instead of prompt_tokens/completion_tokens.
  // Without this mapping, the whitelist filter below strips them, resulting in NaN/0 tokens (#617).
  if (usageRecord.input_tokens !== undefined && usageRecord.prompt_tokens === undefined) {
    usageRecord.prompt_tokens = usageRecord.input_tokens;
  }
  if (usageRecord.output_tokens !== undefined && usageRecord.completion_tokens === undefined) {
    usageRecord.completion_tokens = usageRecord.output_tokens;
  }

  for (const key of ALLOWED_USAGE_FIELDS) {
    if (usageRecord[key] !== undefined) {
      sanitized[key] = usageRecord[key];
    }
  }

  // Ensure required fields
  const promptTokens = toNumber(sanitized.prompt_tokens) ?? 0;
  const completionTokens = toNumber(sanitized.completion_tokens) ?? 0;
  const totalTokens = toNumber(sanitized.total_tokens) ?? promptTokens + completionTokens;

  sanitized.prompt_tokens = promptTokens;
  sanitized.completion_tokens = completionTokens;
  sanitized.total_tokens = totalTokens;

  return sanitized;
}

function sanitizeResponsesUsage(usage: unknown): unknown {
  const usageRecord = toRecord(usage);
  if (!usageRecord) return usage;

  const normalized: JsonRecord = { ...usageRecord };

  if (normalized.prompt_tokens !== undefined && normalized.input_tokens === undefined) {
    normalized.input_tokens = normalized.prompt_tokens;
  }
  if (normalized.completion_tokens !== undefined && normalized.output_tokens === undefined) {
    normalized.output_tokens = normalized.completion_tokens;
  }
  if (
    normalized.prompt_tokens_details !== undefined &&
    normalized.input_tokens_details === undefined
  ) {
    normalized.input_tokens_details = normalized.prompt_tokens_details;
  }
  if (
    normalized.completion_tokens_details !== undefined &&
    normalized.output_tokens_details === undefined
  ) {
    normalized.output_tokens_details = normalized.completion_tokens_details;
  }

  const inputDetails = toRecord(normalized.input_tokens_details) || {};
  const cachedTokens = normalized.cached_tokens ?? normalized.cache_read_input_tokens;
  if (cachedTokens !== undefined && inputDetails.cached_tokens === undefined) {
    inputDetails.cached_tokens = cachedTokens;
  }
  if (
    normalized.cache_creation_input_tokens !== undefined &&
    inputDetails.cache_creation_tokens === undefined
  ) {
    inputDetails.cache_creation_tokens = normalized.cache_creation_input_tokens;
  }
  if (Object.keys(inputDetails).length > 0) {
    normalized.input_tokens_details = inputDetails;
  }

  const outputDetails = toRecord(normalized.output_tokens_details) || {};
  if (normalized.reasoning_tokens !== undefined && outputDetails.reasoning_tokens === undefined) {
    outputDetails.reasoning_tokens = normalized.reasoning_tokens;
  }
  if (Object.keys(outputDetails).length > 0) {
    normalized.output_tokens_details = outputDetails;
  }

  const sanitized: JsonRecord = {};
  for (const key of ALLOWED_RESPONSES_USAGE_FIELDS) {
    if (normalized[key] !== undefined) {
      sanitized[key] = normalized[key];
    }
  }

  const inputTokens = toNumber(sanitized.input_tokens) ?? 0;
  const outputTokens = toNumber(sanitized.output_tokens) ?? 0;
  const totalTokens = toNumber(sanitized.total_tokens) ?? inputTokens + outputTokens;

  sanitized.input_tokens = inputTokens;
  sanitized.output_tokens = outputTokens;
  sanitized.total_tokens = totalTokens;

  return sanitized;
}

/**
 * Normalize response ID to use chatcmpl- prefix.
 */
function normalizeResponseId(id: unknown): string {
  if (!id || typeof id !== "string") {
    return `chatcmpl-${crypto.randomUUID().replace(/-/g, "").slice(0, 29)}`;
  }
  // Already correct format
  if (id.startsWith("chatcmpl-")) return id;
  // Keep custom IDs but don't break them
  return id;
}

function normalizeResponsesId(id: unknown): string {
  if (!id || typeof id !== "string") {
    return `resp_${crypto.randomUUID().replace(/-/g, "").slice(0, 24)}`;
  }
  if (id.startsWith("resp_")) return id;
  return `resp_${id}`;
}

/**
 * True when a Responses output item is an assistant `message` in the internal
 * `commentary` phase — i.e. reasoning/scratchpad text that must never reach the
 * client. Streaming `response.output_text.delta` events do not carry the `phase`
 * themselves, so the passthrough path uses this on the `response.output_item.added`
 * item to decide which subsequent deltas/dones to drop statefully (#6199).
 */
export function isResponsesCommentaryMessageItem(item: unknown): boolean {
  const itemRecord = toRecord(item);
  if (!itemRecord) return false;
  const type = toString(itemRecord.type) || "message";
  if (type !== "message") return false;
  const role = toString(itemRecord.role) || "assistant";
  const phase = toString(itemRecord.phase);
  return role === "assistant" && phase === "commentary";
}

function sanitizeResponsesStreamingOutputItem(item: unknown): JsonRecord | null {
  const itemRecord = toRecord(item);
  if (!itemRecord) return null;

  const type = toString(itemRecord.type) || "message";

  if (type === "message") {
    const role = toString(itemRecord.role) || "assistant";
    if (isResponsesCommentaryMessageItem(itemRecord)) {
      return null;
    }

    const content = sanitizeResponsesMessageContent(itemRecord.content).filter((part) => {
      const partRecord = toRecord(part);
      const partPhase = partRecord ? toString(partRecord.phase) : undefined;
      return partPhase !== "commentary";
    });

    if (role === "assistant" && content.length === 0) {
      return null;
    }

    return {
      ...itemRecord,
      type: "message",
      role,
      content,
    };
  }

  if (type === "reasoning") {
    const summary = Array.isArray(itemRecord.summary)
      ? itemRecord.summary
          .map((part) => {
            const partRecord = toRecord(part);
            if (!partRecord) return null;
            return {
              ...partRecord,
              type: toString(partRecord.type) || "summary_text",
              text: collapseExcessiveNewlines(stripZeroWidthText(toString(partRecord.text) || "")),
            };
          })
          .filter((part) => part !== null)
      : [];

    return {
      ...itemRecord,
      type: "reasoning",
      summary,
    };
  }

  if (type === "function_call") {
    return {
      ...itemRecord,
      type: "function_call",
      arguments: stripZeroWidthToolArgumentJson(itemRecord.arguments),
    };
  }

  if (type === "function_call_output") {
    return {
      ...itemRecord,
      type: "function_call_output",
      output:
        typeof itemRecord.output === "string"
          ? collapseExcessiveNewlines(stripZeroWidthText(itemRecord.output))
          : JSON.stringify(itemRecord.output ?? ""),
    };
  }

  return { ...itemRecord };
}

function sanitizeResponsesStreamingOutput(output: unknown): JsonRecord[] {
  if (!Array.isArray(output)) return [];

  return output
    .map((item) => sanitizeResponsesStreamingOutputItem(item))
    .filter((item): item is JsonRecord => item !== null);
}

// Native Responses streaming events that carry raw model text directly on the
// root `delta` field. These must get the same zero-width-joiner stripping as the
// non-streaming path so agent words (opencode/cursor/aider) are not corrupted.
// Scoped as an allow-list on purpose: other root `delta` events may carry non-text payloads.
// Function-call argument events are handled separately by stripping only zero-width code points.
const RESPONSES_STREAMING_TEXT_DELTA_EVENTS = new Set([
  "response.output_text.delta",
  "response.reasoning_summary_text.delta",
  "response.reasoning_text.delta",
]);

// Matching `*.done` events that carry the finalized text on the root `text` field.
const RESPONSES_STREAMING_TEXT_DONE_EVENTS = new Set([
  "response.output_text.done",
  "response.reasoning_summary_text.done",
  "response.reasoning_text.done",
]);

function sanitizeResponsesStreamingEvent(parsedRecord: JsonRecord): JsonRecord {
  const sanitized: JsonRecord = { ...parsedRecord };
  const eventType = toString(parsedRecord.type) || "";

  // Root-level text events (output_text / reasoning_summary_text / reasoning_text)
  // carry the model text directly on the event, not under item/output. Strip ZWJ
  // there too. Only touch string values and only the allow-listed event types —
  // never function-call argument events.
  if (RESPONSES_STREAMING_TEXT_DELTA_EVENTS.has(eventType) && typeof sanitized.delta === "string") {
    sanitized.delta = stripZeroWidthText(sanitized.delta);
  }
  if (RESPONSES_STREAMING_TEXT_DONE_EVENTS.has(eventType) && typeof sanitized.text === "string") {
    sanitized.text = stripZeroWidthText(sanitized.text);
  }
  if (
    eventType === "response.function_call_arguments.delta" &&
    typeof sanitized.delta === "string"
  ) {
    sanitized.delta = stripZeroWidthText(sanitized.delta);
  }
  if (
    eventType === "response.function_call_arguments.done" &&
    typeof sanitized.arguments === "string"
  ) {
    sanitized.arguments = stripZeroWidthText(sanitized.arguments);
  }

  if (parsedRecord.item !== undefined) {
    const sanitizedItem = sanitizeResponsesStreamingOutputItem(parsedRecord.item);
    if (sanitizedItem) {
      sanitized.item = sanitizedItem;
    } else {
      delete sanitized.item;
      if (eventType === "response.output_item.added" || eventType === "response.output_item.done") {
        sanitized[OMIT_STREAMING_CHUNK_MARKER] = true;
      }
    }
  }

  if (Array.isArray(parsedRecord.output)) {
    const output = sanitizeResponsesStreamingOutput(parsedRecord.output);
    sanitized.output = output;
    const outputText = extractResponsesOutputText(output);
    if (outputText.length > 0) {
      sanitized.output_text = outputText;
    } else {
      delete sanitized.output_text;
    }
  }

  const responseRecord = toRecord(parsedRecord.response);
  if (responseRecord) {
    const responseOutput = Array.isArray(responseRecord.output)
      ? sanitizeResponsesStreamingOutput(responseRecord.output)
      : undefined;
    const sanitizedResponse: JsonRecord = {
      ...responseRecord,
      ...(responseOutput ? { output: responseOutput } : {}),
    };
    const responseOutputText = responseOutput ? extractResponsesOutputText(responseOutput) : "";
    if (responseOutputText.length > 0) {
      sanitizedResponse.output_text = responseOutputText;
    } else {
      delete sanitizedResponse.output_text;
    }
    sanitized.response = sanitizedResponse;
  }

  return sanitized;
}

function sanitizeResponsesOutput(output: unknown): JsonRecord[] {
  if (!Array.isArray(output)) return [];

  return output
    .map((item, index) => sanitizeResponsesOutputItem(item, index))
    .filter((item): item is JsonRecord => item !== null);
}

function sanitizeResponsesOutputItem(item: unknown, index: number): JsonRecord | null {
  const itemRecord = toRecord(item);
  if (!itemRecord) return null;

  const type = toString(itemRecord.type) || "message";

  if (type === "message") {
    const content = sanitizeResponsesMessageContent(itemRecord.content);
    const sanitized: JsonRecord = {
      id: toString(itemRecord.id) || `msg_${index}`,
      type: "message",
      role: toString(itemRecord.role) || "assistant",
      content,
    };
    return sanitized;
  }

  if (type === "reasoning") {
    const summary = Array.isArray(itemRecord.summary)
      ? itemRecord.summary
          .map((part) => {
            const partRecord = toRecord(part);
            if (!partRecord) return null;
            return {
              type: toString(partRecord.type) || "summary_text",
              text: collapseExcessiveNewlines(toString(partRecord.text) || ""),
            };
          })
          .filter((part): part is { type: string; text: string } => part !== null)
      : [];

    return {
      id: toString(itemRecord.id) || `rs_${index}`,
      type: "reasoning",
      summary,
    };
  }

  if (type === "function_call") {
    const callId = toString(itemRecord.call_id) || toString(itemRecord.id) || `call_${index}`;
    return {
      id: toString(itemRecord.id) || `fc_${callId}`,
      type: "function_call",
      call_id: callId,
      name: toString(itemRecord.name) || "",
      arguments: stripZeroWidthToolArgumentJson(itemRecord.arguments),
    };
  }

  if (type === "function_call_output") {
    return {
      id: toString(itemRecord.id) || `fco_${toString(itemRecord.call_id) || index}`,
      type: "function_call_output",
      call_id: toString(itemRecord.call_id) || "",
      output: itemRecord.output ?? "",
    };
  }

  return { ...itemRecord, type };
}

function sanitizeResponsesMessageContent(content: unknown): JsonRecord[] {
  if (typeof content === "string") {
    if (content.length === 0) return [];
    return [
      {
        type: "output_text",
        text: collapseExcessiveNewlines(
          stripInternalReasoningPlaceholder(stripInternalToolEnvelopeText(content))
        ),
        annotations: [],
      },
    ];
  }

  if (!Array.isArray(content)) return [];

  return content
    .map((part) => {
      const partRecord = toRecord(part);
      if (!partRecord) {
        if (typeof part === "string") {
          return {
            type: "output_text",
            text: collapseExcessiveNewlines(
              stripInternalReasoningPlaceholder(stripInternalToolEnvelopeText(part))
            ),
            annotations: [],
          };
        }
        return null;
      }

      const partType = toString(partRecord.type);
      if (
        partType === "output_text" ||
        partType === "text" ||
        ((partType === undefined || partType === "") && typeof partRecord.text === "string")
      ) {
        return {
          ...partRecord,
          type: "output_text",
          text: collapseExcessiveNewlines(
            stripInternalReasoningPlaceholder(
              stripInternalToolEnvelopeText(toString(partRecord.text) || "")
            )
          ),
          annotations: Array.isArray(partRecord.annotations) ? partRecord.annotations : [],
        };
      }

      return { ...partRecord };
    })
    .filter((part): part is JsonRecord => part !== null);
}

function extractResponsesOutputText(output: JsonRecord[]): string {
  const parts: string[] = [];

  for (const item of output) {
    if (item.type !== "message" || !Array.isArray(item.content)) continue;
    for (const part of item.content) {
      const partRecord = toRecord(part);
      if (!partRecord) continue;
      if (
        (partRecord.type === "output_text" || partRecord.type === "text") &&
        typeof partRecord.text === "string" &&
        partRecord.text.length > 0
      ) {
        parts.push(partRecord.text);
      }
    }
  }

  return parts.join("");
}

function convertOpenAIResponseToResponses(openaiResponse: JsonRecord): JsonRecord {
  const responseId = normalizeResponsesId(openaiResponse.id);
  const createdAt = toNumber(openaiResponse.created) ?? Math.floor(Date.now() / 1000);
  const model = toString(openaiResponse.model) || "unknown";
  const choice = Array.isArray(openaiResponse.choices)
    ? (toRecord(openaiResponse.choices[0]) ?? {})
    : {};
  const message = toRecord(choice.message) || {};
  const output: JsonRecord[] = [];

  const reasoningContent =
    toString(message.reasoning_content) ||
    (typeof message.reasoning === "string" ? message.reasoning : "");
  if (reasoningContent) {
    output.push({
      id: `rs_${responseId}_0`,
      type: "reasoning",
      summary: [{ type: "summary_text", text: reasoningContent }],
    });
  }

  const hasToolCalls = Array.isArray(message.tool_calls) && message.tool_calls.length > 0;
  const messageContent = sanitizeResponsesMessageContent(message.content);
  if (messageContent.length > 0 || (!hasToolCalls && !reasoningContent)) {
    output.push({
      id: `msg_${responseId}_0`,
      type: "message",
      role: toString(message.role) || "assistant",
      content:
        messageContent.length > 0
          ? messageContent
          : [{ type: "output_text", text: "", annotations: [] }],
    });
  }

  const toolCalls = Array.isArray(message.tool_calls)
    ? message.tool_calls
    : message.function_call
      ? [
          {
            id: toString(choice.id) || "call_0",
            type: "function",
            function: message.function_call,
          },
        ]
      : [];

  for (let index = 0; index < toolCalls.length; index += 1) {
    const toolCall = toRecord(toolCalls[index]) || {};
    const fn = toRecord(toolCall.function) || {};
    const callId = toString(toolCall.id) || `call_${index}`;
    output.push({
      id: `fc_${callId}`,
      type: "function_call",
      call_id: callId,
      name: toString(fn.name) || "",
      arguments: stripZeroWidthToolArgumentJson(fn.arguments),
    });
  }

  const sanitized: JsonRecord = {
    id: responseId,
    object: "response",
    created_at: createdAt,
    model,
    status: "completed",
    background: false,
    error: null,
    output,
  };

  const outputText = extractResponsesOutputText(output);
  if (outputText.length > 0) {
    sanitized.output_text = outputText;
  }

  if (openaiResponse.usage !== undefined) {
    sanitized.usage = sanitizeResponsesUsage(openaiResponse.usage);
  }

  return sanitized;
}

/**
 * Sanitize a streaming SSE chunk for passthrough mode.
 * Lighter than full sanitization — only strips problematic extra fields.
 */
export function sanitizeStreamingChunk(parsed: unknown): unknown {
  const parsedRecord = toRecord(parsed);
  if (!parsedRecord) return parsed;

  const eventType = toString(parsedRecord.type) || "";
  if (eventType.startsWith("response.") || parsedRecord.object === "response") {
    return sanitizeResponsesStreamingEvent(parsedRecord);
  }

  // #8271: Anthropic-native streaming events (content_block_delta with
  // text_delta / thinking_delta) bypass the OpenAI choices[].delta.content
  // path below. Strip zero-width characters from their text payloads so
  // U+200D and friends don't leak to the client on the Messages API.
  if (eventType === "content_block_delta") {
    const deltaRecord = toRecord(parsedRecord.delta);
    if (deltaRecord) {
      if (typeof deltaRecord.text === "string") {
        deltaRecord.text = stripZeroWidthText(deltaRecord.text);
      }
      if (typeof deltaRecord.thinking === "string") {
        deltaRecord.thinking = stripZeroWidthText(deltaRecord.thinking);
      }
    }
    return parsedRecord;
  }

  // Build sanitized chunk
  const sanitized: JsonRecord = {};

  // Keep only standard fields — normalize id to string to avoid AI_InvalidResponseDataError
  if (parsedRecord.id !== undefined && parsedRecord.id !== null) {
    sanitized.id = normalizeResponseId(
      typeof parsedRecord.id === "string" ? parsedRecord.id : String(parsedRecord.id)
    );
  }
  sanitized.object = toString(parsedRecord.object) || "chat.completion.chunk";
  if (parsedRecord.created !== undefined) sanitized.created = parsedRecord.created;
  if (parsedRecord.model !== undefined) sanitized.model = parsedRecord.model;

  // Sanitize choices with delta
  if (Array.isArray(parsedRecord.choices)) {
    sanitized.choices = parsedRecord.choices.map((choice) => {
      const c: JsonRecord = { index: 0 };
      const choiceRecord = toRecord(choice);
      if (!choiceRecord) return c;

      c.index = toNumber(choiceRecord.index) ?? 0;

      if (choiceRecord.delta !== undefined) {
        const deltaRecord = toRecord(choiceRecord.delta);
        if (deltaRecord) {
          const delta: JsonRecord = {};
          if (deltaRecord.role !== undefined) delta.role = deltaRecord.role;
          if (deltaRecord.content !== undefined) {
            delta.content =
              typeof deltaRecord.content === "string"
                ? collapseExcessiveNewlines(stripZeroWidthText(deltaRecord.content))
                : deltaRecord.content;
          }
          copyOpenAICompatibleReasoningFields(deltaRecord, delta);
          // Parity with the non-streaming path: strip the zero-width joiners that the
          // request side injects into agent words. copyOpenAICompatibleReasoningFields
          // is shared, so strip locally on the fields it writes (string values only).
          for (const reasoningKey of ["reasoning_content", "reasoning", "reasoning_text"]) {
            if (typeof delta[reasoningKey] === "string") {
              delta[reasoningKey] = stripZeroWidthText(delta[reasoningKey] as string);
            }
          }
          if (deltaRecord.tool_calls !== undefined) {
            delta.tool_calls = Array.isArray(deltaRecord.tool_calls)
              ? deltaRecord.tool_calls.map((tc) => {
                  const t = toRecord(tc);
                  if (!t) return tc;
                  const strippedToolCall = stripZeroWidthToolCallArguments(t);
                  const strippedRecord = toRecord(strippedToolCall) || t;
                  if (t.id !== undefined && t.id !== null && typeof t.id !== "string") {
                    return { ...strippedRecord, id: String(t.id) };
                  }
                  return strippedRecord;
                })
              : deltaRecord.tool_calls;
          }
          if (deltaRecord.function_call !== undefined)
            delta.function_call = stripZeroWidthFunctionArguments(deltaRecord.function_call);
          c.delta = delta;
        } else {
          c.delta = choiceRecord.delta;
        }
      }

      if (choiceRecord.finish_reason !== undefined) {
        c.finish_reason = normalizeOpenAICompatibleFinishReason(choiceRecord.finish_reason);
      }
      if (choiceRecord.logprobs !== undefined) c.logprobs = choiceRecord.logprobs;
      return c;
    });
  }

  // Sanitize usage if present
  if (parsedRecord.usage !== undefined) {
    sanitized.usage = sanitizeUsage(parsedRecord.usage);
  }

  // Keep system_fingerprint if present
  if (parsedRecord.system_fingerprint) {
    sanitized.system_fingerprint = parsedRecord.system_fingerprint;
  }

  return sanitized;
}

export const REASONING_TAG_NAMES = ["think", "thinking", "thought", "internal_thought"];
export const REASONING_TAG_PATTERN = REASONING_TAG_NAMES.join("|");
// Matches complete <think>/<thinking>/<thought>/<internal_thought> blocks.
export const THINK_TAG_REGEX = new RegExp(
  `<(${REASONING_TAG_PATTERN})\\b[^>]*>([\\s\\S]*?)<\\/\\1>`,
  "gi"
);
export const REASONING_CLOSE_TAG_REGEX = new RegExp(`</(${REASONING_TAG_PATTERN})>`, "i");
export const REASONING_TAG_FRAGMENT_REGEX = new RegExp(
  `</?(${REASONING_TAG_PATTERN})\\b[^>]*>`,
  "gi"
);
export const CONTENT_OPEN_TAG_REGEX = /<content\b[^>]*>/i;
// Matches an unclosed reasoning tag at the end of a message. Some providers can
// emit malformed/open reasoning wrappers (for example "<thought\n...") before a
// tool call. Treat that tail as reasoning instead of visible assistant text.
export const UNCLOSED_REASONING_TAG_REGEX = new RegExp(
  `<(${REASONING_TAG_PATTERN})(?:\\s[^>]*)?(?:>|\\r?\\n)([\\s\\S]*)$`,
  "i"
);

// #638, #727: Collapse runs of 2+ consecutive newlines into \n\n
// Tool call responses from thinking models often accumulate excessive newlines
export const EXCESSIVE_NEWLINES = /\n{2,}/g;
export function collapseExcessiveNewlines(text: string): string {
  return text.replace(EXCESSIVE_NEWLINES, "\n\n");
}

export function cleanReasoningFragment(text: string): string {
  return text.replace(REASONING_TAG_FRAGMENT_REGEX, "").trim();
}

export function splitClosingOnlyReasoningPrefix(text: string): {
  content: string;
  thinking: string | null;
} | null {
  const closeMatch = text.match(REASONING_CLOSE_TAG_REGEX);
  if (!closeMatch || closeMatch.index === undefined || closeMatch.index === 0) return null;
  const closeIndex = closeMatch.index;

  const suffix = text.slice(closeIndex + closeMatch[0].length);
  if (!CONTENT_OPEN_TAG_REGEX.test(suffix)) return null;

  const thinking = cleanReasoningFragment(text.slice(0, closeIndex));
  if (!thinking) return null;
  return { content: suffix.trim(), thinking };
}

export function movePrefixBeforeContentTagToThinking(
  cleaned: string,
  thinkingParts: string[]
): string {
  const contentMatch = cleaned.match(CONTENT_OPEN_TAG_REGEX);
  if (!contentMatch || contentMatch.index === undefined || contentMatch.index <= 0) return cleaned;
  const contentIndex = contentMatch.index;

  const prefix = cleanReasoningFragment(cleaned.slice(0, contentIndex));
  if (prefix) thinkingParts.unshift(prefix);
  return cleaned.slice(contentIndex);
}

/**
 * Extract <think> blocks from text content and return separated parts.
 * @returns {{ content: string, thinking: string | null }}
 */
export function extractThinkingFromContent(text: string): {
  content: string;
  thinking: string | null;
} {
  if (!text || typeof text !== "string") {
    return { content: text || "", thinking: null };
  }

  const thinkingParts: string[] = [];
  let hasThinkTags = false;

  let cleaned = text.replace(THINK_TAG_REGEX, (_match, _tagName, thinkContent) => {
    hasThinkTags = true;
    const trimmed = thinkContent.trim();
    if (trimmed) {
      thinkingParts.push(trimmed);
    }
    return "";
  });

  if (!hasThinkTags) {
    const closingOnly = splitClosingOnlyReasoningPrefix(cleaned);
    if (closingOnly) {
      return closingOnly;
    }
  }

  const unclosedMatch = cleaned.match(UNCLOSED_REASONING_TAG_REGEX);
  if (unclosedMatch?.index !== undefined) {
    hasThinkTags = true;
    const reasoning = String(unclosedMatch[2] || "").trim();
    if (reasoning) thinkingParts.push(reasoning);
    const prefix = cleaned.slice(0, unclosedMatch.index);
    cleaned = /^(?:\s|§\d+§)*$/.test(prefix) ? "" : prefix;
  }

  if (!hasThinkTags) {
    return { content: text, thinking: null };
  }

  cleaned = movePrefixBeforeContentTagToThinking(cleaned, thinkingParts);

  return {
    content: cleaned.trim(),
    thinking: thinkingParts.length > 0 ? thinkingParts.join("\n\n") : null,
  };
}

export function normalizeReasoningRouteId(value: unknown): string {
  return typeof value === "string" ? value.toLowerCase() : "";
}

export function isAntigravityReasoningRoute(providerId: string, modelId: string): boolean {
  return (
    providerId.includes("antigravity") ||
    providerId === "agy" ||
    modelId.includes("antigravity/") ||
    modelId.startsWith("agy/")
  );
}

export function isTextualReasoningTagNativeRoute(providerId: string, modelId: string): boolean {
  const routeId = `${providerId}/${modelId}`;
  return (
    /deepseek[-_/]?r1\b/.test(routeId) ||
    /r1[-_/]?distill\b/.test(routeId) ||
    /(?:^|[/:_-])qwq(?:[/._:-]|$)/.test(routeId) ||
    /(?:^|[/_-])k3(?:[/._:-]|$)/.test(modelId) ||
    // 9router#2231: MiniMax M3 leaks raw <think>...</think> into `content` on its
    // OpenAI-format provider tiers (trae, huggingchat, bazaarlink, ollama-cloud,
    // opencode, cline, opencode-zen, codebuddy-cn). The direct minimax/minimax-cn
    // tiers stay on Anthropic's Messages format (targetFormat: "claude") and
    // already surface reasoning natively, so they are excluded here.
    (providerId !== "minimax" && providerId !== "minimax-cn" && /minimax[-_]?m3\b/.test(routeId))
  );
}

export function shouldParseTextualReasoningTags(provider?: unknown, model?: unknown): boolean {
  const providerId = normalizeReasoningRouteId(provider);
  const modelId = normalizeReasoningRouteId(model);
  return (
    !isAntigravityReasoningRoute(providerId, modelId) &&
    isTextualReasoningTagNativeRoute(providerId, modelId)
  );
}

// Pure, stateless helpers for the OpenAI Responses <-> Chat response translator.
// Extracted verbatim from response/openai-responses.ts (no host imports, no stream state).

export function normalizeToolName(value) {
  return typeof value === "string" ? value.trim() : "";
}

// Tools whose empty-string/empty-array optional args are safe to strip. Arbitrary
// tools are left untouched because an empty string/array can be a valid payload.
// - "Read": Claude Code's Read tool (empty `pages`) — #2937.
// - "Subagent": Cursor's local subagent tool emits a cloud-only `cloud_base_branch: ""`,
//   which Cursor rejects unless environment is cloud — ported from decolua/9router#2446.
const STRIPPABLE_EMPTY_ARG_TOOLS = new Set(["Read", "Subagent"]);

// Deep-equal for JSON-shaped values (schema `default` comparison). Cheap and safe:
// tool args are always JSON-serializable, so a stringify comparison is exact.
function jsonValuesEqual(a, b) {
  if (a === b) return true;
  if (a == null || b == null) return false;
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return false;
  }
}

function hasUsableSchema(schema) {
  return !!(schema && typeof schema === "object" && !Array.isArray(schema));
}

function schemaProperties(schema) {
  return hasUsableSchema(schema) && schema.properties && typeof schema.properties === "object"
    ? schema.properties
    : null;
}

function schemaRequiredSet(schema) {
  return new Set(hasUsableSchema(schema) && Array.isArray(schema.required) ? schema.required : []);
}

function isEmptyToolArgValue(entry) {
  return entry === "" || (Array.isArray(entry) && entry.length === 0);
}

// True when `entry` strictly equals the property's declared JSON Schema `default` — an
// emitted value indistinguishable from omission, safe to drop for any tool.
function matchesSchemaDefault(propSchema, entry) {
  if (!propSchema || !Object.prototype.hasOwnProperty.call(propSchema, "default")) return false;
  return jsonValuesEqual(entry, propSchema.default);
}

// True when `entry` is empty and either the tool is on the legacy allowlist, or the
// schema declares this property but does not mark it `required` (generalized #6951 rule).
function isDroppableEmptyEntry(entry, propSchema, required, key, allowlisted) {
  if (!isEmptyToolArgValue(entry)) return false;
  return allowlisted || (propSchema != null && !required.has(key));
}

// #7023 — the request-side counterpart (injectOptionalEnumOmissionSentinel) widens
// no-default optional enum properties to accept `null`, meaning "omitted" (OpenAI's own
// nullable-union idiom for Responses-API strict mode). Drop the key when the model
// follows that idiom for a non-required, schema-declared property.
function isDroppableNullEntry(entry, propSchema, required, key) {
  return entry === null && propSchema != null && !required.has(key);
}

function stripEmptyOptionalToolArgsObject(value, toolName, schema) {
  const properties = schemaProperties(schema);
  const required = schemaRequiredSet(schema);
  const allowlisted = STRIPPABLE_EMPTY_ARG_TOOLS.has(toolName);

  const cleaned = { ...value };
  for (const [key, entry] of Object.entries(cleaned)) {
    const propSchema = properties ? properties[key] : null;
    if (
      matchesSchemaDefault(propSchema, entry) ||
      isDroppableEmptyEntry(entry, propSchema, required, key, allowlisted) ||
      isDroppableNullEntry(entry, propSchema, required, key)
    ) {
      delete cleaned[key];
    }
  }
  return cleaned;
}

// #6951 — Responses API strict mode forces every tool property into `required`, so the
// model always emits *some* value for "optional" params (no first-class optional).
// When the tool's JSON Schema is available (`schema`, from the request's `tools[]`),
// normalization becomes schema-aware instead of allowlist-only:
//   - drop-if-default: value strictly equals the property's declared `default`.
//   - drop-if-empty (generalized): empty string/array for a property that is declared
//     in `schema.properties` but absent from `schema.required` — any tool, not just the
//     Read/Subagent allowlist above.
// Without a schema, behavior is unchanged (allowlist + empty-only), preserving existing
// callers that only pass (value, toolName).
export function stripEmptyOptionalToolArgs(value, toolName, schema) {
  if (value == null) return value;

  if (typeof value === "string") {
    // JSON-string cleanup runs for allowlisted tools, or for any tool once a schema is
    // supplied (schema-aware normalization is not restricted to the allowlist).
    if (!hasUsableSchema(schema) && !STRIPPABLE_EMPTY_ARG_TOOLS.has(toolName)) return value;
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed) || typeof parsed !== "object" || parsed === null) return value;
      const cleaned = stripEmptyOptionalToolArgs(parsed, toolName, schema);
      return JSON.stringify(cleaned ?? {});
    } catch {
      return value;
    }
  }

  if (Array.isArray(value) || typeof value !== "object") return value;

  return stripEmptyOptionalToolArgsObject(value, toolName, schema);
}

export function normalizeOutputIndex(outputIndex) {
  const normalized = Number(outputIndex);
  return Number.isInteger(normalized) && normalized >= 0 ? normalized : 0;
}

export function normalizeUpstreamFailure(data, fallbackType = "server_error") {
  const response = data?.response && typeof data.response === "object" ? data.response : null;
  const error =
    response?.error && typeof response.error === "object"
      ? response.error
      : data?.error && typeof data.error === "object"
        ? data.error
        : null;

  const code = typeof error?.code === "string" ? error.code : "";
  const message =
    typeof error?.message === "string"
      ? error.message
      : typeof data?.message === "string"
        ? data.message
        : "Upstream failure";

  // Preserve upstream error semantics:
  // - context_length_exceeded → 400 (client can retry with smaller context)
  // - rate_limit_exceeded → 429 (client should back off)
  // - Everything else → 502 (upstream failure)
  const isContextOverflow = code === "context_length_exceeded";
  const isRateLimit = code === "rate_limit_exceeded" || code === "rate_limited";
  let status: number;
  let type: string;
  if (isRateLimit) {
    status = 429;
    type = "rate_limit_error";
  } else if (isContextOverflow) {
    status = 400;
    type = "invalid_request_error";
  } else {
    status = 502;
    type = fallbackType;
  }

  return {
    status,
    type,
    code: code || (isRateLimit ? "rate_limit_exceeded" : "bad_gateway"),
    message,
  };
}

export function extractResponsesReasoningSummaryText(item) {
  if (!item || !Array.isArray(item.summary)) return "";
  return item.summary
    .map((part) =>
      part && typeof part === "object" && typeof part.text === "string" ? part.text : ""
    )
    .join("");
}

// #7095/#7176 — when Codex exposes a reasoning item only as encrypted private
// reasoning (no plaintext summary), chat clients would otherwise see nothing in
// their thinking panel. Reconciles two goals that used to be in tension:
//   - #7095 wants a visible placeholder in the chat client.
//   - #7176 wants the upstream response item left untouched, so `encrypted_content`
//     (needed by Codex for subsequent requests) is never overwritten by a
//     fabricated `summary`.
// This function computes the placeholder text WITHOUT mutating `item` — callers
// use the returned text for synthetic client-facing events only.
const ENCRYPTED_REASONING_PLACEHOLDER =
  "Codex is reasoning, but the upstream Responses API exposed this reasoning block only as encrypted private reasoning. OmniRoute cannot recover the plaintext.";

export function getVisibleResponsesReasoningSummaryText(item) {
  const existingSummary = extractResponsesReasoningSummaryText(item);
  if (existingSummary) return existingSummary;

  const hasEncryptedReasoning =
    item &&
    item.type === "reasoning" &&
    typeof item.encrypted_content === "string" &&
    item.encrypted_content.length > 0;

  return hasEncryptedReasoning ? ENCRYPTED_REASONING_PLACEHOLDER : "";
}

// Shared event-collector for the OpenAI Responses response translator's three emission
// sites (main per-chunk pass, the deferred-completion empty-choices branch introduced by
// #6906, and flushEvents at stream end) — avoids duplicating the events/emit boilerplate.
// Carries stream state (state.seq), so it lives outside the stateless pureHelpers.ts leaf.
export function createEventEmitter(state: { seq: number }) {
  const events: Array<{ event: string; data: Record<string, unknown> }> = [];
  const emit = (eventType: string, data: Record<string, unknown>) => {
    data.sequence_number = ++state.seq;
    events.push({ event: eventType, data });
  };
  return { events, emit };
}

export function buildResponsesToolCallItem(options: {
  callId: string;
  toolName: string;
  custom: boolean;
  namespace?: string | null;
}) {
  const { callId, toolName, custom, namespace } = options;
  const item: {
    id: string;
    type: string;
    arguments?: string;
    input?: string;
    call_id: string;
    name: string;
    namespace?: string;
    status: string;
  } = {
    id: `fc_${callId}`,
    type: custom ? "custom_tool_call" : "function_call",
    ...(custom ? { input: "" } : { arguments: "" }),
    call_id: callId,
    name: toolName,
    status: "in_progress",
  };
  // Codex's ResponseItem::FunctionCall / CustomToolCall both accept an optional
  // `namespace` field and dispatch on it independently of `name` (see
  // codex-rs/protocol/src/models.rs and the `function_call_deserializes_optional_namespace`
  // round-trip test). Emit it whenever the request-side identity ledger resolved
  // the bare leaf back to a namespace sub-tool.
  if (namespace) item.namespace = namespace;
  return item;
}

/** * Resolve a flattened Chat function name back to the identity declared by the * request's Responses namespace tool. The request path supplies this map on * the response translation state; this resolver intentionally never parses a name. */ export function resolveRequestToolIdentity(
  identityMap: unknown,
  toolName: string
) {
  if (!toolName || !identityMap) return null;
  const identity =
    identityMap instanceof Map
      ? identityMap.get(toolName)
      : typeof identityMap === "object" && !Array.isArray(identityMap)
        ? (identityMap as Record<string, unknown>)[toolName]
        : undefined;
  if (!identity || typeof identity !== "object" || Array.isArray(identity)) return null;
  const { namespace, name } = identity as Record<string, unknown>;
  return typeof namespace === "string" && namespace && typeof name === "string" && name
    ? { namespace, name }
    : null;
}

// Extracted from response/openai-responses.ts (file-size ratchet) — synthesizes
// tool_calls chunks from a response.completed event's output[] snapshot, for
// upstream providers that send a single batched completed event WITHOUT first
// emitting the individual response.output_item.added/.delta/.done events.
// Without this, state.toolCallIndex stays 0 and state.currentToolCallId stays
// null, so computeFinishReason returns "stop" instead of "tool_calls",
// breaking the agent loop for downstream Chat Completions clients.
import { fallbackToolCallId } from "../../helpers/toolCallHelper.ts";
import { normalizeToolName, stripEmptyOptionalToolArgs } from "./pureHelpers.ts";

/**
 * Resolve the terminal finish_reason for a Responses→Chat stream.
 *
 * `currentToolCallId` is intentionally sticky for the current turn: it is set when a
 * function_call item is announced (`response.output_item.added`) and is only cleared once
 * the matching `response.output_item.done` advances `toolCallIndex`. If the stream ends
 * (flush or `response.completed`) after a tool call was emitted but BEFORE its
 * `output_item.done` arrived, `toolCallIndex` is still 0 while `currentToolCallId` is set.
 * Guarding on it as well lets us still finalize as `tool_calls` instead of `stop`, so
 * OpenAI-compatible clients continue tool-result processing instead of stopping prematurely.
 *
 * Lives here (not pureHelpers.ts) because it takes stream `state` — pureHelpers.ts is
 * guarded (tests/unit/response-openai-responses-purehelpers-split.test.ts) to have NO
 * state coupling at all.
 */
export function computeFinishReason(state): "tool_calls" | "stop" {
  return (state.toolCallIndex || 0) > 0 || state.currentToolCallId ? "tool_calls" : "stop";
}

/**
 * OpenAI Chat Completions streams announce the assistant role on the FIRST delta
 * (e.g. `{ "role": "assistant", "content": "" }` or `{ "role": "assistant",
 * "tool_calls": [...] }`). The Responses API has no role-announcement event, so when
 * translating Responses → Chat we must synthesize it on the first emitted chunk.
 *
 * Strict streaming clients — notably @langchain/openai's `_convertDeltaToMessageChunk`
 * (used by n8n's AI Agent) — key off the first chunk's role to build an AIMessageChunk.
 * Without it, streamed tool_call deltas are dropped and the agent returns an empty
 * response, even though the underlying tool call is well-formed.
 */
// Shared by both branches of withAssistantRoleOnFirstDelta below: stamps
// role: "assistant" onto a single delta object when eligible, returning
// whether it did so (used to short-circuit the array branch's loop).
function setAssistantRoleIfEligible(state, delta) {
  if (delta && typeof delta === "object" && !Array.isArray(delta)) {
    delta.role = "assistant";
    state.roleEmitted = true;
    return true;
  }
  return false;
}

export function withAssistantRoleOnFirstDelta(state, result) {
  if (!result || state.roleEmitted) return result;

  // Handle arrays of chunks (e.g. synthesized from response.completed output[])
  if (Array.isArray(result)) {
    for (const chunk of result) {
      if (setAssistantRoleIfEligible(state, chunk?.choices?.[0]?.delta)) break;
    }
    return result;
  }

  setAssistantRoleIfEligible(state, result.choices?.[0]?.delta);
  return result;
}

function baseChunk(state): Record<string, unknown> {
  return {
    id: state.chatId,
    object: "chat.completion.chunk",
    created: state.created,
    model: state.model || "gpt-4",
  };
}

/** Resolve the arguments string to emit — may arrive as a string or object. */
function resolveArgsStr(rawArgs, toolName, toolSchema): string {
  const argsToEmit = stripEmptyOptionalToolArgs(rawArgs, toolName, toolSchema);
  if (argsToEmit != null) {
    return typeof argsToEmit === "string" ? argsToEmit : JSON.stringify(argsToEmit);
  }
  if (rawArgs != null) {
    return typeof rawArgs === "string" ? rawArgs : JSON.stringify(rawArgs);
  }
  return "";
}

/**
 * Build the header + args chunks for one synthesized function_call item,
 * mutating `state` exactly as the incremental output_item.added/.done path
 * would (currentToolCallId, currentToolCallArgsBuffer, currentToolCallDeferred,
 * toolCallIndex), so downstream chunk math (computeFinishReason, subsequent
 * incremental events in the same turn) stays consistent.
 */
function buildToolCallChunks(state, fcItem): Record<string, unknown>[] {
  const chunks: Record<string, unknown>[] = [];
  const callId = fcItem.call_id || fallbackToolCallId(state.toolCallIndex);
  const toolName = normalizeToolName(fcItem.name);
  const toolSchema = state.toolSchemas?.get(toolName);

  // Set state as output_item.added would
  state.currentToolCallId = callId;
  state.currentToolCallArgsBuffer = "";
  state.currentToolCallDeferred = false;

  // Emit the tool call header chunk (id, type, function.name)
  const currentIndex = state.toolCallIndex;
  chunks.push({
    ...baseChunk(state),
    choices: [
      {
        index: 0,
        delta: {
          tool_calls: [
            {
              index: currentIndex,
              id: callId,
              type: "function",
              function: { name: toolName || "", arguments: "" },
            },
          ],
        },
        finish_reason: null,
      },
    ],
  });

  const argsStr = resolveArgsStr(fcItem.arguments, toolName, toolSchema);
  if (argsStr) {
    state.currentToolCallArgsBuffer = argsStr;
    chunks.push({
      ...baseChunk(state),
      choices: [
        {
          index: 0,
          delta: { tool_calls: [{ index: currentIndex, function: { arguments: argsStr } }] },
          finish_reason: null,
        },
      ],
    });
  }

  // Advance state as output_item.done would
  state.toolCallIndex++;
  state.currentToolCallArgsBuffer = "";
  state.currentToolCallId = null;

  return chunks;
}

/** Build the terminal chunk (finish_reason + usage) once all tool calls are synthesized. */
function buildFinalChunk(state): Record<string, unknown> {
  state.finishReasonSent = true;
  const reason = computeFinishReason(state);
  state.finishReason = reason;

  const finalChunk: Record<string, unknown> = {
    ...baseChunk(state),
    choices: [{ index: 0, delta: {}, finish_reason: reason }],
  };
  if (state.usage && typeof state.usage === "object") {
    finalChunk.usage = state.usage;
  }
  return finalChunk;
}

/**
 * Synthesize chat-completion-style tool_calls chunks for any `function_call`
 * items in `output` whose call_id was NOT already tracked via incremental
 * `output_item.added`/`.done` events (`state.toolCallIdsSeen`). This dedup
 * guard prevents double-emission when a provider streams incrementally AND
 * `response.completed` also echoes the same function_call items in its
 * output[] snapshot (standard Responses-API snapshot behavior).
 *
 * Mutates `state` exactly as the incremental path would (toolCallIndex,
 * currentToolCallId, currentToolCallArgsBuffer, currentToolCallDeferred,
 * finishReasonSent, finishReason), so downstream chunk math stays consistent.
 *
 * Returns the array of synthesized chunks, or `null` when there is nothing to
 * synthesize (no un-seen function_call items, or finish_reason already sent)
 * — the caller falls through to its own default finish_reason handling.
 */
export function synthesizeCompletedToolCalls(state, output): Record<string, unknown>[] | null {
  const outputItems = Array.isArray(output) ? output : [];
  const functionCallItems = outputItems.filter(
    (item) => item?.type === "function_call" && !state.toolCallIdsSeen?.has(item.call_id)
  );

  if (functionCallItems.length === 0 || state.finishReasonSent) return null;

  const synthesizedChunks: Record<string, unknown>[] = [];
  for (const fcItem of functionCallItems) {
    synthesizedChunks.push(...buildToolCallChunks(state, fcItem));
  }
  synthesizedChunks.push(buildFinalChunk(state));
  return synthesizedChunks;
}

/**
 * Kiro to OpenAI Response Translator
 * Converts Kiro/AWS CodeWhisperer streaming events to OpenAI SSE format
 */
import { register } from "../registry.ts";
import { FORMATS } from "../formats.ts";
import { fallbackToolCallId } from "../helpers/toolCallHelper.ts";

/**
 * Parse Kiro SSE event and convert to OpenAI format
 * Kiro events: assistantResponseEvent, codeEvent, supplementaryWebLinksEvent, etc.
 */
export function convertKiroToOpenAI(chunk, state) {
  if (!chunk) return null;

  // If chunk is already in OpenAI format (from executor transform), return as-is
  if (chunk.object === "chat.completion.chunk" && chunk.choices) {
    return chunk;
  }

  // Handle string chunk (raw SSE data)
  let data = chunk;
  if (typeof chunk === "string") {
    // Parse SSE format: event:xxx\ndata:xxx
    const lines = chunk.split("\n");
    let eventType = "";
    let eventData = "";

    for (const line of lines) {
      if (line.startsWith("event:")) {
        eventType = line.slice(6).trim();
      } else if (line.startsWith(":event-type:")) {
        eventType = line.slice(12).trim();
      } else if (line.startsWith("data:")) {
        eventData = line.slice(5).trim();
      } else if (line.startsWith(":content-type:")) {
        // Skip content-type header
      } else if (line.trim() && !line.startsWith(":")) {
        // Raw JSON data
        eventData = line.trim();
      }
    }

    if (!eventData) return null;

    try {
      data = JSON.parse(eventData);
      data._eventType = eventType;
    } catch {
      // Not JSON, might be raw text
      data = { text: eventData, _eventType: eventType };
    }
  }

  // Initialize state if needed
  if (!state.responseId) {
    state.responseId = `chatcmpl-${Date.now()}`;
    state.created = Math.floor(Date.now() / 1000);
    state.chunkIndex = 0;
  }

  const eventType = data._eventType || data.event || "";

  // Handle different Kiro event types
  if (eventType === "assistantResponseEvent" || data.assistantResponseEvent) {
    const content = data.assistantResponseEvent?.content || data.content || "";
    if (!content) return null;

    const openaiChunk = {
      id: state.responseId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "kiro",
      choices: [
        {
          index: 0,
          delta: {
            ...(state.chunkIndex === 0 ? { role: "assistant" } : {}),
            content: content,
          },
          finish_reason: null,
        },
      ],
    };

    state.chunkIndex++;
    return openaiChunk;
  }

  // Handle reasoning/thinking events
  if (eventType === "reasoningContentEvent" || data.reasoningContentEvent) {
    const content = data.reasoningContentEvent?.content || data.content || "";
    if (!content) return null;

    const openaiChunk = {
      id: state.responseId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "kiro",
      choices: [
        {
          index: 0,
          delta: {
            ...(state.chunkIndex === 0 ? { role: "assistant" } : {}),
            reasoning_content: content,
          },
          finish_reason: null,
        },
      ],
    };

    state.chunkIndex++;
    return openaiChunk;
  }

  // Handle tool use events
  if (eventType === "toolUseEvent" || data.toolUseEvent) {
    const toolUse = data.toolUseEvent || data;
    const toolCallId = toolUse.toolUseId || fallbackToolCallId();
    // #1375: long tool names were hash-truncated for Kiro (sanitizeKiroTools).
    // Map the streamed name back to the original so the client sees the name
    // it sent. `state.toolNameMap` carries truncated → original entries.
    const rawName = toolUse.name || "";
    const toolName =
      state.toolNameMap instanceof Map ? state.toolNameMap.get(rawName) || rawName : rawName;
    const toolInput = toolUse.input || {};

    // #3980: record that this stream produced tool calls so the terminal
    // event reports finish_reason: "tool_calls" instead of "stop" — otherwise
    // agent clients (Hermes) treat the tool-call turn as finished and break.
    state.sawToolUse = true;

    const openaiChunk = {
      id: state.responseId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "kiro",
      choices: [
        {
          index: 0,
          delta: {
            ...(state.chunkIndex === 0 ? { role: "assistant" } : {}),
            tool_calls: [
              {
                index: 0,
                id: toolCallId,
                type: "function",
                function: {
                  name: toolName,
                  arguments: JSON.stringify(toolInput),
                },
              },
            ],
          },
          finish_reason: null,
        },
      ],
    };

    state.chunkIndex++;
    return openaiChunk;
  }

  // Handle completion/done events
  if (eventType === "messageStopEvent" || eventType === "done" || data.messageStopEvent) {
    // #3980: if the stream produced tool calls, the terminal finish_reason must
    // be "tool_calls" (OpenAI semantics), not "stop".
    const finishReason = state.sawToolUse ? "tool_calls" : "stop";
    state.finishReason = finishReason; // Mark for usage injection in stream.js

    const openaiChunk: Record<string, unknown> = {
      id: state.responseId,
      object: "chat.completion.chunk",
      created: state.created,
      model: state.model || "kiro",
      choices: [
        {
          index: 0,
          delta: {},
          finish_reason: finishReason,
        },
      ],
    };

    // Include usage in final chunk if available
    if (state.usage && typeof state.usage === "object") {
      openaiChunk.usage = state.usage;
    }

    return openaiChunk;
  }

  // Handle usage events
  if (eventType === "usageEvent" || data.usageEvent) {
    const usage = data.usageEvent || data;
    if (usage && typeof usage === "object") {
      state.usage = {
        prompt_tokens: usage.inputTokens || 0,
        completion_tokens: usage.outputTokens || 0,
        total_tokens: (usage.inputTokens || 0) + (usage.outputTokens || 0),
      };
    }
    return null;
  }

  // Unknown event type - skip
  return null;
}

// Register translator
register(FORMATS.KIRO, FORMATS.OPENAI, null, convertKiroToOpenAI);

/**
 * Cursor to OpenAI Response Translator
 * CursorExecutor already emits OpenAI format - this is a passthrough
 */
import { register } from "../registry.ts";
import { FORMATS } from "../formats.ts";

/**
 * Convert Cursor response to OpenAI format
 * Since CursorExecutor.transformProtobufToSSE/JSON already emits OpenAI chunks,
 * this is a passthrough translator (similar to Kiro pattern)
 */
export function convertCursorToOpenAI(chunk, state) {
  if (!chunk) return null;

  // If chunk is already in OpenAI format (from executor transform), return as-is
  if (chunk.object === "chat.completion.chunk" && chunk.choices) {
    return chunk;
  }

  // If chunk is a completion object (non-streaming), return as-is
  if (chunk.object === "chat.completion" && chunk.choices) {
    return chunk;
  }

  // Fallback: return chunk as-is (should not reach here)
  return chunk;
}

register(FORMATS.CURSOR, FORMATS.OPENAI, null, convertCursorToOpenAI);

