export interface ExtractedReasoningIntent {
  model: string;
  effort: ReasoningEffort | null;
  sourceEffort: Exclude<ReasoningSourceEffort, "any"> | "signal";
  hasReasoningSignal: boolean;
  hasThinkingBudget: boolean;
}

export interface ReasoningRuleDecision {
  rule: ReasoningRoutingRule;
  sourceModel: string;
  sourceEffort: Exclude<ReasoningSourceEffort, "any"> | "signal";
  targetModel: string;
  targetCombo: JsonRecord | null;
  targetEffort: ReasoningEffort | null;
  capability: "supported" | "unsupported" | "unknown";
  requiresReasoning: boolean;
  warnings: string[];
}

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function effort(value: unknown): ReasoningEffort | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase() as ReasoningEffort;
  return EFFORTS.has(normalized) ? normalized : null;
}

function thinkingLevelEffort(value: unknown): ReasoningEffort | null {
  if (value === false) return "none";
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  if (["disabled", "off", "false"].includes(normalized)) return "none";
  return effort(normalized);
}

function splitGenericEffortSuffix(model: string): {
  model: string;
  effort: ReasoningEffort | null;
} {
  const claude = model.toLowerCase().includes("claude") ? splitClaudeEffortSuffix(model) : null;
  if (claude?.effort) return { model: claude.baseModel, effort: claude.effort };
  return splitCodexEffortSuffix(model) ?? { model, effort: null };
}

function supportsCodexSuffix(candidate: string, normalizedBase: string): boolean {
  if (candidate === "max") return /^gpt-5\.6-(?:sol|terra|luna)$/.test(normalizedBase);
  if (candidate === "ultra") return /^gpt-5\.6-(?:sol|terra)$/.test(normalizedBase);
  return true;
}

function splitCodexEffortSuffix(model: string): { model: string; effort: ReasoningEffort } | null {
  const lower = model.toLowerCase();
  for (const candidate of ["ultra", "xhigh", "medium", "high", "none", "low", "max"] as const) {
    if (!lower.endsWith(`-${candidate}`)) continue;
    const baseModel = model.slice(0, -(candidate.length + 1));
    const normalizedBase = baseModel.toLowerCase().replace(/^(?:codex|cx)\//, "");
    if (/^gpt-[\w.-]+$/.test(normalizedBase) && supportsCodexSuffix(candidate, normalizedBase)) {
      return { model: baseModel, effort: candidate };
    }
  }
  return null;
}

function firstDefinedEffort(
  body: JsonRecord,
  reasoning: JsonRecord,
  thinking: JsonRecord,
  thinkingConfig: JsonRecord,
  suffixEffort: ReasoningEffort | null
): ReasoningEffort | null {
  const output = asRecord(body.output_config);
  const values = [
    effort(reasoning.effort),
    effort(body.reasoning_effort),
    effort(body.reasoningEffort),
    effort(body.effort),
    effort(output.effort),
    thinkingLevelEffort(body.thinkingLevel),
    thinkingLevelEffort(body.thinking_level),
    thinkingLevelEffort(thinkingConfig.thinkingLevel ?? thinkingConfig.thinking_level),
    body.thinking === false || thinking.type === "disabled" ? "none" : null,
    suffixEffort,
  ];
  return values.find((value): value is ReasoningEffort => value !== null) ?? null;
}

function hasNumericField(record: JsonRecord, key: string): boolean {
  return typeof record[key] === "number";
}

function detectThinkingBudget(
  body: JsonRecord,
  reasoning: JsonRecord,
  thinking: JsonRecord,
  thinkingConfig: JsonRecord
): boolean {
  const budgetFields: Array<[JsonRecord, string]> = [
    [thinking, "budget_tokens"],
    [thinking, "budgetTokens"],
    [reasoning, "budget_tokens"],
    [reasoning, "budgetTokens"],
    [reasoning, "max_tokens"],
    [body, "thinking_budget"],
    [body, "thinkingBudget"],
    [thinkingConfig, "thinkingBudget"],
    [thinkingConfig, "thinking_budget"],
  ];
  return budgetFields.some(([record, key]) => hasNumericField(record, key));
}

function hasReasoningSignal(
  body: JsonRecord,
  reasoning: JsonRecord,
  thinkingConfig: JsonRecord,
  explicitEffort: ReasoningEffort | null,
  hasBudget: boolean
): boolean {
  return (
    explicitEffort !== null ||
    [
      body.thinking,
      body.thinkingLevel,
      body.thinking_level,
      reasoning.effort,
      body.reasoning_effort,
      body.reasoningEffort,
      body.effort,
      asRecord(body.output_config).effort,
      thinkingConfig.thinkingLevel,
      thinkingConfig.thinking_level,
    ].some((value) => value !== undefined) ||
    hasBudget
  );
}

export function extractReasoningIntent(
  modelInput: unknown,
  bodyInput: unknown
): ExtractedReasoningIntent {
  const body = asRecord(bodyInput);
  const rawModel = typeof modelInput === "string" ? modelInput.trim() : "";
  const suffixed = splitGenericEffortSuffix(rawModel);
  const reasoning = asRecord(body.reasoning);
  const thinking = asRecord(body.thinking);
  const generationConfig = asRecord(body.generationConfig);
  const thinkingConfig = asRecord(
    generationConfig.thinkingConfig ?? generationConfig.thinking_config
  );
  const explicitEffort = firstDefinedEffort(
    body,
    reasoning,
    thinking,
    thinkingConfig,
    suffixed.effort
  );
  const hasThinkingBudget = detectThinkingBudget(body, reasoning, thinking, thinkingConfig);
  const hasReasoningSignalValue = hasReasoningSignal(
    body,
    reasoning,
    thinkingConfig,
    explicitEffort,
    hasThinkingBudget
  );
  return {
    model: suffixed.model,
    effort: explicitEffort,
    sourceEffort: explicitEffort ?? (hasReasoningSignalValue ? "signal" : "missing"),
    hasReasoningSignal: hasReasoningSignalValue,
    hasThinkingBudget,
  };
}

export function globMatches(pattern: string, value: string): boolean {
  const escaped = pattern
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*/g, ".*")
    .replace(/\?/g, ".");
  return new RegExp(`^${escaped}$`, "i").test(value);
}

export async function resolveReasoningSourceModels(
  model: string,
  resolve: (model: string) => Promise<{ provider?: string | null; model?: string | null }>
): Promise<{ normalized: string; aliases: string[] }> {
  try {
    const resolved = await resolve(model);
    const resolvedModel =
      typeof resolved?.model === "string" && resolved.model.trim() ? resolved.model.trim() : null;
    const provider =
      typeof resolved?.provider === "string" && resolved.provider.trim()
        ? resolved.provider.trim()
        : null;
    const normalized =
      provider && resolvedModel ? `${provider}/${resolvedModel}` : resolvedModel || model;
    return {
      normalized,
      aliases: normalized.toLowerCase() === model.toLowerCase() ? [] : [model],
    };
  } catch {
    return { normalized: model, aliases: [] };
  }
}

function tagsMatch(rule: ReasoningRoutingRule, requestTags: string[]): boolean {
  if (rule.requestTags.length === 0) return true;
  const available = new Set(normalizeRoutingTags(requestTags));
  return rule.tagMatchMode === "all"
    ? rule.requestTags.every((tag) => available.has(tag))
    : rule.requestTags.some((tag) => available.has(tag));
}

function modelMatches(rule: ReasoningRoutingRule, model: string): boolean {
  if (!rule.modelPattern) return true;
  return globMatches(rule.modelPattern, model);
}

function isExactModelMatch(rule: ReasoningRoutingRule, model: string): boolean {
  return (
    !!rule.modelPattern &&
    !/[?*]/.test(rule.modelPattern) &&
    rule.modelPattern.toLowerCase() === model.toLowerCase()
  );
}

function capabilityFor(
  model: string,
  targetEffort: ReasoningEffort | null,
  requiresReasoning = Boolean(targetEffort && targetEffort !== "none")
) {
  if (!requiresReasoning || targetEffort === "none") return "supported" as const;
  const capabilities = getResolvedModelCapabilities(model);
  if (capabilities.supportsThinking === false) return "unsupported" as const;
  if (targetEffort === "max" || targetEffort === "ultra") {
    const normalized = model.toLowerCase().replace(/^(?:codex|cx)\//, "");
    const supported =
      targetEffort === "ultra"
        ? /^gpt-5\.6-(?:sol|terra)(?:-|$)/.test(normalized)
        : /^gpt-5\.6-(?:sol|terra|luna)(?:-|$)/.test(normalized);
    if (supported) return "supported" as const;
    if (capabilities.supportsThinking === null) return "unknown" as const;
    return "unsupported" as const;
  }
  return capabilities.supportsThinking === null ? ("unknown" as const) : ("supported" as const);
}

type RoutingInput = {
  sourceModel: string;
  sourceModelAliases?: string[];
  sourceEffort: Exclude<ReasoningSourceEffort, "any"> | "signal";
  hasReasoningSignal: boolean;
  hasThinkingBudget?: boolean;
  apiKeyId?: string | null;
  comboId?: string | null;
  connectionId?: string | null;
  requestTags?: string[];
  connectionOnly?: boolean;
  capabilityModel?: string | null;
};

function inputModels(input: RoutingInput): string[] {
  return [input.sourceModel, ...(input.sourceModelAliases ?? [])];
}

function scopeMatches(rule: ReasoningRoutingRule, input: RoutingInput): boolean {
  if (input.connectionOnly ? rule.scope !== "connection" : rule.scope === "connection") {
    return false;
  }
  if (rule.scope === "apiKey" && rule.apiKeyId !== input.apiKeyId) return false;
  if (rule.scope === "combo" && rule.comboId !== input.comboId) return false;
  if (rule.scope === "connection" && rule.connectionId !== input.connectionId) return false;
  return rule.sourceEffort === "any" || rule.sourceEffort === input.sourceEffort;
}

function ruleMatches(rule: ReasoningRoutingRule, input: RoutingInput): boolean {
  return (
    scopeMatches(rule, input) &&
    inputModels(input).some((model) => modelMatches(rule, model)) &&
    tagsMatch(rule, input.requestTags ?? [])
  );
}

function exactMatchScore(rule: ReasoningRoutingRule, input: RoutingInput): number {
  return Number(inputModels(input).some((model) => isExactModelMatch(rule, model)));
}

function compareRules(input: RoutingInput) {
  return (a: ReasoningRoutingRule, b: ReasoningRoutingRule) =>
    SCOPE_RANK[b.scope] - SCOPE_RANK[a.scope] ||
    b.priority - a.priority ||
    exactMatchScore(b, input) - exactMatchScore(a, input) ||
    a.createdAt.localeCompare(b.createdAt) ||
    a.id.localeCompare(b.id);
}

function resolveTargetModel(
  rule: ReasoningRoutingRule,
  sourceModel: string,
  combo: JsonRecord | null
) {
  if (combo) return typeof combo.name === "string" ? combo.name : rule.targetComboId;
  return rule.targetKind === "model" && rule.targetModel ? rule.targetModel : sourceModel;
}

async function resolveTarget(rule: ReasoningRoutingRule, sourceModel: string) {
  if (rule.targetKind !== "combo" || !rule.targetComboId) {
    return { targetCombo: null, targetModel: resolveTargetModel(rule, sourceModel, null) };
  }
  const targetCombo = (await getComboById(rule.targetComboId)) as JsonRecord | null;
  if (!targetCombo) throw new Error("Reasoning routing target combo does not exist");
  return { targetCombo, targetModel: resolveTargetModel(rule, sourceModel, targetCombo) };
}

function resolveTargetEffort(
  rule: ReasoningRoutingRule,
  input: RoutingInput
): ReasoningEffort | null {
  const inherits =
    rule.effortMode === "inherit" || (rule.effortMode === "default" && input.hasReasoningSignal);
  if (!inherits) return rule.targetEffort;
  return input.sourceEffort === "missing" || input.sourceEffort === "signal"
    ? null
    : input.sourceEffort;
}

function resolveCapability(
  targetCombo: JsonRecord | null,
  targetModel: string,
  targetEffort: ReasoningEffort | null,
  requiresReasoning: boolean
): { capability: ReasoningRuleDecision["capability"]; warnings: string[] } {
  if (!targetCombo) {
    return {
      capability: capabilityFor(targetModel, targetEffort, requiresReasoning),
      warnings: [],
    };
  }
  const models = Array.isArray(targetCombo.models) ? targetCombo.models : [];
  const statuses = models.map((entry) => {
    const record = asRecord(entry);
    const model =
      typeof entry === "string"
        ? entry
        : typeof record.model === "string"
          ? String(record.model)
          : null;
    return model ? capabilityFor(model, targetEffort, requiresReasoning) : "unknown";
  });
  const capability =
    statuses.length > 0 && statuses.every((status) => status === "unsupported")
      ? "unsupported"
      : statuses.some((status) => status === "unknown")
        ? "unknown"
        : "supported";
  const unsupportedCount = statuses.filter((status) => status === "unsupported").length;
  const warnings =
    unsupportedCount > 0 && capability !== "unsupported"
      ? [`${unsupportedCount} incompatible combo target(s) will be skipped`]
      : [];
  return { capability, warnings };
}

export async function resolveReasoningRoutingRule(
  input: RoutingInput
): Promise<ReasoningRuleDecision | null> {
  const rules = await getReasoningRoutingRules({ enabledOnly: true });
  const candidates = rules.filter((rule) => ruleMatches(rule, input)).sort(compareRules(input));
  const rule = candidates[0];
  if (!rule) return null;

  const { targetCombo, targetModel } = await resolveTarget(rule, input.sourceModel);
  const targetEffort = resolveTargetEffort(rule, input);
  const budgetAction = targetEffort === "none" ? "remove" : rule.budgetAction;
  const requiresReasoning =
    targetEffort !== "none" &&
    (Boolean(targetEffort) ||
      budgetAction === "set" ||
      (budgetAction === "preserve" && input.hasThinkingBudget === true));
  const capabilityResult = resolveCapability(
    targetCombo,
    input.capabilityModel || targetModel,
    targetEffort,
    requiresReasoning
  );
  const capability = capabilityResult.capability;
  const warnings = capabilityResult.warnings;
  if (capability === "unknown") warnings.push("Reasoning capability could not be verified");
  return {
    rule,
    sourceModel: input.sourceModel,
    sourceEffort: input.sourceEffort,
    targetModel,
    targetCombo,
    targetEffort,
    capability,
    requiresReasoning,
    warnings,
  };
}

function clearReasoning(body: JsonRecord): void {
  delete body.reasoning_effort;
  delete body.reasoningEffort;
  delete body.reasoning;
  delete body.effort;
  delete body.thinking;
  delete body.thinkingLevel;
  delete body.thinking_level;
  delete body.thinking_budget;
  delete body.thinkingBudget;
  if (body.output_config && typeof body.output_config === "object") {
    const output = { ...asRecord(body.output_config) };
    delete output.effort;
    body.output_config = output;
  }
}

function clearDiscreteReasoning(body: JsonRecord): void {
  delete body.reasoning_effort;
  delete body.reasoningEffort;
  delete body.effort;
  delete body.thinkingLevel;
  delete body.thinking_level;
  if (body.reasoning && typeof body.reasoning === "object") {
    const reasoning = { ...asRecord(body.reasoning) };
    delete reasoning.effort;
    if (Object.keys(reasoning).length > 0) body.reasoning = reasoning;
    else delete body.reasoning;
  }
  if (body.output_config && typeof body.output_config === "object") {
    const output = { ...asRecord(body.output_config) };
    delete output.effort;
    if (Object.keys(output).length > 0) body.output_config = output;
    else delete body.output_config;
  }
  const thinking = asRecord(body.thinking);
  if (body.thinking !== undefined && typeof thinking.budget_tokens !== "number") {
    delete body.thinking;
  }
}

function removeBudgets(body: JsonRecord): void {
  delete body.thinking_budget;
  delete body.thinkingBudget;
  const thinking = { ...asRecord(body.thinking) };
  delete thinking.budget_tokens;
  delete thinking.budgetTokens;
  if (Object.keys(thinking).length > 0 && body.thinking !== undefined) body.thinking = thinking;
  else delete body.thinking;
  const reasoning = { ...asRecord(body.reasoning) };
  delete reasoning.budget_tokens;
  delete reasoning.budgetTokens;
  delete reasoning.max_tokens;
  if (Object.keys(reasoning).length > 0 && body.reasoning !== undefined) body.reasoning = reasoning;
  else if (body.reasoning !== undefined) delete body.reasoning;
  const generationConfig = { ...asRecord(body.generationConfig) };
  delete generationConfig.thinkingConfig;
  delete generationConfig.thinking_config;
  if (Object.keys(generationConfig).length > 0) body.generationConfig = generationConfig;
  else delete body.generationConfig;
}

function applyBudget(body: JsonRecord, action: ReasoningBudgetAction, budget: number | null): void {
  if (action === "preserve") return;
  removeBudgets(body);
  if (action === "remove") return;
  body.thinking = { type: "enabled", budget_tokens: budget };
}

export function attachReasoningRuleDirective(
  bodyInput: unknown,
  decision: ReasoningRuleDecision
): JsonRecord {
  const source = asRecord(bodyInput);
  const body: JsonRecord = {
    ...source,
    model: decision.rule.scope === "connection" ? source.model : decision.targetModel,
  };
  body._omnirouteReasoningRule = {
    id: decision.rule.id,
    effortMode: decision.rule.effortMode,
    targetEffort: decision.targetEffort,
    budgetAction: decision.targetEffort === "none" ? "remove" : decision.rule.budgetAction,
    budgetTokens: decision.rule.budgetTokens,
  };
  body._omnirouteReasoningRouteTrace = {
    ruleId: decision.rule.id,
    ruleName: decision.rule.name,
    scope: decision.rule.scope,
    sourceModel: decision.sourceModel,
    targetModel: decision.targetModel,
    sourceEffort: decision.sourceEffort,
    targetEffort: decision.targetEffort,
    effortMode: decision.rule.effortMode,
    budgetAction: decision.targetEffort === "none" ? "remove" : decision.rule.budgetAction,
    capability: decision.capability,
    warnings: decision.warnings,
  };
  return body;
}

export function applyReasoningRuleDirective(bodyInput: unknown): unknown {
  const source = asRecord(bodyInput);
  const directive = asRecord(source._omnirouteReasoningRule);
  if (!directive.id) return bodyInput;
  const body = { ...source };
  delete body._omnirouteReasoningRule;
  const effortMode = directive.effortMode;
  const targetEffort = effort(directive.targetEffort);
  if (effortMode === "force" && targetEffort === "none") clearReasoning(body);
  else if ((effortMode === "force" || effortMode === "default") && targetEffort) {
    if (effortMode === "force") clearDiscreteReasoning(body);
    body.reasoning_effort = targetEffort;
    body.reasoning = { ...asRecord(body.reasoning), effort: targetEffort };
    body.output_config = { ...asRecord(body.output_config), effort: targetEffort };
  }
  applyBudget(
    body,
    directive.budgetAction as ReasoningBudgetAction,
    typeof directive.budgetTokens === "number" ? directive.budgetTokens : null
  );
  return body;
}

export function filterComboForReasoningDecision(
  comboInput: unknown,
  decision: ReasoningRuleDecision
): { combo: JsonRecord | null; removed: string[] } {
  const combo = { ...asRecord(comboInput) };
  if (!Array.isArray(combo.models) || !decision.requiresReasoning) return { combo, removed: [] };
  const removed: string[] = [];
  combo.models = combo.models.filter((entry) => {
    const model =
      typeof entry === "string"
        ? entry
        : typeof asRecord(entry).model === "string"
          ? String(asRecord(entry).model)
          : null;
    if (!model) return true;
    if (capabilityFor(model, decision.targetEffort, true) !== "unsupported") return true;
    removed.push(model);
    return false;
  });
  return { combo: (combo.models as unknown[]).length > 0 ? combo : null, removed };
}

export function isCodexTarget(model: string): boolean {
  return !model.includes("/") || /^(?:codex|cx)\//i.test(model);
}

export function validateCodexWsDecision(decision: ReasoningRuleDecision): string | null {
  if (decision.targetCombo) {
    const models = Array.isArray(decision.targetCombo.models) ? decision.targetCombo.models : [];
    const allCodex =
      models.length > 0 &&
      models.every((entry) => {
        const model =
          typeof entry === "string"
            ? entry
            : typeof asRecord(entry).model === "string"
              ? String(asRecord(entry).model)
              : "";
        return !!model && isCodexTarget(model);
      });
    if (!allCodex) return "Codex WebSocket reasoning rules require a Codex-only target";
    return "Codex WebSocket transport cannot execute combo targets";
  }
  return isCodexTarget(decision.targetModel)
    ? null
    : "Codex WebSocket reasoning rules require a Codex target model";
}

/**
 * db/combos.js — Combo CRUD operations.
 */

import { v4 as uuidv4 } from "uuid";
import { getDbInstance } from "./core";
import { backupDbFile } from "./backup";
import { invalidateDbCache } from "./readCache";
import { invalidateReasoningRoutingRuleCache } from "./reasoningRoutingRules";
import { normalizeComboRecord } from "@/lib/combos/steps";
import { clearSessionModelHistoryForCombo } from "./contextHandoffs";
import { validateComboInvariant } from "@/lib/combos/invariants";

type JsonRecord = Record<string, unknown>;

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function getSerializedData(value: unknown): string | null {
  const row = asRecord(value);
  return typeof row.data === "string" ? row.data : null;
}

function getSortOrder(value: unknown): number | null {
  const row = asRecord(value);
  return typeof row.sort_order === "number" ? row.sort_order : null;
}

function withSortOrder(payload: string, sortOrder: number | null): JsonRecord {
  const parsed = JSON.parse(payload) as JsonRecord;
  if (typeof sortOrder === "number") {
    parsed.sortOrder = sortOrder;
  }
  return parsed;
}

function getComboNameSet(
  db: ReturnType<typeof getDbInstance>,
  extraNames: string[] = []
): Set<string> {
  const rows = db.prepare("SELECT name FROM combos").all();
  const names = new Set<string>();

  for (const row of rows) {
    const record = asRecord(row);
    if (typeof record.name === "string" && record.name.trim().length > 0) {
      names.add(record.name.trim());
    }
  }

  for (const name of extraNames) {
    if (typeof name === "string" && name.trim().length > 0) {
      names.add(name.trim());
    }
  }

  return names;
}

function normalizeStoredCombo(
  combo: JsonRecord,
  db: ReturnType<typeof getDbInstance>,
  extraNames: string[] = []
): JsonRecord {
  return normalizeComboRecord(combo, {
    allCombos: getComboNameSet(db, extraNames),
  }) as JsonRecord;
}

function parseComboRow(row: unknown): JsonRecord | null {
  const payload = getSerializedData(row);
  if (!payload) return null;
  const parsed = withSortOrder(payload, getSortOrder(row));
  // Merge deduplicated column values back into the record
  const record = asRecord(row);
  if (record.context_cache_protection !== undefined && record.context_cache_protection !== null) {
    // Column is authoritative when explicitly enabled (1).
    // When column is 0 (unset default) preserve the JSON blob value
    // to avoid silently disabling the feature on pre-migration rows.
    if (record.context_cache_protection === 1) {
      parsed.context_cache_protection = true;
    }
    // Column is 0 — keep existing JSON blob value
  }
  return parsed;
}

function getNextSortOrder() {
  const db = getDbInstance();
  const row = db.prepare("SELECT COALESCE(MAX(sort_order), 0) AS sort_order FROM combos").get();
  const sortOrder = getSortOrder(row);
  return (sortOrder ?? 0) + 1;
}

export async function getCombos(limit?: number, offset?: number) {
  const db = getDbInstance();
  let sql =
    "SELECT data, sort_order, context_cache_protection FROM combos ORDER BY sort_order ASC, name COLLATE NOCASE ASC";
  const params: unknown[] = [];
  if (limit !== undefined) {
    sql += " LIMIT ? OFFSET ?";
    params.push(limit, offset ?? 0);
  }
  const rawCombos = db
    .prepare(sql)
    .all(...params)
    .map((row) => parseComboRow(row))
    .filter((row): row is JsonRecord => row !== null);

  const comboNames = rawCombos
    .map((combo) => (typeof combo.name === "string" ? combo.name.trim() : ""))
    .filter((name): name is string => name.length > 0);

  return rawCombos.map((combo) =>
    normalizeComboRecord(combo, {
      allCombos: comboNames,
    })
  );
}

export function getCombosCount(): number {
  const db = getDbInstance();
  const row = db.prepare("SELECT count(*) as cnt FROM combos").get() as { cnt: number };
  return row.cnt;
}

export async function getComboById(id: string) {
  const db = getDbInstance();
  const row = db
    .prepare("SELECT data, sort_order, context_cache_protection FROM combos WHERE id = ?")
    .get(id);
  const combo = parseComboRow(row);
  if (!combo) return null;
  return normalizeStoredCombo(combo, db, typeof combo.name === "string" ? [combo.name] : []);
}

export async function getComboByName(name: string) {
  const db = getDbInstance();
  const row = db
    .prepare("SELECT data, sort_order, context_cache_protection FROM combos WHERE name = ?")
    .get(name);
  const combo = parseComboRow(row);
  if (!combo) return null;
  return normalizeStoredCombo(combo, db, [name]);
}

// #4446: case-insensitive name lookup. The opencode dispatch path forwards a
// lowercased combo slug (e.g. "master-light") for a combo provisioned as
// "MASTER-LIGHT"; the default BINARY collation of getComboByName misses it.
// Used only as a fallback after the exact match fails, so it cannot change the
// resolution of any combo that already resolves today.
export async function getComboByNameInsensitive(name: string) {
  const db = getDbInstance();
  const row = db
    .prepare(
      "SELECT data, sort_order, context_cache_protection FROM combos WHERE name = ? COLLATE NOCASE"
    )
    .get(name);
  const combo = parseComboRow(row);
  if (!combo) return null;
  const storedName = typeof combo.name === "string" ? combo.name : name;
  return normalizeStoredCombo(combo, db, [storedName]);
}

export async function createCombo(data: JsonRecord) {
  const db = getDbInstance();
  const now = new Date().toISOString();
  const sortOrder = typeof data.sortOrder === "number" ? data.sortOrder : getNextSortOrder();
  const comboId = typeof data.id === "string" && data.id.trim().length > 0 ? data.id : uuidv4();
  const combo = normalizeStoredCombo(
    {
      ...data,
      id: comboId,
      name: data.name,
      models: data.models || [],
      strategy: data.strategy || "priority",
      config: data.config || {},
      isHidden: Boolean(data.isHidden),
      sortOrder,
      createdAt: now,
      updatedAt: now,
    },
    db,
    typeof data.name === "string" ? [data.name] : []
  );

  validateComboInvariant(combo);
  const contextCache = data.context_cache_protection ? 1 : 0;
  db.prepare(
    "INSERT INTO combos (id, name, data, sort_order, created_at, updated_at, context_cache_protection) VALUES (?, ?, ?, ?, ?, ?, ?)"
  ).run(combo.id, combo.name, JSON.stringify(combo), sortOrder, now, now, contextCache);

  invalidateDbCache("combos");
  backupDbFile("pre-write");
  return combo;
}

export async function updateCombo(id: string, data: JsonRecord) {
  const db = getDbInstance();
  const existing = db
    .prepare("SELECT data, sort_order, context_cache_protection FROM combos WHERE id = ?")
    .get(id);
  if (!existing) return null;

  const current = parseComboRow(existing);
  if (!current) return null;
  const sortOrder =
    typeof data.sortOrder === "number"
      ? data.sortOrder
      : typeof current.sortOrder === "number"
        ? current.sortOrder
        : getNextSortOrder();
  const merged: JsonRecord = {
    ...current,
    ...data,
    sortOrder,
    updatedAt: new Date().toISOString(),
  };
  // Remove fields explicitly set to null (for deletion support)
  for (const key of Object.keys(data)) {
    if (data[key] === null) {
      delete merged[key];
    }
  }
  const currentName = typeof current.name === "string" ? current.name : "";
  const nextName =
    typeof merged["name"] === "string" && merged["name"].trim().length > 0
      ? merged["name"]
      : currentName;
  const normalizedMerged = normalizeStoredCombo({ ...merged, name: nextName }, db, [nextName]);
  validateComboInvariant({
    ...normalizedMerged,
    ...data,
    name: nextName,
    models: normalizedMerged.models,
  });
  const contextCacheProtection = normalizedMerged.context_cache_protection ? 1 : 0;

  db.prepare(
    "UPDATE combos SET name = ?, data = ?, sort_order = ?, updated_at = ?, context_cache_protection = ? WHERE id = ?"
  ).run(
    nextName,
    JSON.stringify(normalizedMerged),
    sortOrder,
    normalizedMerged.updatedAt,
    contextCacheProtection,
    id
  );

  // Invalidate stale context-cache pins when combo targets change.
  // Without this, sessions pinned to removed models keep routing there forever.
  if (data.models !== undefined) {
    const cleared = clearSessionModelHistoryForCombo(currentName);
    if (cleared > 0) {
      // Also clear under the new name if the combo was renamed
      if (nextName !== currentName) {
        clearSessionModelHistoryForCombo(nextName);
      }
    }
  }

  invalidateDbCache("combos");
  backupDbFile("pre-write");
  return normalizedMerged;
}

export async function reorderCombos(comboIds: string[]) {
  const db = getDbInstance();
  const rows = db
    .prepare(
      "SELECT id, name, data, sort_order FROM combos ORDER BY sort_order ASC, name COLLATE NOCASE ASC"
    )
    .all();
  if (rows.length === 0) return [];

  const existingIds = new Set(
    rows
      .map((row) => {
        const record = asRecord(row);
        return typeof record.id === "string" ? record.id : null;
      })
      .filter((id): id is string => id !== null)
  );

  const seen = new Set<string>();
  const requestedIds = comboIds.filter((id) => {
    if (!existingIds.has(id) || seen.has(id)) return false;
    seen.add(id);
    return true;
  });

  const orderedIds = [
    ...requestedIds,
    ...rows
      .map((row) => {
        const record = asRecord(row);
        return typeof record.id === "string" ? record.id : null;
      })
      .filter((id): id is string => id !== null && !seen.has(id)),
  ];

  const update = db.prepare(
    "UPDATE combos SET data = ?, sort_order = ?, updated_at = ? WHERE id = ?"
  );
  const now = new Date().toISOString();
  const rowById = new Map(
    rows.map((row) => {
      const record = asRecord(row);
      return [String(record.id), row];
    })
  );
  const comboNames = rows
    .map((row) => {
      const combo = parseComboRow(row);
      return combo && typeof combo.name === "string" ? combo.name.trim() : "";
    })
    .filter((name): name is string => name.length > 0);

  const reorderTransaction = db.transaction(() => {
    orderedIds.forEach((id, index) => {
      const row = rowById.get(id);
      const combo = row ? parseComboRow(row) : null;
      if (!combo) return;
      const sortOrder = index + 1;
      const updatedCombo = normalizeComboRecord(
        { ...combo, sortOrder, updatedAt: now },
        { allCombos: comboNames }
      );
      update.run(JSON.stringify(updatedCombo), sortOrder, now, id);
    });
  });

  reorderTransaction();
  invalidateDbCache("combos");
  backupDbFile("pre-write");
  return getCombos();
}

export async function deleteCombo(id: string) {
  const db = getDbInstance();
  const result = db.prepare("DELETE FROM combos WHERE id = ?").run(id);
  if (result.changes === 0) return false;
  invalidateDbCache("combos");
  invalidateReasoningRoutingRuleCache();
  backupDbFile("pre-write");
  return true;
}

export async function deleteComboByName(name: string) {
  const combo = await getComboByName(name);
  if (!combo || typeof combo.id !== "string") return false;
  return deleteCombo(combo.id);
}

export function setActiveCombo(name: string, db = getDbInstance()) {
  db.prepare(
    "INSERT OR REPLACE INTO key_value (namespace, key, value) VALUES ('settings', 'activeCombo', ?)"
  ).run(JSON.stringify(name));
}

/**
 * Null out any combo model step whose connectionId matches a deleted connection.
 * Called after a provider connection is removed so combo routes don't carry
 * stale references.
 */
export async function cleanupComboConnectionRefs(connectionId: string) {
  const combos = await getCombos();
  let touched = 0;
  for (const combo of combos) {
    if (!Array.isArray(combo.models)) continue;
    let changed = false;
    const models = (combo.models as unknown as Record<string, unknown>[]).map((step) => {
      let out = step;
      if (out.connectionId === connectionId) {
        const { connectionId: _, ...rest } = out;
        out = rest;
        changed = true;
      }
      if (Array.isArray(out.allowedConnectionIds)) {
        const filtered = out.allowedConnectionIds.filter(
          (id: string) => id !== connectionId
        );
        if (filtered.length !== out.allowedConnectionIds.length) {
          out = { ...out, allowedConnectionIds: filtered };
          changed = true;
        }
      }
      return out;
    });
    if (changed && typeof combo.id === "string") {
      try {
        const { id, ...rest } = combo;
        await updateCombo(combo.id, { ...rest, models });
        touched++;
      } catch {
        // One combo failing should not block cleanup of the rest.
      }
    }
  }
  return touched;
}

import { getDbInstance, rowToCamel } from "./core";

export interface HandoffPayload {
  id?: string;
  sessionId: string;
  comboName: string;
  fromAccount: string;
  summary: string;
  keyDecisions: string[];
  taskProgress: string;
  activeEntities: string[];
  messageCount: number;
  model: string;
  lastModel?: string;
  warningThresholdPct: number;
  generatedAt: string;
  expiresAt: string;
  createdAt?: string;
}

type JsonRecord = Record<string, unknown>;

interface StatementLike<TRow = unknown> {
  get: (...params: unknown[]) => TRow | undefined;
  run: (...params: unknown[]) => { changes: number };
}

interface DbLike {
  prepare: <TRow = unknown>(sql: string) => StatementLike<TRow>;
}

const CLEANUP_THROTTLE_MS = 30 * 60 * 1000;

let lastCleanupAt = 0;

function parseJsonArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((item) => (typeof item === "string" ? item : String(item))).filter(Boolean);
  }

  if (typeof value !== "string" || value.trim().length === 0) {
    return [];
  }

  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed)
      ? parsed.map((item) => (typeof item === "string" ? item : String(item))).filter(Boolean)
      : [];
  } catch {
    return [];
  }
}

function toHandoffPayload(row: unknown): HandoffPayload | null {
  const camel = rowToCamel(row) as JsonRecord | null;
  if (!camel) return null;

  return {
    id: typeof camel.id === "string" ? camel.id : undefined,
    sessionId: typeof camel.sessionId === "string" ? camel.sessionId : "",
    comboName: typeof camel.comboName === "string" ? camel.comboName : "",
    fromAccount: typeof camel.fromAccount === "string" ? camel.fromAccount : "",
    summary: typeof camel.summary === "string" ? camel.summary : "",
    keyDecisions: parseJsonArray(camel.keyDecisions),
    taskProgress: typeof camel.taskProgress === "string" ? camel.taskProgress : "",
    activeEntities: parseJsonArray(camel.activeEntities),
    messageCount: Number.isFinite(Number(camel.messageCount)) ? Number(camel.messageCount) : 0,
    model: typeof camel.model === "string" ? camel.model : "",
    lastModel: typeof camel.lastModel === "string" ? camel.lastModel : undefined,
    warningThresholdPct: Number.isFinite(Number(camel.warningThresholdPct))
      ? Number(camel.warningThresholdPct)
      : 0.85,
    generatedAt: typeof camel.generatedAt === "string" ? camel.generatedAt : "",
    expiresAt: typeof camel.expiresAt === "string" ? camel.expiresAt : "",
    createdAt: typeof camel.createdAt === "string" ? camel.createdAt : undefined,
  };
}

export function upsertHandoff(payload: HandoffPayload): void {
  const db = getDbInstance() as unknown as DbLike;
  const createdAt = new Date().toISOString();

  db.prepare(
    `INSERT INTO context_handoffs
      (session_id, combo_name, from_account, summary, key_decisions,
       task_progress, active_entities, message_count, model, last_model,
       warning_threshold_pct, generated_at, expires_at, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(session_id, combo_name) DO UPDATE SET
       from_account = excluded.from_account,
       summary = excluded.summary,
       key_decisions = excluded.key_decisions,
       task_progress = excluded.task_progress,
       active_entities = excluded.active_entities,
       message_count = excluded.message_count,
       model = excluded.model,
       last_model = excluded.last_model,
       warning_threshold_pct = excluded.warning_threshold_pct,
       generated_at = excluded.generated_at,
       expires_at = excluded.expires_at,
       created_at = excluded.created_at`
  ).run(
    payload.sessionId,
    payload.comboName,
    payload.fromAccount,
    payload.summary,
    JSON.stringify(payload.keyDecisions || []),
    payload.taskProgress,
    JSON.stringify(payload.activeEntities || []),
    payload.messageCount,
    payload.model,
    payload.lastModel || null,
    payload.warningThresholdPct,
    payload.generatedAt,
    payload.expiresAt,
    createdAt
  );
}

export function getHandoff(sessionId: string, comboName: string): HandoffPayload | null {
  const db = getDbInstance() as unknown as DbLike;
  const now = new Date().toISOString();
  const row = db
    .prepare(
      `SELECT *
       FROM context_handoffs
       WHERE session_id = ? AND combo_name = ? AND expires_at > ?
       ORDER BY created_at DESC
       LIMIT 1`
    )
    .get(sessionId, comboName, now);

  return toHandoffPayload(row);
}

export function deleteHandoff(sessionId: string, comboName: string): void {
  const db = getDbInstance() as unknown as DbLike;
  db.prepare("DELETE FROM context_handoffs WHERE session_id = ? AND combo_name = ?").run(
    sessionId,
    comboName
  );
}

export function cleanupExpiredHandoffs(): number {
  const nowMs = Date.now();
  if (nowMs - lastCleanupAt < CLEANUP_THROTTLE_MS) {
    return 0;
  }

  const db = getDbInstance() as unknown as DbLike;
  const now = new Date(nowMs).toISOString();
  const result = db.prepare("DELETE FROM context_handoffs WHERE expires_at <= ?").run(now);
  lastCleanupAt = nowMs;
  return result.changes;
}

export function hasActiveHandoff(sessionId: string, comboName: string): boolean {
  const db = getDbInstance() as unknown as DbLike;
  const now = new Date().toISOString();
  const row = db
    .prepare(
      `SELECT 1
       FROM context_handoffs
       WHERE session_id = ? AND combo_name = ? AND expires_at > ?
       LIMIT 1`
    )
    .get(sessionId, comboName, now);

  return !!row;
}
/**
 * Record a model usage entry for a session/combo combination.
 * Used by context-relay to track which models have been active.
 *
 * @param sessionId - The session identifier.
 * @param comboName - The combo name.
 * @param modelStr - The model string (e.g. "claude-sonnet-4-20250514").
 * @param provider - The provider identifier.
 * @param connectionId - Optional connection ID used.
 */
export function recordSessionModelUsage(
  sessionId: string,
  comboName: string,
  modelStr: string,
  provider: string,
  connectionId?: string
): void {
  const db = getDbInstance() as unknown as DbLike;
  db.prepare(
    `INSERT INTO session_model_history
      (session_id, combo_name, model_str, provider, connection_id)
     VALUES (?, ?, ?, ?, ?)`
  ).run(sessionId, comboName, modelStr, provider, connectionId || null);
}

/**
 * Get the most recently used model for a session/combo combination.
 * Returns null if no usage has been recorded.
 *
 * @param sessionId - The session identifier.
 * @param comboName - The combo name.
 * @returns The model string, or null if no record exists.
 */
export function getLastSessionModel(sessionId: string, comboName: string): string | null {
  const db = getDbInstance() as unknown as DbLike;
  const row = db
    .prepare(
      `SELECT model_str
       FROM session_model_history
       WHERE session_id = ? AND combo_name = ?
       ORDER BY used_at DESC, id DESC
       LIMIT 1`
    )
    .get(sessionId, comboName) as { model_str: string } | undefined;

  return row?.model_str ?? null;
}

/**
 * Clear all session model history entries for a given combo name.
 * Called when a combo's model targets are changed to invalidate stale context-cache pins.
 *
 * @param comboName - The combo name whose pins should be cleared.
 * @returns The number of deleted entries.
 */
export function clearSessionModelHistoryForCombo(comboName: string): number {
  const db = getDbInstance() as unknown as DbLike;
  const result = db
    .prepare("DELETE FROM session_model_history WHERE combo_name = ?")
    .run(comboName);
  return result.changes ?? 0;
}

/**
 * Clear the session model history pin for ONE session on a given combo, leaving
 * every other session's pin on that same combo untouched.
 *
 * Unlike clearSessionModelHistoryForCombo() (combo-wide — used when the combo's
 * model targets themselves change and every pin is stale), this is the
 * session-scoped variant used by the consecutive-failure auto-clear path
 * (open-sse/services/combo/failureTracker.ts::recordComboFailure), where only
 * the failing session's pin should be dropped.
 *
 * @param sessionId - The session identifier whose pin should be cleared.
 * @param comboName - The combo name.
 * @returns The number of deleted entries.
 */
export function deleteSessionModelHistory(sessionId: string, comboName: string): number {
  const db = getDbInstance() as unknown as DbLike;
  const result = db
    .prepare("DELETE FROM session_model_history WHERE session_id = ? AND combo_name = ?")
    .run(sessionId, comboName);
  return result.changes ?? 0;
}

type JsonRecord = Record<string, unknown>;

export class ComboInvariantError extends Error {}

const FAMILY_PATTERNS: ReadonlyArray<[string, RegExp]> = [
  ["gpt", /^gpt(?:-|$)/i],
  ["claude", /^claude(?:-|$)/i],
  ["gemini", /^gemini(?:-|$)/i],
  ["glm", /^glm(?:-|$)/i],
  ["kimi", /^kimi(?:-|$)/i],
  ["llama", /^llama(?:-|$)/i],
  ["minimax", /^minimax(?:-|$)/i],
  ["mistral", /^(?:mistral|mixtral)(?:-|$)/i],
];

function strings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

function modelFamily(model: string): string | null {
  const bare = model.slice(model.lastIndexOf("/") + 1);
  return FAMILY_PATTERNS.find(([, pattern]) => pattern.test(bare))?.[0] ?? null;
}

export function validateComboInvariant(combo: JsonRecord): void {
  const invariant =
    combo.invariant && typeof combo.invariant === "object" && !Array.isArray(combo.invariant)
      ? (combo.invariant as JsonRecord)
      : {};
  const providers = new Set([
    ...strings(combo.allowedProviders),
    ...strings(invariant.allowedProviders),
  ]);
  const families = new Set([
    ...strings(combo.allowedModelFamilies),
    ...strings(invariant.allowedModelFamilies),
  ]);
  if (providers.size === 0 && families.size === 0) return;

  const targets = Array.isArray(combo.models) ? combo.models : [];
  targets.forEach((value, index) => {
    if (!value || typeof value !== "object" || Array.isArray(value)) return;
    const target = value as JsonRecord;
    if (target.kind === "combo-ref") return;
    const model = typeof target.model === "string" ? target.model : "";
    const provider =
      typeof target.providerId === "string"
        ? target.providerId
        : typeof target.provider === "string"
          ? target.provider
          : model.includes("/")
            ? model.slice(0, model.indexOf("/"))
            : "";
    const family = modelFamily(model);
    if (
      (providers.size > 0 && !providers.has(provider)) ||
      (families.size > 0 && (!family || !families.has(family)))
    ) {
      const targetName = model.includes("/") ? model : `${provider}/${model}`;
      throw new ComboInvariantError(
        `Combo "${String(combo.name ?? "unnamed")}" target ${index + 1} (${targetName}) violates its invariant`
      );
    }
  });
}

export {
  getResolvedModelCapabilities,
  supportsReasoning,
  supportsToolCalling,
} from "../../src/lib/modelCapabilities.ts";

/**
 * Role Normalizer — Converts message roles for provider compatibility.
 *
 * Fixes Issues:
 * 1. GLM/ZhipuAI rejects `system` role → merged into first `user` message
 * 2. OpenAI `developer` role not understood by non-OpenAI providers → normalized to `system`
 * 3. Some providers don't support `system` role at all → prepended to user message
 *
 * Provider capability matrix is defined here rather than in the registry to
 * avoid breaking changes to the existing RegistryEntry interface.
 */

// ── Provider capabilities ──────────────────────────────────────────────────

/**
 * Providers that do NOT support the `system` role in messages.
 * For these, system messages are merged into the first user message.
 *
 * Note: This applies only to OpenAI-format passthrough providers.
 * Claude and Gemini have their own system message handling in dedicated translators.
 */
const PROVIDERS_WITHOUT_SYSTEM_ROLE = new Set([
  // Known to reject system role (from troubleshooting report)
  // GLM uses Claude format, so this is handled through claude translator
  // But if accessed through OpenAI-format providers like nvidia, it needs this:
]);

/**
 * Providers known to natively accept the OpenAI `developer` role.
 * Issue #2281: When the upstream provider is OpenAI-compatible but NOT in
 * this allowlist (DeepSeek, MiniMax, Mimo, GLM, etc.), the default behavior
 * maps `developer` → `system`. Without this, requests from Codex/Responses
 * API clients fail with "unknown variant `developer`" 400 errors.
 *
 * Operators can still force preservation per-model via the dashboard
 * "Compatibility → preserveOpenAIDeveloperRole = true" toggle.
 */
const PROVIDERS_PRESERVING_DEVELOPER_ROLE = new Set(["openai", "azure-openai", "azure", "github"]);

function defaultPreserveDeveloperForProvider(provider: string): boolean {
  const id = provider.trim().toLowerCase();
  if (!id) return false;
  if (PROVIDERS_PRESERVING_DEVELOPER_ROLE.has(id)) return true;
  // Treat any provider id containing "openai" as OpenAI-compatible enough
  // to preserve developer role by default (e.g. "azure-openai-gov").
  if (id.includes("openai")) return true;
  return false;
}

/**
 * Models that are known to reject the `system` role regardless of provider.
 * Uses prefix matching (e.g., "ernie-" matches "ernie-4.0").
 */
const MODELS_WITHOUT_SYSTEM_ROLE = [
  "ernie-", // Baidu ERNIE models
];

/**
 * ZhipuAI GLM rejects the `system` role EXCEPT generation > 5.0: per z.ai docs,
 * GLM 5.1 / 5.2 (and newer) accept it, so their system prompt must NOT be folded
 * into the first user turn (#5610). Everything else GLM — bare "glm" (Pollinations),
 * the 4.x family, and the 5.0 generation — still needs the fold. The version is read
 * from "glm-<major>.<minor>" or the Fireworks "glm-5p1" point alias.
 */
function isGlmWithoutSystemRole(modelLower: string): boolean {
  if (!modelLower.startsWith("glm")) return false;
  const match = modelLower.match(/glm-?(\d+)(?:[.p](\d+))?/);
  if (match) {
    const major = Number(match[1]);
    const minor = match[2] ? Number(match[2]) : 0;
    if (major > 5 || (major === 5 && minor >= 1)) return false;
  }
  return true;
}

const PROVIDER_SCOPED_MODELS_WITHOUT_SYSTEM_ROLE: Record<string, RegExp[]> = {
  // ZenMux exposes Z.AI GLM through OpenAI-compatible model ids such as
  // "z-ai/glm-5.2". Z.AI rejects compressed histories that start with a
  // system summary followed by an assistant/tool bundle, while OpenRouter
  // tolerates the same shape. Treat these vendor-prefixed GLM ids like native
  // GLM so normalizeSystemRole moves system/developer content into a user turn.
  zenmux: [/(?:^|\/)glm(?:-|$)/i],
};

interface MessageContentPart {
  type?: string;
  text?: string;
  [key: string]: unknown;
}

interface NormalizedMessage {
  role?: string;
  content?: unknown;
  [key: string]: unknown;
}

function extractTextFromContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .filter(
      (part): part is MessageContentPart =>
        !!part &&
        typeof part === "object" &&
        "type" in part &&
        (part as MessageContentPart).type === "text"
    )
    .map((part) => (typeof part.text === "string" ? part.text : ""))
    .join("\n");
}

/**
 * Check if a provider+model combo supports the system role.
 */
function supportsSystemRole(provider: string, model: string): boolean {
  const providerLower = (provider || "").trim().toLowerCase();
  if (PROVIDERS_WITHOUT_SYSTEM_ROLE.has(providerLower)) return false;

  const modelLower = (model || "").toLowerCase();

  for (const pattern of PROVIDER_SCOPED_MODELS_WITHOUT_SYSTEM_ROLE[providerLower] ?? []) {
    if (pattern.test(modelLower)) return false;
  }

  if (isGlmWithoutSystemRole(modelLower)) return false;

  for (const prefix of MODELS_WITHOUT_SYSTEM_ROLE) {
    if (modelLower.startsWith(prefix)) return false;
  }

  return true;
}

/**
 * Normalize the `developer` role to `system` when the upstream does not support it.
 * OpenAI Responses API sends `developer`; MiniMax and most OpenAI-compatible gateways
 * only accept system/user/assistant/tool and return "role param error" otherwise.
 *
 * Logic:
 * - When targetFormat !== "openai": always convert developer → system (Claude, Gemini, etc.).
 * - When targetFormat === "openai" && preserveDeveloperRole === false: map to system.
 * - When targetFormat === "openai" && preserveDeveloperRole === true: keep developer.
 * - When targetFormat === "openai" && preserveDeveloperRole === undefined (default):
 *   resolve from {@link defaultPreserveDeveloperForProvider} — preserve only for
 *   the OpenAI-compatible allowlist; map to system for everyone else (#2281).
 *
 * @param messages - Array of messages
 * @param targetFormat - The target format (e.g., "openai", "claude", "gemini")
 * @param preserveDeveloperRole - undefined = provider-driven default; true = always keep; false = always map to system
 * @param provider - Provider id (used when preserveDeveloperRole is undefined)
 */
export function normalizeDeveloperRole(
  messages: NormalizedMessage[] | unknown,
  targetFormat: string,
  preserveDeveloperRole?: boolean,
  provider?: string
): NormalizedMessage[] | unknown {
  if (!Array.isArray(messages)) return messages;

  if (targetFormat === "openai") {
    const effectivePreserve =
      preserveDeveloperRole !== undefined
        ? preserveDeveloperRole
        : defaultPreserveDeveloperForProvider(provider ?? "");
    if (effectivePreserve) return messages;
  }

  return messages.map((msg: NormalizedMessage) => {
    if (!msg || typeof msg !== "object") return msg;
    const role = typeof msg.role === "string" ? msg.role : "";
    if (role.toLowerCase() === "developer") {
      return { ...msg, role: "system" };
    }
    return msg;
  });
}

export function normalizeModelRole(
  messages: NormalizedMessage[] | unknown
): NormalizedMessage[] | unknown {
  if (!Array.isArray(messages)) return messages;

  return messages.map((msg: NormalizedMessage) => {
    if (!msg || typeof msg !== "object") return msg;
    const role = typeof msg.role === "string" ? msg.role : "";
    if (role.toLowerCase() === "model") {
      return { ...msg, role: "assistant" };
    }
    return msg;
  });
}

/**
 * Convert `system` messages to user messages for providers that don't support
 * the system role. The system content is prepended to the first user message
 * with a clear delimiter.
 *
 * @param messages - Array of messages
 * @param provider - Provider name
 * @param model - Model name
 * @returns Modified messages array
 */
export function normalizeSystemRole(
  messages: NormalizedMessage[] | unknown,
  provider: string,
  model: string
): NormalizedMessage[] | unknown {
  if (!Array.isArray(messages) || messages.length === 0) return messages;
  if (supportsSystemRole(provider, model)) return messages;

  // Extract system messages
  const systemMessages = messages.filter(
    (message: NormalizedMessage) => message.role === "system" || message.role === "developer"
  );
  if (systemMessages.length === 0) return messages;

  // Build system content string
  const systemContent = systemMessages
    .map((message: NormalizedMessage) => extractTextFromContent(message.content))
    .filter(Boolean)
    .join("\n\n");

  if (!systemContent) {
    return messages.filter(
      (message: NormalizedMessage) => message.role !== "system" && message.role !== "developer"
    );
  }

  // Remove system messages and merge into first user message
  const nonSystemMessages = messages.filter(
    (message: NormalizedMessage) => message.role !== "system" && message.role !== "developer"
  );

  // Find first user message and prepend system content
  const firstUserIdx = nonSystemMessages.findIndex(
    (message: NormalizedMessage) => message.role === "user"
  );
  if (firstUserIdx >= 0) {
    const userMsg = nonSystemMessages[firstUserIdx];
    const userContent = extractTextFromContent(userMsg.content);

    nonSystemMessages[firstUserIdx] = {
      ...userMsg,
      content: `[System Instructions]\n${systemContent}\n\n[User Message]\n${userContent}`,
    };
  } else {
    // No user message found — insert as a user message at the beginning
    nonSystemMessages.unshift({
      role: "user",
      content: `[System Instructions]\n${systemContent}`,
    });
  }

  return nonSystemMessages;
}

/**
 * Full role normalization pipeline.
 * Call this before sending the request to the provider.
 * Applies developer→system (when needed) then system→user for providers/models that do not support system role.
 *
 * @param messages - Array of messages to normalize (or non-array, returned as-is)
 * @param provider - Provider id for capability lookup (e.g. system role support)
 * @param model - Model id for capability lookup
 * @param targetFormat - Target request format (e.g. "openai", "claude", "gemini"); see {@link normalizeDeveloperRole}
 * @param preserveDeveloperRole - Optional; see {@link normalizeDeveloperRole}. When false, developer role is mapped to system.
 * @returns Normalized messages array, or the original value if messages is not an array
 */
export function normalizeRoles(
  messages: NormalizedMessage[] | unknown,
  provider: string,
  model: string,
  targetFormat: string,
  preserveDeveloperRole?: boolean
): NormalizedMessage[] | unknown {
  if (!Array.isArray(messages)) return messages;

  let result = normalizeModelRole(messages);
  result = normalizeDeveloperRole(result, targetFormat, preserveDeveloperRole, provider);
  result = normalizeSystemRole(result, provider, model);

  return result;
}

import { systemMessageMustBeFirst } from "../../../src/lib/memory/injection.ts";

type Message = { role: string; content: unknown; [key: string]: unknown };

function toTextContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .filter((part): part is { type: string; text?: unknown } => {
        return Boolean(part) && typeof part === "object" && (part as { type?: unknown }).type === "text";
      })
      .map((part) => String(part.text ?? ""))
      .join("\n");
  }
  return "";
}

/**
 * #7293: hoist every `system`-role message onto index 0 for providers that reject a
 * non-first system message (`systemMessageMustBeFirst()` — the single source of truth
 * already used by `src/lib/memory/injection.ts`'s memory-injection half, #6135/PR#6225).
 *
 * `translateRequest()` is the single outbound choke point every request passes through,
 * including same-format (OpenAI→OpenAI) passthrough where none of the format-specific
 * translators run — so a client-injected `system` message landing mid-array (OpenCode /
 * Kilo Code style clients, Discussion #6129) previously reached the upstream untouched.
 *
 * Merge, never drop: multiple offending system messages are folded (in original order)
 * into the single leading system message, mirroring `injectSystemFirst()`'s
 * `${memoryText}\n${first.content}` pattern and `openai-to-claude.ts`'s system-array-merge
 * pattern.
 *
 * No-op (same array reference) whenever the provider is not strict, or the request is
 * already compliant — required for prompt-cache prefix stability (#3890 class).
 */
export function hoistLeadingSystemMessage(
  messages: Message[],
  provider: string | null | undefined
): Message[] {
  if (!Array.isArray(messages) || messages.length === 0) return messages;
  if (!systemMessageMustBeFirst(provider)) return messages;

  const offendingIndices: number[] = [];
  for (let i = 1; i < messages.length; i++) {
    if (messages[i]?.role === "system") offendingIndices.push(i);
  }
  if (offendingIndices.length === 0) return messages;

  const offending = offendingIndices.map((i) => messages[i]);
  const rest = messages.filter((_, i) => !offendingIndices.includes(i));

  const mergedText = [
    rest[0]?.role === "system" ? toTextContent(rest[0].content) : null,
    ...offending.map((m) => toTextContent(m.content)),
  ]
    .filter((text): text is string => Boolean(text))
    .join("\n");

  if (rest[0]?.role === "system") {
    const mergedFirst: Message = { ...rest[0], content: mergedText };
    return [mergedFirst, ...rest.slice(1)];
  }

  const leadingSystem: Message = { role: "system", content: mergedText };
  return [leadingSystem, ...rest];
}

/**
 * Memory Injection — prepend retrieved memories into the request message list.
 *
 * Injection strategy:
 *   1. If the provider supports system messages (most providers), inject as a
 *      leading system message so it takes effect without disrupting user turns.
 *   2. Otherwise (fallback for providers that reject system role), inject as the
 *      first user message prefixed with the memory context label.
 *
 * Format: "Memory context: <content>"
 */

import { Memory } from "./types";
import { logger } from "../../../open-sse/utils/logger.ts";

const log = logger("MEMORY_INJECTION");

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
  name?: string;
}

export interface ChatRequest {
  model: string;
  messages: ChatMessage[];
  system?: string;
  temperature?: number;
  max_tokens?: number;
  stream?: boolean;
  [key: string]: unknown;
}

/**
 * Providers known NOT to support a top-level system-role message.
 * These receive memories injected as the first user message instead.
 */
const PROVIDERS_WITHOUT_SYSTEM_MESSAGE = new Set([
  "o1",
  "o1-mini",
  "o1-preview",
  "glm", // GLM/ZhipuAI rejects system role (#1701)
  "glmt", // GLM Thinking variant
  "glm-cn", // GLM China variant
  "zai", // Z.AI uses same GLM backend
  "qianfan", // Baidu ERNIE rejects system role
]);

/**
 * Returns true when the given provider accepts a system-role message.
 * Falls back to true for unknown/null providers (safe default).
 */
export function providerSupportsSystemMessage(provider: string | null | undefined): boolean {
  if (!provider) return true;
  const normalized = provider.toLowerCase().trim();
  return !PROVIDERS_WITHOUT_SYSTEM_MESSAGE.has(normalized);
}

/**
 * Providers that accept a system-role message ONLY at index 0 (a `system`
 * message at any later position is rejected with HTTP 400). For these, the
 * cache-safe mid-array splice (which inserts memory just before the last user
 * turn) is unsafe in multi-turn conversations, so memory must be merged into /
 * prepended as the leading system message instead. See #6135.
 *
 * Populated with the Xiaomi MiMo endpoint (provider id `xiaomi-mimo`, registry
 * alias `mimo`, serving mimo-v2.5) confirmed live to 400 on a non-first system
 * message. Add other providers here only when they are documented as strict.
 */
const PROVIDERS_SYSTEM_MUST_BE_FIRST = new Set(["xiaomi-mimo", "mimo"]);

/**
 * Returns true when the given provider requires the system message to be first.
 * Falls back to false for unknown/null providers (preserves current behavior).
 */
export function systemMessageMustBeFirst(provider: string | null | undefined): boolean {
  if (!provider) return false;
  const normalized = provider.toLowerCase().trim();
  return PROVIDERS_SYSTEM_MUST_BE_FIRST.has(normalized);
}

/**
 * Format memories into a single labeled context string.
 * Format: "Memory context: <content1>\n<content2>..."
 */
export function formatMemoryContext(memories: Memory[]): string {
  if (!memories || memories.length === 0) return "";

  const content = memories
    .map((m) => m.content.trim())
    .filter(Boolean)
    .join("\n");

  return content ? `Memory context: ${content}` : "";
}

/**
 * Inject retrieved memories into the request message array.
 *
 * @param request  - The chat completion request body
 * @param memories - Memories retrieved for the current API key / session
 * @param provider - Provider identifier used to choose injection strategy
 * @returns A new request body with memories prepended to messages
 */
export interface InjectMemoryOptions {
  /**
   * #3890: when the request uses prompt caching (cache_control breakpoints), prepending
   * the memory message at index 0 shifts the entire cacheable prefix — and since the
   * retrieved memories vary per user query, every cache breakpoint then misses on each
   * turn (observed as a sustained cache-miss / cost spike). When `cacheSafe` is set, the
   * memory message is inserted immediately before the LAST user message instead, so the
   * cacheable prefix (system prompt + prior turns) stays byte-stable while memory still
   * contextualizes the current turn.
   */
  cacheSafe?: boolean;
}

/**
 * #6135: place the memory as a leading system message for providers that reject
 * a non-first system role — merging into an existing index-0 system message when
 * present, else prepending. Split out of injectMemory to keep it flat.
 */
function injectSystemFirst(
  request: ChatRequest,
  messages: ChatMessage[],
  memoryText: string,
  count: number
): ChatRequest {
  log.info("memory.injection.injected", { count, strategy: "system-first", model: request.model });
  const first = messages[0];
  if (first && first.role === "system") {
    const merged: ChatMessage = { ...first, content: `${memoryText}\n${first.content}` };
    return { ...request, messages: [merged, ...messages.slice(1)] };
  }
  const memorySystemMessage: ChatMessage = { role: "system", content: memoryText };
  return { ...request, messages: [memorySystemMessage, ...messages] };
}

/**
 * Place a memory message at the #3890 cache-safe anchor (just before the last
 * user turn) when one exists, else prepend it. Shared by the system and user
 * injection strategies to keep injectMemory flat.
 */
function placeMessage(
  request: ChatRequest,
  messages: ChatMessage[],
  msg: ChatMessage,
  cacheSafeIndex: number
): ChatRequest {
  if (cacheSafeIndex >= 0) {
    const next = [...messages];
    next.splice(cacheSafeIndex, 0, msg);
    return { ...request, messages: next };
  }
  return { ...request, messages: [msg, ...messages] };
}

export function injectMemory(
  request: ChatRequest,
  memories: Memory[],
  provider: string | null | undefined,
  options: InjectMemoryOptions = {}
): ChatRequest {
  if (!memories || memories.length === 0) {
    log.info("memory.injection.skipped", { reason: "no_memories", model: request.model });
    return request;
  }

  const memoryText = formatMemoryContext(memories);
  if (!memoryText) {
    log.info("memory.injection.skipped", { reason: "empty_context", model: request.model });
    return request;
  }

  const messages: ChatMessage[] = Array.isArray(request.messages) ? [...request.messages] : [];

  // #3890: in a caching context, anchor the injection just before the LAST user message so
  // the cacheable prefix (system prompt + prior turns) is preserved byte-for-byte. Falls
  // back to a leading message when caching is off or there is no user turn to anchor on.
  const cacheSafeIndex = options.cacheSafe ? messages.findLastIndex((m) => m.role === "user") : -1;

  const supportsSystem = providerSupportsSystemMessage(provider);

  // #6135: strict providers reject a system message at a non-zero index. Never
  // apply the cache-safe mid-array splice for these — keep the system message
  // first (extracted to injectSystemFirst to keep this function flat).
  if (supportsSystem && systemMessageMustBeFirst(provider)) {
    return injectSystemFirst(request, messages, memoryText, memories.length);
  }

  // Strategy 1 (system): prepend before existing system messages, preserving the
  // caller's own instructions. Strategy 2 (user, e.g. o1-mini): inject as a user
  // message. Both honor the #3890 cache-safe anchor via placeMessage.
  const role: ChatMessage["role"] = supportsSystem ? "system" : "user";
  const memoryMessage: ChatMessage = { role, content: memoryText };
  const base = supportsSystem ? "system" : "user";
  log.info("memory.injection.injected", {
    count: memories.length,
    strategy: cacheSafeIndex >= 0 ? `${base}-cache-safe` : base,
    model: request.model,
  });
  return placeMessage(request, messages, memoryMessage, cacheSafeIndex);
}

/**
 * Returns true when memory injection should be attempted for this request.
 */
export function shouldInjectMemory(request: ChatRequest, config?: { enabled?: boolean }): boolean {
  if (config?.enabled === false) return false;
  return Array.isArray(request.messages) && request.messages.length > 0;
}

/**
 * Structured console logger utility for omniroute.
 *
 * Provides consistent, machine-parseable log output across the codebase.
 * Supports two output formats controlled by APP_LOG_FORMAT env var:
 *   - "text" (default): [LEVEL] [TAG] message {metadata}
 *   - "json": Single-line JSON objects for log aggregators
 *
 * Usage:
 *   import { logger, createLogger, generateRequestId } from "../utils/logger.ts";
 *
 *   // Tag-based (simple — for services/utilities):
 *   const log = logger("CHAT");
 *   log.info("Request received", { model: "claude-4" });
 *
 *   // Request-scoped (with correlation ID — for request pipelines):
 *   const reqLog = createLogger(generateRequestId());
 *   reqLog.info("AUTH", "Token refreshed", { provider: "claude" });
 *
 * Environment variables:
 *   APP_LOG_LEVEL  — minimum level: debug | info | warn | error (default: info)
 *   APP_LOG_FORMAT — output format: text | json (default: text)
 */
import { getAppLogFormat, getAppLogLevel } from "../../src/lib/logEnv";

const LEVELS = { debug: 0, info: 1, warn: 2, error: 3 } as const;

type LogLevel = keyof typeof LEVELS;
type LogMetadata = Record<string, unknown>;
type ConsoleFn = (...data: unknown[]) => void;

type TaggedLogger = {
  debug: (message: string, meta?: LogMetadata | null) => void;
  info: (message: string, meta?: LogMetadata | null) => void;
  warn: (message: string, meta?: LogMetadata | null) => void;
  error: (message: string, meta?: LogMetadata | null) => void;
};

type RequestScopedLogger = {
  debug: (tag: string, msg: string, data?: LogMetadata | null) => void;
  info: (tag: string, msg: string, data?: LogMetadata | null) => void;
  warn: (tag: string, msg: string, data?: LogMetadata | null) => void;
  error: (tag: string, msg: string, data?: LogMetadata | null) => void;
};

function isLogLevel(value: string): value is LogLevel {
  return Object.prototype.hasOwnProperty.call(LEVELS, value);
}

const configuredLevel = getAppLogLevel("info").toLowerCase();
const currentLevel = isLogLevel(configuredLevel) ? LEVELS[configuredLevel] : LEVELS.info;

const jsonFormat = getAppLogFormat("text") === "json";

let requestCounter = 0;

/**
 * Generate a unique request ID for log correlation.
 * Format: req_<timestamp>_<counter>
 * @returns {string}
 */
export function generateRequestId() {
  return `req_${Date.now()}_${++requestCounter}`;
}

/**
 * Mask a sensitive key for safe logging.
 * Shows first 6 and last 4 characters: "sk-abc123...xyz9"
 * @param {string} key
 * @returns {string}
 */
export function maskKey(key: string | null | undefined): string {
  if (!key || key.length < 12) return "(redacted)";
  return `${key.slice(0, 6)}...${key.slice(-4)}`;
}

/**
 * Get the correct console method for a log level.
 * @param {string} level
 * @returns {Function}
 */
function getConsoleFn(level: LogLevel): ConsoleFn {
  switch (level) {
    case "debug":
      return console.debug;
    case "warn":
      return console.warn;
    case "error":
      return console.error;
    default:
      return console.log;
  }
}

/**
 * Format metadata object as compact JSON string for log output.
 * Omits keys with null/undefined values to keep logs clean.
 * @param {object} [meta] - Optional metadata
 * @returns {string} Formatted metadata string or empty string
 */
function formatMeta(meta?: LogMetadata | null): string {
  if (!meta || typeof meta !== "object") return "";
  const cleaned: LogMetadata = {};
  for (const [k, v] of Object.entries(meta)) {
    if (v !== undefined && v !== null) cleaned[k] = v;
  }
  return Object.keys(cleaned).length > 0 ? ` ${JSON.stringify(cleaned)}` : "";
}

/**
 * Create a tagged logger instance (simple API for services and utilities).
 * @param {string} tag - Log category tag (e.g. "CHAT", "AUTH", "STREAM")
 * @returns {{ debug: Function, info: Function, warn: Function, error: Function }}
 */
export function logger(tag: string): TaggedLogger {
  const emit = (level: LogLevel, message: string, meta?: LogMetadata | null): void => {
    if (LEVELS[level] < currentLevel) return;
    const consoleFn = getConsoleFn(level);

    if (jsonFormat) {
      const entry: Record<string, unknown> = {
        ts: new Date().toISOString(),
        level,
        tag,
        msg: message,
      };
      if (meta && typeof meta === "object" && Object.keys(meta).length > 0) {
        entry.data = meta;
      }
      consoleFn(JSON.stringify(entry));
    } else {
      consoleFn(`[${level.toUpperCase()}] [${tag}] ${message}${formatMeta(meta)}`);
    }
  };

  return {
    debug: (message, meta) => emit("debug", message, meta),
    info: (message, meta) => emit("info", message, meta),
    warn: (message, meta) => emit("warn", message, meta),
    error: (message, meta) => emit("error", message, meta),
  };
}

/**
 * Create a request-scoped logger with correlation ID.
 * All methods accept (tag, message, data?) for structured logging.
 *
 * @param {string} [requestId] - Unique request ID for correlation
 * @returns {{ debug, info, warn, error }}
 */
export function createLogger(requestId: string | null = null): RequestScopedLogger {
  const emit = (level: LogLevel, tag: string, message: string, data?: LogMetadata | null): void => {
    if (LEVELS[level] < currentLevel) return;
    const consoleFn = getConsoleFn(level);

    if (jsonFormat) {
      const entry: Record<string, unknown> = {
        ts: new Date().toISOString(),
        level,
        tag,
        msg: message,
      };
      if (requestId) entry.reqId = requestId;
      if (data && typeof data === "object" && Object.keys(data).length > 0) {
        entry.data = data;
      }
      consoleFn(JSON.stringify(entry));
    } else {
      const ts = new Date().toISOString().slice(11, 23); // HH:MM:SS.mmm
      const prefix = requestId ? `[${requestId}]` : "";
      const dataStr = formatMeta(data);
      consoleFn(`${ts} ${prefix}[${tag}] ${message}${dataStr}`);
    }
  };

  return {
    debug: (tag, msg, data) => emit("debug", tag, msg, data),
    info: (tag, msg, data) => emit("info", tag, msg, data),
    warn: (tag, msg, data) => emit("warn", tag, msg, data),
    error: (tag, msg, data) => emit("error", tag, msg, data),
  };
}

/**
 * Module-level default logger (no requestId — for startup/config messages).
 */
export const defaultLogger = createLogger();
export const log = defaultLogger;

export default logger;

