/**
 * User-facing messages for upstream ChatGPT-web HTTP error statuses.
 *
 * Pure mapping with no side effects so it can be unit-tested in isolation — the
 * caller owns any state mutation (e.g. clearing the token cache on 401/403).
 * Unmapped statuses fall back to the generic `ChatGPT returned HTTP <status>`.
 */
const CGPT_WEB_HTTP_ERROR_MESSAGES: Record<number, string> = {
  401: "ChatGPT auth failed — session may have expired. Re-paste your __Secure-next-auth.session-token.",
  403: "ChatGPT auth failed — session may have expired. Re-paste your __Secure-next-auth.session-token.",
  404: "ChatGPT returned 404 — usually the model is no longer available on this account or the chat-requirements-token expired. Retry will start a fresh conversation.",
  413: "ChatGPT returned 413 — the request payload is too large for ChatGPT web's size limit (often hit by agentic clients like Cline/Kilo that send big system prompts and file context). Reduce the context: enable compression, trim the conversation/files, or use a smaller request.",
  429: "ChatGPT rate limited. Wait a moment and retry.",
};

export function describeChatGptWebHttpError(status: number): string {
  return CGPT_WEB_HTTP_ERROR_MESSAGES[status] ?? `ChatGPT returned HTTP ${status}`;
}

// Runtime-portable SHA3-512 (FIPS-202).
//
// The ChatGPT-Web sentinel proof-of-work (open-sse/executors/chatgpt-web.ts)
// hashes with SHA3-512. Node built against OpenSSL has it natively, but the
// **Electron desktop app** ships Node built against **BoringSSL, which does not
// implement the SHA-3 family** (electron/electron#30530). There,
// `createHash("sha3-512")` throws `Error: Digest method not supported`, so every
// chatgpt-web request fails with `502 ChatGPT sentinel failed: Digest method not
// supported` and the provider is unusable on the desktop app (#5531).
//
// This module prefers the native digest (fast path on servers / OpenSSL) and
// transparently falls back to a dependency-free pure-JS Keccak-f[1600] when the
// runtime's crypto lacks SHA-3. The pure-JS path is validated bit-for-bit
// against the native digest and the published FIPS-202 vectors in the unit test.

import { createHash } from "node:crypto";

// ─── Keccak-f[1600] (BigInt lanes — correctness-first; only the fallback runs it) ──

const MASK = (1n << 64n) - 1n;

// Round constants RC[0..23].
const RC: bigint[] = [
  0x0000000000000001n,
  0x0000000000008082n,
  0x800000000000808an,
  0x8000000080008000n,
  0x000000000000808bn,
  0x0000000080000001n,
  0x8000000080008081n,
  0x8000000000008009n,
  0x000000000000008an,
  0x0000000000000088n,
  0x0000000080008009n,
  0x000000008000000an,
  0x000000008000808bn,
  0x800000000000008bn,
  0x8000000000008089n,
  0x8000000000008003n,
  0x8000000000008002n,
  0x8000000000000080n,
  0x000000000000800an,
  0x800000008000000an,
  0x8000000080008081n,
  0x8000000000008080n,
  0x0000000080000001n,
  0x8000000080008008n,
];

// Rotation offsets r[x+5y] (rho step).
const ROT: number[] = [
  0, 1, 62, 28, 27, 36, 44, 6, 55, 20, 3, 10, 43, 25, 39, 41, 45, 15, 21, 8, 18, 2, 61, 56, 14,
];

function rotl64(x: bigint, n: number): bigint {
  if (n === 0) return x;
  const bn = BigInt(n);
  return ((x << bn) | (x >> (64n - bn))) & MASK;
}

function keccakF1600(s: bigint[]): void {
  const C = new Array<bigint>(5);
  const D = new Array<bigint>(5);
  const B = new Array<bigint>(25);
  for (let round = 0; round < 24; round++) {
    // θ
    for (let x = 0; x < 5; x++) C[x] = s[x] ^ s[x + 5] ^ s[x + 10] ^ s[x + 15] ^ s[x + 20];
    for (let x = 0; x < 5; x++) D[x] = C[(x + 4) % 5] ^ rotl64(C[(x + 1) % 5], 1);
    for (let x = 0; x < 5; x++) for (let y = 0; y < 5; y++) s[x + 5 * y] ^= D[x];
    // ρ + π
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        B[y + 5 * ((2 * x + 3 * y) % 5)] = rotl64(s[x + 5 * y], ROT[x + 5 * y]);
      }
    }
    // χ
    for (let x = 0; x < 5; x++) {
      for (let y = 0; y < 5; y++) {
        s[x + 5 * y] = B[x + 5 * y] ^ (~B[((x + 1) % 5) + 5 * y] & MASK & B[((x + 2) % 5) + 5 * y]);
      }
    }
    // ι
    s[0] ^= RC[round];
  }
}

// SHA3-512: rate r = 576 bits (72 bytes / 9 lanes), capacity 1024, output 64 bytes.
const RATE_BYTES = 72;

function sha3_512Bytes(msg: Uint8Array): Uint8Array {
  const s: bigint[] = new Array<bigint>(25).fill(0n);

  // FIPS-202 pad10*1 with SHA-3 domain separation (first pad byte 0x06, last |= 0x80).
  const padLen = RATE_BYTES - (msg.length % RATE_BYTES);
  const padded = new Uint8Array(msg.length + padLen);
  padded.set(msg);
  padded[msg.length] = 0x06;
  padded[padded.length - 1] |= 0x80;

  // Absorb (little-endian lanes).
  for (let off = 0; off < padded.length; off += RATE_BYTES) {
    for (let i = 0; i < RATE_BYTES / 8; i++) {
      let lane = 0n;
      for (let b = 0; b < 8; b++) lane |= BigInt(padded[off + i * 8 + b]) << BigInt(8 * b);
      s[i] ^= lane;
    }
    keccakF1600(s);
  }

  // Squeeze 64 bytes (8 lanes — fits in one rate block).
  const out = new Uint8Array(64);
  for (let i = 0; i < 8; i++) {
    const lane = s[i];
    for (let b = 0; b < 8; b++) out[i * 8 + b] = Number((lane >> BigInt(8 * b)) & 0xffn);
  }
  return out;
}

function toBytes(input: string | Uint8Array): Uint8Array {
  return typeof input === "string" ? new Uint8Array(Buffer.from(input, "utf8")) : input;
}

/** Pure-JS SHA3-512 hex digest. Always runs the vendored Keccak (used as the fallback). */
export function sha3_512HexJs(input: string | Uint8Array): string {
  return Buffer.from(sha3_512Bytes(toBytes(input))).toString("hex");
}

type NativeHasher = (data: Uint8Array) => string;

// undefined = not yet probed; null = native SHA-3 unavailable (BoringSSL/Electron).
let nativeHasher: NativeHasher | null | undefined;

function detectNative(): NativeHasher | null {
  try {
    // Construct + digest once — Electron/BoringSSL throws here, not lazily.
    createHash("sha3-512").update(Buffer.alloc(0)).digest("hex");
    return (data) => createHash("sha3-512").update(data).digest("hex");
  } catch {
    return null;
  }
}

/**
 * SHA3-512 hex digest that works on every runtime: native (OpenSSL) where
 * available, pure-JS Keccak fallback where the crypto backend lacks SHA-3
 * (Electron/BoringSSL — #5531). Capability is probed once and cached.
 */
export function sha3_512Hex(input: string | Uint8Array): string {
  const data = toBytes(input);
  if (nativeHasher === undefined) nativeHasher = detectNative();
  if (nativeHasher) {
    try {
      return nativeHasher(data);
    } catch {
      nativeHasher = null; // became unavailable mid-flight — defensive
    }
  }
  return sha3_512HexJs(data);
}

/** Test seam: force the native capability state (null = simulate BoringSSL, undefined = re-probe). */
export function __setSha3NativeForTesting(state: NativeHasher | null | undefined): void {
  nativeHasher = state;
}

/**
 * Browser-TLS-impersonating HTTP client for chatgpt.com.
 *
 * Why this exists: ChatGPT's Cloudflare config pins `cf_clearance` to the
 * client's TLS fingerprint (JA3/JA4) + HTTP/2 SETTINGS frame ordering.
 * Node's Undici fetch presents an obvious "not a browser" handshake and
 * gets challenged with `cf-mitigated: challenge` — even with all the right
 * cookies. This module wraps `tls-client-node` (native shared library
 * built from bogdanfinn/tls-client) to send a Firefox handshake instead.
 *
 * The first call lazily starts the managed sidecar; subsequent calls reuse
 * a singleton TLSClient. Process exit hooks stop the sidecar cleanly.
 */

import { tmpdir } from "node:os";
import { join } from "node:path";
import { mkdtemp, open, unlink, rmdir, stat, readFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { buildNativeTlsClientOptions } from "./tlsClientDownloadDir.ts";

let clientPromise: Promise<unknown> | null = null;
let exitHookInstalled = false;

const CHATGPT_PROFILE = "firefox_148"; // matches the Firefox 148 UA we send
const DEFAULT_TIMEOUT_MS =
  Number.parseInt(process.env.OMNIROUTE_CHATGPT_TLS_TIMEOUT_MS || "", 10) || 60_000;
// Grace period added to the binding's wire-level timeout before our JS-level
// hard timeout fires. Under healthy operation `tls-client-node` honors
// `timeoutMilliseconds` and rejects on its own; the JS-level race only wins
// when the koffi-loaded native library is wedged (which the binding's own
// timer can't escape). Keep the grace small so users don't wait noticeably
// longer than the configured timeout when the binding is dead.
const HARD_TIMEOUT_GRACE_MS =
  Number.parseInt(process.env.OMNIROUTE_CHATGPT_TLS_GRACE_MS || "", 10) || 10_000;
const STREAM_FIRST_BYTE_TIMEOUT_MS =
  Number.parseInt(process.env.OMNIROUTE_CHATGPT_STREAM_FIRST_BYTE_TIMEOUT_MS || "", 10) || 30_000;

function installExitHook(): void {
  if (exitHookInstalled) return;
  exitHookInstalled = true;
  const stop = async () => {
    if (!clientPromise) return;
    try {
      const c = (await clientPromise) as { stop?: () => Promise<unknown> };
      await c.stop?.();
    } catch {
      // ignore
    }
  };
  process.once("beforeExit", stop);
  process.once("SIGINT", () => {
    void stop();
  });
  process.once("SIGTERM", () => {
    void stop();
  });
}

/**
 * Drop the cached client so the next `getClient()` call respawns it. Called
 * when a request observes the native binding has wedged — releasing the
 * reference lets a fresh TLSClient (and a fresh koffi load) take over without
 * a process restart.
 */
function resetClientCache(): void {
  clientPromise = null;
}

export class TlsClientHangError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TlsClientHangError";
  }
}

/**
 * Race a `client.request()` promise against (a) a JS-level hard timeout and
 * (b) the caller's abort signal. The native binding's `timeoutMilliseconds`
 * already covers the wire path; this guards the case where the koffi binding
 * itself deadlocks (observed after sustained load), where neither the
 * binding's own timer nor a post-call `signal.aborted` re-check can recover.
 */
async function raceWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  signal: AbortSignal | null | undefined
): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let abortListener: (() => void) | null = null;
  try {
    const racers: Promise<T>[] = [
      promise,
      new Promise<T>((_, reject) => {
        timer = setTimeout(() => {
          reject(
            new TlsClientHangError(
              `tls-client-node call exceeded ${timeoutMs}ms — native binding likely deadlocked`
            )
          );
        }, timeoutMs);
      }),
    ];
    if (signal) {
      racers.push(
        new Promise<T>((_, reject) => {
          if (signal.aborted) {
            reject(makeAbortError(signal));
            return;
          }
          abortListener = () => reject(makeAbortError(signal));
          signal.addEventListener("abort", abortListener, { once: true });
        })
      );
    }
    return await Promise.race(racers);
  } finally {
    if (timer) clearTimeout(timer);
    if (signal && abortListener) signal.removeEventListener("abort", abortListener);
  }
}

async function getClient(): Promise<{
  request: (url: string, opts: Record<string, unknown>) => Promise<TlsResponseLike>;
}> {
  if (!clientPromise) {
    clientPromise = (async () => {
      try {
        const mod = await import("tls-client-node");
        const TLSClient = (mod as { TLSClient: new (opts?: Record<string, unknown>) => unknown })
          .TLSClient;
        // Native mode loads the shared library directly via koffi, avoiding the
        // managed sidecar's localhost HTTP calls that OmniRoute's global fetch
        // proxy patch interferes with.
        const client = new TLSClient(buildNativeTlsClientOptions()) as {
          start: () => Promise<void>;
          request: (url: string, opts: Record<string, unknown>) => Promise<TlsResponseLike>;
        };
        await client.start();

        installExitHook();
        return client;
      } catch (err) {
        clientPromise = null;
        const msg = err instanceof Error ? err.message : String(err);
        throw new TlsClientUnavailableError(
          `TLS impersonation client failed to start: ${msg}. ` +
            `Verify tls-client-node is installed and its native binary downloaded.`
        );
      }
    })();
  }
  return clientPromise as Promise<{
    request: (url: string, opts: Record<string, unknown>) => Promise<TlsResponseLike>;
  }>;
}

interface TlsResponseLike {
  status: number;
  headers: Record<string, string[]>;
  body: string; // for non-streaming requests, the full response body
  cookies?: Record<string, string>;
  text: () => Promise<string>;
  bytes: () => Promise<Uint8Array>;
  json: <T = unknown>() => Promise<T>;
}

export class TlsClientUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TlsClientUnavailableError";
  }
}

export interface TlsFetchOptions {
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
  signal?: AbortSignal | null;
  /**
   * If true, the response body is streamed to a temp file and exposed as a
   * ReadableStream<Uint8Array>. Use for SSE responses (the conversation
   * endpoint). Otherwise, the full body is read into memory.
   */
  stream?: boolean;
  /** EOF marker the upstream sends to signal end of stream (default: "[DONE]"). */
  streamEofSymbol?: string;
  /**
   * If true, instructs the underlying tls-client to return the response body
   * as a base64 `data:<mime>;base64,...` string (so binary payloads survive
   * the JSON marshalling step). Required for image / binary downloads —
   * without it, raw bytes get UTF-8-decoded and any non-ASCII byte is
   * mangled. Default false (text mode).
   */
  byteResponse?: boolean;
  /**
   * Optional upstream proxy URL (`http://user:pass@host:port` or
   * `socks5://...`). When set, the request is tunneled through this proxy
   * before reaching chatgpt.com. Required for hosts whose bare IP is
   * flagged by ChatGPT/Cloudflare (Russia, datacenter ranges, etc.) —
   * without it, every call leaks the host IP and gets edge-rejected with
   * a templated 401 / `Invalid session cookie`.
   *
   * Resolution order:
   *   1. `options.proxyUrl` (per-call override from caller)
   *   2. `process.env.OMNIROUTE_TLS_PROXY_URL` (single-flag opt-in)
   *   3. `process.env.HTTPS_PROXY` / `HTTP_PROXY` / `ALL_PROXY` (POSIX-standard fallback)
   *
   * The native `tls-client-node` binding does **not** consult Go's
   * `http.ProxyFromEnvironment`, so the env vars need to be plumbed in
   * here at the JS layer. The dashboard's global-fetch monkey-patch only
   * reaches Node's undici, not the koffi-loaded shared library used here.
   */
  proxyUrl?: string;
}

import { resolveProxyForRequest } from "../utils/proxyFetch.ts";
import { resolveTlsClientProxyUrl } from "./tlsClientProxy.ts";

/**
 * Resolve the proxy URL for a tls-client request. Per-call value wins;
 * otherwise we use the standard proxy fetch resolution which reads from
 * the dashboard AsyncLocalStorage context or falls back to env vars.
 *
 * Fail-closed: if resolution throws (e.g. a configured socks5 proxy with
 * ENABLE_SOCKS5_PROXY=false), this rethrows rather than returning undefined —
 * undefined would let the native binding connect directly and leak the real IP.
 */
function resolveProxyUrl(perCall: string | undefined): string | undefined {
  return resolveTlsClientProxyUrl("https://chatgpt.com", perCall, resolveProxyForRequest);
}

export interface TlsFetchResult {
  status: number;
  headers: Headers;
  /** Full response body as text — only populated for non-streaming requests. */
  text: string | null;
  /** Streaming body — only populated when options.stream === true. */
  body: ReadableStream<Uint8Array> | null;
}

// Test-only injection point. Tests call __setTlsFetchOverrideForTesting()
// to replace the real TLS client with a mock; production never touches this.
let testOverride: ((url: string, options: TlsFetchOptions) => Promise<TlsFetchResult>) | null =
  null;

export function __setTlsFetchOverrideForTesting(fn: typeof testOverride): void {
  testOverride = fn;
}

/**
 * Make a single HTTP request to chatgpt.com with a Firefox-like TLS fingerprint.
 *
 * Throws TlsClientUnavailableError if the native binary failed to load.
 */
export async function tlsFetchChatGpt(
  url: string,
  options: TlsFetchOptions = {}
): Promise<TlsFetchResult> {
  if (testOverride) return testOverride(url, options);
  // Honor abort signals up-front. tls-client-node's koffi binding doesn't
  // accept an AbortSignal mid-flight (the binary call is opaque), so the best
  // we can do is bail before issuing the call. We also re-check after — if
  // the caller aborted while the upstream was running, throw rather than
  // returning a stale response so the caller doesn't try to use it.
  if (options.signal?.aborted) {
    throw makeAbortError(options.signal);
  }
  const client = await getClient();
  if (options.signal?.aborted) {
    throw makeAbortError(options.signal);
  }

  const requestOptions: Record<string, unknown> = {
    method: options.method || "GET",
    headers: options.headers || {},
    body: options.body,
    tlsClientIdentifier: CHATGPT_PROFILE,
    timeoutMilliseconds: options.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    followRedirects: true,
    withRandomTLSExtensionOrder: true,
    isByteResponse: options.byteResponse === true,
    // Plumb the configured proxy through to the native binding. tls-client-node
    // consults `proxyUrl` in the per-call options (it does NOT auto-pick up
    // HTTP_PROXY / HTTPS_PROXY env), so callers / env have to be threaded in
    // explicitly. See `resolveProxyUrl()` for the lookup order. Without this
    // line, every chatgpt-web call egresses with the bare host IP regardless
    // of dashboard proxy config — see #2022.
    proxyUrl: resolveProxyUrl(options.proxyUrl),
  };

  if (options.stream) {
    return await tlsFetchStreaming(
      client,
      url,
      requestOptions,
      options.streamEofSymbol,
      options.signal ?? null,
      (options.timeoutMs ?? DEFAULT_TIMEOUT_MS) + HARD_TIMEOUT_GRACE_MS,
      STREAM_FIRST_BYTE_TIMEOUT_MS
    );
  }

  let tlsResponse: TlsResponseLike;
  try {
    tlsResponse = await raceWithTimeout(
      client.request(url, requestOptions),
      (options.timeoutMs ?? DEFAULT_TIMEOUT_MS) + HARD_TIMEOUT_GRACE_MS,
      options.signal ?? null
    );
  } catch (err) {
    if (err instanceof TlsClientHangError) {
      // The native binding is wedged — drop the singleton so the next
      // request respawns a fresh client (and a fresh koffi load).
      resetClientCache();
    }
    throw err;
  }
  if (options.signal?.aborted) {
    throw makeAbortError(options.signal);
  }
  return {
    status: tlsResponse.status,
    headers: toHeaders(tlsResponse.headers),
    text: tlsResponse.body,
    body: null,
  };
}

function makeAbortError(signal: AbortSignal): Error {
  const reason = signal.reason;
  if (reason instanceof Error) return reason;
  const err = new Error(typeof reason === "string" ? reason : "The operation was aborted");
  err.name = "AbortError";
  return err;
}

function toHeaders(raw: Record<string, string[]>): Headers {
  const h = new Headers();
  for (const [k, vs] of Object.entries(raw || {})) {
    for (const v of vs) h.append(k, v);
  }
  return h;
}

// ─── Streaming via temp file ────────────────────────────────────────────────
// tls-client-node's streaming primitive writes the response body chunk-by-chunk
// to a file path, terminating when the upstream sends `streamOutputEOFSymbol`.
// We tail the file from a worker and surface the bytes as a ReadableStream.

async function tlsFetchStreaming(
  client: { request: (url: string, opts: Record<string, unknown>) => Promise<TlsResponseLike> },
  url: string,
  requestOptions: Record<string, unknown>,
  eofSymbol = "[DONE]",
  signal: AbortSignal | null = null,
  hardTimeoutMs: number = DEFAULT_TIMEOUT_MS + HARD_TIMEOUT_GRACE_MS,
  firstByteTimeoutMs: number = STREAM_FIRST_BYTE_TIMEOUT_MS
): Promise<TlsFetchResult> {
  const dir = await mkdtemp(join(tmpdir(), "cgpt-stream-"));
  const path = join(dir, `${randomUUID()}.sse`);

  const streamOpts = {
    ...requestOptions,
    streamOutputPath: path,
    streamOutputBlockSize: 1024,
    streamOutputEOFSymbol: eofSymbol,
  };

  // Kick off the request without awaiting — tls-client writes the body to
  // `path` chunk-by-chunk while the call runs. The Promise resolves when the
  // request fully completes (full body written). Wrapping in raceWithTimeout
  // guarantees this promise eventually settles even if the koffi binding
  // wedges; on hang we reset the singleton so the next request respawns.
  let resetOnHang = true;
  const requestPromise = raceWithTimeout(
    client.request(url, streamOpts),
    hardTimeoutMs,
    signal
  ).catch((err: unknown) => {
    if (resetOnHang && err instanceof TlsClientHangError) {
      resetClientCache();
      resetOnHang = false;
    }
    // Re-throw so downstream consumers (waitForContent, tailFile) observe
    // the rejection and surface it instead of treating the stream as having
    // ended cleanly.
    throw err;
  });

  // Wait for the file to exist AND have at least one byte. tls-client-node
  // creates the output file when the request starts, but the file can be
  // empty for a brief window before the first body chunk lands — peeking
  // during that window would return "" and misclassify the response as
  // non-SSE, dropping us into the buffered-wait branch and silently turning
  // a streaming request into a buffered one. Waiting for content avoids
  // that race; if the request actually fails before producing any bytes,
  // the timeout falls through to the requestPromise drain below (returning
  // the real upstream status).
  const ready = await waitForContent(path, firstByteTimeoutMs, requestPromise);
  if (!ready) {
    const r = await requestPromise.catch(
      (e) => ({ status: 502, headers: {}, body: String(e) }) as TlsResponseLike
    );
    // If the first byte arrived after our first-byte wait but before the
    // request settled, tls-client-node may have written the full SSE body to
    // streamOutputPath while leaving r.body empty. Prefer those captured bytes
    // over misclassifying a successful delayed stream as "empty response body".
    const fileText = await readTextFileIfExists(path);
    await cleanupTempPath(path);
    return {
      status: r.status,
      headers: toHeaders(r.headers),
      text: fileText || r.body,
      body: null,
    };
  }

  // Peek the first bytes to decide whether this looks like SSE. Anything
  // that doesn't positively look like SSE (JSON `{...}`, HTML `<...>`, plain
  // text rate-limit messages, Cloudflare challenge pages, etc.) gets surfaced
  // as a non-streaming response so the executor sees the real upstream status
  // and body — otherwise non-2xx error pages get silently treated as 200 OK
  // and the SSE parser produces an empty completion.
  const peek = await readFirstBytes(path, 256);
  if (!looksLikeSse(peek)) {
    const r = await requestPromise.catch(
      (e) => ({ status: 502, headers: {}, body: String(e) }) as TlsResponseLike
    );
    const fileText = await readTextFileIfExists(path);
    await cleanupTempPath(path);
    return {
      status: r.status,
      headers: toHeaders(r.headers),
      text: r.body || fileText,
      body: null,
    };
  }

  // Looks like SSE — start tailing. SSE bodies in practice are always 2xx;
  // tls-client-node doesn't expose response status separately from full-body
  // completion, so we report 200 and let the SSE parser consume the stream.
  const stream = tailFile(path, eofSymbol, requestPromise, signal);
  const headers = new Headers({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
  });
  return { status: 200, headers, text: null, body: stream };
}

/**
 * Returns true if the peeked response body looks like an SSE stream — i.e.,
 * begins (after any leading whitespace) with one of the SSE field markers
 * (`data:`, `event:`, `id:`, `retry:`) or a comment line (`:`).
 *
 * Exported for tests.
 */
export function looksLikeSse(text: string): boolean {
  const trimmed = text.replace(/^[\s\r\n]+/, "");
  if (!trimmed) return false;
  if (trimmed.startsWith(":")) return true;
  return /^(data|event|id|retry):/i.test(trimmed);
}

async function cleanupTempPath(path: string): Promise<void> {
  await unlink(path).catch(() => {});
  const dir = path.substring(0, path.lastIndexOf("/"));
  await rmdir(dir).catch(() => {});
}

async function readTextFileIfExists(path: string): Promise<string> {
  try {
    return await readFile(path, "utf8");
  } catch {
    return "";
  }
}

export async function __tlsFetchStreamingForTesting(
  client: { request: (url: string, opts: Record<string, unknown>) => Promise<unknown> },
  url: string,
  requestOptions: Record<string, unknown>,
  eofSymbol = "[DONE]",
  signal: AbortSignal | null = null,
  hardTimeoutMs: number = DEFAULT_TIMEOUT_MS + HARD_TIMEOUT_GRACE_MS,
  firstByteTimeoutMs: number = STREAM_FIRST_BYTE_TIMEOUT_MS
): Promise<TlsFetchResult> {
  return tlsFetchStreaming(
    client as { request: (url: string, opts: Record<string, unknown>) => Promise<TlsResponseLike> },
    url,
    requestOptions,
    eofSymbol,
    signal,
    hardTimeoutMs,
    firstByteTimeoutMs
  );
}

async function readFirstBytes(path: string, n: number): Promise<string> {
  const fd = await open(path, "r");
  try {
    const buf = Buffer.alloc(n);
    const { bytesRead } = await fd.read(buf, 0, n, 0);
    return buf.subarray(0, bytesRead).toString("utf8");
  } finally {
    await fd.close().catch(() => {});
  }
}

/**
 * Wait for the streaming output file to exist AND contain at least one byte.
 * Returns false if the request settles before any bytes arrive (so the caller
 * can drain `requestPromise` and surface the real upstream status). Returns
 * true as soon as the file has data — even one byte is enough for the SSE
 * heuristic to give a useful answer.
 */
async function waitForContent(
  path: string,
  timeoutMs: number,
  requestPromise: Promise<TlsResponseLike>
): Promise<boolean> {
  let requestSettled = false;
  requestPromise.then(
    () => {
      requestSettled = true;
    },
    () => {
      requestSettled = true;
    }
  );
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const s = await stat(path);
      if (s.size > 0) return true;
    } catch {
      // file doesn't exist yet
    }
    // If the request finished without producing any bytes, no point waiting
    // out the rest of the timeout — let the caller drain it.
    if (requestSettled) return false;
    await sleep(25);
  }
  return false;
}

function tailFile(
  path: string,
  eofSymbol: string,
  done: Promise<TlsResponseLike>,
  signal: AbortSignal | null = null
): ReadableStream<Uint8Array> {
  return new ReadableStream<Uint8Array>({
    async start(controller) {
      const fd = await open(path, "r");
      const buf = Buffer.alloc(64 * 1024);
      let offset = 0;
      let finished = false;
      let aborted = false;
      let upstreamError: Error | null = null;

      // Track request settlement, capturing both fulfillment and rejection.
      // Without the rejection branch, a mid-stream tls-client-node error
      // becomes an unhandledRejection — the stream cleans up silently and
      // the consumer sees what looks like a successful truncated response.
      done.then(
        () => {
          finished = true;
        },
        (err) => {
          upstreamError = err instanceof Error ? err : new Error(String(err));
          finished = true;
        }
      );

      // If the caller aborts, stop tailing immediately.
      const onAbort = () => {
        aborted = true;
      };
      if (signal) {
        if (signal.aborted) aborted = true;
        else signal.addEventListener("abort", onAbort, { once: true });
      }

      let errored = false;
      try {
        while (!aborted) {
          const { bytesRead } = await fd.read(buf, 0, buf.length, offset);
          if (bytesRead > 0) {
            const chunk = buf.subarray(0, bytesRead);
            offset += bytesRead;
            const text = chunk.toString("utf8");
            if (text.includes(eofSymbol)) {
              const cutAt = text.indexOf(eofSymbol) + eofSymbol.length;
              controller.enqueue(new Uint8Array(chunk.subarray(0, cutAt)));
              break;
            }
            controller.enqueue(new Uint8Array(chunk));
          } else if (finished) {
            // No more data and request completed. If the request rejected,
            // surface the error so the consumer doesn't think the stream
            // ended cleanly.
            if (upstreamError) {
              controller.error(upstreamError);
              errored = true;
            }
            break;
          } else {
            await sleep(25);
          }
        }
      } catch (err) {
        controller.error(err);
        errored = true;
      } finally {
        if (signal) signal.removeEventListener("abort", onAbort);
        await fd.close().catch(() => {});
        await unlink(path).catch(() => {});
        const dir = path.substring(0, path.lastIndexOf("/"));
        await rmdir(dir).catch(() => {});
        if (!errored) controller.close();
      }
    },
  });
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * In-memory cache for ChatGPT-generated images so we can serve them via a
 * regular HTTP URL instead of inlining megabytes of base64 into SSE deltas.
 *
 * Why: chatgpt.com's `image_asset_pointer` resolves to a session-signed
 * `estuary/content` URL that 403s for any anonymous client. We have to
 * download the bytes server-side (with the user's session) and re-serve
 * them. Streaming the raw base64 back through SSE works but Open WebUI's
 * progressive markdown renderer displays each chunk as text mid-stream —
 * the user sees ~3 MB of base64 scroll past before the final `)` arrives
 * and the renderer recognizes it as an image. Hosting the image on a
 * regular URL avoids that entirely: we emit a tiny `![image](http://...)`
 * markdown delta and the browser fetches the image normally.
 *
 * The cache is in-memory only, with a short TTL — these URLs are single-use
 * artifacts of one chat turn, not persistent assets. If the user reloads
 * the conversation in a few hours the URLs will 404; that's expected.
 */

import { createHash, randomUUID } from "node:crypto";

interface CachedImage {
  bytes: Buffer;
  mime: string;
  expiresAt: number;
  context?: ChatGptImageConversationContext;
  /** sha256(bytes) — used by /v1/images/edits to correlate an uploaded
   *  image (Open WebUI re-uploads the bytes via multipart) back to the
   *  conversation context we cached when the image was first generated. */
  bytesSha256: string;
}

const cache = new Map<string, CachedImage>();
let cacheBytes = 0;
const DEFAULT_TTL_MS = 30 * 60 * 1000;
const MAX_ENTRIES = 25;
// Per-entry images cap at 8 MB (enforced upstream in the executor) so 10 MB
// covers ~1 large image. The byte cap matters more than entry count: a hot
// loop of 8 MB images would otherwise pin 1.6 GB of RSS before count
// eviction kicked in. Tune via OMNIROUTE_CGPT_WEB_IMAGE_CACHE_MAX_MB.
const DEFAULT_MAX_BYTES = 10 * 1024 * 1024;

function configuredMaxBytes(): number {
  const raw = Number(process.env.OMNIROUTE_CGPT_WEB_IMAGE_CACHE_MAX_MB);
  if (!Number.isFinite(raw) || raw <= 0) return DEFAULT_MAX_BYTES;
  return Math.floor(raw * 1024 * 1024);
}

export interface ChatGptImageConversationContext {
  conversationId: string;
  parentMessageId: string;
}

function deleteEntry(id: string): void {
  const entry = cache.get(id);
  if (!entry) return;
  cacheBytes -= entry.bytes.length;
  cache.delete(id);
}

function evictExpired(now = Date.now()): void {
  for (const [id, entry] of cache) {
    if (now >= entry.expiresAt) deleteEntry(id);
  }
}

function evictUntilWithinLimits(maxBytes: number, incomingBytes: number): void {
  // Drop oldest until both the entry-count and total-byte caps are satisfied.
  // Map iteration is insertion-ordered so the first key is the oldest entry.
  while ((cache.size >= MAX_ENTRIES || cacheBytes + incomingBytes > maxBytes) && cache.size > 0) {
    const firstKey = cache.keys().next().value;
    if (!firstKey) break;
    deleteEntry(firstKey);
  }
}

export function storeChatGptImage(
  bytes: Buffer,
  mime: string,
  ttlMs = DEFAULT_TTL_MS,
  context?: ChatGptImageConversationContext
): string {
  evictExpired();
  evictUntilWithinLimits(configuredMaxBytes(), bytes.length);
  const id = randomUUID().replace(/-/g, "");
  const bytesSha256 = createHash("sha256").update(bytes).digest("hex");
  cache.set(id, {
    bytes,
    mime,
    expiresAt: Date.now() + ttlMs,
    context,
    bytesSha256,
  });
  cacheBytes += bytes.length;
  return id;
}

export function getChatGptImage(id: string): CachedImage | null {
  evictExpired();
  const entry = cache.get(id);
  if (!entry) return null;
  if (Date.now() >= entry.expiresAt) {
    deleteEntry(id);
    return null;
  }
  return entry;
}

export function getChatGptImageConversationContext(
  id: string
): ChatGptImageConversationContext | null {
  return getChatGptImage(id)?.context ?? null;
}

/**
 * Look up a cached entry by sha256(bytes). Used by /v1/images/edits to
 * correlate Open WebUI's re-uploaded image back to the conversation
 * context we cached at generation time, so the executor can continue the
 * saved chatgpt.com conversation node and actually edit the image instead
 * of generating an unrelated one from scratch.
 */
export function findChatGptImageBySha256(hash: string): { id: string; entry: CachedImage } | null {
  evictExpired();
  const target = hash.toLowerCase();
  for (const [id, entry] of cache.entries()) {
    if (entry.bytesSha256 === target) {
      if (Date.now() < entry.expiresAt) return { id, entry };
      deleteEntry(id);
    }
  }
  return null;
}

/** Test-only: clear the cache between tests. */
export function __resetChatGptImageCacheForTesting(): void {
  cache.clear();
  cacheBytes = 0;
}

/** Test-only: peek at current resident-byte total. */
export function __getChatGptImageCacheBytesForTesting(): number {
  return cacheBytes;
}

// Pure model-mapping / thinking-effort resolution for the ChatGPT-web executor.
// Extracted verbatim from chatgpt-web.ts (static maps + pure resolvers, no state).

export const MODEL_MAP: Record<string, string> = {
  // ChatGPT backend slugs are also accepted directly for power users / tests.
  "gpt-5-6-pro": "gpt-5-6-pro",
  "gpt-5-6-thinking": "gpt-5-6-thinking",
  "gpt-5-5-pro": "gpt-5-5-pro",
  "gpt-5-5-pro-extended": "gpt-5-5-pro",
  "gpt-5-5-thinking": "gpt-5-5-thinking",
  "gpt-5-5": "gpt-5-5",
  "gpt-5-3": "gpt-5-3",
  "gpt-5-3-mini": "gpt-5-3-mini",

  // Public OmniRoute dot-form ids exposed by the provider catalog.
  "gpt-5.6-pro": "gpt-5-6-pro",
  "gpt-5.6-thinking": "gpt-5-6-thinking",
  "gpt-5.5-pro": "gpt-5-5-pro",
  "gpt-5.5-pro-extended": "gpt-5-5-pro",
  "gpt-5.5-thinking": "gpt-5-5-thinking",
  "gpt-5.5": "gpt-5-5",
  "gpt-5.3-instant": "gpt-5-3-instant",
  "gpt-5.3": "gpt-5-3",
  "gpt-5.3-mini": "gpt-5-3-mini",
  o3: "o3",
};

export const MODEL_FORCED_EFFORT: Record<string, "standard" | "extended"> = {
  "gpt-5-6-pro": "standard",
  "gpt-5.6-pro": "standard",
  "gpt-5-5-pro": "standard",
  "gpt-5-5-pro-extended": "extended",
  "gpt-5.5-pro": "standard",
  "gpt-5.5-pro-extended": "extended",
};

/** Set of chatgpt.com slugs that the user_last_used_model_config endpoint
 * accepts a `thinking_effort` value for, derived from MODEL_MAP so adding a
 * new thinking entry there automatically extends this set.
 *
 * Derived from MODEL_MAP keys (always dot-form) that contain "thinking" or
 * are the `o3` reasoning model; the values are the chatgpt.com-side slugs. */
export const THINKING_CAPABLE_SLUGS: ReadonlySet<string> = new Set(
  Object.entries(MODEL_MAP)
    .filter(([k]) => k.includes("thinking") || k === "o3")
    .map(([, v]) => v)
);

/** chatgpt.com only exposes the thinking-effort toggle on dedicated thinking
 * models and the o-series. PATCHing for a non-thinking surface is a no-op
 * (the server accepts it but the routing-time read picks the wrong knob).
 *
 * The lookup also catches callers that pass a chatgpt.com slug directly as
 * the `model` field without MODEL_MAP translation. */
export function isThinkingCapableModel(modelId: string, slug: string): boolean {
  return (
    modelId.includes("thinking") ||
    modelId === "o3" ||
    slug.includes("thinking") ||
    THINKING_CAPABLE_SLUGS.has(slug) ||
    THINKING_CAPABLE_SLUGS.has(modelId)
  );
}

/** Map either a chatgpt.com-native value (`standard`/`extended`) or the
 * OpenAI Chat Completions `reasoning_effort` field to the value the
 * `user_last_used_model_config` endpoint expects.
 *
 *   minimal | low | medium | standard  → standard
 *   high    | xhigh | extended         → extended
 *
 * `medium` collapses to `standard` because chatgpt.com only has two levels —
 * there is no separate medium tier on the web product. Returns null for
 * absent/unknown inputs. */
export function normalizeThinkingEffort(input: unknown): "standard" | "extended" | null {
  if (typeof input !== "string") return null;
  const v = input.trim().toLowerCase();
  if (v === "extended" || v === "high" || v === "xhigh") return "extended";
  if (v === "standard" || v === "low" || v === "medium" || v === "minimal") {
    return "standard";
  }
  return null;
}

/** Resolve the requested effort for this turn.
 * Order: `providerSpecificData.thinkingEffort` (raw override, takes
 * `standard`/`extended` directly) > `body.reasoning_effort` (top-level OpenAI
 * Chat Completions field) > `body.reasoning.effort` (Responses-API nesting).
 * Returns null when the caller did not request one. */
export function resolveThinkingEffort(
  body: unknown,
  providerSpecificData: Record<string, unknown> | undefined
): "standard" | "extended" | null {
  if (providerSpecificData && providerSpecificData.thinkingEffort !== undefined) {
    return normalizeThinkingEffort(providerSpecificData.thinkingEffort);
  }
  const b = (body as Record<string, unknown> | null) ?? null;
  if (!b) return null;
  const top = normalizeThinkingEffort(b.reasoning_effort);
  if (top) return top;
  const nested = (b.reasoning as Record<string, unknown> | undefined)?.effort;
  return normalizeThinkingEffort(nested);
}

export interface ResolvedChatGptModel {
  slug: string;
  effort: "standard" | "extended" | null;
  isPro: boolean;
}

export function resolveChatGptModel(
  model: string,
  body: unknown,
  providerSpecificData: Record<string, unknown> | undefined
): ResolvedChatGptModel {
  const slug = MODEL_MAP[model] ?? model;
  const forcedEffort = MODEL_FORCED_EFFORT[model] ?? null;
  const effort = forcedEffort ?? resolveThinkingEffort(body, providerSpecificData);
  const isPro = slug === "gpt-5-6-pro" || slug === "gpt-5-5-pro";
  return { slug, effort, isPro };
}

// Pure ChatGPT-web citation-marker parsing/rendering, extracted verbatim from
// chatgpt-web.ts (no module state — safe to unit test in isolation).
//
// Strip ChatGPT's internal entity/citation markup. The browser renders these
// private-use markers (for example `citeturn0search0`) with metadata from
// `message.metadata.content_references`; API clients need plain Markdown with
// real links instead of raw ChatGPT UI tokens.
//   entity["city","Paris","capital of France"]  →  Paris
//   entity["…","value", …]                       →  value
const ENTITY_RE = /entity\["[^"]*","([^"]*)"[^\]]*\]/g;
const CHATGPT_MARKER_START = "\uE200";
const CHATGPT_MARKER_SEP = "\uE202";
const CHATGPT_MARKER_END = "\uE201";
const CHATGPT_REF_TOKEN_RE = /turn\d+(?:search|product|news|image|webpage)\d+/g;

type ChatGptCitationSource = {
  title: string;
  url: string;
  attribution: string;
};

type ChatGptCitationMention = {
  start?: number;
  end?: number;
  markerText?: string;
  replacement: string;
};

type ChatGptCitationData = {
  sources: ChatGptCitationSource[];
  mentions: ChatGptCitationMention[];
  refTokenToSourceNumber: Map<string, number>;
};

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : null;
}

function asString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null;
}

function asNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function markdownLinkText(value: string): string {
  // Escape the backslash first — otherwise a label ending in (or containing) a
  // backslash leaks past the `[…]` escaping and breaks the generated link, e.g.
  // `[Path C:\](url)` where the trailing `\` escapes the closing bracket.
  return value
    .replace(/\\/g, "\\\\")
    .replace(/\[/g, "\\[")
    .replace(/\]/g, "\\]")
    .replace(/\n/g, " ")
    .trim();
}

function markdownUrl(value: string): string {
  return value.replace(/\(/g, "%28").replace(/\)/g, "%29");
}

function canonicalCitationUrl(value: string): string {
  try {
    const url = new URL(value);
    url.searchParams.delete("utm_source");
    return url.toString();
  } catch {
    return value;
  }
}

function referenceUrls(ref: Record<string, unknown>): string[] {
  const urls: string[] = [];
  for (const key of ["url", "safe_url", "link"]) {
    const url = asString(ref[key]);
    if (url) urls.push(url);
  }
  for (const url of asArray(ref.safe_urls)) {
    if (typeof url === "string" && url.trim()) urls.push(url);
  }
  return [...new Set(urls)];
}

function refTokenFromStructuredRef(ref: Record<string, unknown>): string | null {
  const turn = asNumber(ref.turn_index);
  const refType = asString(ref.ref_type);
  const refIndex = asNumber(ref.ref_index);
  if (turn == null || refIndex == null || !refType) return null;
  return `turn${turn}${refType}${refIndex}`;
}

function mapStructuredRefs(
  refs: unknown,
  sourceNumber: number,
  refTokenToSourceNumber: Map<string, number>
): void {
  for (const refValue of asArray(refs)) {
    const ref = asRecord(refValue);
    if (!ref) continue;
    const token = refTokenFromStructuredRef(ref);
    if (token && !refTokenToSourceNumber.has(token)) {
      refTokenToSourceNumber.set(token, sourceNumber);
    }
  }
}

function formatCitationLinks(numbers: number[], sources: ChatGptCitationSource[]): string {
  return [...new Set(numbers)]
    .sort((a, b) => a - b)
    .map((num) => {
      const source = sources[num - 1];
      return source ? `[${num}](${markdownUrl(source.url)})` : "";
    })
    .filter(Boolean)
    .join("");
}

function urlMarkerLabel(markerText?: string | null): string | null {
  if (!markerText) return null;
  const privateMatch = markerText.match(/\uE200url\uE202([^\uE201\uE202]+)/u);
  if (privateMatch?.[1]) return privateMatch[1].trim();
  const plainMatch = markerText.match(/^url[:\s]+(.+)$/i);
  return plainMatch?.[1]?.trim() || null;
}

function citationMarkerCandidates(markerText?: string): string[] {
  if (!markerText) return [];
  const candidates = [markerText];
  const tokens = markerText.match(CHATGPT_REF_TOKEN_RE) ?? [];
  if (tokens.length > 0 && markerText.includes("cite")) {
    candidates.push(
      `${CHATGPT_MARKER_START}cite${tokens.map((token) => CHATGPT_MARKER_SEP + token).join("")}${CHATGPT_MARKER_END}`
    );
  }
  return [...new Set(candidates)];
}

type AddCitationSourceFn = (
  titleValue: unknown,
  urlValue: unknown,
  attributionValue?: unknown
) => number;
type AddCitationMentionFn = (ref: Record<string, unknown>, replacement: string) => void;

/** Supporting-website sources nested under one `grouped_webpages` item. */
function collectSupportingWebsiteNumbers(
  item: Record<string, unknown>,
  addSource: AddCitationSourceFn,
  refTokenToSourceNumber: Map<string, number>
): number[] {
  const numbers: number[] = [];
  for (const supportingValue of asArray(item.supporting_websites)) {
    const supporting = asRecord(supportingValue);
    if (!supporting) continue;
    const supportingNumber = addSource(supporting.title, supporting.url, supporting.attribution);
    if (supportingNumber) {
      numbers.push(supportingNumber);
      mapStructuredRefs(supporting.refs, supportingNumber, refTokenToSourceNumber);
    }
  }
  return numbers;
}

/** One `grouped_webpages` item — its own primary source plus any supporting-website
 * sources nested under it. */
function collectGroupedWebpageItemNumbers(
  itemValue: unknown,
  addSource: AddCitationSourceFn,
  refTokenToSourceNumber: Map<string, number>
): number[] {
  const item = asRecord(itemValue);
  if (!item) return [];
  const numbers: number[] = [];
  const mainNumber = addSource(item.title, item.url, item.attribution);
  if (mainNumber) {
    numbers.push(mainNumber);
    mapStructuredRefs(item.refs, mainNumber, refTokenToSourceNumber);
  }
  numbers.push(...collectSupportingWebsiteNumbers(item, addSource, refTokenToSourceNumber));
  return numbers;
}

/** Fallback when no `grouped_webpages` item yielded a usable source — fall back to
 * the ref's own URLs directly. */
function collectGroupedWebpagesFallbackNumbers(
  ref: Record<string, unknown>,
  addSource: AddCitationSourceFn
): number[] {
  const numbers: number[] = [];
  for (const url of referenceUrls(ref)) {
    const fallbackNumber = addSource(ref.title, url, ref.attribution);
    if (fallbackNumber) numbers.push(fallbackNumber);
  }
  return numbers;
}

/** `content_references[].type === "grouped_webpages"` — a primary source per item,
 * each optionally paired with supporting-website sources; falls back to the ref's
 * own URLs when no item yielded a usable source. */
function collectGroupedWebpagesRef(
  ref: Record<string, unknown>,
  sources: ChatGptCitationSource[],
  addSource: AddCitationSourceFn,
  addMention: AddCitationMentionFn,
  refTokenToSourceNumber: Map<string, number>
): void {
  let numbers: number[] = [];
  for (const itemValue of asArray(ref.items)) {
    numbers.push(...collectGroupedWebpageItemNumbers(itemValue, addSource, refTokenToSourceNumber));
  }

  if (numbers.length === 0) {
    numbers = collectGroupedWebpagesFallbackNumbers(ref, addSource);
  }

  addMention(ref, formatCitationLinks(numbers, sources));
}

/** `content_references[].type === "sources_footnote"` — a flat list of sources with
 * no inline mention to replace (the footnote itself carries no marker text). */
function collectSourcesFootnoteRef(
  ref: Record<string, unknown>,
  addSource: AddCitationSourceFn
): void {
  for (const sourceValue of asArray(ref.sources)) {
    const source = asRecord(sourceValue);
    if (source) addSource(source.title, source.url, source.attribution);
  }
}

/** Any other reference type — a direct `webpage`/`url` marker with an inline label
 * renders as `[label](url)`; everything else falls back to numbered source links. */
function collectDefaultRef(
  ref: Record<string, unknown>,
  type: string,
  sources: ChatGptCitationSource[],
  addSource: AddCitationSourceFn,
  addMention: AddCitationMentionFn,
  refTokenToSourceNumber: Map<string, number>
): void {
  const urls = referenceUrls(ref);
  const label = urlMarkerLabel(asString(ref.matched_text));
  if ((type === "webpage" || type === "url") && label && urls[0]) {
    addMention(ref, `[${markdownLinkText(label)}](${markdownUrl(urls[0])})`);
    return;
  }

  const numbers = urls
    .map((url) => addSource(ref.title ?? ref.alt, url, ref.attribution))
    .filter((num) => num > 0);
  if (numbers.length === 0) return;

  mapStructuredRefs(ref.refs, numbers[0], refTokenToSourceNumber);
  addMention(ref, formatCitationLinks(numbers, sources));
}

function collectChatGptCitationData(metadata?: Record<string, unknown>): ChatGptCitationData {
  const refs = asArray(metadata?.content_references);
  const sources: ChatGptCitationSource[] = [];
  const mentions: ChatGptCitationMention[] = [];
  const sourceIndexByCanonicalUrl = new Map<string, number>();
  const refTokenToSourceNumber = new Map<string, number>();

  const addSource: AddCitationSourceFn = (titleValue, urlValue, attributionValue) => {
    const url = asString(urlValue);
    if (!url) return 0;
    const canonical = canonicalCitationUrl(url);
    const existing = sourceIndexByCanonicalUrl.get(canonical);
    if (existing) return existing;

    const title = asString(titleValue) ?? url;
    const attribution = asString(attributionValue) ?? "";
    const idx = sources.length + 1;
    sources.push({ title: title.replace(/\n/g, " ").trim(), url, attribution });
    sourceIndexByCanonicalUrl.set(canonical, idx);
    return idx;
  };

  const addMention: AddCitationMentionFn = (ref, replacement) => {
    if (!replacement) return;
    const start = asNumber(ref.start_idx);
    const end = asNumber(ref.end_idx);
    const markerText = asString(ref.matched_text) ?? undefined;
    if (markerText || (start != null && end != null)) {
      mentions.push({
        ...(start != null ? { start } : {}),
        ...(end != null ? { end } : {}),
        ...(markerText ? { markerText } : {}),
        replacement,
      });
    }
  };

  for (const refValue of refs) {
    const ref = asRecord(refValue);
    if (!ref) continue;
    const type = asString(ref.type) ?? "";

    if (type === "grouped_webpages") {
      collectGroupedWebpagesRef(ref, sources, addSource, addMention, refTokenToSourceNumber);
      continue;
    }
    if (type === "sources_footnote") {
      collectSourcesFootnoteRef(ref, addSource);
      continue;
    }
    collectDefaultRef(ref, type, sources, addSource, addMention, refTokenToSourceNumber);
  }

  return { sources, mentions, refTokenToSourceNumber };
}

function replacePrivateCitationMarkers(text: string, citationData: ChatGptCitationData): string {
  const replaceTokens = (tokens: string[]): string => {
    const numbers = tokens
      .map((token) => citationData.refTokenToSourceNumber.get(token))
      .filter((num): num is number => typeof num === "number");
    return numbers.length > 0 ? formatCitationLinks(numbers, citationData.sources) : "";
  };

  return text
    .replace(/\uE200cite((?:\uE202[^\uE201\uE202]+)+)\uE201/gu, (_all, body: string) => {
      const tokens = [...body.matchAll(/\uE202([^\uE201\uE202]+)/gu)].map((match) => match[1]);
      return replaceTokens(tokens);
    })
    .replace(
      /\bcite((?:turn\d+(?:search|product|news|image|webpage)\d+)+)\b/g,
      (_all, body: string) => {
        return replaceTokens(body.match(CHATGPT_REF_TOKEN_RE) ?? []);
      }
    );
}

function stripDanglingChatGptMarkers(text: string, citationData: ChatGptCitationData): string {
  return replacePrivateCitationMarkers(text, citationData)
    .replace(
      /\uE200url\uE202([^\uE201\uE202]+)\uE202(https?:\/\/[^\uE201]+)\uE201/gu,
      (_all, label: string, url: string) => {
        return `[${markdownLinkText(label)}](${markdownUrl(url)})`;
      }
    )
    .replace(
      /\uE200url\uE202([^\uE201\uE202]+)\uE202(?:[^\uE201]*\uE201)?/gu,
      (_all, label: string) => {
        return label.trim();
      }
    )
    .replace(/\uE200cite(?:\uE202[^\uE201\uE202]*)*$/gu, "")
    .replace(/\uE200[a-z_]+(?:\uE202[^\uE201\uE202]*)*\uE201/giu, "")
    .replace(/\uE200[a-z_]+(?:\uE202[^\uE201\uE202]*)*$/giu, "")
    .replace(/\uE202?turn\d+(?:search|product|news|image|webpage)\d+\uE201?/gu, "")
    .replace(/[\uE200\uE201\uE202]/gu, "");
}

function applyChatGptCitations(text: string, metadata?: Record<string, unknown>): string {
  const citationData = collectChatGptCitationData(metadata);
  let rendered = text;

  for (const mention of [...citationData.mentions].sort(
    (a, b) => (b.start ?? -1) - (a.start ?? -1)
  )) {
    let replaced = false;
    for (const markerText of citationMarkerCandidates(mention.markerText)) {
      const limit =
        mention.start != null
          ? Math.min(rendered.length, mention.start + markerText.length)
          : rendered.length;
      let pos = rendered.lastIndexOf(markerText, limit);
      if (pos < 0) pos = rendered.indexOf(markerText);
      if (pos >= 0) {
        rendered =
          rendered.slice(0, pos) + mention.replacement + rendered.slice(pos + markerText.length);
        replaced = true;
        break;
      }
    }

    if (!replaced && mention.start != null && mention.end != null) {
      const start = Math.max(0, Math.min(mention.start, rendered.length));
      const end = Math.max(start, Math.min(mention.end, rendered.length));
      rendered = rendered.slice(0, start) + mention.replacement + rendered.slice(end);
    }
  }

  return stripDanglingChatGptMarkers(rendered, citationData);
}

export function cleanChatGptText(text: string, metadata?: Record<string, unknown>): string {
  return applyChatGptCitations(text.replace(ENTITY_RE, "$1"), metadata);
}

import { tlsFetchChatGpt } from "../../services/chatgptTlsClient.ts";

const CONVERSATION_RESUME_URL = "https://chatgpt.com/backend-api/f/conversation/resume";
const RESUME_OFFSETS = [0, 1, 2] as const;

export interface FinalAssistantAnswer {
  text: string;
  messageId?: string;
  metadata?: Record<string, unknown>;
  finished: boolean;
}

interface HandoffContentChunk {
  answer?: string;
  messageId?: string;
  metadata?: Record<string, unknown>;
  error?: string;
}

type HandoffContentReader = (
  eventStream: ReadableStream<Uint8Array>,
  signal?: AbortSignal | null
) => AsyncIterable<HandoffContentChunk>;

interface ResumeHandoffOptions {
  conversationId: string;
  resumeToken: string;
  headers: Record<string, string>;
  timeoutMs: number;
  signal?: AbortSignal | null;
  log?: { warn?: (tag: string, message: string) => void } | null;
  readContent: HandoffContentReader;
}

interface ResumeAttemptOptions extends Pick<
  ResumeHandoffOptions,
  "conversationId" | "timeoutMs" | "signal" | "log" | "readContent"
> {
  offset: (typeof RESUME_OFFSETS)[number];
  resumeHeaders: Record<string, string>;
}

interface ResumeAttemptResult {
  answer: FinalAssistantAnswer | null;
  shouldRetry: boolean;
}

function stringToStream(text: string): ReadableStream<Uint8Array> {
  const bytes = new TextEncoder().encode(text);
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(bytes);
      controller.close();
    },
  });
}

async function readFinalAssistantAnswer(
  eventStream: ReadableStream<Uint8Array>,
  signal: AbortSignal | null | undefined,
  readContent: HandoffContentReader
): Promise<FinalAssistantAnswer | null> {
  let text = "";
  let messageId: string | undefined;
  let metadata: Record<string, unknown> | undefined;

  for await (const chunk of readContent(eventStream, signal)) {
    if (chunk.error) return null;
    if (chunk.answer) text = chunk.answer;
    if (chunk.messageId) messageId = chunk.messageId;
    if (chunk.metadata) metadata = chunk.metadata;
  }

  if (!text.trim()) return null;
  return { text, messageId, metadata, finished: true };
}

async function attemptResumeOffset({
  conversationId,
  offset,
  resumeHeaders,
  timeoutMs,
  signal,
  log,
  readContent,
}: ResumeAttemptOptions): Promise<ResumeAttemptResult> {
  try {
    const response = await tlsFetchChatGpt(CONVERSATION_RESUME_URL, {
      method: "POST",
      headers: resumeHeaders,
      body: JSON.stringify({ conversation_id: conversationId, offset }),
      timeoutMs,
      signal,
      stream: true,
    });

    if (response.status === 404) return { answer: null, shouldRetry: true };
    if (response.status >= 400) {
      log?.warn?.(
        "CGPT-WEB",
        `conversation resume ${response.status}: ${(response.text || "").slice(0, 300)}`
      );
      return { answer: null, shouldRetry: false };
    }

    const eventStream = response.body ?? (response.text ? stringToStream(response.text) : null);
    if (!eventStream) return { answer: null, shouldRetry: true };

    const answer = await readFinalAssistantAnswer(eventStream, signal, readContent);
    return { answer, shouldRetry: !answer };
  } catch (error) {
    log?.warn?.(
      "CGPT-WEB",
      `conversation resume failed: ${error instanceof Error ? error.message : String(error)}`
    );
    return { answer: null, shouldRetry: false };
  }
}

export async function resumeChatGptHandoff({
  conversationId,
  resumeToken,
  headers,
  timeoutMs,
  signal,
  log,
  readContent,
}: ResumeHandoffOptions): Promise<FinalAssistantAnswer | null> {
  const resumeHeaders = {
    ...headers,
    Accept: "text/event-stream",
    "Content-Type": "application/json",
    "x-conduit-token": resumeToken,
    "X-OpenAI-Target-Path": "/backend-api/f/conversation/resume",
    "X-OpenAI-Target-Route": "/backend-api/f/conversation/resume",
  };

  for (const offset of RESUME_OFFSETS) {
    const attempt = await attemptResumeOffset({
      conversationId,
      resumeHeaders,
      offset,
      timeoutMs,
      signal,
      log,
      readContent,
    });
    if (attempt.answer) return attempt.answer;
    if (!attempt.shouldRetry) return null;
  }

  log?.warn?.("CGPT-WEB", `conversation resume returned no assistant text for ${conversationId}`);
  return null;
}

