function parseSseBlock(block: string): { event: string; data: unknown } | null {
  const lines = block.split(/\r?\n/);
  const event = lines
    .find((line) => line.startsWith("event:"))
    ?.slice(6)
    .trim();
  const dataLines = lines
    .filter((line) => line.startsWith("data:"))
    .map((line) => line.slice(5).trim());
  if (dataLines.length === 0) return null;
  const rawData = dataLines.join("\n");
  if (rawData === "[DONE]") return { event: event || "done", data: "[DONE]" };
  try {
    return { event: event || "", data: JSON.parse(rawData) };
  } catch {
    return null;
  }
}

function extractDolaBlockDeltas(blocks: unknown[], state?: DolaTextExtractionState): string[] {
  const deltas: string[] = [];

  for (const block of blocks) {
    const blockRecord = asRecord(block);
    if (state && isDolaAnswerBoundary(blockRecord)) {
      state.answerStarted = true;
      state.bufferedDeltas = [];
      continue;
    }

    const text = toContentText(asRecord(asRecord(blockRecord.content).text_block).text);
    if (!text) continue;

    if (!state || state.answerStarted) {
      deltas.push(text);
    } else {
      state.bufferedDeltas.push(text);
    }
  }

  return deltas;
}

function flushDolaTextExtractionState(state: DolaTextExtractionState): string[] {
  if (state.answerStarted) return [];
  const fallback = state.bufferedDeltas;
  state.bufferedDeltas = [];
  state.answerStarted = true;
  return fallback;
}

export function extractDolaTextDeltas(data: unknown, state?: DolaTextExtractionState): string[] {
  const root = asRecord(data);
  const payload = asRecord(root.data);
  const content = asRecord(root.content);
  const payloadContent = asRecord(payload.content);
  const initialBlocks = Array.isArray(content.content_block)
    ? content.content_block
    : Array.isArray(payloadContent.content_block)
      ? payloadContent.content_block
      : [];
  const patchOps = Array.isArray(root.patch_op)
    ? root.patch_op
    : Array.isArray(payload.patch_op)
      ? payload.patch_op
      : [];
  const deltas = extractDolaBlockDeltas(initialBlocks, state);

  for (const op of patchOps) {
    const patchValue = asRecord(asRecord(op).patch_value);
    const blocks = Array.isArray(patchValue.content_block) ? patchValue.content_block : [];
    deltas.push(...extractDolaBlockDeltas(blocks, state));
  }

  return deltas;
}

function extractDolaError(data: unknown): string {
  const root = asRecord(data);
  const payload = asRecord(root.data);
  return (
    toString(root.message) ||
    toString(payload.message) ||
    toString(payload.error_msg) ||
    toString(payload.errorMessage)
  );
}

export function isDolaBusyMessage(content: string): boolean {
  const normalized = content.trim().toLowerCase();
  return (
    normalized.includes("a lot of people are using the app right now") &&
    normalized.includes("try again later")
  );
}

function openAiChunk(modelId: string, content: string): JsonRecord {
  return {
    id: `chatcmpl-dola-${Date.now()}`,
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model: modelId,
    choices: [{ index: 0, delta: { content }, finish_reason: null }],
  };
}

function openAiCompletion(modelId: string, content: string): JsonRecord {
  return {
    id: `chatcmpl-dola-${Date.now()}`,
    object: "chat.completion",
    created: Math.floor(Date.now() / 1000),
    model: modelId,
    choices: [{ index: 0, message: { role: "assistant", content }, finish_reason: "stop" }],
  };
}

export class DoubaoWebExecutor extends BaseExecutor {
  constructor() {
    super("doubao-web", { id: "doubao-web", baseUrl: BASE_URL });
  }

  private createHeaders(cookieHeader: string): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      "User-Agent": USER_AGENT,
      Accept: "text/event-stream",
      Referer: `${BASE_URL}/chat/`,
      Origin: BASE_URL,
      "Agw-Js-Conv": "str",
    };
    if (cookieHeader) headers.Cookie = cookieHeader;
    return headers;
  }

  private async collectText(upstream: Response, modelId: string): Promise<string> {
    const raw = await upstream.text();
    const state = createDolaTextExtractionState(modelId);
    const deltas: string[] = [];

    for (const block of raw.split(/\r?\n\r?\n/)) {
      const event = parseSseBlock(block);
      if (event) deltas.push(...extractDolaTextDeltas(event.data, state));
    }
    deltas.push(...flushDolaTextExtractionState(state));

    return deltas.join("");
  }

  private createStream(upstream: Response, modelId: string, signal?: AbortSignal | null) {
    const encoder = new TextEncoder();
    const decoder = new TextDecoder();
    const state = createDolaTextExtractionState(modelId);
    let sentDone = false;

    return new ReadableStream({
      async start(controller) {
        const reader = upstream.body?.getReader();
        if (!reader) {
          controller.enqueue(encoder.encode("data: [DONE]\n\n"));
          controller.close();
          return;
        }
        let buffer = "";
        let errored = false;
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const blocks = buffer.split(/\r?\n\r?\n/);
            buffer = blocks.pop() || "";

            for (const block of blocks) {
              const event = parseSseBlock(block);
              if (!event) continue;
              if (event.event === "STREAM_ERROR") {
                const message = extractDolaError(event.data) || "Dola stream error";
                errored = true;
                controller.error(new Error(message));
                return;
              }
              for (const text of extractDolaTextDeltas(event.data, state)) {
                controller.enqueue(
                  encoder.encode(`data: ${JSON.stringify(openAiChunk(modelId, text))}\n\n`)
                );
              }
              if (event.event === "SSE_REPLY_END") {
                sentDone = true;
                controller.enqueue(encoder.encode("data: [DONE]\n\n"));
              }
            }
          }
        } catch (err) {
          if (!signal?.aborted) {
            errored = true;
            controller.error(err);
          }
          return;
        } finally {
          if (errored) return;
          for (const text of flushDolaTextExtractionState(state)) {
            controller.enqueue(
              encoder.encode(`data: ${JSON.stringify(openAiChunk(modelId, text))}\n\n`)
            );
          }
          if (!sentDone) controller.enqueue(encoder.encode("data: [DONE]\n\n"));
          controller.close();
        }
      },
    });
  }

  async execute(input: ExecuteInput) {
    const { body, credentials, signal, stream: wantStream } = input;
    const bodyObj = asRecord(body);
    const providerSpecificData = credentials?.providerSpecificData;
    const rawCredential = toString(credentials?.apiKey);
    const cookieHeader = buildDolaCookieHeader(rawCredential, providerSpecificData);
    const requestedModel = toString(bodyObj.model) || input.model || DEFAULT_MODEL;
    const modelId = requestedModel.split("/").pop() || DEFAULT_MODEL;
    const prompt = foldMessages(bodyObj.messages);
    const fingerprint = resolveDolaFingerprint(cookieHeader, providerSpecificData, rawCredential);
    const transformedBody = buildDolaPayload(
      prompt,
      modelId,
      cookieHeader,
      providerSpecificData,
      rawCredential
    );
    const query = buildDolaQueryParams(cookieHeader, providerSpecificData, rawCredential);
    const url = `${CHAT_URL}?${query.toString()}`;
    const reqHeaders = this.createHeaders(cookieHeader);

    if (!extractCookieValue(cookieHeader, "sessionid")) {
      return {
        ...makeErrorResult(
          401,
          "Dola Web requires a www.dola.com Cookie header containing at least sessionid, ttwid, and s_v_web_id.",
          body,
          url
        ),
        headers: reqHeaders,
        transformedBody,
      };
    }
    if (!fingerprint) {
      return {
        ...makeErrorResult(
          401,
          "Dola Web requires the browser fingerprint value from www.dola.com. Add s_v_web_id=... from Cookies or fp=verify_... from a Network chat/completion request URL.",
          body,
          url
        ),
        headers: reqHeaders,
        transformedBody,
      };
    }

    let upstream: Response;
    try {
      upstream = await fetch(url, {
        method: "POST",
        headers: reqHeaders,
        body: JSON.stringify(transformedBody),
        signal,
      });
    } catch (err) {
      return {
        ...makeErrorResult(
          502,
          `Dola fetch failed: ${err instanceof Error ? err.message : "unknown"}`,
          body,
          url
        ),
        headers: reqHeaders,
        transformedBody,
      };
    }

    if (!upstream.ok) {
      const errText = await upstream.text().catch(() => "");
      return {
        ...makeErrorResult(upstream.status, `Dola error: ${errText}`, body, url),
        headers: reqHeaders,
        transformedBody,
      };
    }

    const contentType = upstream.headers.get("Content-Type") || "";
    if (!contentType.toLowerCase().includes("text/event-stream")) {
      const text = await upstream.text().catch(() => "");
      return {
        ...makeErrorResult(502, `Dola returned non-SSE response: ${text}`, body, url),
        headers: reqHeaders,
        transformedBody,
      };
    }

    if (!wantStream) {
      const content = await this.collectText(upstream, modelId);
      if (isDolaBusyMessage(content)) {
        return {
          ...makeErrorResult(429, "Dola is temporarily busy. Please try again later.", body, url),
          headers: reqHeaders,
          transformedBody,
        };
      }
      return {
        response: new Response(JSON.stringify(openAiCompletion(modelId, content)), {
          headers: { "Content-Type": "application/json" },
        }),
        url,
        headers: reqHeaders,
        transformedBody,
      };
    }

    return {
      response: new Response(this.createStream(upstream, modelId, signal), {
        headers: {
          "Content-Type": "text/event-stream",
          "Cache-Control": "no-cache",
          Connection: "keep-alive",
        },
      }),
      url,
      headers: reqHeaders,
      transformedBody,
    };
  }
}

/**
 * QwenWebExecutor — Alibaba Tongyi Qwen Chat via chat.qwen.ai (v2 API)
 *
 * Routes requests through Qwen's consumer chat API. The legacy v1 endpoint
 * (`/api/chat/completions`) was retired upstream in 2026 and now answers 504
 * HTML from Alibaba's gateway for every request, regardless of credentials
 * (#3288 / discussion #2768). The current contract is a two-step v2 flow:
 *
 *   1. POST /api/v2/chats/new                  → create a chat, returns chat_id
 *   2. POST /api/v2/chat/completions?chat_id=  → phase-based SSE stream
 *
 * The v2 endpoints sit behind Alibaba's "baxia" WAF, which requires the full
 * browser cookie jar from a real logged-in session (cna, ssxmod_itna,
 * ssxmod_itna2, token, ...). We therefore replay the captured/pasted Cookie
 * header verbatim plus the bearer token, mirroring how grok-web replays its
 * anti-bot cookies.
 *
 * SSE chunks carry `choices[0].delta` with a `phase` field: `think` /
 * `thinking_summary` map to reasoning, `answer` (or a null phase) carries the
 * assistant content.
 *
 * Reference implementations: gpt4free `g4f/Provider/Qwen.py`,
 * Chat2API `proxy/adapters/qwen-ai.ts`.
 *
 * Auth: full Cookie header from chat.qwen.ai + bearer token (localStorage
 *       `token`, also mirrored to a `token` cookie).
 * Format: OpenAI-compatible (translated from Qwen's phase protocol).
 */
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import { makeExecutorErrorResult as makeErrorResult } from "../utils/error.ts";
import { prepareToolMessages, buildToolAwareResult } from "../translator/webTools.ts";
import { buildQwenCookieHeader, extractQwenToken } from "@/lib/providers/webCookieAuth";

const BASE_URL = "https://chat.qwen.ai";
const CHATS_NEW_URL = `${BASE_URL}/api/v2/chats/new`;
const CHAT_COMPLETIONS_URL = `${BASE_URL}/api/v2/chat/completions`;
const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36";

// Anti-bot headers the v2 endpoint expects. `bx-umidtoken` is normally minted
// per-session from sg-wum.alibaba.com; a captured value travels with the cookie
// jar, but we also send a static fallback so the header is always present.
const BX_VERSION = "2.5.36";
const BX_UMIDTOKEN_FALLBACK = "T2gA0000000000000000000000000000000000000000";

// Qwen SPA version — required by the v2 chat completion endpoint. Without this
// header the upstream returns HTTP 200 with `{"success":false,"data":{"code":"Bad_Request"}}`
// for every completion request, even with a valid session. The version string is
// the SPA build identifier shipped in the React client's `version` request header.
// Pinned from a live capture (2026-07); bump if Qwen ships a breaking change.
const QWEN_SPA_VERSION = "0.2.66";

const MODEL_ALIASES: Record<string, string> = {
  // Legacy OmniRoute ids → current upstream catalog (GET /api/models).
  "qwen-plus": "qwen3.7-plus",
  "qwen-max": "qwen3.7-max",
  "qwen-turbo": "qwen3.6-plus",
  "qwen3-plus": "qwen3.7-plus",
  "qwen3-max": "qwen3.7-max",
  "qwen3-flash": "qwen3.6-plus",
  // Note: `qwen3-coder-plus` is a real upstream model id (Qwen3-Coder) and
  // must NOT be aliased — the previous `"qwen3-coder-plus": "qwen3.7-max"`
  // entry silently rewrote valid coder requests to the wrong model.
  "qwen3-coder-flash": "qwen3.6-plus",
  qwen: "qwen3.7-max",
  qwen3: "qwen3.7-max",
};

const DEFAULT_MODEL = "qwen3.7-max";
const REQUIRED_THINKING_MODELS = new Set(["qwen3.8-max-preview"]);

function mapModel(modelId: string): string {
  return MODEL_ALIASES[modelId] || modelId;
}

function uuid(): string {
  return crypto.randomUUID();
}

/** Detect Alibaba's WAF / retired-v1 gateway page so we never surface raw HTML. */
function isWafResponse(status: number, contentType: string, bodyText: string): boolean {
  if (contentType.includes("text/html")) return true;
  if (status === 504) return true;
  return /aliyun_waf|baxia|<html/i.test(bodyText);
}

const WAF_ERROR_MESSAGE =
  "Qwen session expired or blocked by Alibaba's WAF. Re-login at https://chat.qwen.ai and " +
  "paste a fresh full Cookie header (must include cna, ssxmod_itna and token) — a bearer token " +
  "alone is no longer accepted by the v2 endpoint.";

export class QwenWebExecutor extends BaseExecutor {
  constructor() {
    super("qwen-web", { id: "qwen-web", baseUrl: BASE_URL });
  }

  private buildApiHeaders(
    token: string,
    cookieHeader: string,
    chatId?: string
  ): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Accept: "*/*",
      "User-Agent": USER_AGENT,
      Origin: BASE_URL,
      Referer: chatId ? `${BASE_URL}/c/${chatId}` : `${BASE_URL}/`,
      source: "web",
      version: QWEN_SPA_VERSION,
      "x-request-id": uuid(),
      "bx-v": BX_VERSION,
      "bx-umidtoken": BX_UMIDTOKEN_FALLBACK,
    };
    if (token) headers["Authorization"] = `Bearer ${token}`;
    if (cookieHeader) headers["Cookie"] = cookieHeader;
    return headers;
  }

  async execute(input: ExecuteInput) {
    const { body, credentials, signal, stream: wantStream } = input;
    const bodyObj = (body || {}) as Record<string, unknown>;

    const rawCred = String(credentials?.apiKey ?? "").trim();
    const cookieHeader = buildQwenCookieHeader(rawCred);
    let token = extractQwenToken(rawCred);
    if (!token && credentials?.accessToken) token = String(credentials.accessToken).trim();

    const messages = (bodyObj.messages as Array<{ role: string; content: string }>) || [];
    const requestedModel = (bodyObj.model as string) || DEFAULT_MODEL;
    const modelId = mapModel(requestedModel);

    const { hasTools, requestedTools, effectiveMessages } = prepareToolMessages(bodyObj, messages);

    // Qwen Web is single-turn: fold the conversation into one user prompt.
    const prompt = this.foldMessages(effectiveMessages);

    // ── Step 1: create a chat ────────────────────────────────────────────────
    let chatId: string;
    try {
      const newChatRes = await fetch(CHATS_NEW_URL, {
        method: "POST",
        headers: this.buildApiHeaders(token, cookieHeader),
        body: JSON.stringify({
          title: "New Chat",
          models: [modelId],
          chat_mode: "normal",
          chat_type: "t2t",
          timestamp: Date.now(),
        }),
        signal,
      });

      const ct = newChatRes.headers.get("content-type") || "";
      if (!newChatRes.ok || ct.includes("text/html")) {
        const text = await newChatRes.text().catch(() => "");
        if (isWafResponse(newChatRes.status, ct, text)) {
          return makeErrorResult(401, WAF_ERROR_MESSAGE, body, CHATS_NEW_URL);
        }
        return makeErrorResult(
          newChatRes.status || 502,
          `Qwen create-chat failed: ${text.slice(0, 300)}`,
          body,
          CHATS_NEW_URL
        );
      }

      const data = (await newChatRes.json()) as { data?: { id?: string } };
      chatId = data?.data?.id ?? "";
      if (!chatId) {
        return makeErrorResult(502, "Qwen create-chat returned no chat id", body, CHATS_NEW_URL);
      }
    } catch (err) {
      return makeErrorResult(
        502,
        `Qwen create-chat error: ${err instanceof Error ? err.message : "unknown"}`,
        body,
        CHATS_NEW_URL
      );
    }

    // ── Step 2: send the message ─────────────────────────────────────────────
    const completionUrl = `${CHAT_COMPLETIONS_URL}?chat_id=${chatId}`;
    const msgPayload = this.buildMessagePayload(chatId, modelId, prompt, requestedModel);

    let upstream: Response;
    try {
      upstream = await fetch(completionUrl, {
        method: "POST",
        headers: this.buildApiHeaders(token, cookieHeader, chatId),
        body: JSON.stringify(msgPayload),
        signal,
      });
    } catch (err) {
      return makeErrorResult(
        502,
        `Qwen completion fetch failed: ${err instanceof Error ? err.message : "unknown"}`,
        body,
        completionUrl
      );
    }

    const ct = upstream.headers.get("content-type") || "";
    if (!upstream.ok || ct.includes("text/html")) {
      const errText = await upstream.text().catch(() => "");
      if (isWafResponse(upstream.status, ct, errText)) {
        return makeErrorResult(401, WAF_ERROR_MESSAGE, body, completionUrl);
      }
      return makeErrorResult(
        upstream.status || 502,
        `Qwen error: ${errText.slice(0, 300)}`,
        body,
        completionUrl
      );
    }

    if (!wantStream) {
      const { content } = await this.collectStream(upstream);
      const finalText = content;

      if (hasTools) {
        const {
          content: toolContent,
          toolCalls,
          finishReason,
        } = buildToolAwareResult(finalText, requestedTools, "qwen");
        const message: Record<string, unknown> = { role: "assistant", content: toolContent };
        if (toolCalls) {
          message.tool_calls = toolCalls;
          message.content = null;
        }
        return this.jsonResponse(modelId, message, finishReason, completionUrl, msgPayload);
      }

      return this.jsonResponse(
        modelId,
        { role: "assistant", content: finalText },
        "stop",
        completionUrl,
        msgPayload
      );
    }

    // Streaming: transform Qwen phase SSE → OpenAI chat.completion.chunk SSE.
    const stream = this.buildClientStream(upstream, modelId, hasTools, requestedTools, signal);
    return {
      response: new Response(stream, {
        headers: {
          "Content-Type": "text/event-stream",
          "Cache-Control": "no-cache",
          Connection: "keep-alive",
        },
      }),
      url: completionUrl,
      headers: this.buildApiHeaders(token, cookieHeader, chatId),
      transformedBody: msgPayload,
    };
  }

  /** Flatten OpenAI-style content (string | Array<{type,text}>) into plain text.
   *  A bare String() on an array of content parts yields "[object Object]" — the
   *  serialization bug reported on the support mesh. */
  private contentToText(content: unknown): string {
    if (typeof content === "string") return content;
    if (Array.isArray(content)) {
      return content
        .map((part) => {
          if (typeof part === "string") return part;
          if (part && typeof part === "object") {
            const p = part as { type?: unknown; text?: unknown };
            if (typeof p.text === "string") return p.text;
          }
          return "";
        })
        .filter(Boolean)
        .join("\n");
    }
    return content == null ? "" : String(content);
  }

  private foldMessages(messages: Array<{ role: string; content: unknown }>): string {
    let systemContent = "";
    let userContent = "";
    for (const m of messages) {
      const text = this.contentToText(m.content);
      if (m.role === "system") {
        systemContent += (systemContent ? "\n\n" : "") + text;
      } else if (m.role === "user") {
        userContent = text;
      }
    }
    return systemContent ? `${systemContent}\n\nUser: ${userContent}` : userContent;
  }

  private buildMessagePayload(
    chatId: string,
    modelId: string,
    prompt: string,
    requestedModel: string
  ): Record<string, unknown> {
    const fid = uuid();
    const enableThinking =
      REQUIRED_THINKING_MODELS.has(modelId) || /think|reason|r1/i.test(requestedModel);
    const featureConfig: Record<string, unknown> = {
      thinking_enabled: enableThinking,
      output_schema: "phase",
      auto_thinking: enableThinking,
      research_mode: "normal",
      auto_search: false,
    };
    return {
      stream: true,
      incremental_output: true,
      chat_id: chatId,
      chat_mode: "normal",
      model: modelId,
      parent_id: null,
      messages: [
        {
          fid,
          parentId: null,
          childrenIds: [],
          role: "user",
          content: prompt,
          user_action: "chat",
          files: [],
          timestamp: Math.floor(Date.now() / 1000),
          models: [modelId],
          chat_type: "t2t",
          feature_config: featureConfig,
          sub_chat_type: "t2t",
          parent_id: null,
        },
      ],
    };
  }

  /** Read the whole upstream SSE stream, returning the joined answer + reasoning. */
  private async collectStream(upstream: Response): Promise<{ content: string; reasoning: string }> {
    const reader = upstream.body?.getReader();
    const decoder = new TextDecoder();
    let content = "";
    let reasoning = "";
    if (!reader) return { content, reasoning };

    let buffer = "";
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || "";
        for (const line of lines) {
          const delta = parseSseDelta(line);
          if (!delta) continue;
          if (delta.kind === "answer") content += delta.text;
          else if (delta.kind === "think") reasoning += delta.text;
        }
      }
    } catch {
      /* upstream closed mid-stream — return what we have */
    }
    return { content, reasoning };
  }

  /** Transform the Qwen phase SSE into OpenAI chat.completion.chunk SSE. */
  private buildClientStream(
    upstream: Response,
    modelId: string,
    hasTools: boolean,
    requestedTools: unknown,
    signal: AbortSignal | null | undefined
  ): ReadableStream {
    const encoder = new TextEncoder();
    const decoder = new TextDecoder();
    const id = `chatcmpl-qwen-${Date.now()}`;
    const created = Math.floor(Date.now() / 1000);
    const emitChunk = (delta: Record<string, unknown>, finishReason: string | null) =>
      `data: ${JSON.stringify({
        id,
        object: "chat.completion.chunk",
        created,
        model: modelId,
        choices: [{ index: 0, delta, finish_reason: finishReason }],
      })}\n\n`;

    return new ReadableStream({
      async start(controller) {
        const reader = upstream.body?.getReader();
        if (!reader) {
          controller.enqueue(encoder.encode("data: [DONE]\n\n"));
          controller.close();
          return;
        }
        let buffer = "";
        let fullContent = "";
        controller.enqueue(encoder.encode(emitChunk({ role: "assistant", content: "" }, null)));
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split("\n");
            buffer = lines.pop() || "";
            for (const line of lines) {
              const delta = parseSseDelta(line);
              if (!delta || !delta.text) continue;
              if (delta.kind === "answer") {
                fullContent += delta.text;
                if (!hasTools) {
                  controller.enqueue(encoder.encode(emitChunk({ content: delta.text }, null)));
                }
              } else if (delta.kind === "think" && !hasTools) {
                controller.enqueue(
                  encoder.encode(emitChunk({ reasoning_content: delta.text }, null))
                );
              }
            }
          }
        } catch (err) {
          if (!signal?.aborted) {
            controller.error(err);
            return;
          }
        }

        if (hasTools) {
          const { content, toolCalls, finishReason } = buildToolAwareResult(
            fullContent,
            requestedTools,
            "qwen"
          );
          const delta = toolCalls
            ? { role: "assistant", content: null, tool_calls: toolCalls }
            : { role: "assistant", content };
          controller.enqueue(encoder.encode(emitChunk(delta, null)));
          controller.enqueue(encoder.encode(emitChunk({}, finishReason)));
        } else {
          controller.enqueue(encoder.encode(emitChunk({}, "stop")));
        }
        controller.enqueue(encoder.encode("data: [DONE]\n\n"));
        controller.close();
      },
    });
  }

  private jsonResponse(
    modelId: string,
    message: Record<string, unknown>,
    finishReason: string,
    url: string,
    transformedBody: unknown
  ) {
    return {
      response: new Response(
        JSON.stringify({
          id: `chatcmpl-qwen-${Date.now()}`,
          object: "chat.completion",
          created: Math.floor(Date.now() / 1000),
          model: modelId,
          choices: [{ index: 0, message, finish_reason: finishReason }],
        }),
        { headers: { "Content-Type": "application/json" } }
      ),
      url,
      headers: {} as Record<string, string>,
      transformedBody,
    };
  }
}

/** Parse one SSE line into a typed delta, or null if it carries no content. */
function parseSseDelta(line: string): { kind: "answer" | "think"; text: string } | null {
  if (!line.startsWith("data:")) return null;
  const payload = line.slice(5).trim();
  if (!payload || payload === "[DONE]") return null;
  let parsed: {
    choices?: Array<{ delta?: { phase?: string | null; content?: unknown } }>;
  };
  try {
    parsed = JSON.parse(payload);
  } catch {
    return null;
  }
  const delta = parsed?.choices?.[0]?.delta;
  if (!delta) return null;
  const phase = delta.phase;
  const content = typeof delta.content === "string" ? delta.content : "";
  if (phase === "think" || phase === "thinking_summary") {
    return { kind: "think", text: content };
  }
  // `answer` phase or a null/absent phase both carry assistant content.
  if (phase === "answer" || phase === null || phase === undefined) {
    return { kind: "answer", text: content };
  }
  return null;
}

/**
 * HailuoWebExecutor — Hailuo AI (MiniMax) web chat via www.hailuo.ai.
 *
 * Distinct from the paid API-key `minimax`/`minimax-cn` providers
 * (open-sse/config/providers/registry/minimax/) — this targets the free
 * consumer chat product at hailuo.ai / chat.minimax.io.
 *
 * Endpoint: POST https://www.hailuo.ai/v4/api/chat/msg?<fingerprint query>
 * Auth:     `token` header — value read from the site's `_token` localStorage
 *           entry, plus a per-request `yy` signature header.
 * Body:     multipart/form-data — characterID, msgContent, chatID, searchMode.
 * Response: text/event-stream lines (`event:` / `data:`) carrying
 *           `send_result` (chat title + chatID, once) and `message_result`
 *           (cumulative — not delta — `content` field per event) until a
 *           `close_chunk` event ends the stream.
 *
 * Ported from the g4f reference implementation
 * (g4f/Provider/needs_auth/mini_max/{HailuoAI,crypt}.py) — request signing
 * (`generate_yy_header`/`get_body_to_yy`) and the SSE event shape are ported
 * 1:1. The device-fingerprint fields (device_id, uuid, os/browser name,
 * screen dims) are normally generated by the browser and stored in
 * localStorage; when the user hasn't captured them, this executor derives
 * stable per-connection values from the token via MD5 so the signature stays
 * consistent across requests without server-side state.
 *
 * ⚠️ Not yet validated against a live hailuo.ai session — see PR description
 * for the exact VPS live-check command that must be run before this is
 * treated as fully verified. The host, API path, header shape, and signing
 * scheme are ported directly from the (actively maintained) g4f source, but
 * upstream reverse-engineered protocols can change without notice.
 */
import { createHash } from "node:crypto";
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import { makeExecutorErrorResult as makeErrorResult, sanitizeErrorMessage } from "../utils/error.ts";

const BASE_URL = "https://www.hailuo.ai";
const API_PATH = "/v4/api/chat/msg";
const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36";
const DEFAULT_CHARACTER_ID = "1";
const DEFAULT_CHAT_ID = "0";

type JsonRecord = Record<string, unknown>;

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toStringOrEmpty(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

function md5(input: string): string {
  return createHash("md5").update(input, "utf8").digest("hex");
}

/**
 * Percent-encode matching Python's `urllib.parse.quote(s, safe="")` — encode
 * every byte except the always-safe RFC 3986 unreserved set (letters,
 * digits, `_.-~`). `encodeURIComponent` leaves a few extra characters
 * (`!*'()`) unescaped, so it is not a drop-in replacement for the upstream
 * signature to match byte-for-byte.
 */
export function pyQuote(input: string): string {
  const bytes = new TextEncoder().encode(input);
  let out = "";
  for (const byte of bytes) {
    const ch = String.fromCharCode(byte);
    if (/[A-Za-z0-9_.\-~]/.test(ch)) {
      out += ch;
    } else {
      out += `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
    }
  }
  return out;
}

/** Port of `get_body_to_yy()` from crypt.py. */
export function getBodyToYy(characterID: string, msgContent: string, chatID: string): string {
  const normalized = msgContent.replace(/\r\n/g, "").replace(/\n/g, "").replace(/\r/g, "");
  return md5(characterID) + md5(normalized) + md5(chatID) + md5("");
}

/** Port of `generate_yy_header()` from crypt.py. */
export function generateYyHeader(
  pathAndQuery: string,
  bodyToYy: string,
  timestampMs: number
): string {
  const encodedPath = pyQuote(pathAndQuery);
  const timeHash = md5(String(timestampMs));
  const combined = `${encodedPath}_${bodyToYy}${timeHash}ooui`;
  return md5(combined);
}

/**
 * Derive a stable per-connection fingerprint id from the token when the user
 * hasn't captured the real browser-generated value from localStorage. Pure
 * function of the token, so it stays identical across requests without
 * needing to persist any new state.
 */
function deriveFingerprintId(token: string, salt: string): string {
  return md5(`${token}:${salt}`);
}

export function buildHailuoPathAndQuery(
  token: string,
  providerSpecificData: unknown,
  unixMs: number
): string {
  const data = asRecord(providerSpecificData);
  const deviceId =
    toStringOrEmpty(data.device_id) ||
    toStringOrEmpty(data.deviceId) ||
    deriveFingerprintId(token, "device_id");
  const uuid = toStringOrEmpty(data.uuid) || deriveFingerprintId(token, "uuid");

  const params = new URLSearchParams({
    device_platform: "web",
    biz_id: "2",
    app_id: "3001",
    version_code: "22201",
    lang: "en",
    uuid,
    device_id: deviceId,
    os_name: toStringOrEmpty(data.os_name) || "Windows",
    browser_name: toStringOrEmpty(data.browser_name) || "chrome",
    cpu_core_num: toStringOrEmpty(data.cpu_core_num) || "8",
    browser_language: toStringOrEmpty(data.browser_language) || "en-US",
    browser_platform: toStringOrEmpty(data.browser_platform) || "Win32",
    screen_width: toStringOrEmpty(data.screen_width) || "1920",
    screen_height: toStringOrEmpty(data.screen_height) || "1080",
    unix: String(unixMs),
  });
  return `${API_PATH}?${params.toString()}`;
}

type HailuoInputMessage = {
  role: string;
  content: unknown;
  tool_calls?: unknown;
};

function textFromContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) {
    throw new Error("Hailuo Web only supports text message content");
  }
  return content
    .map((part) => {
      if (!part || typeof part !== "object" || Array.isArray(part)) {
        throw new Error("Hailuo Web only supports text message content");
      }
      const record = part as Record<string, unknown>;
      if (
        (record.type === "text" || record.type === "input_text") &&
        typeof record.text === "string"
      ) {
        return record.text;
      }
      throw new Error("Hailuo Web does not support image, audio, file, or tool content");
    })
    .join("");
}

/** Fold text-only OpenAI history into the single msgContent field Hailuo accepts. */
export function foldHailuoMessages(messages: HailuoInputMessage[]): string {
  const parts: string[] = [];
  for (const message of messages) {
    if (message.role === "tool" || message.role === "function") {
      throw new Error("Hailuo Web does not support tool result messages");
    }
    if (message.tool_calls !== undefined) {
      throw new Error("Hailuo Web does not support assistant tool calls");
    }
    const text = textFromContent(message.content);
    if (!text) continue;
    if (message.role === "system" || message.role === "developer") {
      parts.push(`System: ${text}`);
    } else if (message.role === "user") {
      parts.push(parts.length > 0 ? `User: ${text}` : text);
    } else if (message.role === "assistant") {
      parts.push(`Assistant: ${text}`);
    } else {
      throw new Error(`Hailuo Web does not support message role ${message.role}`);
    }
  }
  return parts.join("\n\n").trim();
}

export interface HailuoStreamState {
  emittedLen: number;
}

/** `message_result.content` is a cumulative snapshot, not a delta — diff it. */
export function extractHailuoMessageDelta(content: string, state: HailuoStreamState): string {
  if (typeof content !== "string" || content.length <= state.emittedLen) return "";
  const delta = content.slice(state.emittedLen);
  state.emittedLen = content.length;
  return delta;
}

export type HailuoSseLine =
  | { type: "event"; value: string }
  | { type: "data"; value: unknown }
  | null;

/** Parse a single raw SSE line. Malformed/truncated `data:` lines are swallowed, not thrown. */
export function parseHailuoLine(line: string): HailuoSseLine {
  if (line.startsWith("event:")) {
    return { type: "event", value: line.slice(6).trim() };
  }
  if (line.startsWith("data:")) {
    const raw = line.slice(5).trim();
    try {
      return { type: "data", value: JSON.parse(raw) };
    } catch {
      return null;
    }
  }
  return null;
}

export function extractHailuoMessageResultContent(data: unknown): string | null {
  const root = asRecord(data);
  const payload = asRecord(root.data);
  const messageResult = asRecord(payload.messageResult);
  return typeof messageResult.content === "string" ? messageResult.content : null;
}

function openAiChunk(id: string, created: number, modelId: string, content: string): JsonRecord {
  return {
    id,
    object: "chat.completion.chunk",
    created,
    model: modelId,
    choices: [{ index: 0, delta: { content }, finish_reason: null }],
  };
}

function openAiCompletion(id: string, created: number, modelId: string, content: string): JsonRecord {
  return {
    id,
    object: "chat.completion",
    created,
    model: modelId,
    choices: [{ index: 0, message: { role: "assistant", content }, finish_reason: "stop" }],
  };
}

export class HailuoWebExecutor extends BaseExecutor {
  constructor() {
    super("hailuo-web", { id: "hailuo-web", baseUrl: BASE_URL });
  }

  private buildStreamHeaders(token: string, yy: string): Record<string, string> {
    return {
      Accept: "text/event-stream",
      "User-Agent": USER_AGENT,
      Origin: BASE_URL,
      Referer: `${BASE_URL}/`,
      token,
      yy,
    };
  }

  private async streamToText(
    upstream: Response,
    onDelta: (delta: string) => void
  ): Promise<{ ok: boolean; errorMessage?: string }> {
    const reader = upstream.body?.getReader();
    if (!reader) return { ok: true };

    const decoder = new TextDecoder();
    const state: HailuoStreamState = { emittedLen: 0 };
    let currentEvent = "";
    let buffer = "";

    const processLine = (line: string): "continue" | "close" => {
      const parsed = parseHailuoLine(line);
      if (!parsed) return "continue";
      if (parsed.type === "event") {
        currentEvent = parsed.value;
        if (currentEvent === "close_chunk") return "close";
        return "continue";
      }
      if (currentEvent === "message_result") {
        const content = extractHailuoMessageResultContent(parsed.value);
        if (content !== null) {
          const delta = extractHailuoMessageDelta(content, state);
          if (delta) onDelta(delta);
        }
      }
      return "continue";
    };

    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || "";
        for (const line of lines) {
          if (processLine(line) === "close") return { ok: true };
        }
      }
      if (buffer) processLine(buffer);
      return { ok: true };
    } catch (error) {
      return {
        ok: false,
        errorMessage: error instanceof Error ? error.message : "Hailuo stream read failed",
      };
    }
  }

  /** Validate tool/function-call fields and fold messages into a single msgContent string. */
  private prepareMsgContent(bodyObj: JsonRecord): { msgContent: string } | { error: string } {
    const tools = bodyObj.tools;
    const functions = bodyObj.functions;
    if (tools != null && (!Array.isArray(tools) || tools.length > 0)) {
      return { error: "Hailuo Web does not support OpenAI function tools" };
    }
    if (functions != null && (!Array.isArray(functions) || functions.length > 0)) {
      return { error: "Hailuo Web does not support legacy function tools" };
    }
    try {
      const messages = Array.isArray(bodyObj.messages)
        ? (bodyObj.messages as HailuoInputMessage[])
        : [];
      const msgContent = foldHailuoMessages(messages);
      if (!msgContent) throw new Error("Hailuo Web requires a non-empty user message");
      return { msgContent };
    } catch (error) {
      return { error: error instanceof Error ? error.message : "Invalid Hailuo Web request" };
    }
  }

  /** Build the signed request: URL, headers, and the multipart form body. */
  private buildSignedRequest(
    token: string,
    providerSpecificData: unknown,
    msgContent: string
  ): { url: string; headers: Record<string, string>; form: FormData } {
    const now = Date.now();
    const pathAndQuery = buildHailuoPathAndQuery(token, providerSpecificData, now);
    const psd = asRecord(providerSpecificData);
    const characterID = toStringOrEmpty(psd.characterID) || DEFAULT_CHARACTER_ID;
    const chatID = toStringOrEmpty(psd.chatID) || DEFAULT_CHAT_ID;
    const bodyToYy = getBodyToYy(characterID, msgContent, chatID);
    const yy = generateYyHeader(pathAndQuery, bodyToYy, now);

    const form = new FormData();
    form.set("characterID", characterID);
    form.set("msgContent", msgContent);
    form.set("chatID", chatID);
    form.set("searchMode", "0");

    return { url: `${BASE_URL}${pathAndQuery}`, headers: this.buildStreamHeaders(token, yy), form };
  }

  /** POST the signed multipart request and normalize both network + upstream-status errors. */
  private async dispatch(
    url: string,
    reqHeaders: Record<string, string>,
    form: FormData,
    signal: AbortSignal | null | undefined,
    body: unknown,
    bodyObj: JsonRecord
  ): Promise<{ upstream: Response } | { errorResult: ReturnType<typeof makeErrorResult> }> {
    let upstream: Response;
    try {
      upstream = await fetch(url, { method: "POST", headers: reqHeaders, body: form, signal });
    } catch (err) {
      return {
        errorResult: {
          ...makeErrorResult(
            502,
            `Hailuo fetch failed: ${err instanceof Error ? err.message : "unknown"}`,
            body,
            url
          ),
          headers: reqHeaders,
          transformedBody: bodyObj,
        },
      };
    }
    if (!upstream.ok) {
      const errText = await upstream.text().catch(() => "");
      return {
        errorResult: {
          ...makeErrorResult(
            upstream.status,
            `Hailuo error: ${sanitizeErrorMessage(errText)}`,
            body,
            url
          ),
          headers: reqHeaders,
          transformedBody: bodyObj,
        },
      };
    }
    return { upstream };
  }

  /** Buffer the SSE stream into a single OpenAI-shaped chat.completion response. */
  private async buildNonStreamingResponse(
    upstream: Response,
    id: string,
    created: number,
    modelId: string,
    url: string,
    reqHeaders: Record<string, string>,
    body: unknown,
    bodyObj: JsonRecord
  ) {
    let answer = "";
    const result = await this.streamToText(upstream, (delta) => {
      answer += delta;
    });
    if (!result.ok) {
      return {
        ...makeErrorResult(
          502,
          `Hailuo protocol error: ${sanitizeErrorMessage(result.errorMessage || "unknown")}`,
          body,
          url
        ),
        headers: reqHeaders,
        transformedBody: bodyObj,
      };
    }
    return {
      response: new Response(JSON.stringify(openAiCompletion(id, created, modelId, answer)), {
        headers: { "Content-Type": "application/json" },
      }),
      url,
      headers: reqHeaders,
      transformedBody: bodyObj,
    };
  }

  private buildStreamingResponse(
    upstream: Response,
    id: string,
    created: number,
    modelId: string,
    signal?: AbortSignal | null
  ): ReadableStream {
    const encoder = new TextEncoder();
    return new ReadableStream({
      start: async (controller) => {
        let emittedRole = false;
        const result = await this.streamToText(upstream, (delta) => {
          if (!emittedRole) {
            emittedRole = true;
            controller.enqueue(
              encoder.encode(`data: ${JSON.stringify(openAiChunk(id, created, modelId, ""))}\n\n`)
            );
          }
          controller.enqueue(
            encoder.encode(`data: ${JSON.stringify(openAiChunk(id, created, modelId, delta))}\n\n`)
          );
        });
        if (!result.ok) {
          if (!signal?.aborted) {
            controller.error(new Error(result.errorMessage || "Hailuo stream error"));
          } else {
            try {
              controller.close();
            } catch {
              /* already closed */
            }
          }
          return;
        }
        controller.enqueue(
          encoder.encode(
            `data: ${JSON.stringify({
              id,
              object: "chat.completion.chunk",
              created,
              model: modelId,
              choices: [{ index: 0, delta: {}, finish_reason: "stop" }],
            })}\n\n`
          )
        );
        controller.enqueue(encoder.encode("data: [DONE]\n\n"));
        controller.close();
      },
    });
  }

  async execute(input: ExecuteInput) {
    const { body, credentials, signal, stream: wantStream } = input;
    const bodyObj = asRecord(body);

    const token = toStringOrEmpty(credentials?.apiKey) || toStringOrEmpty(credentials?.accessToken);
    if (!token) {
      return makeErrorResult(
        401,
        "Missing Hailuo _token — log in at hailuo.ai and capture _token from localStorage.",
        body,
        `${BASE_URL}${API_PATH}`
      );
    }

    const prepared = this.prepareMsgContent(bodyObj);
    if ("error" in prepared) {
      return makeErrorResult(400, prepared.error, body, BASE_URL);
    }

    const { url, headers: reqHeaders, form } = this.buildSignedRequest(
      token,
      credentials?.providerSpecificData,
      prepared.msgContent
    );

    const dispatched = await this.dispatch(url, reqHeaders, form, signal, body, bodyObj);
    if ("errorResult" in dispatched) return dispatched.errorResult;
    const { upstream } = dispatched;

    const id = `chatcmpl-hailuo-${Date.now()}`;
    const created = Math.floor(Date.now() / 1000);
    const modelId = input.model || "hailuo";

    if (wantStream) {
      const outStream = this.buildStreamingResponse(upstream, id, created, modelId, signal);
      return {
        response: new Response(outStream, {
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache",
            Connection: "keep-alive",
          },
        }),
        url,
        headers: reqHeaders,
        transformedBody: bodyObj,
      };
    }

    return this.buildNonStreamingResponse(upstream, id, created, modelId, url, reqHeaders, body, bodyObj);
  }
}

/**
 * ZaiWebExecutor — Z.ai Web Chat (chat.z.ai, free web-session/cookie auth)
 *
 * Distinct from the existing API-key `zai`/`glm`/`glm-cn`/`glmt` providers
 * (Anthropic/OpenAI-compatible `api.z.ai`, see `providers/apikey/regional.ts`).
 * This executor targets the *consumer chat* frontend at chat.z.ai — the same
 * product family as `chatglm.cn` (Zhipu AI), but the international domain —
 * so users without an API key can drive it for free via their browser session,
 * modeled on the `chatglm-web` credential entry (#4056) and the `doubao-web` /
 * `venice-web` cookie executors.
 *
 * Endpoint: POST https://chat.z.ai/api/v2/chat/completions
 *           (the older unversioned `/api/chat/completions` path is stale and
 *           404s model-independently as of 2026-07 — see #8014)
 * Auth:     full Cookie header from chat.z.ai (must contain the `token` JWT).
 *           Sent both as `Cookie` and as `Authorization: Bearer <token>` —
 *           the SPA's own fetch client sets both, and stripping either one
 *           has been reported (upstream repos) to 401 the request.
 * Response: SSE. Frames are z.ai's internal envelope
 *           `{"type":"chat:completion","data":{"delta_content":"...","phase":"answer","done":false}}`
 *           — mirrored from the shared Zhipu chatglm.cn/chat.z.ai frontend
 *           protocol. Some deployments/models pass through an already
 *           OpenAI-shaped `{"choices":[{"delta":{"content":"..."}}]}` frame
 *           instead, so the parser accepts both shapes defensively.
 */
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import {
  makeExecutorErrorResult as makeErrorResult,
  normalizeCookie,
  sanitizeErrorMessage,
} from "../utils/error.ts";

const BASE_URL = "https://chat.z.ai";
const CHAT_URL = `${BASE_URL}/api/v2/chat/completions`;
const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36";

/** Extract the `token` cookie value (JWT) from a full Cookie header string. */
export function extractZaiToken(rawCookie: string): string {
  const cookie = normalizeCookie(rawCookie.trim());
  if (!cookie) return "";
  const match = cookie.match(/(?:^|;\s*)token=([^;]+)/);
  if (match) return match[1].trim();
  // Users may paste the bare JWT with no `token=` prefix.
  return cookie.includes(";") || cookie.includes("=") ? "" : cookie;
}

/**
 * One parsed delta out of a z.ai SSE frame: either a content/reasoning chunk
 * or a signal that the stream has finished.
 */
export interface ZaiDelta {
  content: string;
  reasoning: string;
  done: boolean;
}

/** Parse an already OpenAI-shaped `{choices:[{delta}]}` pass-through frame. */
function parseOpenAiShapedFrame(choices: Array<Record<string, unknown>>): ZaiDelta {
  const delta = (choices[0]?.delta ?? {}) as Record<string, unknown>;
  const finishReason = choices[0]?.finish_reason;
  return {
    content: typeof delta.content === "string" ? delta.content : "",
    reasoning: typeof delta.reasoning_content === "string" ? delta.reasoning_content : "",
    done: finishReason != null,
  };
}

/** Parse the z.ai / chatglm internal `{data:{delta_content,phase,done}}` envelope. */
function parseInternalEnvelopeFrame(
  frame: Record<string, unknown>,
  data: Record<string, unknown>
): ZaiDelta | null {
  const phase = String(data.phase ?? "");
  const deltaContent = data.delta_content ?? data.edit_content ?? data.content;
  const done =
    data.done === true ||
    phase === "done" ||
    phase === "finish" ||
    String(frame.type ?? "") === "chat:completion:finish";

  if (typeof deltaContent === "string" && deltaContent) {
    const isThinking = phase === "thinking";
    return {
      content: isThinking ? "" : deltaContent,
      reasoning: isThinking ? deltaContent : "",
      done,
    };
  }
  if (done) return { content: "", reasoning: "", done: true };
  return null;
}

/**
 * Parse a single decoded z.ai SSE `data:` JSON payload into a normalized
 * delta. Handles both the internal `{data:{delta_content,phase,done}}`
 * envelope and a pass-through OpenAI-shaped `{choices:[{delta}]}` frame.
 */
export function parseZaiFrame(raw: unknown): ZaiDelta | null {
  if (!raw || typeof raw !== "object") return null;
  const frame = raw as Record<string, unknown>;

  const choices = frame.choices as Array<Record<string, unknown>> | undefined;
  if (Array.isArray(choices) && choices.length > 0) {
    return parseOpenAiShapedFrame(choices);
  }

  const data = (frame.data ?? frame) as Record<string, unknown>;
  return parseInternalEnvelopeFrame(frame, data);
}

export function foldMessages(
  messages: Array<{ role: string; content: unknown }>
): Array<{ role: string; content: string }> {
  return messages.map((m) => ({
    role: m.role,
    content: typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? ""),
  }));
}

/** Split a chunk of decoded SSE text into complete `data:` payload strings. */
function extractSseDataPayloads(buffer: { text: string }, incoming: string): string[] {
  buffer.text += incoming;
  const lines = buffer.text.split("\n");
  buffer.text = lines.pop() || "";
  const payloads: string[] = [];
  for (const line of lines) {
    if (!line.startsWith("data:")) continue;
    const data = line.slice(5).trim();
    if (!data || data === "[DONE]") continue;
    payloads.push(data);
  }
  return payloads;
}

/** Parse a raw SSE payload string into a normalized delta, or null if unusable. */
function parseSsePayload(data: string): ZaiDelta | null {
  try {
    return parseZaiFrame(JSON.parse(data));
  } catch {
    return null;
  }
}

/**
 * Read the upstream SSE body to completion, invoking `onDelta` for every
 * parsed delta. Returns true when `onDelta` signalled the stream ended
 * (returned true), false when the body was exhausted without a done delta.
 */
async function drainSseDeltas(
  sourceBody: ReadableStream<Uint8Array>,
  onDelta: (delta: ZaiDelta) => boolean
): Promise<boolean> {
  const decoder = new TextDecoder();
  const reader = sourceBody.getReader();
  const buffer = { text: "" };
  while (true) {
    const { done, value } = await reader.read();
    if (done) return false;
    const payloads = extractSseDataPayloads(buffer, decoder.decode(value, { stream: true }));
    for (const raw of payloads) {
      const delta = parseSsePayload(raw);
      if (delta && onDelta(delta)) return true;
    }
  }
}

type ChunkEmitter = (
  controller: ReadableStreamDefaultController,
  delta: Record<string, unknown>,
  finish?: string | null
) => void;

/** Emit role/reasoning/content/stop chunks for one delta. Returns true when the stream ended. */
function emitDeltaChunks(
  controller: ReadableStreamDefaultController,
  delta: ZaiDelta,
  emitChunk: ChunkEmitter,
  roleState: { emitted: boolean }
): boolean {
  if (!roleState.emitted && (delta.content || delta.reasoning)) {
    roleState.emitted = true;
    emitChunk(controller, { role: "assistant", content: "" });
  }
  if (delta.reasoning) emitChunk(controller, { reasoning_content: delta.reasoning });
  if (delta.content) emitChunk(controller, { content: delta.content });
  if (delta.done) {
    emitChunk(controller, {}, "stop");
    controller.enqueue(new TextEncoder().encode("data: [DONE]\n\n"));
    controller.close();
    return true;
  }
  return false;
}

export class ZaiWebExecutor extends BaseExecutor {
  constructor() {
    super("zai-web", { id: "zai-web", baseUrl: BASE_URL });
  }

  private buildZaiHeaders(rawCookie: string, token: string): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Accept: "text/event-stream",
      "User-Agent": USER_AGENT,
      Origin: BASE_URL,
      Referer: `${BASE_URL}/`,
    };
    if (rawCookie) headers.Cookie = rawCookie;
    if (token) headers.Authorization = `Bearer ${token}`;
    return headers;
  }

  private buildRequestBody(
    messages: Array<{ role: string; content: unknown }>,
    modelId: string
  ): Record<string, unknown> {
    return {
      stream: true,
      model: modelId,
      messages: foldMessages(messages),
      params: {},
      features: {
        image_generation: false,
        web_search: false,
        auto_web_search: false,
      },
    };
  }

  /** Drain the streaming response body into an OpenAI-shaped SSE ReadableStream. */
  private buildStreamingBody(
    sourceBody: ReadableStream<Uint8Array>,
    modelId: string,
    emitChunk: ChunkEmitter,
    signal: AbortSignal | null | undefined
  ): ReadableStream {
    return new ReadableStream({
      async start(controller) {
        const roleState = { emitted: false };
        try {
          const ended = await drainSseDeltas(sourceBody, (delta) =>
            emitDeltaChunks(controller, delta, emitChunk, roleState)
          );
          if (ended) return; // emitDeltaChunks already sent [DONE] and closed
          if (!roleState.emitted) emitChunk(controller, { role: "assistant", content: "" });
          emitChunk(controller, {}, "stop");
          controller.enqueue(new TextEncoder().encode("data: [DONE]\n\n"));
          controller.close();
        } catch (err) {
          if (!signal?.aborted) {
            try {
              controller.error(err);
            } catch {
              /* controller already closed */
            }
          }
        }
      },
    });
  }

  /** Drain the response body and aggregate all deltas into a single answer/reasoning pair. */
  private async collectNonStreaming(
    sourceBody: ReadableStream<Uint8Array>
  ): Promise<{ answer: string; reasoning: string }> {
    let answer = "";
    let reasoning = "";
    try {
      await drainSseDeltas(sourceBody, (delta) => {
        if (delta.reasoning) reasoning += delta.reasoning;
        if (delta.content) answer += delta.content;
        return delta.done;
      });
    } catch {
      /* best-effort — return what we have */
    }
    return { answer, reasoning };
  }

  /** POST the chat request upstream. Returns either the upstream Response or an error result. */
  private async fetchUpstream(
    reqHeaders: Record<string, string>,
    reqBody: Record<string, unknown>,
    body: unknown,
    signal: AbortSignal | null | undefined
  ): Promise<{ upstream: Response } | { errorResult: ReturnType<typeof makeErrorResult> }> {
    let upstream: Response;
    try {
      upstream = await fetch(CHAT_URL, {
        method: "POST",
        headers: reqHeaders,
        body: JSON.stringify(reqBody),
        signal,
      });
    } catch (err) {
      return {
        errorResult: makeErrorResult(
          502,
          `Z.ai fetch failed: ${err instanceof Error ? err.message : "unknown"}`,
          body,
          CHAT_URL
        ),
      };
    }

    if (!upstream.ok) {
      const errText = await upstream.text().catch(() => "");
      return {
        errorResult: makeErrorResult(
          upstream.status,
          `Z.ai error: ${sanitizeErrorMessage(errText)}`,
          body,
          CHAT_URL
        ),
      };
    }
    return { upstream };
  }

  private makeChunkEmitter(id: string, created: number, modelId: string): ChunkEmitter {
    return (controller, delta, finish = null) => {
      const chunk = {
        id,
        object: "chat.completion.chunk",
        created,
        model: modelId,
        choices: [{ index: 0, delta, finish_reason: finish }],
      };
      controller.enqueue(new TextEncoder().encode(`data: ${JSON.stringify(chunk)}\n\n`));
    };
  }

  async execute(input: ExecuteInput) {
    const { body, credentials, signal, stream: wantStream } = input;
    const bodyObj = (body || {}) as Record<string, unknown>;

    const rawCookie = normalizeCookie(String(credentials?.apiKey ?? "").trim());
    const token = extractZaiToken(rawCookie);
    if (!rawCookie && !token) {
      return makeErrorResult(
        400,
        "Missing Z.ai session — paste the full Cookie header from chat.z.ai (must contain token=<JWT>).",
        body,
        CHAT_URL
      );
    }

    const messages = (bodyObj.messages as Array<{ role: string; content: unknown }>) || [];
    const modelId = (bodyObj.model as string) || "glm-4.6";
    const reqBody = this.buildRequestBody(messages, modelId);
    const reqHeaders = this.buildZaiHeaders(rawCookie, token);

    const fetched = await this.fetchUpstream(reqHeaders, reqBody, body, signal);
    if ("errorResult" in fetched) return fetched.errorResult;
    const { upstream } = fetched;

    const id = `chatcmpl-zai-${Date.now()}`;
    const created = Math.floor(Date.now() / 1000);
    const sourceBody = upstream.body ?? new ReadableStream({ start: (c) => c.close() });
    const emitChunk = this.makeChunkEmitter(id, created, modelId);

    if (wantStream) {
      const outStream = this.buildStreamingBody(sourceBody, modelId, emitChunk, signal);
      return {
        response: new Response(outStream, {
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache",
            Connection: "keep-alive",
          },
        }),
        url: CHAT_URL,
        headers: reqHeaders,
        transformedBody: reqBody,
      };
    }

    const { answer, reasoning } = await this.collectNonStreaming(sourceBody);
    const message: Record<string, unknown> = { role: "assistant", content: answer };
    if (reasoning) message.reasoning_content = reasoning;
    const completion = {
      id,
      object: "chat.completion",
      created,
      model: modelId,
      choices: [{ index: 0, message, finish_reason: "stop" }],
    };
    return {
      response: new Response(JSON.stringify(completion), {
        headers: { "Content-Type": "application/json" },
      }),
      url: CHAT_URL,
      headers: reqHeaders,
      transformedBody: reqBody,
    };
  }
}

import {
  buildKimiCodeIdentityHeaders,
  getKimiCodeCliUserAgent,
  KIMI_CODING_ANTHROPIC_URL,
  KIMI_CODING_OPENAI_URL,
} from "../config/providers/registry/kimi/coding/runtime.ts";
import { FORMATS } from "../translator/formats.ts";
import { DefaultExecutor } from "./default.ts";
import type { ProviderCredentials } from "./base.ts";

type JsonRecord = Record<string, unknown>;
type KimiProtocol = "openai" | "claude";

const KIMI_CONTEXT_MANAGEMENT_BETA = "context-management-2025-06-27";

type KimiThinkingPolicy = {
  supportsThinking?: boolean;
  alwaysThinking?: boolean;
  supportedThinkingEfforts?: string[];
  defaultThinkingEffort?: string;
};

function asRecord(value: unknown): JsonRecord | null {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : null;
}

function resolveKimiProtocol(
  credentials: ProviderCredentials | null | undefined,
  body?: unknown
): KimiProtocol {
  const targetFormat = credentials?.providerSpecificData?._omnirouteKimiTargetFormat;
  if (targetFormat === FORMATS.OPENAI) return "openai";
  if (targetFormat === FORMATS.CLAUDE) return "claude";

  const record = asRecord(body);
  if (
    record?.system !== undefined ||
    record?.output_config !== undefined ||
    record?.context_management !== undefined
  ) {
    return "claude";
  }
  return "openai";
}

function getThinkingPolicy(credentials: ProviderCredentials): KimiThinkingPolicy {
  return (asRecord(credentials.providerSpecificData?._omnirouteKimiThinking) ||
    {}) as KimiThinkingPolicy;
}

function normalizeEffort(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const effort = value.trim().toLowerCase();
  if (!effort) return null;
  if (effort === "none") return "off";
  if (effort === "auto") return "on";
  return effort;
}

function resolveRequestedEffort(body: JsonRecord): string | null {
  const direct = normalizeEffort(body.reasoning_effort);
  if (direct) return direct;
  const reasoning = asRecord(body.reasoning);
  const nested = normalizeEffort(reasoning?.effort);
  if (nested) return nested;
  const thinking = asRecord(body.thinking);
  if (thinking?.type === "disabled") return "off";
  if (thinking?.type === "enabled" || thinking?.type === "adaptive") {
    return normalizeEffort(thinking.effort) || "on";
  }
  return null;
}

function constrainEffort(effort: string, policy: KimiThinkingPolicy): string {
  if (effort === "off" || effort === "on") return effort;
  const supported = policy.supportedThinkingEfforts;
  if (!Array.isArray(supported)) return effort;
  if (supported.includes(effort)) return effort;
  return policy.defaultThinkingEffort && supported.includes(policy.defaultThinkingEffort)
    ? policy.defaultThinkingEffort
    : "on";
}

function applyThinkingPolicyDefaults(
  requestedEffort: string | null,
  policy: KimiThinkingPolicy
): string | null {
  let effort = requestedEffort;
  if (!effort && policy.defaultThinkingEffort) effort = policy.defaultThinkingEffort;
  if (policy.alwaysThinking && effort === "off") {
    effort = policy.defaultThinkingEffort || "on";
  }
  if (policy.alwaysThinking && !effort) effort = policy.defaultThinkingEffort || "on";
  return effort;
}

function buildOpenAIThinking(
  effort: string,
  currentThinking: unknown,
  policy: KimiThinkingPolicy
): JsonRecord {
  const constrained = constrainEffort(effort, policy);
  const previousKeep = asRecord(currentThinking)?.keep;
  if (constrained === "off") {
    return { type: "disabled", ...(previousKeep !== undefined ? { keep: previousKeep } : {}) };
  }
  return {
    type: "enabled",
    ...(constrained !== "on" ? { effort: constrained } : {}),
    keep: previousKeep ?? "all",
  };
}

function normalizeExistingOpenAIThinking(value: unknown): JsonRecord | null {
  const thinking = asRecord(value);
  if (!thinking) return null;
  const type = thinking.type === "adaptive" ? "enabled" : thinking.type;
  return {
    ...thinking,
    ...(type ? { type } : {}),
    ...(type && type !== "disabled" && thinking.keep === undefined ? { keep: "all" } : {}),
  };
}

function applyOpenAIThinking(body: JsonRecord, policy: KimiThinkingPolicy): void {
  const requestedEffort = resolveRequestedEffort(body);
  delete body.reasoning_effort;
  delete body.reasoning;

  if (policy.supportsThinking === false) {
    delete body.thinking;
    return;
  }

  const effort = applyThinkingPolicyDefaults(requestedEffort, policy);
  if (effort) {
    body.thinking = buildOpenAIThinking(effort, body.thinking, policy);
    return;
  }

  const thinking = normalizeExistingOpenAIThinking(body.thinking);
  if (thinking) body.thinking = thinking;
}

function hasAssistantToolCalls(message: JsonRecord): boolean {
  return Array.isArray(message.tool_calls) && message.tool_calls.length > 0;
}

function backfillKimiReasoningContent(body: JsonRecord): JsonRecord {
  const thinking = asRecord(body.thinking);
  if (thinking?.keep !== "all" || thinking.type === "disabled" || !Array.isArray(body.messages)) {
    return body;
  }

  let changed = false;
  const messages = body.messages.map((message) => {
    const record = asRecord(message);
    if (
      !record ||
      record.role !== "assistant" ||
      !hasAssistantToolCalls(record) ||
      Object.hasOwn(record, "reasoning_content")
    ) {
      return message;
    }
    changed = true;
    return { ...record, reasoning_content: "" };
  });
  return changed ? { ...body, messages } : body;
}

function normalizeOpenAIRequest(
  body: JsonRecord,
  stream: boolean,
  policy: KimiThinkingPolicy
): JsonRecord {
  let next: JsonRecord = { ...body };
  if (next.max_completion_tokens === undefined && next.max_tokens !== undefined) {
    next.max_completion_tokens = next.max_tokens;
  }
  delete next.max_tokens;

  applyOpenAIThinking(next, policy);

  if (stream) {
    next.stream_options = {
      ...(asRecord(next.stream_options) || {}),
      include_usage: true,
    };
  }
  next = backfillKimiReasoningContent(next);
  return next;
}

function budgetToEffort(value: unknown): string | null {
  if (typeof value !== "number" || !Number.isFinite(value)) return null;
  if (value <= 1024) return "low";
  if (value <= 10240) return "medium";
  return "high";
}

function removeClearThinkingEdit(body: JsonRecord): void {
  const contextManagement = asRecord(body.context_management);
  if (!contextManagement || !Array.isArray(contextManagement.edits)) return;
  const edits = contextManagement.edits.filter(
    (edit) => asRecord(edit)?.type !== "clear_thinking_20251015"
  );
  if (edits.length > 0) {
    body.context_management = { ...contextManagement, edits };
  } else {
    delete body.context_management;
    const betas = Array.isArray(body.betas)
      ? body.betas.filter((beta) => beta !== KIMI_CONTEXT_MANAGEMENT_BETA)
      : null;
    if (betas?.length) body.betas = betas;
    else if (betas) delete body.betas;
  }
}

function addClearThinkingKeep(body: JsonRecord): void {
  const contextManagement = asRecord(body.context_management) || {};
  const existingEdits = Array.isArray(contextManagement.edits) ? contextManagement.edits : [];
  body.context_management = {
    ...contextManagement,
    edits: [
      { type: "clear_thinking_20251015", keep: "all" },
      ...existingEdits.filter((edit) => asRecord(edit)?.type !== "clear_thinking_20251015"),
    ],
  };
  const betas = Array.isArray(body.betas) ? body.betas : [];
  body.betas = [
    ...betas.filter((beta) => beta !== KIMI_CONTEXT_MANAGEMENT_BETA),
    KIMI_CONTEXT_MANAGEMENT_BETA,
  ];
}

function backfillKimiAnthropicThinking(body: JsonRecord): void {
  if (!Array.isArray(body.messages)) return;
  body.messages = body.messages.map((message) => {
    const record = asRecord(message);
    if (record?.role !== "assistant" || !Array.isArray(record.content)) return message;
    const content = record.content;
    if (!content.some((block) => asRecord(block)?.type === "tool_use")) return message;
    if (
      content.some((block) => {
        const type = asRecord(block)?.type;
        return type === "thinking" || type === "redacted_thinking";
      })
    ) {
      return message;
    }
    return {
      ...record,
      content: [{ type: "thinking", thinking: "" }, ...content],
    };
  });
}

function firstNormalizedEffort(...values: unknown[]): string | null {
  for (const value of values) {
    const effort = normalizeEffort(value);
    if (effort) return effort;
  }
  return null;
}

function resolveAnthropicEffort(
  body: JsonRecord,
  existingThinking: JsonRecord | null,
  outputConfig: JsonRecord | null,
  policy: KimiThinkingPolicy
): string | null {
  const reasoning = asRecord(body.reasoning);
  let effort = firstNormalizedEffort(
    body.reasoning_effort,
    reasoning?.effort,
    outputConfig?.effort,
    existingThinking?.effort
  );
  if (!effort && existingThinking?.type === "disabled") effort = "off";
  if (!effort) effort = budgetToEffort(existingThinking?.budget_tokens);
  if (!effort && (existingThinking?.type === "enabled" || existingThinking?.type === "adaptive")) {
    effort = "on";
  }
  return applyThinkingPolicyDefaults(effort, policy);
}

function applyAnthropicEffort(
  body: JsonRecord,
  effort: string | null,
  outputConfig: JsonRecord | null,
  policy: KimiThinkingPolicy
): boolean {
  if (!effort) return false;

  const constrained = constrainEffort(effort, policy);
  if (constrained === "off") {
    body.thinking = { type: "disabled" };
    delete body.output_config;
    removeClearThinkingEdit(body);
    return true;
  }

  body.thinking = { type: "enabled" };
  if (constrained === "on") {
    delete body.output_config;
  } else {
    body.output_config = { ...(outputConfig || {}), effort: constrained };
  }
  addClearThinkingKeep(body);
  backfillKimiAnthropicThinking(body);
  return true;
}

function normalizeExistingAnthropicThinking(
  body: JsonRecord,
  existingThinking: JsonRecord | null
): void {
  if (!existingThinking) return;

  const type = existingThinking.type === "adaptive" ? "enabled" : existingThinking.type;
  body.thinking = { ...(type ? { type } : {}) };
  if (type === "disabled") {
    delete body.output_config;
    removeClearThinkingEdit(body);
  } else if (type === "enabled") {
    addClearThinkingKeep(body);
    backfillKimiAnthropicThinking(body);
  }
}

function normalizeAnthropicRequest(body: JsonRecord, policy: KimiThinkingPolicy): JsonRecord {
  const next: JsonRecord = { ...body };
  const existingThinking = asRecord(next.thinking);
  const outputConfig = asRecord(next.output_config);
  const effort = resolveAnthropicEffort(next, existingThinking, outputConfig, policy);
  delete next.reasoning_effort;
  delete next.reasoning;

  if (policy.supportsThinking === false) {
    delete next.thinking;
    delete next.output_config;
    removeClearThinkingEdit(next);
    return next;
  }

  if (applyAnthropicEffort(next, effort, outputConfig, policy)) return next;
  normalizeExistingAnthropicThinking(next, existingThinking);
  return next;
}

function deleteHeaders(headers: Record<string, string>, names: string[]): void {
  const blocked = new Set(names.map((name) => name.toLowerCase()));
  for (const name of Object.keys(headers)) {
    if (blocked.has(name.toLowerCase())) delete headers[name];
  }
}

export class KimiExecutor extends DefaultExecutor {
  constructor(provider = "kimi-coding") {
    super(provider);
  }

  buildUrl(
    model: string,
    stream: boolean,
    urlIndex = 0,
    credentials: ProviderCredentials | null = null
  ): string {
    void model;
    void stream;
    void urlIndex;
    return resolveKimiProtocol(credentials) === "claude"
      ? KIMI_CODING_ANTHROPIC_URL
      : KIMI_CODING_OPENAI_URL;
  }

  buildHeaders(
    credentials: ProviderCredentials,
    stream = true,
    clientHeaders?: Record<string, string> | null
  ): Record<string, string> {
    const headers = super.buildHeaders(credentials, stream, clientHeaders);
    const protocol = resolveKimiProtocol(credentials);
    const token = headers["x-api-key"] || credentials.apiKey || credentials.accessToken || "";

    if (protocol === "claude") {
      deleteHeaders(headers, ["authorization"]);
      headers["x-api-key"] = token;
      headers["Anthropic-Version"] = "2023-06-01";
    } else {
      deleteHeaders(headers, ["x-api-key", "anthropic-version", "anthropic-beta"]);
      headers.Authorization = `Bearer ${token}`;
    }

    if (credentials.accessToken && !credentials.apiKey) {
      Object.assign(headers, buildKimiCodeIdentityHeaders(credentials.providerSpecificData || {}), {
        "User-Agent": getKimiCodeCliUserAgent(),
      });
    }
    return headers;
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ): unknown {
    const cleanedBody = super.transformRequest(model, body, stream, credentials);
    const record = asRecord(cleanedBody);
    if (!record) return cleanedBody;
    const policy = getThinkingPolicy(credentials);
    const normalized =
      resolveKimiProtocol(credentials, record) === "claude"
        ? normalizeAnthropicRequest(record, policy)
        : normalizeOpenAIRequest(record, stream, policy);
    return stream ? { ...normalized, stream: true } : normalized;
  }
}

export default KimiExecutor;

import { DefaultExecutor } from "./default.ts";
import type { ProviderCredentials } from "./base.ts";

type JsonRecord = Record<string, unknown>;

const FIXED_SAMPLING_PARAMS = [
  "temperature",
  "top_p",
  "frequency_penalty",
  "presence_penalty",
  "n",
] as const;

function asRecord(value: unknown): JsonRecord | null {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : null;
}

function normalizeMaxCompletionTokens(body: JsonRecord, ceiling: number): void {
  if (body.max_completion_tokens === undefined && body.max_tokens !== undefined) {
    body.max_completion_tokens = body.max_tokens;
  }
  delete body.max_tokens;

  if (
    typeof body.max_completion_tokens === "number" &&
    Number.isFinite(body.max_completion_tokens) &&
    body.max_completion_tokens > ceiling
  ) {
    body.max_completion_tokens = ceiling;
  }
}

function stripFixedSamplingParams(body: JsonRecord): void {
  for (const key of FIXED_SAMPLING_PARAMS) delete body[key];
}

function stripFixedTemperature(body: JsonRecord): void {
  delete body.temperature;
}

function isK2ThinkingDisabled(
  requested: string,
  enableThinking: unknown,
  existingThinking: JsonRecord | null
): boolean {
  return (
    requested === "none" ||
    requested === "off" ||
    enableThinking === false ||
    existingThinking?.type === "disabled"
  );
}

function isK2ThinkingEnabled(
  requested: string,
  enableThinking: unknown,
  existingThinking: JsonRecord | null
): boolean {
  return (
    Boolean(requested) ||
    enableThinking === true ||
    existingThinking?.type === "enabled" ||
    existingThinking?.type === "adaptive" ||
    existingThinking?.keep === "all"
  );
}

function normalizeK2Thinking(body: JsonRecord, preservedThinkingOnly: boolean): void {
  const existingThinking = asRecord(body.thinking);
  const reasoning = asRecord(body.reasoning);
  const requestedEffort = body.reasoning_effort ?? reasoning?.effort;
  const enableThinking = body.enable_thinking;
  delete body.reasoning_effort;
  delete body.reasoning;
  delete body.enable_thinking;

  if (preservedThinkingOnly) {
    body.thinking = { type: "enabled", keep: "all" };
    return;
  }

  const requested = typeof requestedEffort === "string" ? requestedEffort.toLowerCase() : "";
  const explicitlyDisabled = isK2ThinkingDisabled(requested, enableThinking, existingThinking);
  const explicitlyEnabled = isK2ThinkingEnabled(requested, enableThinking, existingThinking);

  if (explicitlyDisabled) {
    body.thinking = { type: "disabled" };
  } else if (explicitlyEnabled) {
    body.thinking = {
      type: "enabled",
      ...(existingThinking?.keep === "all" ? { keep: "all" } : {}),
    };
  } else {
    delete body.thinking;
  }
}

export function normalizeMoonshotRequest(model: string, body: unknown): unknown {
  const record = asRecord(body);
  if (!record) return body;

  const normalizedModel = model.toLowerCase();
  if (!normalizedModel.startsWith("kimi-")) return body;

  const next: JsonRecord = { ...record };
  const isK3 = /^kimi-k3(?:$|-)/.test(normalizedModel);
  const isK27 = /^kimi-k2\.7-code(?:$|-)/.test(normalizedModel);
  const isK26 = /^kimi-k2\.6(?:$|-)/.test(normalizedModel);
  const outputCeiling = isK3 ? 1048576 : 262144;

  normalizeMaxCompletionTokens(next, outputCeiling);
  if (isK3 || isK27 || isK26) {
    stripFixedSamplingParams(next);
  } else {
    stripFixedTemperature(next);
  }

  if (isK3) {
    delete next.thinking;
    delete next.enable_thinking;
    delete next.reasoning;
    next.reasoning_effort = "max";
    return next;
  }

  normalizeK2Thinking(next, isK27);
  if ((isK27 || isK26) && next.tool_choice === "required") next.tool_choice = "auto";
  return next;
}

export class MoonshotExecutor extends DefaultExecutor {
  constructor(provider = "moonshot") {
    super(provider);
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ): unknown {
    const normalized = normalizeMoonshotRequest(
      model,
      super.transformRequest(model, body, stream, credentials)
    );
    const record = asRecord(normalized);
    return stream && this.provider === "kimi" && record ? { ...record, stream: true } : normalized;
  }
}

export default MoonshotExecutor;

