/**
 * 429 response classifier — distinguish rate-limit from quota-exhausted.
 *
 * Most LLM providers return HTTP 429 for two semantically different reasons:
 *
 * 1. **Rate-limit**: short transient back-off ("too many requests in
 *    the last minute"). Fix: wait the Retry-After window and retry.
 * 2. **Quota-exhausted**: long-period cap hit ("daily/monthly limit
 *    reached"). Fix: wait until the period rolls over (could be hours
 *    or days). Retrying every 60s wastes calls and burns alerts.
 *
 * The HTTP status alone cannot disambiguate. This helper inspects the
 * response body and headers to return a `FailureKind` the circuit
 * breaker can use to pick the right cooldown.
 *
 * Companion to OmniRoute issue #2100.
 *
 * @module shared/utils/classify429
 */

export type FailureKind = "rate_limit" | "quota_exhausted" | "transient";

/**
 * Heuristic regexes for "explicit quota exhausted" vs "rate-limited"
 * detection in 429 error bodies. A 429 alone never implies quota
 * exhausted — only an explicit keyword does.
 *
 * Patterns observed across OpenAI, Anthropic, Groq, Cerebras, Mistral,
 * Google Gemini, and OpenRouter free-tier responses.
 */
const QUOTA_PATTERNS: ReadonlyArray<RegExp> = [
  /daily.*limit/i,
  /daily.*quota/i,
  /per.?day.*limit/i,
  /monthly.*limit/i,
  /monthly.*quota/i,
  /per.?month.*limit/i,
  /quota.*exceed/i,
  /exceed.*quota/i,
  /insufficient.*quota/i,
  /billing.*cap/i,
  /credit.*exhaust/i,
  /out of credits/i,
  /hard.?limit/i,
  /plan.*limit/i,

  // Antigravity / Cloud Code quota exhaustion ("Individual quota reached.
  // Contact your administrator to enable overages. Resets in 164h27m24s.").
  // None of the patterns above match it, so the 429 was misclassified as a
  // transient rate-limit and locked for only ~5s instead of the real window.
  // Keep these specific: a bare /quota reached/ would also flag transient
  // per-minute limits like "request quota reached, retry in 60s".
  /individual quota reached/i,
  /enable overages/i,
  /INSUFFICIENT_G1_CREDITS_BALANCE/i,

  // Google APIs return this generic RESOURCE_EXHAUSTED message when a
  // billing-period quota has been consumed. Keep the reset-window qualifier
  // so transient Google rate limits are not treated as long-term exhaustion.
  /resource has been exhausted.*reset after/i,

  // Cloudflare Workers AI daily neuron exhaustion (Issue #6980).
  // Body: "you have used up your daily free allocation of 10,000 neurons,
  //        please upgrade to Cloudflare's Workers Paid plan..."
  // No existing pattern matches "daily free allocation" — without this,
  // the 429 is misclassified as transient rate_limit and retried every
  // ~60s against a budget that only resets at UTC midnight.
  /daily free allocation/i,
];

/**
 * Best-effort case-insensitive header lookup.
 */
function getHeader(headers: Record<string, string> | undefined, name: string): string | undefined {
  if (!headers) return undefined;
  const target = name.toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === target) return v;
  }
  return undefined;
}

/**
 * Coerce a body of unknown shape to a string for keyword scanning.
 * - string: returned as-is
 * - object: JSON-stringified (so nested error.message gets scanned)
 * - undefined/null: empty string
 */
function bodyToText(body: unknown): string {
  if (typeof body === "string") return body;
  if (body == null) return "";
  try {
    return JSON.stringify(body);
  } catch {
    return "";
  }
}

/**
 * Returns true if the body looks like an explicit quota-exhausted
 * error — i.e. the upstream is telling us a long-period cap was hit.
 */
export function looksLikeQuotaExhausted(body: unknown): boolean {
  const text = bodyToText(body);
  if (!text) return false;
  return QUOTA_PATTERNS.some((pat) => pat.test(text));
}

/**
 * Classify a 429 (or any) response into a `FailureKind`.
 *
 * Decision order:
 * 1. status !== 429 → `"transient"` (don't pretend to know more than
 *    the caller does about non-429 failures).
 * 2. body matches a quota keyword → `"quota_exhausted"`.
 * 3. otherwise → `"rate_limit"` (default for 429 — even without
 *    Retry-After, a 429 is per definition a rate-limit signal).
 *
 * @param response - the upstream response with status, optional headers,
 *                   optional body. Headers are looked up
 *                   case-insensitively.
 */
export function classify429(response: {
  status: number;
  headers?: Record<string, string>;
  body?: unknown;
}): FailureKind {
  if (response.status !== 429) return "transient";
  if (looksLikeQuotaExhausted(response.body)) return "quota_exhausted";
  return "rate_limit";
}

/**
 * Parse a `Retry-After` header value into seconds.
 *
 * Accepts:
 * - integer seconds: `"60"`
 * - HTTP date: `"Wed, 08 May 2026 03:00:00 GMT"`
 * - Groq-style relative: `"60s"`, `"5m"`, `"2h"`
 *
 * Returns `null` if unparseable.
 *
 * Note: integer seconds vs Groq relative units are easy to confuse —
 * `parseInt("5m", 10)` returns `5` (parses leading digits and ignores
 * trailing). This helper checks the relative-unit pattern FIRST.
 */
export function parseRetryAfter(headerValue: string | undefined): number | null {
  if (!headerValue) return null;
  const trimmed = headerValue.trim();
  if (!trimmed) return null;

  // Groq-style relative: must check BEFORE plain int parse.
  const relMatch = trimmed.match(/^(\d+)([smh])$/i);
  if (relMatch) {
    const n = Number(relMatch[1]);
    const unit = relMatch[2].toLowerCase();
    if (Number.isFinite(n)) {
      if (unit === "s") return n;
      if (unit === "m") return n * 60;
      if (unit === "h") return n * 3600;
    }
  }

  // Pure integer seconds.
  if (/^\d+$/.test(trimmed)) {
    const n = Number(trimmed);
    return Number.isFinite(n) ? n : null;
  }

  // HTTP date.
  const ts = Date.parse(trimmed);
  if (Number.isFinite(ts)) {
    return Math.max(0, Math.floor((ts - Date.now()) / 1000));
  }

  return null;
}

/**
 * Convenience wrapper: pull the Retry-After from a response's headers
 * and parse it to seconds. Returns null if absent or unparseable.
 */
export function retryAfterFromResponse(response: {
  headers?: Record<string, string>;
}): number | null {
  return parseRetryAfter(getHeader(response.headers, "retry-after"));
}

/**
 * Normalize an unknown headers-like value into a plain `Record<string, string>`.
 * Native `Headers` (from `fetch`) does NOT respond to `Object.entries` — it
 * exposes `.entries()` instead. Without this normalization, `getHeader` would
 * silently miss every header on a Headers instance.
 */
function normalizeHeaders(raw: unknown): Record<string, string> | undefined {
  if (raw === null || typeof raw !== "object") return undefined;
  const maybeIter = (raw as { entries?: unknown }).entries;
  if (typeof maybeIter === "function") {
    try {
      return Object.fromEntries((raw as { entries: () => Iterable<[string, string]> }).entries());
    } catch {
      // fall through to plain-object treatment
    }
  }
  return raw as Record<string, string>;
}

/**
 * Adapter that takes an error thrown by an HTTP client (fetch wrapper, axios,
 * upstream SDK, etc.) and produces a {@link FailureKind} suitable for the
 * `classifyError` option of the circuit breaker.
 *
 * Recognises the common error shapes:
 * - `err.status` + `err.headers` + `err.body` (low-level fetch wrapper)
 * - `err.response.status` + `err.response.headers` + `err.response.data` (axios-style)
 * - `err.message` (last-resort body for keyword scan)
 *
 * Returns `undefined` when the error doesn't carry enough information to
 * classify, so the breaker can decide what to do without a kind tag.
 *
 * Companion to issue #2100 follow-up.
 */
export function classify429FromError(err: unknown): FailureKind | undefined {
  if (err === null || typeof err !== "object") return undefined;
  const e = err as Record<string, unknown>;

  let status: number | undefined;
  let headers: Record<string, string> | undefined;
  let body: unknown;

  if (typeof e.status === "number") {
    status = e.status;
  }
  if (typeof e.statusCode === "number" && status === undefined) {
    status = e.statusCode;
  }

  if (e.response && typeof e.response === "object") {
    const resp = e.response as Record<string, unknown>;
    if (typeof resp.status === "number" && status === undefined) {
      status = resp.status;
    }
    if (resp.headers && typeof resp.headers === "object") {
      headers = normalizeHeaders(resp.headers);
    }
    if (resp.data !== undefined) {
      body = resp.data;
    } else if (typeof resp.body !== "undefined") {
      body = resp.body;
    }
  }

  if (headers === undefined && e.headers && typeof e.headers === "object") {
    headers = normalizeHeaders(e.headers);
  }
  if (body === undefined) {
    if (typeof e.body !== "undefined") {
      body = e.body;
    } else if (typeof e.message === "string") {
      body = e.message;
    }
  }

  if (typeof status !== "number") return undefined;
  return classify429({ status, headers, body });
}

/**
 * Per-provider default policy for upstream 429 hint trust.
 *
 * @see Issue #2100 follow-up — surface a user-overridable per-profile toggle
 * that decides whether the circuit breaker uses upstream 429 body / Retry-After
 * hints (`classify429`, `cooldownByKind`) to differentiate rate-limit from
 * quota-exhausted failure cooldowns.
 *
 * This helper returns the **default** answer for a given provider. The actual
 * runtime decision is the user override (if any) OR this default. See
 * `accountFallback.ts` / `chat.ts` / `chatHelpers.ts` for the resolution
 * call sites:
 *
 * ```ts
 * const userValue = providerProfile.useUpstream429BreakerHints; // boolean | undefined
 * const useHints  = userValue !== undefined
 *   ? userValue
 *   : defaultUseUpstream429BreakerHints(provider);
 * ```
 *
 * Default policy: direct cloud providers default `true` because their 429
 * bodies and `Retry-After` headers are authoritative. Reverse-proxy /
 * self-hosted / CLI-backed providers default `false` because forwarded 429
 * metadata is often unreliable or fabricated by the proxy.
 *
 * @module shared/utils/providerHints
 */

import {
  UPSTREAM_PROXY_PROVIDERS,
  SELF_HOSTED_CHAT_PROVIDER_IDS,
  isLocalProvider,
  isClaudeCodeCompatibleProvider,
} from "../constants/providers";

/**
 * Conservative per-provider default for `useUpstream429BreakerHints`.
 *
 * Returns `false` for any provider whose 429 metadata may be forwarded by
 * an intermediary (proxy, self-hosted runtime, CLI wrapper). Returns `true`
 * for direct cloud providers where the upstream response is authoritative.
 */
export function defaultUseUpstream429BreakerHints(providerId: string): boolean {
  if (Object.prototype.hasOwnProperty.call(UPSTREAM_PROXY_PROVIDERS, providerId)) {
    return false;
  }
  if (isLocalProvider(providerId)) {
    return false;
  }
  if (SELF_HOSTED_CHAT_PROVIDER_IDS.has(providerId)) {
    return false;
  }
  if (isClaudeCodeCompatibleProvider(providerId)) {
    return false;
  }
  return true;
}

/**
 * Resolve the effective `useHints` decision: the user override wins if set,
 * otherwise fall back to the per-provider default.
 *
 * `undefined` means "not user-set" and triggers the default lookup.
 */
export function resolveUseUpstream429BreakerHints(
  providerId: string,
  userValue: boolean | undefined
): boolean {
  if (userValue !== undefined) {
    return userValue;
  }
  return defaultUseUpstream429BreakerHints(providerId);
}

const ANTIGRAVITY_PROVIDER_ID = "antigravity";

export type AntigravityQuotaFamily = "gemini" | "claude" | "other";

function normalizeModelId(model: string | null | undefined): string {
  return String(model || "")
    .trim()
    .toLowerCase();
}

/**
 * Classify Antigravity models by the quota bucket Google Cloud Code/Antigravity
 * appears to enforce. This is intentionally conservative:
 * - gemini-* / google/gemini-* variants share the Gemini family quota.
 * - claude-* and legacy cloud-* aliases are treated as the Claude/Cloud family.
 * - unknown models remain exact-model scoped for compatibility.
 */
export function getAntigravityQuotaFamily(
  model: string | null | undefined
): AntigravityQuotaFamily {
  const normalized = normalizeModelId(model).replace(/^(antigravity|agy)\//, "");
  const slashIndex = normalized.indexOf("/");
  const bare = slashIndex >= 0 ? normalized.slice(slashIndex + 1) : normalized;

  if (bare.startsWith("gemini-") || bare.includes("/gemini-") || bare.includes("gemini")) {
    return "gemini";
  }
  if (
    bare.startsWith("claude-") ||
    bare.startsWith("cloud-") ||
    bare.includes("/claude-") ||
    bare.includes("/cloud-") ||
    bare.includes("anthropic")
  ) {
    return "claude";
  }
  return "other";
}

export function getQuotaScopedModelForProvider(
  provider: string | null | undefined,
  model: string | null | undefined
): string | null {
  if (!model) return null;
  if (provider !== "antigravity" && provider !== "agy") return model;
  const family = getAntigravityQuotaFamily(model);
  return family === "other" ? model : `family:${family}`;
}

export function getQuotaScopeLabelForProvider(
  provider: string | null | undefined,
  model: string | null | undefined
): string {
  if (provider !== "antigravity" && provider !== "agy") return "model";
  return getAntigravityQuotaFamily(model) === "other" ? "model" : "family";
}

/**
 * In-memory request/token counters for Gemini models — tracks both RPD (daily),
 * RPM (sliding 60s window), and TPM (sliding 60s token window) so that 429
 * responses can be classified as either quota_exhausted (RPD hit),
 * rate_limit_exceeded (RPM hit), or token_rate_exceeded (TPM hit).
 *
 * Gemini returns identical error bodies for all three, so we rely on
 * published per-model limits from geminiRateLimits.json to distinguish them.
 *
 * Counters are incremented on every Gemini request so that once usage
 * reaches the published limit, subsequent 429s are correctly classified.
 */

import geminiLimits from "../config/geminiRateLimits.json";

// ── RPD (daily) state ────────────────────────────────────────────────────────

interface DailyCount {
  date: string; // "YYYY-MM-DD"
  count: number;
}

const dailyCounts = new Map<string, DailyCount>();

// ── RPM (sliding 60s window) state ───────────────────────────────────────────

const minuteWindows = new Map<string, number[]>();

// ── TPM (sliding 60s token window) state ─────────────────────────────────────

const tokenWindows = new Map<string, number[]>();

// ── Helpers ──────────────────────────────────────────────────────────────────

function toDateKey(): string {
  return new Date().toISOString().slice(0, 10);
}

function stripModelPrefix(modelId: string): string {
  // Only strip the "gemini/" provider prefix, never "gemini-" which is part
  // of the actual model name (e.g. "gemini-2.5-flash", "gemini-3.5-live-translate").
  return modelId.replace(/^gemini\//, "").trim();
}

function lookupValue(modelId: string, field: "rpm" | "rpd" | "tpm"): number {
  if (!modelId) return 0;
  const key = stripModelPrefix(modelId);
  const entry = (geminiLimits as Record<string, Record<string, number>>)[key];
  if (!entry) {
    for (const [knownKey, knownEntry] of Object.entries(geminiLimits)) {
      if (key.endsWith(knownKey) || knownKey.endsWith(key)) {
        const val = knownEntry[field];
        return typeof val === "number" && val > 0 ? val : 0;
      }
    }
    return 0;
  }
  const val = entry[field];
  return typeof val === "number" && val > 0 ? val : 0;
}

// ── RPD exports ──────────────────────────────────────────────────────────────

export function getModelRpd(modelId: string): number {
  return lookupValue(modelId, "rpd");
}

export function incrementDailyRequestCount(modelId: string): void {
  if (!modelId) return;
  const key = stripModelPrefix(modelId);
  const today = toDateKey();
  const existing = dailyCounts.get(key);
  if (existing && existing.date === today) {
    existing.count++;
  } else {
    dailyCounts.set(key, { date: today, count: 1 });
  }
}

export function getDailyRequestCount(modelId: string): number {
  if (!modelId) return 0;
  const key = stripModelPrefix(modelId);
  const today = toDateKey();
  const entry = dailyCounts.get(key);
  if (entry && entry.date === today) return entry.count;
  return 0;
}

export function isRpdExhausted(modelId: string): boolean {
  const rpd = getModelRpd(modelId);
  if (rpd <= 0) return false;
  return getDailyRequestCount(modelId) >= rpd;
}

// ── RPM exports ──────────────────────────────────────────────────────────────

export function getModelRpm(modelId: string): number {
  return lookupValue(modelId, "rpm");
}

/** Prune timestamps older than 60 seconds from a model's window. */
function pruneMinuteWindow(key: string): void {
  const now = Date.now();
  const cutoff = now - 60_000;
  const timestamps = minuteWindows.get(key);
  if (!timestamps) return;
  let i = 0;
  while (i < timestamps.length && timestamps[i] < cutoff) i++;
  if (i > 0) {
    minuteWindows.set(key, timestamps.slice(i));
  }
}

function pruneTokenWindow(key: string): void {
  const now = Date.now();
  const cutoff = now - 60_000;
  const entries = tokenWindows.get(key);
  if (!entries) return;
  let i = 0;
  while (i < entries.length && entries[i] < cutoff) i += 2;
  if (i > 0) {
    tokenWindows.set(key, entries.slice(i));
  }
}

export function incrementMinuteRequestCount(modelId: string): void {
  if (!modelId) return;
  const key = stripModelPrefix(modelId);
  pruneMinuteWindow(key);
  const timestamps = minuteWindows.get(key) ?? [];
  timestamps.push(Date.now());
  minuteWindows.set(key, timestamps);
}

export function getMinuteRequestCount(modelId: string): number {
  if (!modelId) return 0;
  const key = stripModelPrefix(modelId);
  pruneMinuteWindow(key);
  return minuteWindows.get(key)?.length ?? 0;
}

export function isRpmExhausted(modelId: string): boolean {
  const rpm = getModelRpm(modelId);
  if (rpm <= 0) return false;
  return getMinuteRequestCount(modelId) >= rpm;
}

// ── TPM exports ──────────────────────────────────────────────────────────────

export function getModelTpm(modelId: string): number {
  return lookupValue(modelId, "tpm");
}

/**
 * Record prompt token consumption for a Gemini model.
 * Allows the per-minute token pre-check to avoid 429s.
 */
export function incrementTokenUsage(modelId: string, promptTokens: number): void {
  if (!modelId || !Number.isFinite(promptTokens) || promptTokens <= 0) return;
  const key = stripModelPrefix(modelId);
  pruneTokenWindow(key);
  const entries = tokenWindows.get(key) ?? [];
  entries.push(Date.now(), promptTokens);
  tokenWindows.set(key, entries);
}

export function getMinuteTokenCount(modelId: string): number {
  if (!modelId) return 0;
  const key = stripModelPrefix(modelId);
  pruneTokenWindow(key);
  const entries = tokenWindows.get(key);
  if (!entries) return 0;
  let total = 0;
  for (let i = 1; i < entries.length; i += 2) {
    total += entries[i];
  }
  return total;
}

export function isTpmExhausted(modelId: string): boolean {
  const tpm = getModelTpm(modelId);
  if (tpm <= 0) return false;
  return getMinuteTokenCount(modelId) >= tpm;
}

// ── Text-based metric classification ─────────────────────────────────────────

/**
 * Extract which quota class ("rpd" | "rpm" | "tpm") a Gemini 429 error text
 * names, directly from Google's own metric identifier — e.g.:
 *   "Quota exceeded for metric: generativelanguage.googleapis.com/
 *    generate_content_free_tier_input_token_count, limit: 16000"
 *
 * This is authoritative (Google's own signal) and must be checked BEFORE the
 * local usage counters (isRpdExhausted/isRpmExhausted/isTpmExhausted): those
 * counters only increment via `incrementTokenUsage`/`incrementRequestCount`,
 * which fire AFTER a request completes successfully. A request that gets
 * REJECTED — especially the first of several concurrent requests that all
 * trip the same per-minute limit before any of them completes — never
 * contributes to the local counter, so `isTpmExhausted` reads 0 at the exact
 * moment it needs to return true, and the generic "quota exceeded" text
 * classifier (which matches ALL Gemini 429 bodies, per the file header)
 * mis-classifies a genuine TPM/RPM burst as QUOTA_EXHAUSTED (midnight lockout)
 * instead of RATE_LIMIT_EXCEEDED (short cooldown).
 */
export function classifyGeminiQuotaMetricFromText(
  errorText: string | null | undefined
): "rpd" | "rpm" | "tpm" | null {
  if (!errorText) return null;
  const lower = errorText.toLowerCase();
  if (!lower.includes("generativelanguage.googleapis.com")) return null;
  if (lower.includes("_per_day") || lower.includes("per day")) return "rpd";
  if (lower.includes("input_token_count") || lower.includes("token_count")) return "tpm";
  if (lower.includes("_requests")) return "rpm";
  return null;
}

// ── Increment both (convenience) ─────────────────────────────────────────────

/** Increment both daily and minute counters for a Gemini request. */
export function incrementRequestCount(modelId: string): void {
  incrementDailyRequestCount(modelId);
  incrementMinuteRequestCount(modelId);
}

// ── Composite check ──────────────────────────────────────────────────────────

/** Returns true if either RPM or TPM is exhausted for this model. */
export function isMinuteRateExhausted(modelId: string): boolean {
  return isRpmExhausted(modelId) || isTpmExhausted(modelId);
}

// ── Reset (testing) ──────────────────────────────────────────────────────────

export function resetCounters(): void {
  dailyCounts.clear();
  minuteWindows.clear();
  tokenWindows.clear();
}

type JsonRecord = Record<string, unknown>;

function objectRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function positiveCappedMs(value: unknown, maxMs: number): number | null {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.min(value, maxMs)
    : null;
}

function futureTimestampMs(value: unknown, maxMs: number): number | null {
  if (typeof value !== "string") return null;
  const parsedTs = Date.parse(value);
  if (!Number.isFinite(parsedTs)) return null;
  const waitMs = parsedTs - Date.now();
  return waitMs > 0 ? Math.min(waitMs, maxMs) : null;
}

// RetryInfo.retryDelay / "please retry in Ns" are short per-request throttling
// hints (Gemini free-tier RPM/TPM), not long-lived quota resets like Antigravity's
// "Resets in 160h" — cap them independently of the caller's maxMs so a malformed or
// adversarial upstream value cannot masquerade as a multi-day reset (#7940).
export const MAX_SHORT_RETRY_HINT_MS = 24 * 60 * 60 * 1000; // 24h

/**
 * Parse delay strings like "33s", "26.660853464s", "2m", "1h", "1500ms", or a bare
 * number of seconds. Shared by `parseRetryAfterFromBody` (rateLimitManager wiring)
 * and `parseRetryHintFromJsonBody` (model-lockout wiring) so both honor the same
 * upstream `RetryInfo.retryDelay` grammar (#7940).
 */
export function parseDelayString(value: unknown): number | null {
  if (!value) return null;
  const str = String(value).trim();
  const msMatch = /^(\d+(?:\.\d+)?)\s*ms$/i.exec(str);
  if (msMatch) return Math.round(Number.parseFloat(msMatch[1]));
  const secMatch = /^(\d+(?:\.\d+)?)\s*s$/i.exec(str);
  if (secMatch) return Math.round(Number.parseFloat(secMatch[1]) * 1000);
  const minMatch = /^(\d+(?:\.\d+)?)\s*m$/i.exec(str);
  if (minMatch) return Math.round(Number.parseFloat(minMatch[1]) * 60 * 1000);
  const hrMatch = /^(\d+(?:\.\d+)?)\s*h$/i.exec(str);
  if (hrMatch) return Math.round(Number.parseFloat(hrMatch[1]) * 3600 * 1000);
  // Bare number → seconds
  const num = Number.parseFloat(str);
  return Number.isFinite(num) ? Math.round(num * 1000) : null;
}

// Gemini/Google RPC 429 bodies embed the short throttle hint as
// `error.details[].{"@type": ".../google.rpc.RetryInfo", "retryDelay": "26s"}`.
function retryInfoDetailsMs(details: unknown): number | null {
  for (const detail of Array.isArray(details) ? details : []) {
    const detailRecord = objectRecord(detail);
    const type = String(detailRecord["@type"] ?? "");
    if (!type.includes("RetryInfo")) continue;
    const ms = parseDelayString(detailRecord.retryDelay);
    if (ms !== null && ms > 0) return Math.min(ms, MAX_SHORT_RETRY_HINT_MS);
  }
  return null;
}

/**
 * Parse Retry-After hints from a 429 JSON response body. Providers use both
 * top-level and nested `error` fields for ISO timestamps and millisecond values.
 */
export function parseRetryHintFromJsonBody(body: string, maxMs: number): number | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    return null;
  }

  const root = objectRecord(parsed);
  if (!Object.keys(root).length) return null;
  const errorObj = objectRecord(root.error);

  const retryInfoMs = retryInfoDetailsMs(errorObj.details ?? root.details);
  if (retryInfoMs !== null) return retryInfoMs;

  const isoHint = futureTimestampMs(errorObj.retryAfter ?? root.retryAfter, maxMs);
  if (isoHint !== null) return isoHint;

  return positiveCappedMs(
    errorObj.retry_after_ms ?? root.retry_after_ms ?? errorObj.retryAfterMs ?? root.retryAfterMs,
    maxMs
  );
}

/**
 * Text-based quota-exhaustion classifiers for the account-fallback engine.
 *
 * Extracted out of `accountFallback.ts` (frozen at its file-size-baseline
 * cap — see `config/quality/file-size-baseline.json`) so a new quota-text
 * signal (Issue #3709) could be added without growing that file. These are
 * pure functions with no dependency back on `accountFallback.ts`, so there
 * is no circular import (`npm run check:cycles`).
 *
 * @module services/quotaTextCooldowns
 */

import { RateLimitReason } from "../config/constants.ts";

type RateLimitReasonValue = (typeof RateLimitReason)[keyof typeof RateLimitReason];

export interface QuotaTextFallback {
  shouldFallback: true;
  cooldownMs: number;
  reason: RateLimitReasonValue;
  usedUpstreamRetryHint?: boolean;
  quotaResetHintMs?: number;
}

// ─── Issue #2321 — Subscription (5h) usage-limit text ──────────────────────
//
// Anthropic OAuth (Claude Pro/Team) returns 429 with "Usage Limit Reached"
// for the 5-hour subscription quota. Without a dedicated branch the request
// falls through to the generic 429 retry path (~5s base cooldown).

export function isSubscriptionQuotaText(lower: string, provider?: string | null): boolean {
  return (
    lower.includes("usage limit reached") ||
    lower.includes("usage limit has been") ||
    lower.includes("claude pro usage limit") ||
    lower.includes("you've reached your usage limit") ||
    lower.includes("you have reached your usage limit") ||
    // Native Claude OAuth uses this otherwise-generic 429 wording for an
    // exhausted subscription window. Keep it provider-scoped: other upstreams
    // can use the same phrase for a short RPM throttle.
    (provider === "claude" &&
      lower.includes("this request would exceed your account's rate limit"))
  );
}

const SUBSCRIPTION_QUOTA_COOLDOWN_MS = 60 * 60 * 1000; // 1 hour

/**
 * Builds the QUOTA_EXHAUSTED fallback for the subscription-quota text above.
 * Honor upstream Retry-After / reset hints only when the caller's profile
 * enables them (via `getUpstreamRetryHintMs`); otherwise apply a local 1h
 * cooldown so all Pro accounts on the same subscription tier stop cycling
 * through tight retries. (We deliberately do not use COOLDOWN_MS.paymentRequired
 * — that constant is 2 minutes, shorter than the recovery time of a
 * subscription quota.)
 *
 * `getUpstreamRetryHintMs`/`parseRetryFromErrorText` are injected by the
 * caller (accountFallback.ts) to avoid importing back into that file.
 */
export function buildSubscriptionQuotaFallback(
  errorStr: string,
  getUpstreamRetryHintMs: () => number | null,
  parseRetryFromErrorText: (text: string) => number | null,
  provider?: string | null
): QuotaTextFallback | null {
  if (!isSubscriptionQuotaText(errorStr.toLowerCase(), provider)) return null;
  const hintMs = getUpstreamRetryHintMs();
  const bodyHint = parseRetryFromErrorText(errorStr);
  return {
    shouldFallback: true,
    cooldownMs: hintMs ?? SUBSCRIPTION_QUOTA_COOLDOWN_MS,
    reason: RateLimitReason.QUOTA_EXHAUSTED,
    usedUpstreamRetryHint: Boolean(hintMs),
    quotaResetHintMs: bodyHint ?? undefined,
  };
}

// ─── Issue #3709 — Ollama Cloud weekly usage cap ───────────────────────────
//
// Ollama Cloud free-tier accounts have a hard WEEKLY request cap. On cap the
// upstream returns 429 "you (<account>) have reached your weekly usage
// limit". ollama-cloud is an apikey-category provider (not oauth), so the
// `shouldUseQuotaSignal` gate in `checkFallbackError` (oauth-only) skips the
// subscription-quota-text branch above for its 429s — without a dedicated,
// ungated check the account fell through to the generic 429 backoff
// (~1s, capped at 2min) and got retried every few minutes for the rest of
// the week (one account took 285x429 in 48h — issue #3709).
//
// The exact weekly reset anchor (UTC Monday? rolling 7d from first request?)
// is not publicly documented by Ollama, so this uses a fixed 24h cooldown —
// short enough to recover promptly once the real window resets, long enough
// to stop the every-5-minute retry storm. The phrase match is generic (not
// ollama-specific), so any other provider using the same wording benefits.
const WEEKLY_QUOTA_COOLDOWN_MS = 24 * 60 * 60 * 1000; // 24 hours

export function isWeeklyUsageLimitText(lower: string): boolean {
  return (
    lower.includes("weekly usage limit") ||
    lower.includes("weekly limit reached") ||
    lower.includes("reached your weekly")
  );
}

export function buildWeeklyQuotaFallback(errorStr: string): QuotaTextFallback | null {
  if (!isWeeklyUsageLimitText(errorStr.toLowerCase())) return null;
  return {
    shouldFallback: true,
    cooldownMs: WEEKLY_QUOTA_COOLDOWN_MS,
    reason: RateLimitReason.QUOTA_EXHAUSTED,
  };
}

// ─── Issue #7071 — Ollama Cloud 5-hour SESSION usage cap ───────────────────
//
// Ollama Cloud also enforces a rolling 5-hour "session" usage cap, sibling to
// the weekly cap above (#3709/#6638). On cap the upstream returns 429 with a
// body like "you (<account>) have reached your session usage limit". Same
// root cause as the weekly gap: neither the generic subscription-quota-text
// classifier nor the weekly one recognize "session" wording, so the account
// fell through to the generic 429 backoff and got retried within the same
// 5-hour window instead of cooling down for it — combo/LKGP routing cycled
// back to the "exhausted" account instead of advancing to the next one.
//
// Patterns are scoped to "session ... usage limit" / "session limit reached"
// / "reached your session ... usage limit" phrasing (not a bare "session"
// match) so unrelated "session expired"/"session token invalid" auth errors
// from other providers are not misclassified as quota-exhausted.
const SESSION_QUOTA_COOLDOWN_MS = 5 * 60 * 60 * 1000; // 5 hours

export function isSessionUsageLimitText(lower: string): boolean {
  return (
    lower.includes("session usage limit") ||
    lower.includes("session limit reached") ||
    (lower.includes("reached your session") && lower.includes("usage limit"))
  );
}

export function buildSessionQuotaFallback(errorStr: string): QuotaTextFallback | null {
  if (!isSessionUsageLimitText(errorStr.toLowerCase())) return null;
  return {
    shouldFallback: true,
    cooldownMs: SESSION_QUOTA_COOLDOWN_MS,
    reason: RateLimitReason.QUOTA_EXHAUSTED,
  };
}

import { looksLikeQuotaExhausted } from "../../src/shared/utils/classify429";
import { getProviderCategory } from "../config/providerRegistry.ts";

/**
 * Issue #6638 — Ollama Cloud (and any other apikey-category provider) 429s
 * skip body-text quota classification by default: a bare 429 usually just
 * means "too many requests/min" for these providers, so a short exponential
 * backoff applies instead of the long cooldown reserved for genuine
 * daily/monthly/weekly quota exhaustion.
 *
 * That default is correct for plain rate limiting, but it must not swallow
 * an EXPLICIT quota-exhausted signal in the body (see `looksLikeQuotaExhausted`
 * / QUOTA_PATTERNS) — otherwise the account looks "available" again seconds
 * after a multi-day quota was exhausted, and combo routing retries it right
 * away (the reported symptom). OAuth-category providers always preserve
 * quota signals; apikey-category providers only do when the body explicitly
 * says a long-period cap was hit.
 */
export function shouldPreserveQuotaSignals(
  provider: string | null | undefined,
  errorText?: string | null
): boolean {
  if (!provider) return true;
  if (getProviderCategory(provider) === "oauth") return true;
  return Boolean(errorText) && looksLikeQuotaExhausted(errorText);
}

/**
 * Parse a day-granularity quota reset countdown ("Your quota will reset in
 * 3 days.", "Resets in 13 days") out of an upstream 429 body.
 *
 * Companion to the Xh/Ym/Zs countdown parsing already handled inline by
 * `parseRetryFromErrorText` — none of those patterns match when the upstream
 * expresses the reset window in whole days rather than hours/minutes/seconds,
 * so a multi-day quota reset previously parsed to `null` and fell back to the
 * engine's ~seconds-scale default cooldown.
 */
export function parseDayGranularityResetMs(msg: string, maxMs: number): number | null {
  const dayMatch = /reset(?:s)?\s+in\s+(\d+)\s*day(?:s)?/i.exec(msg);
  if (!dayMatch) return null;
  const days = Number.parseInt(dayMatch[1], 10);
  if (!Number.isFinite(days) || days <= 0) return null;
  return Math.min(days * 24 * 3600 * 1000, maxMs);
}

/**
 * accountFallback/lockoutEviction.ts — model-lockout map eviction (cap enforcement).
 *
 * Extracted from services/accountFallback.ts (file-size gate, #6923): the bounded-growth
 * eviction sweep for the in-memory `modelLockouts` / `modelFailureState` maps. Pure w.r.t.
 * module state — operates only on the maps passed in by the caller — so it is independently
 * testable and reusable outside accountFallback.ts, which wraps evictLockoutOverflow() with
 * its own private map instances and re-exports MODEL_LOCKOUT_EVICTION_CAP.
 */

import type { ModelLockoutEntry, ModelFailureState } from "../accountFallback.ts";

// Cap prevents unbounded growth under sustained load. Entries beyond this limit
// are evicted (oldest first, in insertion order) during the periodic cleanup.
export const MODEL_LOCKOUT_EVICTION_CAP = 1000;

/**
 * Evict oldest (insertion-order) entries once a map exceeds the cap — but NEVER a
 * still-active (until > now) lockout: cleanupModelLockKey() has already run on every
 * key this tick, so anything active left here is a real, in-progress cooldown, and
 * dropping it would wrongly let routing resume to it. If a map is still over cap
 * purely from active entries, the cap is a soft bound in that rare case rather than
 * a correctness trade-off.
 */
export function evictLockoutOverflow(
  modelLockouts: Map<string, ModelLockoutEntry>,
  modelFailureState: Map<string, ModelFailureState>,
  cap: number = MODEL_LOCKOUT_EVICTION_CAP
): void {
  if (modelLockouts.size > cap) {
    const overflow = modelLockouts.size - cap;
    const now = Date.now();
    // Only expired entries are eviction candidates (oldest-first, up to the
    // overflow count) — active ones never appear in this list at all.
    const evictableKeys = [...modelLockouts.entries()]
      .filter(([, entry]) => entry.until <= now)
      .slice(0, overflow)
      .map(([key]) => key);
    for (const key of evictableKeys) {
      modelLockouts.delete(key);
      modelFailureState.delete(key);
    }
  }
  if (modelFailureState.size > cap) {
    const overflow = modelFailureState.size - cap;
    let evicted = 0;
    for (const key of modelFailureState.keys()) {
      if (evicted >= overflow) break;
      if (!modelLockouts.has(key)) modelFailureState.delete(key);
      evicted++;
    }
  }
}

/**
 * accountFallback/cooldownCap.ts — absolute ceiling for exponentially-scaled cooldowns.
 *
 * Extracted from services/accountFallback.ts (file-size gate): a pure, one-purpose clamp
 * so the connection-level 429/retryable-error cooldown path (getScaledBaseCooldown, inside
 * checkFallbackError) applies the same absolute ceiling the model-lockout path
 * (recordModelLockoutFailure) already enforces. Fixes #8396 — after a sustained 429 burst
 * pushed backoffLevel high, `baseCooldownMs * 2^level` had no upper bound on this path and
 * could black a connection out for hours, long past any real rate-limit reset window.
 */

/**
 * Clamp an exponentially-scaled cooldown to `maxCooldownMs` (operator-configured, per
 * ProviderProfile) falling back to `fallbackMaxMs` (e.g. BACKOFF_CONFIG.max) when the
 * profile did not configure one. Never widens the cooldown, only bounds it — the
 * exponential backoff itself is untouched.
 */
export function capScaledCooldownMs(
  cooldownMs: number,
  maxCooldownMs: number | undefined | null,
  fallbackMaxMs: number
): number {
  const cap =
    typeof maxCooldownMs === "number" && maxCooldownMs > 0 ? maxCooldownMs : fallbackMaxMs;
  return Math.min(cooldownMs, cap);
}

/**
 * #8775 — Detect Cloudflare (and similar edge) errors that explicitly forbid
 * retries. When these bodies are misclassified as short AUTH_ERROR cooldowns,
 * OmniRoute waits 3× for a permanent client-signature ban and burns 21–33s
 * before falling through to the next combo tier.
 *
 * Kept as a pure helper so checkFallbackError stays within its file-size freeze
 * and every branch is unit-testable without DB/auth wiring.
 */

function tryParseJsonObject(text: string): Record<string, unknown> | null {
  const trimmed = text.trim();
  if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) return null;
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
  } catch {
    // Body may be truncated HTML/JSON hybrids — fall through to string probes.
  }
  return null;
}

function hasCloudflareBanSignal(value: unknown): boolean {
  if (typeof value === "number") return value === 1010;
  if (typeof value !== "string") return false;
  const lower = value.toLowerCase();
  return (
    lower.includes("browser_signature_banned") ||
    lower.includes("error 1010") ||
    lower === "1010" ||
    lower.includes("cloudflare")
  );
}

/**
 * Returns true when upstream error text says the failure must not be retried —
 * Cloudflare error 1010 / browser_signature_banned, or an explicit
 * `retryable: false` paired with Cloudflare / owner_action_required signals.
 */
export function isNonRetryableCloudflareError(errorText: string | null | undefined): boolean {
  if (typeof errorText !== "string" || errorText.length === 0) return false;

  const obj = tryParseJsonObject(errorText);
  if (obj) {
    const retryable = obj.retryable;
    const errorCode = obj.error_code ?? obj.errorCode;
    const errorName = typeof obj.error_name === "string" ? obj.error_name : "";
    const cloudflareError = obj.cloudflare_error === true || obj.cloudflareError === true;
    const ownerActionRequired =
      obj.owner_action_required === true || obj.ownerActionRequired === true;

    if (errorCode === 1010 || errorCode === "1010") return true;
    if (errorName.toLowerCase() === "browser_signature_banned") return true;
    if (retryable === false && (cloudflareError || ownerActionRequired)) return true;
    if (retryable === false && hasCloudflareBanSignal(obj.title ?? obj.type ?? obj.detail)) {
      return true;
    }
  }

  // Non-JSON / nested-string fallbacks (logs often stringify the body).
  if (/browser_signature_banned/i.test(errorText)) return true;
  if (/"error_code"\s*:\s*1010\b/.test(errorText)) return true;
  if (
    /"retryable"\s*:\s*false/.test(errorText) &&
    (/"cloudflare_error"\s*:\s*true/.test(errorText) ||
      /"owner_action_required"\s*:\s*true/.test(errorText) ||
      /cloudflare/i.test(errorText))
  ) {
    return true;
  }

  return false;
}

type ApiKeyForbiddenFallback = {
  shouldFallback: boolean;
  cooldownMs: number;
  reason: string;
  baseCooldownMs?: number;
  newBackoffLevel?: number;
  usedUpstreamRetryHint?: boolean;
};

/**
 * Api-key 403 branch helper (#8775): CF 1010 / retryable:false gets cooldown 0
 * so COOLDOWN_RETRY does not wait; other 403s keep the short retryable cooldown.
 */
export function resolveApiKeyForbiddenFallback(
  errorStr: string,
  buildRetryableFallback: (reason: string) => ApiKeyForbiddenFallback,
  authErrorReason: string
): ApiKeyForbiddenFallback {
  if (isNonRetryableCloudflareError(errorStr)) {
    return { shouldFallback: true, cooldownMs: 0, reason: authErrorReason };
  }
  return buildRetryableFallback(authErrorReason);
}

/**
 * GrokCliExecutor — Grok Build Provider
 *
 * Routes Responses API requests through Grok's chat proxy using OAuth authentication.
 * The standard BaseExecutor transport provides streaming, retries, abort propagation,
 * proxy-aware fetch dispatch, upstream-header merging, and credential-refresh persistence.
 */

import { PROVIDERS } from "../config/constants.ts";
import {
  getGrokBuildSessionHeaders,
  GROK_BUILD_DEFAULT_REASONING_EFFORT,
  GROK_BUILD_REASONING_INCLUDE,
  GROK_BUILD_RESPONSES_URL,
  GROK_BUILD_TOKEN_URL,
} from "../config/grokBuild.ts";
import { resolvePublicCred } from "../utils/publicCreds.ts";
import { BaseExecutor, type ExecutorLog, type ProviderCredentials } from "./base.ts";

const GROK_BUILD_MAX_TOOLS = 200;
const GROK_BUILD_SUPPORTED_REASONING_EFFORTS = new Set(["low", "medium", "high"]);
const GROK_BUILD_REFRESH_MAX_ATTEMPTS = 3;
const GROK_BUILD_REFRESH_MIN_DELAY_MS = 200;
const GROK_BUILD_TERMINAL_REFRESH_ERRORS = new Set(["invalid_grant", "invalid_client"]);
const GROK_BUILD_UNSUPPORTED_PARAMS = [
  "presencePenalty",
  "frequencyPenalty",
  "logprobs",
  "topLogprobs",
  "presence_penalty",
  "frequency_penalty",
  "top_logprobs",
  "reasoning_effort",
];


/**
 * Grok Build's cli-chat-proxy is stricter about Responses `function_call_output.output`
 * than OpenAI's Responses API. Agent tool results can contain truncated / incomplete
 * JSON strings or invalid `\uXXXX` escapes, which fail upstream with:
 *   Failed to parse the request body as JSON: input[N].output: unexpected end of hex escape
 *
 * Normalize outputs to valid JSON text (or plain text) before dispatch (#7611).
 */
function sanitizeGrokBuildFunctionCallOutput(output: unknown): string {
  if (output == null) return "";
  if (typeof output === "string") {
    const value = output;
    try {
      return JSON.stringify(JSON.parse(value));
    } catch {
      // fall through
    }
    // Drop incomplete \u escapes (0-3 hex digits) that break strict JSON parsers.
    const repaired = value.replace(/\\u([0-9A-Fa-f]{0,3})(?![0-9A-Fa-f])/g, "");
    try {
      return JSON.stringify(JSON.parse(repaired));
    } catch {
      return repaired.replace(/[\uD800-\uDFFF]/g, "\uFFFD");
    }
  }
  if (Array.isArray(output)) {
    const textParts = output
      .map((part) => {
        if (part && typeof part === "object") {
          const rec = part as Record<string, unknown>;
          if (typeof rec.text === "string") return rec.text;
        }
        return typeof part === "string" ? part : JSON.stringify(part);
      })
      .join("\n");
    return sanitizeGrokBuildFunctionCallOutput(textParts);
  }
  try {
    return JSON.stringify(output);
  } catch {
    return String(output);
  }
}

function sanitizeGrokBuildResponsesBody(body: Record<string, unknown>): Record<string, unknown> {
  const input = body.input;
  if (!Array.isArray(input)) return body;
  let changed = false;
  const nextInput = input.map((item) => {
    if (!item || typeof item !== "object") return item;
    const rec = item as Record<string, unknown>;
    if (rec.type !== "function_call_output") return item;
    const sanitized = sanitizeGrokBuildFunctionCallOutput(rec.output);
    if (sanitized === rec.output) return item;
    changed = true;
    return { ...rec, output: sanitized };
  });
  return changed ? { ...body, input: nextInput } : body;
}

type GrokBuildRefreshResult = Partial<ProviderCredentials> | null | undefined;

function nonEmptyString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function getRefreshRetryDelayMs(retryNumber: number): number {
  const baseDelay = Math.min(
    2_000,
    GROK_BUILD_REFRESH_MIN_DELAY_MS * 2 ** Math.max(0, retryNumber - 1)
  );
  return Math.max(1, Math.round(baseDelay * (0.5 + Math.random())));
}

function asRequestRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? { ...(value as Record<string, unknown>) }
    : {};
}

function ensureReasoningInclude(value: unknown): unknown[] {
  const include = Array.isArray(value) ? [...value] : [];
  if (!include.includes(GROK_BUILD_REASONING_INCLUDE)) {
    include.push(GROK_BUILD_REASONING_INCLUDE);
  }
  return include;
}

function normalizeGrokBuildReasoning(
  value: unknown,
  model: string
): Record<string, unknown> | null {
  const reasoning = asRequestRecord(value);
  const hasExplicitEffort = Object.prototype.hasOwnProperty.call(reasoning, "effort");
  if (!GROK_BUILD_SUPPORTED_REASONING_EFFORTS.has(String(reasoning.effort))) {
    delete reasoning.effort;
  }
  if (model === "grok-composer-2.5-fast") {
    delete reasoning.effort;
  } else if (model === "grok-4.5" && !hasExplicitEffort) {
    reasoning.effort = GROK_BUILD_DEFAULT_REASONING_EFFORT;
  }
  return Object.keys(reasoning).length > 0 ? reasoning : null;
}

function stripUnsupportedGrokBuildParams(request: Record<string, unknown>): void {
  for (const param of GROK_BUILD_UNSUPPORTED_PARAMS) {
    delete request[param];
  }
}

async function refreshGrokBuildCredentialsOnce(
  body: URLSearchParams,
  credentials: ProviderCredentials,
  attempt: number,
  log?: ExecutorLog | null
): Promise<GrokBuildRefreshResult> {
  try {
    const response = await fetch(GROK_BUILD_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body,
      signal: AbortSignal.timeout(15_000),
    });
    const data = (await response.json().catch(() => ({}))) as Record<string, unknown>;

    if (!response.ok) {
      const errorCode = nonEmptyString(data.error);
      const isTerminal =
        attempt === GROK_BUILD_REFRESH_MAX_ATTEMPTS ||
        (errorCode !== null && GROK_BUILD_TERMINAL_REFRESH_ERRORS.has(errorCode));
      log?.warn?.("TOKEN_REFRESH", `Grok Build: refresh failed with status ${response.status}`);
      return isTerminal ? null : undefined;
    }

    const accessToken = nonEmptyString(data.access_token);
    if (!accessToken) {
      log?.warn?.("TOKEN_REFRESH", "Grok Build: no access_token in refresh response");
      return attempt === GROK_BUILD_REFRESH_MAX_ATTEMPTS ? null : undefined;
    }

    const expiresIn =
      typeof data.expires_in === "number" && Number.isFinite(data.expires_in) && data.expires_in > 0
        ? data.expires_in
        : 21600;
    const expiresAt = new Date(Date.now() + expiresIn * 1000).toISOString();

    log?.info?.("TOKEN_REFRESH", `Grok Build: token refreshed, expires ${expiresAt}`);

    return {
      accessToken,
      refreshToken: nonEmptyString(data.refresh_token) || credentials.refreshToken,
      expiresAt,
    };
  } catch (error) {
    log?.warn?.(
      "TOKEN_REFRESH",
      `Grok Build: refresh error: ${error instanceof Error ? error.message : String(error)}`
    );
    return attempt === GROK_BUILD_REFRESH_MAX_ATTEMPTS ? null : undefined;
  }
}

export class GrokCliExecutor extends BaseExecutor {
  constructor() {
    super("grok-cli", PROVIDERS["grok-cli"]);
  }

  buildUrl(
    _model: string,
    _stream: boolean,
    _urlIndex = 0,
    _credentials: ProviderCredentials | null = null
  ) {
    return GROK_BUILD_RESPONSES_URL;
  }

  async refreshCredentials(
    credentials: ProviderCredentials,
    log?: ExecutorLog | null
  ): Promise<Partial<ProviderCredentials> | null> {
    if (!credentials?.refreshToken) {
      log?.warn?.("TOKEN_REFRESH", "Grok Build: no refresh token available");
      return null;
    }

    const clientId = resolvePublicCred("grok_id", "GROK_OAUTH_CLIENT_ID");

    const body = new URLSearchParams({
      grant_type: "refresh_token",
      client_id: clientId,
      refresh_token: credentials.refreshToken,
    });

    const providerData = credentials.providerSpecificData || {};
    const principalType = nonEmptyString(providerData.principalType);
    const principalId = nonEmptyString(providerData.principalId);
    if (principalType) body.set("principal_type", principalType);
    if (principalId) body.set("principal_id", principalId);

    for (let attempt = 1; attempt <= GROK_BUILD_REFRESH_MAX_ATTEMPTS; attempt++) {
      if (attempt > 1) {
        const delayMs = getRefreshRetryDelayMs(attempt - 1);
        log?.debug?.(
          "TOKEN_REFRESH",
          `Grok Build: retrying token refresh (${attempt}/${GROK_BUILD_REFRESH_MAX_ATTEMPTS})`
        );
        await new Promise((resolve) => setTimeout(resolve, delayMs));
      }

      const refreshed = await refreshGrokBuildCredentialsOnce(body, credentials, attempt, log);
      if (refreshed !== undefined) return refreshed;
    }

    return null;
  }

  buildHeaders(
    credentials: ProviderCredentials,
    stream = true,
    clientHeaders?: Record<string, string> | null,
    model?: string
  ) {
    const headers = super.buildHeaders(credentials, stream, clientHeaders, model);
    const providerData = credentials.providerSpecificData || {};
    const principalType = nonEmptyString(providerData.principalType);
    const sessionHeaders = getGrokBuildSessionHeaders({
      model,
      stream,
      userId: nonEmptyString(providerData.userId),
      email: nonEmptyString(credentials.email) || nonEmptyString(providerData.email),
      principalType,
    });

    // Preserve the standard GROK_CLI_USER_AGENT override produced by BaseExecutor.
    if (headers["User-Agent"] || headers["user-agent"]) {
      delete sessionHeaders["User-Agent"];
    }

    return { ...headers, ...sessionHeaders };
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    _credentials: ProviderCredentials
  ) {
    const base = super.transformRequest(model, body, stream, _credentials);
    const transformed = asRequestRecord(base);
    if (!transformed.model) {
      transformed.model = model || "grok-composer-2.5-fast";
    }
    transformed.stream = !!stream;

    // Grok Build applies these Responses defaults before every request.
    if (transformed.store === undefined) transformed.store = false;
    transformed.include = ensureReasoningInclude(transformed.include);

    // OpenAI-compatible clients may carry fields the Grok Responses endpoint rejects.
    stripUnsupportedGrokBuildParams(transformed);

    const reasoning = normalizeGrokBuildReasoning(transformed.reasoning, model);
    if (reasoning) {
      transformed.reasoning = reasoning;
    } else {
      delete transformed.reasoning;
    }

    // xAI's cli-chat-proxy rejects requests containing more than 200 tools.
    if (Array.isArray(transformed.tools) && transformed.tools.length > GROK_BUILD_MAX_TOOLS) {
      transformed.tools = transformed.tools.slice(0, GROK_BUILD_MAX_TOOLS);
    }

    // Repair tool-result payloads that would fail Grok's strict JSON body parser (#7611).
    return sanitizeGrokBuildResponsesBody(transformed);
  }
}

import { DefaultExecutor } from "./default.ts";
import type { ProviderCredentials } from "./base.ts";

/**
 * CodeBuddyCnExecutor — talks to https://copilot.tencent.com/v2/chat/completions
 *
 * CodeBuddy CN is an OpenAI-compatible Tencent gateway but it rejects non-stream
 * chat requests (HTTP 400, code 11101 "Non-stream chat request is currently not
 * supported"). The same-format (openai→openai) translator path leaves body.stream
 * as the client sent it, so we force it true here — OmniRoute still re-aggregates
 * the SSE into a JSON response for non-streaming clients.
 *
 * Reasoning params are opt-in: reasoning_summary:"auto" is only added when the
 * client explicitly sets reasoning_effort. Plain requests are left untouched.
 * When the caller explicitly asks for "none"/"off" we drop the field entirely
 * (the gateway has no "none" value). Forcing reasoning on plain requests trips
 * CodeBuddy's content filter and returns an error.
 */
export class CodeBuddyCnExecutor extends DefaultExecutor {
  constructor() {
    super("codebuddy-cn");
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ): unknown {
    const transformed = super.transformRequest(model, body, stream, credentials);
    if (!transformed || typeof transformed !== "object" || Array.isArray(transformed)) {
      return transformed;
    }
    const out = transformed as Record<string, unknown>;
    out.stream = true;

    const eff = out.reasoning_effort;
    if (eff === "none" || eff === "off") {
      // Gateway has no "none" — just omit. Do NOT set reasoning_summary.
      delete out.reasoning_effort;
    } else if (eff) {
      // Client explicitly asked for reasoning — mirror the CLI's reasoning_summary
      // so CodeBuddy surfaces the model's reasoning.
      out.reasoning_summary = "auto";
    }
    // No reasoning requested: leave both unset. Forcing reasoning_effort:"medium"
    // + reasoning_summary on plain requests makes CodeBuddy trip its content
    // filter and return an error.
    return out;
  }
}

export default CodeBuddyCnExecutor;

/**
 * ZenmuxFreeExecutor — ZenMux Free (web-cookie) provider
 *
 * Accesses ZenMux's free-tier LLM gateway via session cookies exported from
 * the browser. Uses ZenMux's Anthropic-compatible SSE endpoint, translating
 * the response to OpenAI-format chunks for OmniRoute consumers.
 *
 * Endpoint: POST https://zenmux.ai/api/anthropic/v1/messages
 * Auth: Full cookie header string from zenmux.ai (must include ctoken)
 */
import { randomUUID } from "crypto";
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import { makeExecutorErrorResult as makeErrorResult, normalizeCookie } from "../utils/error.ts";

const CHAT_URL = "https://zenmux.ai/api/anthropic/v1/messages";
const USER_AGENT =
  "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36";

function extractCtoken(cookieStr: string): string {
  const m = cookieStr.match(/ctoken=([^;]+)/);
  return m ? m[1] : "";
}

export class ZenmuxFreeExecutor extends BaseExecutor {
  constructor() {
    super("zenmux-free", { id: "zenmux-free", baseUrl: CHAT_URL });
  }

  async execute(input: ExecuteInput) {
    const { body, credentials, signal, stream: wantStream } = input;
    const bodyObj = (body || {}) as Record<string, unknown>;

    const rawCookie = normalizeCookie(String(credentials?.apiKey ?? "").trim());
    const ctoken = extractCtoken(rawCookie);
    if (!ctoken) {
      return makeErrorResult(
        401,
        "ZenMux Free: ctoken not found in cookies. Export all cookies from zenmux.ai and paste as the credential.",
        body,
        CHAT_URL
      );
    }

    const messages = (
      bodyObj.messages as Array<{ role: string; content: unknown }>
    ) || [];
    const modelId = (bodyObj.model as string) || "deepseek/deepseek-chat";
    const maxTokens = (bodyObj.max_tokens as number) || 4096;

    // Flatten messages into a single user text to accommodate ZenMux's
    // Anthropic-compatible endpoint (which is the upstream's pattern).
    const userMessages = messages.filter((m) => m.role === "user");
    const sysMessages = messages.filter((m) => m.role === "system");
    const lastUser = userMessages[userMessages.length - 1];
    const userText =
      typeof lastUser?.content === "string"
        ? lastUser.content
        : JSON.stringify(lastUser?.content ?? "Hello");
    const sysText =
      sysMessages.length > 0
        ? typeof sysMessages[0].content === "string"
          ? sysMessages[0].content
          : JSON.stringify(sysMessages[0].content)
        : null;
    const fullText = sysText ? `${sysText}\n\n${userText}` : userText;

    const reqId = randomUUID().replace(/-/g, "");

    const anthropicBody: Record<string, unknown> = {
      model: modelId,
      max_tokens: maxTokens,
      messages: [{ role: "user", content: [{ type: "text", text: fullText }] }],
      stream: true,
    };
    if (bodyObj.temperature !== undefined) anthropicBody.temperature = bodyObj.temperature;

    const url = new URL(CHAT_URL);
    url.searchParams.set("ctoken", ctoken);

    const reqHeaders: Record<string, string> = {
      "Content-Type": "application/json",
      "User-Agent": USER_AGENT,
      Accept: "text/event-stream",
      Origin: "https://zenmux.ai",
      Referer: "https://zenmux.ai/platform/chat",
      "anthropic-version": "2023-06-01",
      "chat-request-id": reqId,
      "x-zenmux-accept-processing": "true, true",
      "x-zenmux-apikey-source": "subscription",
    };
    if (rawCookie) reqHeaders.Cookie = rawCookie;

    let upstream: Response;
    try {
      upstream = await fetch(url.toString(), {
        method: "POST",
        headers: reqHeaders,
        body: JSON.stringify(anthropicBody),
        signal,
      });
    } catch (err) {
      return makeErrorResult(
        502,
        `ZenMux Free fetch failed: ${err instanceof Error ? err.message : "unknown"}`,
        body,
        CHAT_URL
      );
    }

    if (!upstream.ok) {
      if (upstream.status === 401 || upstream.status === 403) {
        return makeErrorResult(401, "ZenMux Free: cookies expired or invalid", body, CHAT_URL);
      }
      if (upstream.status === 402) {
        return makeErrorResult(402, "ZenMux Free: free-tier quota exhausted", body, CHAT_URL);
      }
      const errText = await upstream.text().catch(() => "");
      return makeErrorResult(upstream.status, `ZenMux Free error: ${errText}`, body, CHAT_URL);
    }

    const cid = `chatcmpl-zmf-${randomUUID().slice(0, 12)}`;
    const created = Math.floor(Date.now() / 1000);

    if (!wantStream) {
      // Collect SSE text from the Anthropic-format stream
      const txt = await collectText(upstream.body);
      return {
        response: new Response(
          JSON.stringify({
            id: cid,
            object: "chat.completion",
            created,
            model: modelId,
            choices: [
              {
                index: 0,
                message: { role: "assistant", content: txt },
                finish_reason: "stop",
              },
            ],
            usage: { prompt_tokens: 0, completion_tokens: Math.ceil(txt.length / 4), total_tokens: 0 },
          }),
          { headers: { "Content-Type": "application/json" } }
        ),
        url: CHAT_URL,
        headers: reqHeaders,
        transformedBody: anthropicBody,
      };
    }

    // Streaming: translate Anthropic SSE → OpenAI SSE
    const encoder = new TextEncoder();
    const decoder = new TextDecoder();
    const responseStream = new ReadableStream({
      async start(controller) {
        const reader = upstream.body?.getReader();
        if (!reader) {
          controller.close();
          return;
        }
        // Send role delta first
        controller.enqueue(
          encoder.encode(
            `data: ${JSON.stringify({
              id: cid,
              object: "chat.completion.chunk",
              created,
              model: modelId,
              choices: [{ index: 0, delta: { role: "assistant" }, finish_reason: null }],
            })}\n\n`
          )
        );
        let buffer = "";
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split("\n");
            buffer = lines.pop() || "";
            for (const line of lines) {
              const t = line.trim();
              if (!t.startsWith("data: ")) continue;
              const raw = t.slice(6);
              if (raw === "[DONE]") {
                controller.enqueue(encoder.encode("data: [DONE]\n\n"));
                continue;
              }
              try {
                const d = JSON.parse(raw) as Record<string, unknown>;
                const delta = d.delta as Record<string, unknown> | undefined;
                if (d.type === "content_block_delta" && delta) {
                  const text = (delta.text as string) || (delta.thinking as string) || "";
                  if (text) {
                    controller.enqueue(
                      encoder.encode(
                        `data: ${JSON.stringify({
                          id: cid,
                          object: "chat.completion.chunk",
                          created,
                          model: modelId,
                          choices: [{ index: 0, delta: { content: text }, finish_reason: null }],
                        })}\n\n`
                      )
                    );
                  }
                } else if (d.type === "message_delta" && delta) {
                  controller.enqueue(
                    encoder.encode(
                      `data: ${JSON.stringify({
                        id: cid,
                        object: "chat.completion.chunk",
                        created,
                        model: modelId,
                        choices: [
                          {
                            index: 0,
                            delta: {},
                            finish_reason: (delta.stop_reason as string) || "stop",
                          },
                        ],
                      })}\n\n`
                    )
                  );
                }
              } catch {
                // malformed SSE chunk — skip silently
              }
            }
          }
        } catch (err) {
          if (!signal?.aborted) controller.error(err);
        } finally {
          controller.enqueue(encoder.encode("data: [DONE]\n\n"));
          controller.close();
        }
      },
    });

    return {
      response: new Response(responseStream, {
        headers: {
          "Content-Type": "text/event-stream",
          "Cache-Control": "no-cache",
          Connection: "keep-alive",
        },
      }),
      url: CHAT_URL,
      headers: reqHeaders,
      transformedBody: anthropicBody,
    };
  }
}

/** Collect text from an Anthropic-format SSE stream body. */
async function collectText(body: ReadableStream<Uint8Array> | null): Promise<string> {
  if (!body) return "";
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  let txt = "";
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true });
    const lines = buf.split("\n");
    buf = lines.pop() || "";
    for (const ln of lines) {
      const t = ln.trim();
      if (!t.startsWith("data: ")) continue;
      try {
        const d = JSON.parse(t.slice(6)) as Record<string, unknown>;
        const delta = d.delta as Record<string, unknown> | undefined;
        if (d.type === "content_block_delta" && delta) {
          txt += (delta.text as string) || (delta.thinking as string) || "";
        }
      } catch {
        // skip
      }
    }
  }
  return txt;
}

/**
 * HyperAgentExecutor — hyperagent.com agent chat (Unofficial/Experimental)
 *
 * Reverse-engineered from SPA captures (2026-07-21, hyperagent/*.txt):
 *   - New thread: GET /threads/new (Next.js) → redirect /thread/{cuid}
 *   - Chat: POST /api/threads/{threadId}/chat  (SSE data: lines)
 *   - First turn: sessionId=null → session_start event yields sessionId
 *   - Follow-up: same threadId + sessionId in body
 *   - Stream events: text / thinking / session_start / session_end / done / [DONE]
 *   - Auth: browser Cookie header (credentials:include)
 *   - Credits: GET /api/settings/billing/usage (usage/hyperagent.ts)
 *
 * OpenAI multi-turn is preserved via sticky thread+session cache (PromptQL-style).
 */
import { createHash, randomUUID } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import { makeExecutorErrorResult as makeErrorResult } from "../utils/error.ts";
import {
  HYPERAGENT_FALLBACK_MODELS,
  clientFacingHyperAgentModelId,
  resolveHyperAgentModel,
  wireHyperAgentModelId,
  wireHyperAgentRuntimeId,
  wireHyperAgentSubagentModelId,
} from "../services/hyperagentModels.ts";

const ORIGIN = "https://hyperagent.com";
const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36";
const THREAD_CACHE_MAX = 200;

// ─── Types ──────────────────────────────────────────────────────────────────

interface ChatMessage {
  role: string;
  content: unknown;
}

interface HyperAgentRequestBody {
  messages?: ChatMessage[];
  model?: string;
  hyperagent_thread_id?: string;
  thread_id?: string;
  session_id?: string;
  hyperagent_session_id?: string;
}

type ThreadBinding = {
  threadId: string;
  sessionId: string;
  projectKey: string;
  updatedAt: number;
};

// ─── Credential helpers ─────────────────────────────────────────────────────

function readStr(v: unknown): string {
  if (typeof v !== "string") return "";
  const t = v.trim();
  return t.length ? t : "";
}

function readPs(data: unknown, keys: readonly string[]): string {
  if (!data || typeof data !== "object" || Array.isArray(data)) return "";
  const rec = data as Record<string, unknown>;
  for (const k of keys) {
    const v = readStr(rec[k]);
    if (v) return v;
  }
  return "";
}

/** Normalize pasted cookie: full Cookie header or bare value. */
export function normalizeHyperAgentCookie(raw: string): string {
  const t = (raw || "").trim();
  if (!t) return "";
  // Strip accidental "Cookie: " prefix
  return t.replace(/^Cookie:\s*/i, "").trim();
}

export function resolveHyperAgentCredentials(credentials: ExecuteInput["credentials"]): {
  cookie: string;
} {
  const direct =
    readStr(credentials?.apiKey) ||
    readStr((credentials as Record<string, unknown> | undefined)?.cookie) ||
    readStr((credentials as Record<string, unknown> | undefined)?.accessToken);
  const ps = credentials?.providerSpecificData;
  const cookie = normalizeHyperAgentCookie(
    direct || readPs(ps, ["cookie", "sessionCookie", "authCookie", "Cookie"])
  );
  return { cookie };
}

// ─── Message helpers ────────────────────────────────────────────────────────

/**
 * Flatten message content for chat + fingerprints.
 * Handles OpenAI string/parts and Anthropic content blocks (tool_use / tool_result).
 * Without tool_result extraction, Claude Code multi-turn sends empty lastUserText
 * and HyperAgent drops the tool output entirely.
 */
export function extractMessageText(content: unknown): string {
  if (typeof content === "string") return content;
  if (content == null) return "";
  if (Array.isArray(content)) {
    return content
      .map((part) => {
        if (typeof part === "string") return part;
        if (!part || typeof part !== "object") return "";
        const p = part as Record<string, unknown>;
        const type = typeof p.type === "string" ? p.type.toLowerCase() : "";

        // Anthropic tool_result — content may be string or nested parts
        if (type === "tool_result" || type === "function_result") {
          const name = typeof p.name === "string" ? p.name : "tool";
          const body = extractMessageText(p.content ?? p.output ?? p.result ?? "");
          return body ? `[tool result ${name}]\n${body}` : `[tool result ${name}]`;
        }

        // Anthropic tool_use — include so fingerprints / observations stay non-empty
        if (type === "tool_use" || type === "function_call" || type === "tool_call") {
          const name = typeof p.name === "string" ? p.name : "tool";
          let args = "";
          if (p.input != null) {
            try {
              args = typeof p.input === "string" ? p.input : JSON.stringify(p.input);
            } catch {
              args = String(p.input);
            }
          } else if (typeof p.arguments === "string") {
            args = p.arguments;
          }
          return args ? `[tool call ${name}] ${args}` : `[tool call ${name}]`;
        }

        if (typeof p.text === "string") return p.text;
        if (typeof p.content === "string") return p.content;
        if (p.content != null && typeof p.content !== "string") {
          return extractMessageText(p.content);
        }
        return "";
      })
      .filter(Boolean)
      .join("\n");
  }
  if (content && typeof content === "object") {
    const o = content as Record<string, unknown>;
    if (typeof o.text === "string") return o.text;
    if (typeof o.content === "string") return o.content;
  }
  return "";
}

function lastUserText(messages: ChatMessage[]): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    const role = (messages[i]?.role || "").toLowerCase();
    if (role === "user" || role === "human" || role === "tool" || role === "function") {
      return extractMessageText(messages[i]!.content).trim();
    }
  }
  return "";
}

// ─── Sticky thread cache ────────────────────────────────────────────────────

const memoryThreads = new Map<string, ThreadBinding>();

function threadCachePath(): string | null {
  const dataDir = process.env.DATA_DIR || process.env.OMNIROUTE_DATA_DIR;
  if (!dataDir) return null;
  return join(dataDir, "hyperagent-thread-sessions.json");
}

function loadThreadDisk(): Record<string, ThreadBinding> {
  const p = threadCachePath();
  if (!p || !existsSync(p)) return {};
  try {
    return JSON.parse(readFileSync(p, "utf8")) as Record<string, ThreadBinding>;
  } catch {
    return {};
  }
}

function saveThreadDisk(map: Record<string, ThreadBinding>) {
  const p = threadCachePath();
  if (!p) return;
  try {
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, JSON.stringify(map), "utf8");
  } catch {
    /* best-effort */
  }
}

function getThreadBinding(key: string): ThreadBinding | null {
  if (!key) return null;
  const mem = memoryThreads.get(key);
  if (mem) return mem;
  const disk = loadThreadDisk()[key];
  if (disk) {
    memoryThreads.set(key, disk);
    return disk;
  }
  return null;
}

function setThreadBinding(key: string, binding: ThreadBinding) {
  if (!key) return;
  memoryThreads.set(key, binding);
  const disk = loadThreadDisk();
  disk[key] = binding;
  const keys = Object.keys(disk);
  if (keys.length > THREAD_CACHE_MAX) {
    keys
      .sort((a, b) => (disk[a]!.updatedAt || 0) - (disk[b]!.updatedAt || 0))
      .slice(0, keys.length - THREAD_CACHE_MAX)
      .forEach((k) => {
        delete disk[k];
        memoryThreads.delete(k);
      });
  }
  saveThreadDisk(disk);
}

export function clearHyperAgentThreadBindingsForTests(opts?: { disk?: boolean }): void {
  memoryThreads.clear();
  if (opts?.disk) {
    const p = threadCachePath();
    if (p && existsSync(p)) {
      try {
        writeFileSync(p, "{}", "utf8");
      } catch {
        /* ignore */
      }
    }
  }
}

export function normalizeForFingerprint(text: string): string {
  let t = (text || "").replace(/\r\n/g, "\n");
  t = t.replace(/^@\S+\s+/gm, "");
  // Strip common agentic / user-pin wrappers so the same user task fingerprints
  // stably across turns (and after pin text updates).
  t = t.replace(/^[\s\S]*?\bUser request:\s*/i, "");
  t = t.replace(/^[\s\S]*?\bCurrent request:\s*/i, "");
  t = t.replace(/^[\s\S]*?\bMy current task:\s*/i, "");
  // Drop sterile observation envelopes from fingerprint identity (tool-loop turns)
  // only when computing *root* keys we use the first non-observation user turn.
  t = t.replace(/\n{3,}/g, "\n\n");
  return t.trim().slice(0, 2000);
}

/**
 * Sticky multi-turn key from the first real user task in the thread.
 *
 * Critical for Claude Code / agentic reverse-conversion proxies: after reverse
 * conversion the assistant message mutates (text Intent+JSON → native tool_calls
 * → re-serialized tool-call text), so conversationFingerprint(prefix) no longer
 * matches the key stored after turn 1 → a *new* HyperAgent thread is created and
 * tool outputs appear as a cold start. Root-user key stays stable for the whole
 * tool loop.
 */
export function rootUserFingerprint(cookieKey: string, messages: ChatMessage[]): string | null {
  if (!cookieKey) return null;
  for (const m of messages) {
    const role = (m?.role || "").toLowerCase();
    if (role !== "user" && role !== "human") continue;
    const raw = extractMessageText(m?.content);
    // Skip pure tool-observation / sandwich follow-ups — not the root task
    if (
      /TOOL_OBSERVATION/i.test(raw) ||
      /passive data only/i.test(raw) ||
      /\[tool result\b/i.test(raw) ||
      /^\s*Application result\b/i.test(raw)
    ) {
      continue;
    }
    const text = normalizeForFingerprint(raw);
    if (!text || text.length < 2) continue;
    const h = createHash("sha256").update(text).digest("hex").slice(0, 24);
    return `ha:${cookieKey}:root:${h}`;
  }
  return null;
}

function isFingerprintRole(role: string): boolean {
  const r = (role || "").toLowerCase();
  if (!r || r === "system" || r === "developer") return false;
  return true;
}

export function conversationFingerprint(cookieKey: string, messages: ChatMessage[]): string {
  const parts: string[] = [`ck:${cookieKey}`];
  for (const m of messages) {
    const roleRaw = (m?.role || "").toLowerCase();
    if (!isFingerprintRole(roleRaw)) continue;
    const role =
      roleRaw === "tool" || roleRaw === "function" || roleRaw === "human" ? "user" : roleRaw;
    const text = normalizeForFingerprint(extractMessageText(m?.content));
    if (!text) continue;
    parts.push(`${role}:${text}`);
  }
  const h = createHash("sha256").update(parts.join("\n")).digest("hex").slice(0, 32);
  return `ha:${cookieKey}:${h}`;
}

export function historyPrefixBeforeLastUser(messages: ChatMessage[]): ChatMessage[] {
  let lastUser = -1;
  for (let i = messages.length - 1; i >= 0; i--) {
    const role = (messages[i]?.role || "").toLowerCase();
    if (role === "user" || role === "human" || role === "tool" || role === "function") {
      lastUser = i;
      break;
    }
  }
  if (lastUser <= 0) return [];
  return messages.slice(0, lastUser);
}

export function hasAssistantMessage(messages: ChatMessage[]): boolean {
  return messages.some((m) => {
    const r = (m?.role || "").toLowerCase();
    return r === "assistant" || r === "ai" || r === "model";
  });
}

export function lastAssistantFingerprint(
  cookieKey: string,
  messages: ChatMessage[]
): string | null {
  for (let i = messages.length - 1; i >= 0; i--) {
    const role = (messages[i]?.role || "").toLowerCase();
    if (role !== "assistant" && role !== "ai" && role !== "model") continue;
    const text = normalizeForFingerprint(extractMessageText(messages[i]?.content));
    if (!text) continue;
    const h = createHash("sha256").update(text).digest("hex").slice(0, 24);
    return `ha:${cookieKey}:asst:${h}`;
  }
  return null;
}

/** Short stable key from cookie for cache isolation (not the full secret). */
export function cookieFingerprint(cookie: string): string {
  return createHash("sha256")
    .update(cookie || "")
    .digest("hex")
    .slice(0, 16);
}

export function readClientThreadIds(
  body: HyperAgentRequestBody,
  headers?: Record<string, string>
): { threadId: string; sessionId: string } {
  const fromBodyThread = readStr(body.hyperagent_thread_id) || readStr(body.thread_id);
  const fromBodySession = readStr(body.hyperagent_session_id) || readStr(body.session_id);
  if (!headers) return { threadId: fromBodyThread, sessionId: fromBodySession };
  const lower: Record<string, string> = {};
  for (const [k, v] of Object.entries(headers)) lower[k.toLowerCase()] = String(v ?? "");
  const threadId =
    fromBodyThread ||
    readStr(lower["x-hyperagent-thread-id"]) ||
    readStr(lower["x-thread-id"]) ||
    "";
  const sessionId =
    fromBodySession ||
    readStr(lower["x-hyperagent-session-id"]) ||
    readStr(lower["x-session-id"]) ||
    "";
  return { threadId, sessionId };
}

export type HyperAgentThreadResolve = {
  threadId: string;
  sessionId: string;
  isFollowUp: boolean;
  prefixKey: string | null;
};

export function resolveHyperAgentThreadBinding(
  cookieKey: string,
  messages: ChatMessage[],
  clientThreadId?: string,
  clientSessionId?: string
): HyperAgentThreadResolve {
  const clientId = (clientThreadId || "").trim();
  const clientSess = (clientSessionId || "").trim();
  const prefix = historyPrefixBeforeLastUser(messages);
  const prefixKey =
    prefix.length > 0 && hasAssistantMessage(prefix)
      ? conversationFingerprint(cookieKey, prefix)
      : null;
  const rootKey = rootUserFingerprint(cookieKey, messages);

  if (clientId) {
    return {
      threadId: clientId,
      sessionId: clientSess,
      isFollowUp: true,
      prefixKey: prefixKey || rootKey,
    };
  }

  // 1) Exact history prefix (works when assistant text is unchanged across turns)
  if (prefixKey) {
    const cached = getThreadBinding(prefixKey);
    if (cached?.threadId && cached.projectKey === cookieKey) {
      return {
        threadId: cached.threadId,
        sessionId: cached.sessionId || clientSess,
        isFollowUp: true,
        prefixKey,
      };
    }
  }

  // 2) Root user task (stable across agentic tool_calls reverse-convert + tool loops)
  if (rootKey && hasAssistantMessage(messages)) {
    const cached = getThreadBinding(rootKey);
    if (cached?.threadId && cached.projectKey === cookieKey) {
      return {
        threadId: cached.threadId,
        sessionId: cached.sessionId || clientSess,
        isFollowUp: true,
        prefixKey: rootKey,
      };
    }
  }

  // 3) Last assistant text (legacy; may miss when reverse conversion rewrote the turn)
  if (hasAssistantMessage(messages)) {
    const asstKey = lastAssistantFingerprint(cookieKey, prefix.length ? prefix : messages);
    if (asstKey) {
      const cached = getThreadBinding(asstKey);
      if (cached?.threadId && cached.projectKey === cookieKey) {
        return {
          threadId: cached.threadId,
          sessionId: cached.sessionId || clientSess,
          isFollowUp: true,
          prefixKey: asstKey,
        };
      }
    }
  }

  return { threadId: "", sessionId: "", isFollowUp: false, prefixKey: null };
}

export function storeHyperAgentThreadAfterTurn(
  cookieKey: string,
  messages: ChatMessage[],
  assistantText: string,
  threadId: string,
  sessionId: string
): string | null {
  if (!cookieKey || !threadId) return null;
  const full: ChatMessage[] = [...messages, { role: "assistant", content: assistantText || "" }];
  if (
    !hasAssistantMessage(full) ||
    !messages.some((m) => {
      const r = (m.role || "").toLowerCase();
      return r === "user" || r === "human" || r === "tool" || r === "function";
    })
  ) {
    return null;
  }
  const binding: ThreadBinding = {
    threadId,
    sessionId: sessionId || "",
    projectKey: cookieKey,
    updatedAt: Date.now(),
  };
  const key = conversationFingerprint(cookieKey, full);
  setThreadBinding(key, binding);
  const prefix = historyPrefixBeforeLastUser(messages);
  if (prefix.length > 0 && hasAssistantMessage(prefix)) {
    setThreadBinding(conversationFingerprint(cookieKey, prefix), binding);
  }
  const asstKey = lastAssistantFingerprint(cookieKey, full);
  if (asstKey) setThreadBinding(asstKey, binding);
  // Always pin root user task → thread so tool-loop follow-ups (mutated assistant
  // content after Agentic reverse conversion) still hit the same HyperAgent thread.
  const rootKey = rootUserFingerprint(cookieKey, messages);
  if (rootKey) setThreadBinding(rootKey, binding);
  return key;
}

// ─── HTTP helpers ───────────────────────────────────────────────────────────

function browserHeaders(cookie: string, extra?: Record<string, string>): Record<string, string> {
  return {
    accept: "*/*",
    "accept-language": "en-US,en;q=0.9",
    cookie,
    origin: ORIGIN,
    referer: `${ORIGIN}/`,
    "user-agent": USER_AGENT,
    ...extra,
  };
}

/**
 * Create a new HyperAgent thread id.
 * Primary (live-validated): POST /api/threads → { id }.
 * Fallback: GET /threads/new (Next RSC) and parse Location / body.
 */
export async function createHyperAgentThread(
  cookie: string,
  signal?: AbortSignal | null
): Promise<string> {
  try {
    const res = await fetch(`${ORIGIN}/api/threads`, {
      method: "POST",
      headers: browserHeaders(cookie, {
        "content-type": "application/json",
        "x-request-id": randomUUID(),
      }),
      body: JSON.stringify({}),
      signal: signal ?? undefined,
      redirect: "manual",
    });
    const loc = res.headers.get("location") || res.headers.get("Location") || "";
    const fromLoc = extractThreadIdFromUrl(loc);
    if (fromLoc) return fromLoc;
    if (res.ok) {
      const text = await res.text();
      try {
        const j = JSON.parse(text) as Record<string, unknown>;
        const id =
          readStr(j.id) ||
          readStr(j.threadId) ||
          readStr(j.thread_id) ||
          (j.thread && typeof j.thread === "object"
            ? readStr((j.thread as Record<string, unknown>).id)
            : "");
        if (id) return id;
      } catch {
        const m = text.match(/cm[a-z0-9]{20,}/i);
        if (m) return m[0]!;
      }
    }
  } catch {
    /* fall through */
  }

  const res2 = await fetch(`${ORIGIN}/threads/new`, {
    method: "GET",
    headers: browserHeaders(cookie, {
      rsc: "1",
      "next-url": "/",
      "x-request-id": randomUUID(),
    }),
    signal: signal ?? undefined,
    redirect: "manual",
  });
  const loc2 =
    res2.headers.get("location") ||
    res2.headers.get("Location") ||
    res2.headers.get("x-middleware-rewrite") ||
    "";
  const fromLoc2 = extractThreadIdFromUrl(loc2);
  if (fromLoc2) return fromLoc2;

  if (res2.status >= 200 && res2.status < 400) {
    const text = await res2.text().catch(() => "");
    const m = text.match(/\/thread\/(cm[a-z0-9]{20,})/i) || text.match(/"(cm[a-z0-9]{20,})"/i);
    if (m) return m[1]!;
  }

  throw new Error(
    `Could not create HyperAgent thread (HTTP ${res2.status}). Ensure the session Cookie is valid and not expired.`
  );
}

/**
 * Apply model + execution settings on a thread (live SPA does this before chat).
 *
 * - modelId: wire id (e.g. fable-latest — NOT bare "fable")
 * - defaultSubagentModel: short family (fable|opus|sonnet|haiku) matching selected model
 * - executionMode: "auto" (only non-null value accepted live)
 * - runtimeId: claude-agents-sdk for Claude family
 *
 * Chat body must NOT carry modelId (API returns model_unknown for bare pricing keys).
 */
export async function configureHyperAgentThread(
  cookie: string,
  threadId: string,
  opts: {
    modelId: string;
    subagentModelId: string;
    runtimeId?: string;
    executionMode?: "auto" | null;
  },
  signal?: AbortSignal | null
): Promise<void> {
  const body: Record<string, unknown> = {
    modelId: opts.modelId,
    defaultSubagentModel: opts.subagentModelId,
    runtimeId: opts.runtimeId || "claude-agents-sdk",
  };
  // "auto" = execution-style agent loop (validated). null clears. Never "plan".
  if (opts.executionMode === "auto") body.executionMode = "auto";
  else if (opts.executionMode === null) body.executionMode = null;

  const res = await fetch(`${ORIGIN}/api/threads/${encodeURIComponent(threadId)}`, {
    method: "PATCH",
    headers: browserHeaders(cookie, {
      "content-type": "application/json",
      "x-request-id": randomUUID(),
      referer: `${ORIGIN}/thread/${threadId}`,
    }),
    body: JSON.stringify(body),
    signal: signal ?? undefined,
  });
  if (!res.ok) {
    const errText = await res.text().catch(() => "");
    throw new Error(
      `HyperAgent configure thread HTTP ${res.status}: ${errText.slice(0, 300) || res.statusText}`
    );
  }
}

export function extractThreadIdFromUrl(url: string): string {
  if (!url) return "";
  const m = url.match(/\/thread\/([A-Za-z0-9_-]{10,})/i) || url.match(/(cm[a-z0-9]{20,})/i);
  return m ? m[1]! : "";
}

