/**
 * Parse HyperAgent SSE stream into assistant text (+ sessionId).
 * Accumulates `type:"text"` content; ignores thinking for the OpenAI body.
 */
export async function parseHyperAgentSseStream(
  response: Response
): Promise<{ text: string; sessionId: string; modelId: string; events: number }> {
  if (!response.body) {
    throw new Error("Empty HyperAgent stream body");
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let text = "";
  let sessionId = "";
  let modelId = "";
  let events = 0;

  const handleData = (payload: string) => {
    const trimmed = payload.trim();
    if (!trimmed || trimmed === "[DONE]") return;
    let obj: Record<string, unknown>;
    try {
      obj = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      return;
    }
    events += 1;
    const type = readStr(obj.type);
    if (type === "text") {
      text += typeof obj.content === "string" ? obj.content : "";
    } else if (type === "session_start") {
      const sid = readStr(obj.sessionId);
      if (sid) sessionId = sid;
    } else if (type === "thread_runtime_latched") {
      const mid = readStr(obj.modelId);
      if (mid) modelId = mid;
    } else if (type === "error" || type === "stream_error") {
      const msg =
        readStr(obj.content) ||
        readStr(obj.message) ||
        readStr(obj.error) ||
        "HyperAgent stream error";
      throw new Error(msg);
    }
  };

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    // Split SSE frames
    const parts = buffer.split("\n");
    buffer = parts.pop() || "";
    for (const line of parts) {
      const t = line.trimEnd();
      if (t.startsWith("data:")) {
        handleData(t.slice(5).trimStart());
      }
    }
  }
  if (buffer.trim()) {
    const t = buffer.trim();
    if (t.startsWith("data:")) handleData(t.slice(5).trimStart());
  }

  return { text, sessionId, modelId, events };
}

// ─── OpenAI response helpers ────────────────────────────────────────────────

function estimateUsage(messages: ChatMessage[] | undefined, content: string) {
  const prompt = (messages || []).map((m) => extractMessageText(m.content)).join("\n");
  const prompt_tokens = Math.max(1, Math.ceil(prompt.length / 4));
  const completion_tokens = Math.max(1, Math.ceil(content.length / 4));
  return {
    prompt_tokens,
    completion_tokens,
    total_tokens: prompt_tokens + completion_tokens,
    estimated: true,
  };
}

function chatCompletionResponse(
  content: string,
  model: string,
  messages: ChatMessage[] | undefined,
  threadId?: string,
  sessionId?: string
) {
  const id = threadId ? `chatcmpl-ha-${threadId}` : `chatcmpl-ha-${Date.now()}`;
  return new Response(
    JSON.stringify({
      id,
      object: "chat.completion",
      created: Math.floor(Date.now() / 1000),
      model,
      choices: [{ index: 0, message: { role: "assistant", content }, finish_reason: "stop" }],
      usage: estimateUsage(messages, content),
      hyperagent_thread_id: threadId || undefined,
      hyperagent_session_id: sessionId || undefined,
    }),
    {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        ...(threadId ? { "X-HyperAgent-Thread-Id": threadId } : {}),
        ...(sessionId ? { "X-HyperAgent-Session-Id": sessionId } : {}),
      },
    }
  );
}

function pseudoStreamResponse(
  content: string,
  model: string,
  threadId?: string,
  sessionId?: string
) {
  const encoder = new TextEncoder();
  const id = threadId ? `chatcmpl-ha-${threadId}` : `chatcmpl-ha-${Date.now()}`;
  const chunk = (delta: string, finishReason: string | null) => ({
    id,
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{ index: 0, delta: delta ? { content: delta } : {}, finish_reason: finishReason }],
  });
  const readable = new ReadableStream({
    start(controller) {
      const parts = content.match(/\S+\s*/g) || [content];
      let buf = "";
      for (const p of parts) {
        buf += p;
        if (buf.length >= 40) {
          controller.enqueue(encoder.encode(`data: ${JSON.stringify(chunk(buf, null))}\n\n`));
          buf = "";
        }
      }
      if (buf) controller.enqueue(encoder.encode(`data: ${JSON.stringify(chunk(buf, null))}\n\n`));
      controller.enqueue(encoder.encode(`data: ${JSON.stringify(chunk("", "stop"))}\n\n`));
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      controller.close();
    },
  });
  return new Response(readable, {
    status: 200,
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
      ...(threadId ? { "X-HyperAgent-Thread-Id": threadId } : {}),
      ...(sessionId ? { "X-HyperAgent-Session-Id": sessionId } : {}),
    },
  });
}

// ─── Executor ───────────────────────────────────────────────────────────────

export class HyperAgentExecutor extends BaseExecutor {
  constructor() {
    super("hyperagent", {
      id: "hyperagent",
      baseUrl: `${ORIGIN}/api/threads`,
    });
  }

  async execute(input: ExecuteInput) {
    const { model, body, stream: wantStream, credentials, signal } = input;
    const requestBody = (body || {}) as HyperAgentRequestBody;
    const { cookie } = resolveHyperAgentCredentials(credentials);

    if (!cookie) {
      return makeErrorResult(
        401,
        "Missing HyperAgent session cookie — paste the full Cookie header from hyperagent.com (DevTools → Network → any document request → Request Headers → Cookie)",
        body,
        `${ORIGIN}/api/threads`
      );
    }

    const messages = requestBody.messages || [];
    const userText = lastUserText(messages);
    if (!userText) {
      return makeErrorResult(400, "No user message found", body, `${ORIGIN}/api/threads`);
    }

    const clientFacing = clientFacingHyperAgentModelId(model || requestBody.model);
    const wireModel = wireHyperAgentModelId(model || requestBody.model);
    const subagentModel = wireHyperAgentSubagentModelId(model || requestBody.model);
    const runtimeId = wireHyperAgentRuntimeId(model || requestBody.model);
    const cookieKey = cookieFingerprint(cookie);

    const inboundHeaders =
      (input.clientHeaders as Record<string, string> | null | undefined) ??
      ((input as { headers?: Record<string, string> }).headers as
        Record<string, string> | undefined);
    const clientIds = readClientThreadIds(requestBody, inboundHeaders ?? undefined);
    const binding = resolveHyperAgentThreadBinding(
      cookieKey,
      messages,
      clientIds.threadId,
      clientIds.sessionId
    );

    let threadId = binding.threadId;
    let sessionId = binding.sessionId || null;

    try {
      if (!binding.isFollowUp || !threadId) {
        threadId = await createHyperAgentThread(cookie, signal);
        sessionId = null;
      }

      // Always apply model + execution settings on the thread (SPA does this
      // before /chat). Chat body must not carry modelId.
      await configureHyperAgentThread(
        cookie,
        threadId,
        {
          modelId: wireModel,
          subagentModelId: subagentModel,
          runtimeId,
          executionMode: "auto",
        },
        signal
      );

      const chatUrl = `${ORIGIN}/api/threads/${encodeURIComponent(threadId)}/chat`;
      const chatBody = buildHyperAgentChatBody({
        content: userText,
        sessionId,
      });

      const res = await fetch(chatUrl, {
        method: "POST",
        headers: browserHeaders(cookie, {
          "content-type": "application/json",
          referer: `${ORIGIN}/thread/${threadId}`,
          "x-request-id": randomUUID(),
        }),
        body: JSON.stringify(chatBody),
        signal: signal ?? undefined,
      });

      if (!res.ok) {
        const errText = await res.text().catch(() => "");
        // Stale thread → create once, reconfigure, retry
        if (res.status === 404 || /not found|unknown thread/i.test(errText)) {
          threadId = await createHyperAgentThread(cookie, signal);
          sessionId = null;
          await configureHyperAgentThread(
            cookie,
            threadId,
            {
              modelId: wireModel,
              subagentModelId: subagentModel,
              runtimeId,
              executionMode: "auto",
            },
            signal
          );
          const retryUrl = `${ORIGIN}/api/threads/${encodeURIComponent(threadId)}/chat`;
          const retryBody = buildHyperAgentChatBody({
            content: userText,
            sessionId: null,
          });
          const res2 = await fetch(retryUrl, {
            method: "POST",
            headers: browserHeaders(cookie, {
              "content-type": "application/json",
              referer: `${ORIGIN}/thread/${threadId}`,
              "x-request-id": randomUUID(),
            }),
            body: JSON.stringify(retryBody),
            signal: signal ?? undefined,
          });
          if (!res2.ok) {
            const t2 = await res2.text().catch(() => "");
            return makeErrorResult(
              res2.status >= 400 && res2.status < 600 ? res2.status : 502,
              `HyperAgent chat HTTP ${res2.status}: ${t2.slice(0, 300)}`,
              body,
              retryUrl
            );
          }
          const parsed2 = await parseHyperAgentSseStream(res2);
          return finalize(parsed2, messages, clientFacing, threadId, cookieKey, wantStream);
        }
        return makeErrorResult(
          res.status >= 400 && res.status < 600 ? res.status : 502,
          `HyperAgent chat HTTP ${res.status}: ${errText.slice(0, 300)}`,
          body,
          chatUrl
        );
      }

      const parsed = await parseHyperAgentSseStream(res);
      // Prefer session from stream; keep prior if stream omitted on follow-up
      if (!parsed.sessionId && sessionId) parsed.sessionId = sessionId;
      return finalize(parsed, messages, clientFacing, threadId, cookieKey, wantStream);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      const status = /cookie|401|unauthor/i.test(msg) ? 401 : /timeout/i.test(msg) ? 504 : 502;
      return makeErrorResult(status, `HyperAgent: ${msg}`, body, `${ORIGIN}/api/threads`);
    }
  }
}

function finalize(
  parsed: { text: string; sessionId: string; modelId: string; events: number },
  messages: ChatMessage[],
  clientFacing: string,
  threadId: string,
  cookieKey: string,
  wantStream?: boolean
) {
  const text = (parsed.text || "").trim();
  if (!text) {
    return makeErrorResult(
      502,
      `HyperAgent returned empty content (events=${parsed.events})`,
      undefined,
      `${ORIGIN}/api/threads`
    );
  }
  storeHyperAgentThreadAfterTurn(cookieKey, messages, text, threadId, parsed.sessionId || "");
  const modelOut = parsed.modelId || clientFacing;
  const response = wantStream
    ? pseudoStreamResponse(text, modelOut, threadId, parsed.sessionId)
    : chatCompletionResponse(text, modelOut, messages, threadId, parsed.sessionId);
  return {
    response,
    url: `${ORIGIN}/api/threads/${threadId}/chat`,
    headers: { Cookie: "***" },
    transformedBody: {
      threadId,
      sessionId: parsed.sessionId || null,
      model: modelOut,
    },
  };
}

export { HYPERAGENT_FALLBACK_MODELS, ORIGIN as HYPERAGENT_ORIGIN };

import { BaseExecutor, type ExecutorLog, type ProviderCredentials } from "./base.ts";
import { PROVIDERS } from "../config/constants.ts";
import { getModelTargetFormat } from "../config/providerModels.ts";

type JsonRecord = Record<string, unknown>;

/**
 * xAI/Grok model ids (open-sse/config/providers/registry/xai/index.ts) that accept
 * a graduated `reasoning_effort`. Kept narrow and reconciled against the REAL
 * catalog rather than upstream's example ids (grok-4/grok-3 do not exist here):
 *   - grok-4.3                  — current-generation flagship, reasoning-capable.
 *   - grok-4.20-0309-reasoning  — explicit reasoning variant.
 *
 * grok-4.20-multi-agent-0309 is intentionally left unclassified (neither allow
 * nor deny): its reasoning support is not documented in the local catalog, so
 * we pass it through unchanged rather than guess.
 */
const REASONING_ALLOWED = ["grok-4.3", "grok-4.20-0309-reasoning"];

/**
 * Model ids that reject `reasoning_effort` outright:
 *   - grok-build-0.1                — build/tool-oriented model, no reasoning mode.
 *   - grok-4.20-0309-non-reasoning   — already encodes "no reasoning" in the id;
 *     forwarding reasoning_effort here would be redundant/rejected upstream.
 */
const REASONING_DENIED = ["grok-build-0.1", "grok-4.20-0309-non-reasoning"];

/** `-{level}` suffixes some clients append to a model id to select reasoning intensity. */
const EFFORT_SUFFIXES = ["low", "medium", "high", "xhigh"] as const;

function asRecord(value: unknown): JsonRecord | null {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : null;
}

/**
 * xAI/Grok executor (port of decolua/9router#2147).
 *
 * Some Grok clients select reasoning intensity via a `-{low,medium,high,xhigh}`
 * suffix on the model id (e.g. `grok-4.3-high`) rather than a native
 * `reasoning_effort` field — xAI itself does not recognize the suffixed id.
 * This executor:
 *   1. Parses and strips that suffix off the model id before the request
 *      reaches xAI, mapping it to `reasoning_effort` for allow-listed models.
 *   2. Strips any `reasoning_effort` for deny-listed models — including ids
 *      that already encode their reasoning state in the name (`-reasoning` /
 *      `-non-reasoning`), which must not be double-mutated by also stacking a
 *      `reasoning_effort` field on top of what the id already declares.
 *   3. Leaves unclassified models and bodies untouched otherwise.
 */
export class XaiExecutor extends BaseExecutor {
  constructor(provider = "xai") {
    super(provider, PROVIDERS[provider]);
  }

  /**
   * Port of decolua/9router#2439 (author: @ryanngit): xAI ships a native
   * `/v1/responses` endpoint alongside `/v1/chat/completions`. Models tagged
   * `targetFormat: "openai-responses"` in the registry (currently
   * grok-4.20-multi-agent-0309, per upstream) resolve to that endpoint instead
   * of the default chat-completions bridge. The per-model registry tag is the
   * single source of truth — it also drives chatCore's body translation — so
   * the URL stays in lockstep with the translated body, mirroring the gh
   * executor's targetFormat-driven routing (9router#102) and the "openai"
   * -pro heuristic in open-sse/executors/default.ts.
   */
  buildUrl(model: string, _stream: boolean, _urlIndex = 0) {
    if (getModelTargetFormat(this.provider, model) === "openai-responses") {
      return this.config.responsesBaseUrl || this.config.baseUrl;
    }
    return this.config.baseUrl;
  }

  async refreshCredentials(
    credentials: ProviderCredentials,
    log?: ExecutorLog | null
  ): Promise<Partial<ProviderCredentials> | null> {
    if (this.provider !== "xai-oauth" || !credentials.refreshToken) return null;

    try {
      const response = await fetch(this.config.tokenUrl || "https://auth.x.ai/oauth2/token", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Accept: "application/json",
        },
        body: new URLSearchParams({
          grant_type: "refresh_token",
          client_id: this.config.clientId || "",
          refresh_token: credentials.refreshToken,
        }),
      });

      if (!response.ok) {
        log?.warn?.("TOKEN_REFRESH", `xAI OAuth refresh failed with status ${response.status}`);
        return null;
      }

      const data = await response.json();
      if (!data.access_token) {
        log?.warn?.("TOKEN_REFRESH", "xAI OAuth refresh response omitted access_token");
        return null;
      }

      const expiresIn = Number(data.expires_in) || 21600;
      return {
        accessToken: data.access_token,
        refreshToken: data.refresh_token || credentials.refreshToken,
        expiresAt: new Date(Date.now() + expiresIn * 1000).toISOString(),
      };
    } catch (error) {
      log?.warn?.(
        "TOKEN_REFRESH",
        `xAI OAuth refresh error: ${error instanceof Error ? error.message : String(error)}`
      );
      return null;
    }
  }

  transformRequest(
    model: string,
    body: unknown,
    stream: boolean,
    credentials: ProviderCredentials
  ): unknown {
    const cleaned = super.transformRequest(model, body, stream, credentials);
    const record = asRecord(cleaned);
    if (!record) return cleaned;

    const out: JsonRecord = { ...record };
    let modelId = typeof out.model === "string" ? out.model : model;

    let suffixEffort: string | null = null;
    for (const level of EFFORT_SUFFIXES) {
      const suffix = `-${level}`;
      if (modelId.endsWith(suffix)) {
        suffixEffort = level;
        modelId = modelId.slice(0, -suffix.length);
        break;
      }
    }
    if (suffixEffort && typeof out.model === "string") {
      out.model = modelId;
    }

    const isDenied = REASONING_DENIED.some((id) => modelId.includes(id));
    const isAllowed = REASONING_ALLOWED.some((id) => modelId.includes(id));

    if (isDenied) {
      delete out.reasoning_effort;
    } else if (isAllowed) {
      const effort = suffixEffort || out.reasoning_effort;
      if (effort) out.reasoning_effort = effort;
    }

    return out;
  }
}

export default XaiExecutor;

/**
 * PromptQLExecutor — prompt.ql.app playground agent (Unofficial/Experimental)
 *
 * Reverse-engineered from the SPA (2026-07-20):
 *   - Mutations start_thread / send_thread_message only return UserMessage
 *   - AI output is AgentMessage rows on thread_events (Hasura stream or poll)
 *   - Auth: Bearer JWT (Hasura enrich-token) + projectId claim
 *   - Models: FetchLlmConfigs; optional llmConfigId on start_thread (String!)
 *   - Credits: promptql_project_credit_summary on data.pro.ql.app (usage leaf)
 *
 * OpenAI multi-turn is preserved via sticky PromptQL thread_id:
 *   - Prefer body.promptql_thread_id / X-PromptQL-Thread-Id from the client
 *   - Else history-prefix fingerprint (full user+assistant before last user)
 *   - First turn always start_thread (never first-user-only sticky — that
 *     collided across SkillsManager/agent sessions and routed follow-ups to
 *     older chats)
 * Response always echoes X-PromptQL-Thread-Id + promptql_thread_id.
 *
 * Token refresh (POST auth.pro.ql.app/ddn/project/token with session cookies)
 * is implemented best-effort and still needs production verification.
 */
import { BaseExecutor, type ExecuteInput } from "./base.ts";
import { makeExecutorErrorResult as makeErrorResult } from "../utils/error.ts";
import {
  PROMPTQL_FALLBACK_MODELS,
  clientFacingPromptQlModelId,
  resolvePromptQlModel,
  type PromptQlModel,
} from "../services/promptqlModels.ts";
